insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مِنْ كُلِّ اللَّيْلِ قَدْ أَوْتَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ. (م)', 'ആഇക(റ): രാവിന്റെ മുഴുവൻ ദശകളിലും നബി(സ) വിത്ർ നിസ്കരിച്ചിട്ടുണ്ട്. അത് അത്താഴസമയം വരെ നീണ്ടു നിൽക്കാറുമുണ്ടായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇക(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، قِيلَ لَهَا: مَتَى كَانَ يُوتِرُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: كُلَّ ذَلِكَ قَدْ فَعَلَ أَوْتَرَ أَوَّلَ اللَّيْلِ، وَوَسَطَهُ وَآخِرَهُ، وَلَكِنِ انْتَهَى وِتْرُهُ حِينَ مَاتَ إِلَى السَّحَرِ. (د,جه)', 'ആഇശ(റ): അവരോട് ചോദിക്കപ്പെട്ടു: എപ്പോഴായിരുന്നു പ്രവാചകന്റെ(സ) വിത്ർ നിസ്കാരം?. അവർ പറഞ്ഞു: രാത്രിയുടെ ആദ്യ ഭാഗത്തും, മധ്യത്തിലും, അന്ത്യത്തിലും പ്രവാചകൻ(സ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. മരണത്തിനോടടുത്തപ്പോൾ അത്താഴ സമയത്തായിരുന്നു വിത്ർ അവസാനിപ്പിച്ചിരുന്നത്. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَادِرُوا الصُّبْحَ بِالْوِتْرِ". (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സുബ്ഹ് നിസ്കാരത്തെ വിത്റിന്റെ ഉടനെയാക്കുക." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: سُئِلَتْ عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: رُبَّمَا أَوْتَرَ أَوَّلَ اللَّيْلِ، وَرُبَّمَا أَوْتَرَ مِنْ آخِرِهِ، قُلْتُ: كَيْفَ كَانَتْ قِرَاءَتُهُ، أَكَانَ يُسِرُّ بِالْقِرَاءَةِ، أَمْ يَجْهَرُ؟ قَالَتْ: كُلَّ ذَلِكَ كَانَ يَفْعَلُ، رُبَّمَا أَسَرَّ، وَرُبَّمَا جَهَرَ، وَرُبَّمَا اغْتَسَلَ فَنَامَ، وَرُبَّمَا تَوَضَّأَ فَنَامَ، قَالَ أَبُو دَاوُد: تَعْنِي فِي الْجَنَابَةِ. (د)', 'ആഇശ(റ): നബി(സ)യുടെ വിത്ർ നിസ്കാരത്തെക്കുറിച്ച് അവർ ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: നബി(സ) ചിലപ്പോൾ രാത്രിയുടെ ആദ്യ ഭാഗത്തിൽ വിത്റ് നിസ്കരിച്ചു. മറ്റു ചിലപ്പോൾ അവസാന ദശയിലും. ഞാൻ ചോദിച്ചു: നബി(സ)യുടെ വിത്ർ നിസ്കാരത്തിലെ ഖുർആൻ പാരായണം എങ്ങിനെയായിരുന്നു, അത് ഉറക്കെയായിരുന്നോ അതോ പതുക്കെയായിരുന്നോ? അവർ പറഞ്ഞു: അവയെല്ലാം പ്രവാചകൻ(സ) ചെയ്തിട്ടുണ്ട്. ചില സമയങ്ങളിൽ ഉറക്കെയാക്കി. മറ്റുചിലപ്പോൾ പതുക്കെയും പാരായണം ചെയ്തു. മറ്റു ചിലപ്പോൾ കുളിച്ച ശേഷം ഉറങ്ങി, ചിലപ്പോൾ വുദു ചെയ്ത ശേഷം ഉറങ്ങി. (അബൂദാവൂദ് പറഞ്ഞു:അവർ ഉദ്ദേശിച്ചത് ജനാബത്ത് കുളിയാണ്). (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اجْعَلُوا آخِرَ صَلَاتِكُمْ بِاللَّيْلِ وِتْرًا". (خ,د)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളുടെ രാത്രിയിലെ അവസാന നിസ്കാരം വിത്റ് നിസ്കാരമാക്കുക." (ബു,ദ)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ: كَانَ يَنَامُ أَوَّلَ اللَّيْلِ, ثُمَّ يَقُومُ، فَإِذَا كَانَ مِنَ السَّحَرِ أَوْتَرَ، ثُمَّ أَتَى فِرَاشَهُ، فَإِذَا كَانَ لَهُ حَاجَةٌ أَلَمَّ بِأَهْلِهِ، فَإِذَا سَمِعَ الْأَذَانَ وَثَبَ، فَإِنْ كَانَ جُنُبًا أَفَاضَ عَلَيْهِ مِنَ الْمَاءِ، وَإِلَّا تَوَضَّأَ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ. (ن)', 'ആഇശ(റ): നബി(സ)യുടെ നിസ്കാരത്തെപ്പറ്റി മഹതിയോട് ചോദിക്കപ്പെട്ടു. മഹതി പറഞ്ഞു: രാത്രിയുടെ ആദ്യ ദശയിൽ ഉറങ്ങും. പിന്നീട് എഴുന്നേൽക്കും. അന്ത്യയാമമായാൽ വിത്ർ നിസ്കരിക്കും. ശേഷം വിരിപ്പിലേക്ക് ചെല്ലും. ഇണയിലേക്ക് ആവശ്യമായാൽ അത് നിറവേറ്റും. ബാങ്ക് കേട്ടാൽ ധൃതിയിൽ എഴുന്നേൽക്കും. ജനാബത്തുകാരനാണെങ്കിൽ കുളിക്കും. അല്ലെങ്കിൽ വുദു ചെയ്യും. പിന്നീട് നിസ്കാരത്തിനായി പുറപ്പെടും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَوْتَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَوَّلِهِ وَآخِرِهِ وَأَوْسَطِهِ، وَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ. (ن)', 'ആഇശ(റ): നബി(സ) രാവിന്റെ ആദ്യ ദശയിൽ വിത്ർ നിസ്കരിക്കാറുണ്ട്. അന്ത്യത്തിലും, മധ്യത്തിലും നിസ്കരിക്കാറുണ്ടായിരുന്നു. അവസാന കാലത്ത് അന്ത്യ ദശയിലാണ് വിത്ർ നിസ്കരിച്ചിരുന്നത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَنْ صَلَّى مِنَ اللَّيْلِ فَلْيَجْعَلْ آخِرَ صَلَاتِهِ وِتْرًا، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْمُرُ بِذَلِكَ. (ن)', 'ഇബ്നുഉമർ(റ): ആരെങ്കിലും രാത്രി നിസ്കരിക്കുകയാണെങ്കിൽ അവസാനം വിത്ർ നിസ്കാരമാക്കിക്കൊള്ളട്ടെ. കാരണം പ്രവാചകൻ(സ) അങ്ങനെ ഉപദേശിക്കാറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَهْلَ الْقُرْآنِ أَوْتِرُوا، فَإِنَّ اللهَ وِتْرٌ، يُحِبُّ الْوِتْرَ". وَفِي رِوَايَةٍ: قَالَ أَعْرَابِيٌّ: مَا تَقُولُ؟ فَقَالَ: "لَيْسَ لَكَ، وَلَا لأَصْحَابِكَ". (د,جه)', 'അലി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഓ, അഹ്ലുൽ ഖുർആൻ. നിങ്ങൾ വിത്ർ നിസ്കരിക്കുക. നിശ്ചയം, അല്ലാഹു ഒറ്റ (വിത്ർ)യാണ്. അവൻ ഒറ്റയെ ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നു." മറ്റൊരു റിപ്പോർട്ടിൽ: ഒരു ഗ്രാമവാസി ചോദിച്ചു: താങ്കളെന്താണു പറയുന്നത്? നബി(സ) പറഞ്ഞു: "നിനക്കും നിന്റെ ആളുകൾക്കും ഇത് ബാധകമല്ല." (ദ,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: قَالَ أَعْرَابِيٌّ: مَا تَقُولُ؟ فَقَالَ: "لَيْسَ لَكَ، وَلَا لأَصْحَابِكَ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: ഒരു ഗ്രാമവാസി ചോദിച്ചു: താങ്കളെന്താണു പറയുന്നത്? നബി(സ) പറഞ്ഞു: "നിനക്കും നിന്റെ ആളുകൾക്കും ഇത് ബാധകമല്ല." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبُو الْوَلِيدِ الْعَدَوِيُّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ قَدْ أَمَدَّكُمْ بِصَلَاةٍ، وَهِيَ خَيْرٌ لَكُمْ مِنْ حُمْرِ النَّعَمِ، وَهِيَ الْوِتْرُ. فَجَعَلَهَا لَكُمْ فِيمَا بَيْنَ الْعِشَاءِ إِلَى طُلُوعِ الْفَجْرِ". (د,ت,جه)', 'അബുൽ വലീദുൽ അദവി(റ): നബി(സ) പുറത്തേക്കു വന്നുകൊണ്ട് പറഞ്ഞു: "പ്രതാപശാലിയും ഉന്നതനുമായ അല്ലാഹു നിങ്ങളെ ഒരു പ്രത്യേക നിസ്കാരം കൊണ്ടനുഗ്രഹിച്ചിരിക്കുന്നു. അത് നിങ്ങൾക്ക് ചുവന്ന ഒട്ടകത്തെക്കാൾ¹ ഉത്തമമാണ്. അതാണ് വിത്ർ നിസ്കാരം. അതിനെയവൻ നിങ്ങൾക്ക് വേണ്ടി നിശ്ചയിച്ചിരിക്കുന്നത് ഇശാഇനും സൂര്യോദയത്തിനും ഇടയിലാണ്. (ദ,തു,ജ)', 'أَبُو الْوَلِيدِ الْعَدَوِيُّ', 'അബുൽ വലീദുൽ അദവി(റ)', '¹. അറബികൾ ഇഷ്ടപ്പെട്ടിരുന്ന ഏറ്റവും നല്ല സമ്പത്താണത്.', null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَامَ عَنْ وِتْرِهِ أَوْ نَسِيَهُ فَلْيُصَلِّهِ إِذَا ذَكَرَهُ". (د,ت,جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉറങ്ങിയോ മറന്നോ വിത്ർ ഉപേക്ഷിച്ചാൽ അവൻ ഓർമ്മ വരുമ്പോൾ നിസ്കരിക്കട്ടെ." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ زَيْدِ بْنِ أَسْلَمَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَامَ عَنْ وِتْرِهِ فَلْيُصَلِّ إِذَا أَصْبَحَ". (ت)', 'സൈദുബ്നു അസ്ലം(റ): നബി(സ) പറഞ്ഞു: "വിത്റ് നിർവ്വഹിക്കാതെ ആരെങ്കിലും ഉറങ്ങിപ്പോയാൽ അവൻ പ്രഭാതത്തിൽ നിസ്കരിക്കട്ടെ." (തു)', 'زَيْدِ بْنِ أَسْلَمَ', 'സൈദുബ്നു അസ്ലം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: الْوِتْرُ لَيْسَ بِحَتْمٍ كَهَيْئَةِ الْمَكْتُوبَةِ، وَلَكِنَّهُ سُنَّةٌ سَنَّهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت,ن)', 'അലി(റ): നിർബന്ധ പ്രാർത്ഥനപോലെ വിത്ർ ഒരു നിർബന്ധ നിസ്കാരമല്ല. എന്നാൽ പ്രവാചകൻ(സ) നിത്യചര്യയാക്കിയ ഒരു നിസ്കാരമാണത്. (തു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ الْوِتْرَ لَيْسَ بِحَتْمٍ، وَلَا كَصَلَاتِكُمُ الْمَكْتُوبَةِ. وَلَكِنْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْتَرَ، ثُمَّ قَالَ: "يَا أَهْلَ الْقُرْآنِ أَوْتِرُوا، فَإِنَّ اللهَ وِتْرٌ يُحِبُّ الْوِتْرَ". (ن,جه)', 'അലി(റ): വിത്റ് നിസ്കാരം നിർബന്ധമല്ല. അത് നിർബന്ധ പ്രാർത്ഥനപോലെയുമല്ല. എങ്കിലും പ്രവാചകൻ(സ) വിത്ർ നിസ്കരിച്ചു. ശേഷം പറഞ്ഞു: "ഓ അഹ്ലുൽ ഖുർആൻ, നിങ്ങൾ വിത്ർ നിസ്കരിക്കുക. കാരണം അല്ലാഹു ഒറ്റയാണ്. അവൻ ഒറ്റയെ ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നു." (ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَنَسِ بْنِ سِيرِينَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ ابْنَ عُمَرَ، قُلْتُ: أَرَأَيْتَ الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْغَدَاةِ، أَأُطِيلُ فِيهِمَا الْقِرَاءَةَ؟ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ، قَالَ: قُلْتُ: إِنِّي لَسْتُ عَنْ هَذَا أَسْأَلُكَ، قَالَ: إِنَّكَ لَضَخْمٌ، أَلَا تَدَعُنِي أَسْتَقْرِئُ لَكَ الْحَدِيثَ، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ، وَيُصَلِّي رَكْعَتَيْنِ قَبْلَ الْغَدَاةِ كَأَنَّ الْأَذَانَ بِأُذُنَيْهِ. (ق)', 'അനസുബ്നു സീരീൻ(റ): ഇബ്നുഉമറി(റ) നോട് ഞാൻ ചോദിച്ചു: പ്രഭാത നിസ്കാരത്തിന് മുമ്പുള്ള രണ്ട് റക്അത്തിനെ കുറിച്ച് താങ്കളുടെ അഭിപ്രായമെന്താണ്? അവ രണ്ടിലും എന്റെ ഖുർആൻ പാരായണം ദീർഘിപ്പിക്കേണ്ടതുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) രാത്രിയിൽ ഈരണ്ട് ഈരണ്ട് റക്അത്തായാണ് നിസ്കരിച്ചിരുന്നത്. ഒരു റക്അത്ത് ഒറ്റയായും. ഇബ്നുസീരീൻ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: ഇതിനെ സംബന്ധിച്ചല്ല ഞാൻ താങ്കളോട് ചോദിച്ചത്. നിങ്ങൾ പെരുപ്പിക്കുകയാണ്. നിങ്ങൾക്ക് ഹദീസ് പറഞ്ഞുതരാൻ എന്നെ അനുവദിച്ചാലും! നബി(സ) രാത്രിയിൽ ഈരണ്ട് ഈരണ്ട് റക്അത്തായാണ് നിസ്കരിച്ചിരുന്നത്. ഒരു റക്അത് ഒറ്റയായും. പ്രഭാതത്തിന് മുമ്പ് സുബ്ഹി ബാങ്ക് ചെവിയിലെത്തുന്ന സന്ദർഭത്തിൽ രണ്ട് റക്അതും നിസ്കരിക്കും. (ബാങ്കിനു തൊട്ടു മുമ്പ്) (ബു,മു)', 'أَنَسِ بْنِ سِيرِينَ', 'അനസുബ്നു സീരീൻ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ. (ق,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ രാത്രിയിൽ ഈരണ്ട് ഈരണ്ട് റക്അത്തായി നമസ്കരിക്കുമായിരുന്നു. ഒരു റക്അത് ഒറ്റയായും. (ബു,മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، وَالْوِتْرُ رَكْعَةٌ". قُلْتُ: أَرَأَيْتَ إِنْ غَلَبَتْنِي عَيْنِي، أَرَأَيْتَ إِنْ نِمْتُ؟ قَالَ: "اجْعَلْ أَرَأَيْتَ". عِنْدَ ذَلِكَ النَّجْمِ؟ فَرَفَعْتُ رَأْسِي، فَإِذَا السِّمَاكُ رَضِيَ اللهُ عَنْهُ، ثُمَّ أَعَادَ، فَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، وَالْوِتْرُ رَكْعَةٌ قَبْلَ الصُّبْحِ". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി നിസ്കാരം ഈരണ്ടായും, വിത്റ് ഒരു റക്അതുമാണ്." ഞാൻ ചോദിച്ചു: എനിക്ക് നന്നായി ഉറക്കം വരികയും അങ്ങനെ ഞാൻ ഉറങ്ങുകയും ചെയ്താലോ?. നബി(സ) പറഞ്ഞു: "അങ്ങിനെത്തന്നെ ചെയ്യുക. (ഉറങ്ങുക)" ആ നക്ഷത്രം (പ്രഭാത നക്ഷത്രം) ഉദിക്കുമ്പോഴാണു ഞാൻ ഉണർന്നതെങ്കിലോ? അപ്പോൾ ഞാൻ തലയുയർത്തി നോക്കി. സമ്മാക്ക്(റ) എന്റെ അടുത്ത് നിൽക്കുന്നു. അദ്ദേഹവും ചോദ്യങ്ങൾ ആവർത്തിച്ചു. നബി(സ) പറഞ്ഞു: "രാത്രിനിസ്കാരം രണ്ട് റക്അത്തായിട്ടാണ്. വിത്റ് സുബഹ്ന് മുമ്പ് ഒരു റക്അത്തും." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: وَقَدْ سَأَلَهُ رَجُلٌ فَقَالَ: كَيْفَ أُوتِرُ؟ قَالَ: أَوْتِرْ بِوَاحِدَةٍ، قَالَ: إِنِّي أَخْشَى أَنْ يَقُولَ النَّاسُ الْبُتَيْرَاءُ، فَقَالَ: سُنَّةُ اللهِ وَرَسُولِهِ، يُرِيدُ هَذِهِ سُنَّةُ اللهِ وَرَسُولِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ഇബ്നുഉമർ(റ): ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: ഞാൻ എങ്ങിനെയാണ് വിത്ർ നിസ്കരിക്കേണ്ടത്? അദ്ദേഹം പറഞ്ഞു: നീ വിത്ർ ഒരു റക്അത്ത് നിസ്കരിക്കുക. അയാൾ വീണ്ടും ചോദിച്ചു: പൂർത്തിയാക്കാത്ത നിസ്കാരം എന്നു പറഞ്ഞ് ജനങ്ങൾ എന്നെ ആക്ഷേപിക്കുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെയും അവന്റെ ദൂതന്റെയും സുന്നത്ത്. ഇതാണ് അല്ലാഹുവിന്റെയും അവന്റെ ദൂതന്റെയും സുന്നത്ത് എന്നാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسَلِّمُ فِي كُلِّ ثِنْتَيْنِ، وَيُوتِرُ بِوَاحِدَةٍ. (جه)', 'ആഇശ(റ) പറയുന്നു: ഓരോ രണ്ട് റക്അത്തുകളിലും നബി(സ) സലാം വീട്ടാറുണ്ടായിരുന്നു. ഒരു റക്അത്ത് ഒറ്റയുമാക്കും. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كُنْتُ أُلْفِي، أَوْ أَلْقَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ آخِرِ اللَّيْلِ، إِلَّا وَهُوَ نَائِمٌ عِنْدِي.[قَالَ وَكِيعٌ: تَعْنِي بَعْدَ الْوِتْرِ] (جه)', 'ആഇശ(റ) പറഞ്ഞു: രാത്രിയുടെ അന്ത്യത്തിൽ നബി(സ)യെ ഉറങ്ങുന്നതായിട്ടല്ലാതെ ഞാൻ കാണാറില്ല. വകീഅ് പറഞ്ഞു: മഹതി ഉദ്ദേശിച്ചത് വിത്റിന് ശേഷമെന്നാണ്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'قَالَ وَكِيعٌ: تَعْنِي بَعْدَ الْوِتْرِ', null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى رَكْعَتَيِ الْفَجْرِ اضْطَجَعَ. (جه)', 'അബൂഹുറൈറ(റ): സുബ്ഹിന്റെ സുന്നത്ത് നിസ്കരിച്ചാൽ നബി(സ) ചെരിഞ്ഞ് കിടക്കാറുണ്ടായിരുന്നു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَنَسِ بْنِ سِيرِينَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ ابْنَ عُمَرَ فَقُلْتُ: أُطِيلُ فِي رَكْعَتَيِ الْفَجْرِ؟ فَقَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ، وَكَانَ يُصَلِّي الرَّكْعَتَيْنِ، وَالْأَذَانُ فِي أُذُنِهِ يَعْنِي – يُخَفِّفُ. حَسَنٌ صَحِيحٌ (ت)', 'അനസുബ്നു സീരീൻ(റ): ഞാൻ ഇബ്നു ഉമറി(റ)നോട് ചോദിച്ചു. സുബ്ഹികയുടെ സുന്നത്തായ രണ്ട് റക്അത്ത് ഞാൻ ദീർഘിപ്പിക്കേണ്ടതുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) രാത്രിയിൽ നിസ്കരിച്ചിരുന്നത് ഈരണ്ട് റക്അത്തുകളായും, ഒരു റക്അത് ഒറ്റയാക്കിയുമായിരുന്നു. (ശേഷം) നബി(സ) രണ്ട് റക്അത് നിസ്കരിക്കുമായിരുന്നു. ആ സമയത്തും ബാങ്കിന്റെ അലയൊലി അടങ്ങിയിട്ടുണ്ടാകില്ല. അതായത്. ലഘുവാക്കികൊണ്ട് (നമസ്കരിച്ചു). (തു)', 'أَنَسِ بْنِ سِيرِينَ', 'അനസുബ്നു സീരീൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 552, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ أَهْلِ الْبَادِيَةِ سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلَاةِ اللَّيْلِ, قَالَ: "مَثْنَى مَثْنَى, وَالْوِتْرُ رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ". (م,د,ن)', 'ഇബ്നുഉമർ(റ): ഒരു ഗ്രാമവാസി നബി(സ)യോട് രാത്രി നിസ്കാരത്തെപ്പറ്റി ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "ഈരണ്ടീരണ്ട് റക്അത്താണ്, വിത്ർ നിസ്കാരം രാവിന്റെ അന്ത്യദശയിലെ ഒരു റക്അതാണ്." (മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْوِتْرُ حَقٌّ عَلَى كُلِّ مُسْلِمٍ، فَمَنْ أَحَبَّ أَنْ يُوتِرَ بِخَمْسٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِثَلَاثٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِوَاحِدَةٍ فَلْيَفْعَلْ". (د,ن,جه)', 'അബൂഅയ്യൂബിൽ അൻസാരി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "വിത്ർ നിസ്കാരം മുഴുവൻ മുസ്ലിംകൾക്കും ബാധ്യതയാണ്. ആരെങ്കിലും അഞ്ച് റക്അത്ത് വിത്ർ നിസ്കരിക്കാൻ ഉദ്ദേശിച്ചാൽ അവൻ അങ്ങനെ ചെയ്യട്ടെ. മൂന്ന് റക്അത്ത് നിസ്കരിക്കാനുദ്ദേശിച്ചാൽ അവൻ അപ്രകാരം ചെയ്യട്ടെ. ഇനി ഒരു റക്അത്ത് നിസ്കരിക്കാനുദ്ദേശിച്ചവൻ അപ്രകാരം ചെയ്യട്ടെ." (ദ,ന,ജ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബിൽ അൻസാരി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ, فَقَالَتْ: كَانَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً، تِسْعَ رَكَعَاتٍ قَائِمًا يُوتِرُ فِيهَا، وَرَكْعَتَيْنِ جَالِسًا، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ، فَرَكَعَ وَسَجَدَ، وَيَفْعَلُ ذَلِكَ بَعْدَ الْوِتْرِ، فَإِذَا سَمِعَ نِدَاءَ الصُّبْحِ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ. (ت,ن)', 'ആഇശ(റ): നബി(സ)യുടെ രാത്രി നിസ്കാരത്തെക്കുറിച്ച് അവരോട് ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: പ്രവാചകൻ പതിമൂന്ന് റക്ത്താണ് നിസ്കരിച്ചിരുന്നത്. ഒമ്പത് റക്അത് നിന്ന് നിർവ്വഹിച്ചു. അതിൽ വിത്റാക്കുകയും ചെയ്തു. രണ്ട് റക്അത് ഇരുന്നും നിർവ്വഹിച്ചു. റുകൂഇലെത്തുമ്പോൾ എഴുന്നേറ്റ് നിന്ന് റുകൂഉം സുജൂദും നിർവ്വഹിക്കും. അത് വിത്റിന്ന് ശേഷമാണ് ചെയ്തിരുന്നത്. ശേഷം സുബ്ഹ് ബാങ്ക് കേട്ടാൽ എഴുന്നേറ്റ് ലഘുവായ രണ്ട് റക്അത്ത് നിസ്കരിക്കും. (തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ مَا تَرَى فِي صَلَاةِ اللَّيْلِ؟ قَالَ: مَثْنَى مَثْنَى، فَإِذَا خَشِيَ الصُّبْحَ صَلَّى وَاحِدَةً، فَأَوْتَرَتْ لَهُ مَا صَلَّى، وَإِنَّهُ كَانَ يَقُولُ: اجْعَلُوا آخِرَ صَلَاتِكُمْ وِتْرًا، فَإِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِهِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) മിമ്പറിലായിരിക്കെ ഒരാൾ ചോദിച്ചു: രാത്രി നിസ്കാരത്തെക്കുറിച്ച് എന്തു പറയുന്നു?. നബി(സ) പറഞ്ഞു: "ഈരണ്ടായി നിസ്കരിക്കണം. സുബ്ഹി യാവുമെന്ന് ഭയന്നാൽ ഒരു റക്അത്ത് നിസ്കരിക്കണം. ഈ ഒരു റക്അത്ത് അവൻ നിർവ്വഹിച്ച നിസ്കാരത്തെ ഒറ്റയായതാക്കുകയും ചെയ്യും." ഇബ്നുഉമർ(റ) പറയുമായിരുന്നു: നിങ്ങൾ നിസ്കാരത്തിന്റെ അവസാനം ഒറ്റയാക്കുക. കാരണം നബി(സ) അത് കൽപിച്ചിട്ടുണ്ട്. (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَمَانَ رَكَعَاتٍ، وَيُوتِرُ بِثَلَاثٍ، وَيُصَلِّي رَكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) രാത്രിയിൽ എട്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. മൂന്ന് റക്അത്തുകൾ വിത്റും നിർവഹിക്കുമായിരുന്നു. ഫജ്റ് നമസ്കാരത്തിനു മുമ്പായി രണ്ട് റക്അത്തുകൾ റിർവ്വഹിക്കാറുമുണ്ടായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 553, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ وَعَبْدِ اللهِ بْنِ عُمَرَ – رَضِيَ اللهُ عَنْهُمْ – سُئِلَا عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ فَقَالَا: ثَلَاثَ عَشْرَةَ رَكْعَةً: مِنْهَا ثَمَانٍ، وَيُوتِرُ بِثَلَاثٍ، وَرَكْعَتَيْنِ بَعْدَ الْفَجْرِ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ), ഇബ്നുഉമർ(റ) എന്നിവരോട് പ്രവാചകരുടെ(സ) രാത്രിയിലെ നമസ്കാരത്തെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അവർ ഇരുവരും പറഞ്ഞു: പതിമൂന്ന് റക്അത്തുകളാണ് നിർവ്വഹിക്കാറുള്ളത്. അവിടുന്ന് എട്ട് റക്അത്തുകൾ നിർവ്വഹിക്കുകയും, മൂന്ന് റക്അത്തുൾ വിത്റ് നിസ്കരിക്കുകയും, ഫജ്റിന് ശേഷം രണ്ടുറക്അത്തുകൾ നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ وَعَبْدِ اللهِ بْنِ عُمَرَ –', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ خَافَ أَنْ لَا يَقُومَ مِنْ آخِرِ اللَّيْلِ فَلْيُوتِرْ أَوَّلَهُ، وَمَنْ طَمِعَ أَنْ يَقُومَ آخِرَهُ فَلْيُوتِرْ آخِرَ اللَّيْلِ، فَإِنَّ صَلَاةَ آخِرِ اللَّيْلِ مَشْهُودَةٌ، وَذَلِكَ أَفْضَلُ". (جه)', 'ജാബിർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരാൾ രാത്രിയുടെ അന്ത്യദശയിൽ എഴുന്നേൽക്കാൻ സാധ്യമല്ലെന്ന് ഭയന്നാൽ ആദ്യ ദശയിൽ നിസ്കരിക്കട്ടെ. ഭയമില്ലെങ്കിൽ അവസാന ദശയിലാക്കട്ടെ. രാത്രിയുടെ അന്ത്യയാമത്തിലെ നിസ്കാരത്തിന് (അനുഗ്രഹത്തിന്റെ മലക്കുകൾ) സാക്ഷ്യം വഹിക്കും. അതാണ് കൂടുതൽ ഉത്തമവും." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوْتِرُوا قَبْلَ أَنْ تُصْبِحُوا". (م,ت,ن,جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സുബ്ഹ് നിസ്കാരത്തിന് മുമ്പ് വിത്ർ നിസ്കരിക്കുക." (മു,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلَاةِ اللَّيْلِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً، تُوتِرُ لَهُ مَا قَدْ صَلَّى". (ق,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ)യോട് രാത്രി നിസ്കാരത്തെ പറ്റി ഒരാൾ ചോദിച്ചു. പ്രവാചകൻ (സ) അരുളി: "രാത്രി നിസ്കാരം ഈരണ്ടു റക്അത്തുകളാണ്. സുബ്ഹിയാകാൻ പോവുകയാണെന്ന് ആർക്കെങ്കിലും ശങ്ക തോന്നിയാൽ ഒരു റക്അത്ത് നിസ്കരിക്കണം. അപ്പോൾ അത് മുമ്പ് നിസ്കരിച്ചു കഴിഞ്ഞവയെ ഒറ്റയാക്കിത്തീർക്കും." (ബു,മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ: "أَيَّ حِينٍ تُوتِرُ؟" قَالَ: أَوَّلَ اللَّيْلِ بَعْدَ الْعَتَمَةِ، قَالَ: "فَأَنْتَ يَا عُمَرُ؟" فَقَالَ: آخِرَ اللَّيْلِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا أَنْتَ يَا أَبَا بَكْرٍ فَأَخَذْتَ بِالْوُثْقَى, وَأَمَّا أَنْتَ يَا عُمَرُ فَأَخَذْتَ بِالْقُوَّةِ". وَفِي رِوَايَةٍ عَنِ ابْنِ عُمَرَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَبِي بَكْرٍ......... فَذَكَرَ نَحْوَهُ. وَفِي رِوَايَةٍ: فَقَالَ لِأَبِي بَكْرٍ: "أَخَذَ هَذَا بِالْحَزْمِ". وَقَالَ لِعُمَرَ: "أَخَذَ هَذَا بِالْقُوَّةِ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): പ്രവാചകൻ(സ) അബൂബക്കറി(റ)നോട് ചോദിച്ചു: "താങ്കൾ എപ്പോഴാണ് വിത്ർ നിസ്കരിക്കാറ്?" അദ്ദേഹം പറഞ്ഞു: ഇശാഇന് ശേഷം രാത്രിയുടെ ആദ്യത്തിൽ. പിന്നെ നബി(സ) ചോദിച്ചു: "താങ്കളോ ഉമറേ". ഉമർ(റ) പറഞ്ഞു: രാത്രിയുടെ അന്ത്യത്തിൽ. റസൂൽ(സ) അരുളി: "ഓ അബൂബക്കർ, താങ്കൾ ഉറപ്പായതിനെ സ്വീകരിച്ചു. ഓ ഉമർ, താങ്കൾ ഉണരുമെന്ന ദൃഢവിശ്വാസത്തെയും അവലംബിച്ചു." മറ്റൊരു റിപ്പോർട്ടിൽ ഇബ്നുഉമർ(റ) പറയുന്നു: നബി(സ) അബൂബക്കർ(റ)വിനോട് ചോദിച്ചു..... തുടർന്ന് മുകളിലെ ഹദീസിന്റെ അതേ ആശയത്തിലുള്ള ഹദീസ് പറഞ്ഞു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) അബൂബക്കറിനോട് പറഞ്ഞു: "ഇദ്ദേഹം മനസ്സിന്റെ ഉറപ്പനുസരിച്ച് ചെയ്യുന്നു." ഉമറി(റ)വിനോട് പറഞ്ഞു: "ഇദ്ദേഹം ഉണരുമെന്ന ദൃഢവിശ്വാസത്തെ അവലംബിക്കുന്നു." (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 554, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=32), 1, 'وَفِي رِوَايَةٍ عَنِ ابْنِ عُمَرَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَبِي بَكْرٍ......... فَذَكَرَ نَحْوَهُ.', 'മറ്റൊരു നിവേദനിൽ ഇബ്നുഉമർ(റ) പറയുന്നു: നബി(സ) അബൂബക്കർ(റ)വിനോട് ചോദിച്ചു..... തുടർന്ന് മുകളിലെ ഹദീസിന്റെ അതേ ആശയത്തിലുള്ള ഹദീസ് പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=32), 2, 'وَفِي رِوَايَةٍ: فَقَالَ لِأَبِي بَكْرٍ: "أَخَذَ هَذَا بِالْحَزْمِ". وَقَالَ لِعُمَرَ: "أَخَذَ هَذَا بِالْقُوَّةِ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) അബൂബക്കറിനോട് പറഞ്ഞു: "ഇദ്ദേഹം മനസ്സിന്റെ ഉറപ്പനുസരിച്ച് ചെയ്യുന്നു." ഉമറി(റ)വിനോട് പറഞ്ഞു: "ഇദ്ദേഹം ഉണരുമെന്ന ദൃഢവിശ്വാസത്തെ അവലംബിക്കുന്നു." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ قَيْسِ بْنِ طَلْقٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: زَارَنَا أَبِي طَلْقُ ابْنُ عَلِيٍّ فِي يَوْمٍ مِنْ رَمَضَانَ, فَأَمْسَى بِنَا, وَقَامَ بِنَا تِلْكَ اللَّيْلَةَ وَأَوْتَرَ بِنَا, ثُمَّ انْحَدَرَ إِلَى الْمَسْجِدِ, فَصَلَّى بِأَصْحَابِهِ حَتَّى بَقِيَ الْوِتْرُ, ثُمَّ قَدَّمَ رَجُلًا, فَقَالَ لَهُ: أَوْتِرْ بِهِمْ, فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا وِتْرَانِ فِي لَيْلَةٍ". (د,ت,ن)', 'ഖൈസുബ്നു ത്വൽഖ്(റ): എന്റെ പിതാവ് ത്വൽഖ് ബിൻ അലി(റ) റമദാനിലെ ഒരുദിവസം ഞങ്ങളെ സന്ദർശിച്ചു. ഞങ്ങളോടൊപ്പം രാത്രി കഴിച്ചുകൂട്ടുകയും നിസ്കരിക്കുകയും, വിത്റ് നിർവ്വഹിക്കുകയും ചെയ്തു. പിന്നെ പോയി അദ്ദേഹത്തിന്റെ ആളുകളോടൊപ്പം പള്ളിയിൽ നിസ്കരിക്കുകയും ചെയ്തു. വിത്റിനു സമയമായപ്പോൾ മറ്റൊരാളെ മുന്നോട്ട് നിർത്തി ഇപ്രകാരം പറഞ്ഞു: അവരോടൊപ്പം വിത്റ് നിസ്കരിക്കുക. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഒരു രാത്രിയിൽ രണ്ട് വിത്ർ നിസ്കാരമില്ല." (ദ,തു,ന)', 'قَيْسِ بْنِ طَلْقٍ', 'ഖൈസുബ്നു ത്വൽഖ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بَعْدَ الْوِتْرِ رَكْعَتَيْنِ خَفِيفَتَيْنِ وَهُوَ جَالِسٌ. (ت,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) വിത്റിന് ശേഷം ഇരുന്നുകൊണ്ട് ലഘുവായ രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (തു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِوَاحِدَةٍ، ثُمَّ يَرْكَعُ رَكْعَتَيْنِ يَقْرَأُ فِيهِمَا وَهُوَ جَالِسٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ. (جه)', 'ആഇശ(റ): നബി(സ) ഒരു റക്അത്ത് വിത്റാക്കി നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. പിന്നെ ഇരുന്ന് രണ്ട് റക്ത്തുകൾ നിർവ്വഹിക്കും. അതിൽ ഖുർആൻ പാരായണം ചെയ്യുകയും, റുകൂഇനു സമയമാവുമ്പോൾ എഴുന്നേറ്റ് നിന്ന് റുകൂഉം ചെയ്യും. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُحِبُّ أَحَدُكُمْ إِذَا رَجَعَ إِلَى أَهْلِهِ أَنْ يَجِدَ فِيهِ ثَلَاثَ خَلِفَاتٍ عِظَامٍ سِمَانٍ؟" قُلْنَا: نَعَمْ, قَالَ: "فَثَلَاثُ آيَاتٍ يَقْرَأُ بِهِنَّ أَحَدُكُمْ فِي صَلَاتِهِ، خَيْرٌ لَهُ مِنْ ثَلَاثِ خَلِفَاتٍ عِظَامٍ سِمَانٍ". (م,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും സ്വഭവനത്തിൽ മൂന്ന് തടിമാടന്മാരായ മേത്തരം ഒട്ടകങ്ങളുണ്ടാകുന്നത് ആഗ്രഹിക്കുന്നുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ തന്റെ നിസ്കാരത്തിൽ മൂന്ന് സൂക്തങ്ങൾ ഓതുന്നുണ്ടെങ്കിൽ അതാണ് അവന് മൂന്ന് തടിച്ച മേത്തരം ഒട്ടകങ്ങളെക്കാൾ നല്ലത്." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً، كَانَتْ تِلْكَ صَلَاتَهُ – تَعْنِي بِاللَّيْلِ، فَيَسْجُدُ السَّجْدَةَ مِنْ ذَلِكَ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً، قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ، وَيَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ، ثُمَّ يَضْطَجِعُ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ لِلصَّلَاةِ. (خ)', 'ആഇശ(റ): നിശ്ചയം റസൂൽ(സ) പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അപ്രകാരമായിരുന്നു നബി(സ)യുടെ രാത്രി നിസ്കാരം. അതിൽ അവിടുന്ന് സുജൂദ് ചെയ്തിരുന്നത്. സുജൂദിൽനിന്ന് അവിടുന്ന് തലയുയർത്തുന്നതിനു മുമ്പായി നിങ്ങളിലൊരാൾ അൻപത് ആയത്ത് ഓതുന്നത്രയും ദീർഘിപ്പിച്ചു കൊണ്ടായിരുന്നു. ഫജ്റ് നിസ്കാരത്തിനു മുമ്പായി രണ്ട് റക്അത്തു കൂടി നിസ്കരിച്ചിരുന്നു. പിന്നീട് മുഅദ്ദിൻ നിസ്കാരത്തിന്നു വരുന്നതുവരെ വലത് വശത്തേക്കു ചെരിഞ്ഞ് കിടക്കും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ بَيْنَ مَكَّةَ وَالْمَدِينَةِ، فَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ، ثُمَّ قَامَ فَصَلَّى رَكْعَةً أَوْتَرَ بِهَا، فَقَرَأَ فِيهَا بِمِائَةِ آيَةٍ مِنَ النِّسَاءِ، ثُمَّ قَالَ: مَا أَلَوْتُ أَنْ أَضَعَ قَدَمِي حَيْثُ وَضَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدَمَيْهِ، وَأَنَا أَقْرَأُ بِمَا قَرَأَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മൂസ(റ): അദ്ദേഹം മക്കയുടെയും മദീനയുടെയും ഇടയിലായിരിക്കെ അവിടെ വെച്ച് ഇശാ നിസ്കാരം രണ്ട് റക്അത്തും ശേഷം ഒരു റക്അത്ത് വിത്റും നിർവഹിച്ചു. അതിൽ സൂറത്തു ന്നിസാഇലെ നൂറ് സൂക്തങ്ങൾ ഓതി. പിന്നീടദ്ദേഹം പറഞ്ഞു: നബി(സ) അവിടുത്തെ ഇരു പാദങ്ങൾ വെച്ചിടത്ത് എന്റെ പാദങ്ങൾ വെക്കുന്നതിൽ ഞാനൊരിക്കലും വീഴ്ച വരുത്തിയിട്ടില്ല. റസൂൽ(സ) ഓതിയ അതേ സൂക്തങ്ങൾ ഞാൻ ഓതുകയും ചെയ്യുന്നു. (ന)', 'مُوسَى', 'മൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِ:{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}, وَ {قُلْ لِلَّذِينَ كَفَرُوا....} [آل عمران] وَاللهُ الْوَاحِدُ الصَّمَدُ. (د)', 'ഉബയ്യുബ്നു കഅബ്(റ): ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ'', ''ഖുൽ ലില്ലദീന കഫറൂ...........'' (ആലുഇംറാൻ:12). ''അല്ലാഹു ഏകനും നിരാശ്രയനുമാകുന്നു'' (എന്നു പ്രസ്താവിക്കുന്ന സൂറത്തുൽ ഇഖ്ലാസ്) എന്നിവ ഓതിക്കൊണ്ടാണ് നബി(സ) വിത്റ് നിർവ്വഹിച്ചിരുന്നത്. (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'آل عمران', null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْوِتْرِ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ{قُلْ هُوَ اللهُ أَحَدٌ} فِي رَكْعَةٍ رَكْعَةٍ. (ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) വിത്ർ നിസ്കാരത്തിൽ ഒരു റക്അത്തിൽ ''സബ്ബിഹിസ്മ.............''യും, അടുത്ത റക്അത്തിൽ ''ഖുൽയാഅയ്യുഹ..........''യും, അടുത്തതിൽ ''ഖുൽഹുവല്ലാഹു..........'' എന്നീ സൂറത്തുകൾ ഓതാറുണ്ടായിരുന്നു. (തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا وَقَدْ سُئِلَتْ: بِأَيِّ شَيْءٍ كَانَ يُوتِرُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: كَانَ يَقْرَأُ فِي الْأُولَى بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}, وَفِي الثَّانِيَةِ بِ{قُلْ يَا أَيُّهَا الْكَافِرُونَ}, وَفِي الثَّالِثَةِ بِ{قُلْ هُوَ اللهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ. (د,جه)', 'ആഇശ(റ): നബി(സ) ഏത് (സൂറത്ത്) ഓതിക്കൊണ്ടാണ് വിത്റ് നമസ്കാരം നിർവ്വഹിച്ചിരുന്നത് എന്ന് അവരോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: നബി(സ) ഒന്നാമത്തെ റക്അത്തിൽ ''സബ്ബിഹിസ്മ..............''യും, രണ്ടാമത്തേതിൽ ''ഖുൽയാ അയ്യുഹൽ ..........''യും, മൂന്നാമത്തേതിൽ ''ഖുൽഹുവല്ലാഹു............'', മുഅവ്വദത്തെനി'' എന്നീ സൂറത്തുകളും പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الْوِتْرِ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}, وَ{قُلْ يَا أَيُّهَا الْكَافِرُونَ}, وَ{قُلْ هُوَ اللهُ أَحَدٌ}. (ن)', 'അബ്ദുറഹ്മാനുബ്നു അബ്സ(റ): നബി(സ) വിത്റിൽ ''സബ്ബിഹിസ്മ.......'', ''ഖുൽയാ അയ്യുഹൽ കാഫിറൂന.....'', ''ഖുൽഹുവല്ലാഹു അഹദ്.....'' എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى', 'അബ്ദുറഹ്മാനുബ്നു അബ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْتَرَ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}. (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) വിത്റ് നിർവ്വഹിച്ചിരുന്നത് ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ'' എന്ന സൂറത്തു കൊണ്ടായിരുന്നു. (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ، فَقَرَأَ رَجُلٌ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} فَلَمَّا صَلَّى قَالَ: "مَنْ قَرَأَ بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى؟" قَالَ رَجُلٌ: أَنَا, قَالَ: "قَدْ عَلِمْتُ أَنَّ بَعْضُهُمْ خَالَجَنِيهَا". (ن)', 'ഇംറാനുബാനു ഹുസൈൻ(റ): റസൂൽ(സ) ളുഹർ നിസ്കരിക്കുമ്പോൾ ഒരാൾ ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ'' ഓതി. നിസ്കാരശേഷം നബി(സ) ചോദിച്ചു: "ആരാണ് ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ'' ഓതിയത്?" ഒരാൾ പറഞ്ഞു: ഞാൻ, നബി(സ) പറഞ്ഞു: "അവരിൽ ചിലർ അത് ഓതുന്നത് എന്റെ ശ്രദ്ധ തിരിച്ചു കളഞ്ഞു." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബാനു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْوِتْرِ {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ{قُلْ هُوَ اللهُ أَحَدٌ} فَإِذَا سَلَّمَ قَالَ: "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ". ثَلَاثَ مَرَّاتٍ. (د,ن,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) വിത്റിൽ ''സബ്ബിഹിസ്മ റബ്ബികൽ അഅ്ലാ.....'', ''ഖുൽയാ അയ്യുഹൽ കാഫിറൂന.........'', ''ഖുൽഹുവല്ലാഹു അഹദ്........'' എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്തിരുന്നു. സലാമിനുശേഷം: "സുബ്ഹാനൽ മലികുൽ ഖുദൂസ്" (രാജാധിപനും പരമ പരിശുദ്ധനുമായന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു) എന്ന് മൂന്ന് പ്രാവശ്യം പറയും. (ദ,ന,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{قُلْ يَا أَيُّهَا الْكَافِرُونَ}، وَ{قُلْ هُوَ اللهُ أَحَدٌ} وَيَقُولُ إِذَا سَلَّمَ – وَفِي رِوَايَةٍ: فَإِذَا فَرَغَ مِنَ الصَّلَاةِ – قَالَ: "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ ثَلَاثَ مَرَّاتٍ. وَفِي رِوَايَةٍ: طَوَّلَ فِي الثَّالِثَةِ. وَفِي رِوَايَةٍ: يَرْفَعُ صَوْتَهُ بِالثَّالِثَةِ. (ن)', 'അബ്ദുറഹ്മാനുബ്നു അബ്സ(റ): വിത്ർ നിസ്കാരത്തിൽ നബി(സ) ''സബ്ബിഹിസ്മ..........'', ''ഖുൽയാ അയ്യുഹ............'', ''ഖുൽഹുവല്ലാഹു............'' എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്തിരുന്നു. സലാമിനു ശേഷം: (മറ്റൊരു റിപ്പോർട്ടിൽ: നിസ്കാരത്തിൽ നിന്നു വിരമിച്ചശേഷം) "സുബ്ഹാനൽ മലികിൽ ഖുദൂസ്" എന്ന് മൂന്ന് പ്രാവശ്യം പറയാറുണ്ടായിരുന്നു". ഒരു റിപ്പോർട്ടിൽ: മൂന്നാമത്തേത് നീട്ടിപ്പറയും. മറ്റൊരു റിപ്പോർട്ട്: മൂന്നാമത്തേത് ശബ്ദം ഉയർത്തിപ്പറയും. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى', 'അബ്ദുറഹ്മാനുബ്നു അബ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=46), 1, 'وَفِي رِوَايَةٍ: فَإِذَا فَرَغَ مِنَ الصَّلَاةِ – قَالَ: "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ ثَلَاثَ مَرَّاتٍ.', 'മറ്റൊരു നിവേദനിൽ: നിസ്കാരത്തിൽ നിന്നു വിരമിച്ചശേഷം) "സുബ്ഹാനൽ മലികിൽ ഖുദൂസ്" എന്ന് മൂന്ന് പ്രാവശ്യം പറയാറുണ്ടായിരുന്നു". ഒരു റിപ്പോർട്ടിൽ: മൂന്നാമത്തേത് നീട്ടിപ്പറയും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=46), 2, 'وَفِي رِوَايَةٍ: طَوَّلَ فِي الثَّالِثَةِ.', 'മറ്റൊരു നിവേദന്: മൂന്നാമത്തേത് ശബ്ദം ഉയർത്തിപ്പറയും. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=46), 3, 'وَفِي رِوَايَةٍ: يَرْفَعُ صَوْتَهُ بِالثَّالِثَةِ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا: عَلَّمَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَلِمَاتٍ أَقُولُهُنَّ فِي الْوِتْرِ: (وَفِي رِوَايَةٍ: فِي قُنُوتِ الْوِتْرِ) اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ. وَفِي رِوَايَةٍ: وَصَلَّى اللهُ عَلَى النَّبِيِّ مُحَمَّدٍ. (د,ت,ن,جه)', 'ഹസനുബ്നു അലി(റ): നബി(സ) എനിക്ക് വിത്റിൽ ചൊല്ലേണ്ട ചില വാക്യങ്ങൾ പറഞ്ഞു തന്നു. (ഒരു റിപ്പോർട്ടിൽ: വിത്റിന്റെ ഖൂനൂതിൽ.) അല്ലാഹുവേ, നീ സന്മാർഗത്തിലാക്കിയവരുടെ കൂട്ടത്തിൽ എന്നെയും നേർമാർഗത്തിലാക്കണമേ. നീ സൗഖ്യം നൽകിയവരുടെ കൂട്ടത്തിൽ എന്നെ നീ ഉൾപെടുത്തണേ. നീ ഏറ്റെടുത്തവരുടെ കൂട്ടത്തിൽ എന്നെയും ഏറ്റെടുക്കേണമേ. നീ എനിക്ക് നൽകിയതിൽ നീ ബർകത് നൽകണമേ. നീ വിധിച്ചിട്ടുള്ള ചീത്തയിൽ നിന്ന് എന്നെ നീ കാക്കേണമേ. നീ വിധിക്കുന്നവനാണ്. നിനക്കെതിരിൽ വിധിക്കപ്പെടുകയില്ല. നീ നിശ്ചയം ആരെ ഏറ്റെടുത്തോ അവർ നിന്ദ്യരാവുകയില്ല. നീ ശത്രുത കാണിക്കുന്നവർ പ്രതാപത്തിലാവുകയുമില്ല. രക്ഷിതാവേ, നീ ഗുണവാനും ഉന്നതനുമായിരിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: മുഹമ്മദ് നബിക്ക് അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ. (ദ,തു,ന,ജ)', 'الْحَسَنِ بْنِ عَلِيٍّ', 'ഹസനുബ്നു അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=47), 1, 'وَفِي رِوَايَةٍ: فِي قُنُوتِ الْوِتْرِ) اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.', 'മറ്റൊരു നിവേദനിൽ: മുഹമ്മദ് നബിക്ക് അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ. (ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=47), 2, 'وَفِي رِوَايَةٍ: وَصَلَّى اللهُ عَلَى النَّبِيِّ مُحَمَّدٍ. (د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي وِتْرِهِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ". (د,ن,جه)', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ): വിത്റിൽ നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവെ, നിന്റെ പ്രീതി കൊണ്ട് നിന്റെ ദേഷ്യത്തിൽ നിന്നും, നിന്റെ പൊറുക്കൽ കൊണ്ട് നിന്റെ ശിക്ഷയിൽ നിന്നും ഞാൻ കാവൽ തേടുന്നു. നിന്നെക്കൊണ്ട് നിന്നിൽനിന്നും ഞാൻ കാവൽ തേടുന്നു. നിന്നെ സ്തുതിക്കുന്നതിനെ പരിമിതിപ്പെടുത്തുകയില്ല. നീ നിന്നെ സ്വയം വാഴ്തിയത് എപ്രകാരമാണോ അതുപോലെത്തന്നെയാണ് നീ." (ദ,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَمَّهُمْ يَعْنِي فِي رَمَضَانَ، وَكَانَ يَقْنُتُ فِي النِّصْفِ الْآخِرِ مِنْ رَمَضَانَ. (د)', 'ഉബയ്യ്ബ്നു കഅ്ബ്(റ): നബി(സ) (റമദാനിൽ) അവർക്ക് (അനുചരർക്ക്) ഇമാമായി നിന്നു. റമദാനിന്റെ അവസാനത്തെ പകുതിയിൽ അവിടുന്ന് ഖുനൂത്ത് ഓതിയിരുന്നു. (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യ്ബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ جَمَعَ النَّاسَ عَلَى أُبَيِّ بْنِ كَعْبٍ، فَكَانَ يُصَلِّي لَهُمْ عِشْرِينَ لَيْلَةً، وَلَا يَقْنُتُ بِهِمْ إِلَّا فِي النِّصْفِ الْبَاقِي، فَإِذَا كَانَتِ الْعَشْرُ الْأَوَاخِرُ تَخَلَّفَ، فَصَلَّى فِي بَيْتِهِ، فَكَانُوا يَقُولُونَ: أَبَقَ أُبَيٌّ. (د)', 'ഉമർ(റ): അദ്ദേഹം ജനങ്ങളെ ഉബയ്യ്ബ്നു കഅ്ബിന്റെ അടുക്കൽ ഒരുമിച്ചു കൂട്ടും. അദ്ദേഹം ഇരുപത് രാത്രികളോളം അവർക്ക് വേണ്ടി (തറാവീഹ്) നിസ്കരിക്കും. അവസാനത്തെ പകുതിയിലല്ലാതെ ഖുനൂത്ത് ഓതാറുണ്ടായിരുന്നില്ല. റമദാനിൽ നിന്ന് പത്ത് രാത്രികൾ മാത്രം ബാക്കി നിന്നാൽ അദ്ദേഹം പിൻവലിഞ്ഞ് വീട്ടിൽ വെച്ച് നിസ്കരിക്കും. ഉബയ്യ് ഒളിച്ചോടി എന്ന് ജനങ്ങൾ പറയും. (ദ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ فَيَقْنُتُ قَبْلَ الرُّكُوعِ. (ن,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) വിത്റ് നിസ്കരിക്കുകയും റുകൂഇന് മുമ്പ് ഖുനൂത് ഓതുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سَمِعَهُ يَقُولُ: "صَلَاةُ اللَّيْلِ رَكْعَتَيْنِ رَكْعَتَيْنِ، فَإِذَا خِفْتُمُ الصُّبْحَ فَأَوْتِرُوا بِوَاحِدَةٍ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "രാത്രി നിസ്കാരം ഈരണ്ട് റക്അത്താണ്. സുബ്ഹാകുമെന്ന് നിങ്ങൾ ഭയന്നാൽ ഒറ്റ റക്അത്ത് നിസ്കരിച്ച് വിത്റാക്കുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي مِنَ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً، وَيُوتِرُ مِنْهَا بِوَاحِدَةٍ، ثُمَّ يَضْطَجِعُ عَلَى شِقِّهِ الْأَيْمَنِ. (ن)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അതിൽനിന്ന് ഒരു റക്അത്തുകൊണ്ട് വിത്റാക്കുകയും പിന്നെ വലതു ഭാഗത്തേക്ക് ചെരിഞ്ഞ് കിടക്കുകയും ചെയ്യും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ: كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ؟ قَالَتْ: مَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَزِيدُ فِي رَمَضَانَ وَلَا غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّي أَرْبَعًا، فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ, ثُمَّ يُصَلِّي أَرْبَعًا، فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلَاثًا، قَالَتْ عَائِشَةُ: فَقُلْتُ: يَا رَسُولَ اللهِ، أَتَنَامُ قَبْلَ أَنْ تُوتِرَ؟ قَالَ: "يَا عَائِشَةُ، إِنَّ عَيْنِي تَنَامُ، وَلَا يَنَامُ قَلْبِي". (ن)', 'ആഇശ(റ): അവരോട് ചോദിക്കപ്പെട്ടു: റമദാനിൽ തിരുമേനിയുടെ (വിത്ർ) നിസ്കാരം എപ്രകാരമായിരുന്നു? അവർ പറഞ്ഞു: നബി(സ) റമദാനിലോ അതല്ലാത്ത സമയങ്ങളിലോ പതിനൊന്നിൽ കൂടുതൽ നിസ്കരിച്ചിരുന്നില്ല. നാല് റകഅത്ത് നിസ്കരിക്കും, അതിന്റെ ദൈർഘ്യത്തെക്കുറിച്ചോ വൈശിഷ്ട്യത്തെക്കുറിച്ചോ നിങ്ങൾ ചോദിക്കേണ്ടതില്ല. വീണ്ടും നാല് റക്അത് നിസ്കരിക്കും. അതിന്റെ ദൈർഘ്യത്തെക്കുറിച്ചും വൈശിഷ്ട്യത്തെക്കുറിച്ചും ചോദിക്കേണ്ടതില്ല. (അത്രക്ക് ദൈർഘ്യത്തോടെയും ഭംഗിയോടെയുമായിരുന്നു നിർവ്വഹിച്ചത്) പിന്നെ മൂന്ന് റക്അത്ത് നിസ്കരിക്കും. ആഇശ(റ) പറയുന്നു: അപ്പോൾ ഞാൻ ചോദിക്കും. അല്ലാഹുവിന്റെ ദൂതരെ, ഒറ്റയാക്കുന്നതിനു മുമ്പ് താങ്കൾ ഉറങ്ങുകയാണോ? നബി(സ) പറഞ്ഞു: "ആഇശാ, എന്റെ കണ്ണുകൾ ഉറങ്ങും. എന്നാൽ എന്റെ മനസ്സ് ഉറങ്ങുന്നില്ല." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا : أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يُسَلِّمُ فِي رَكْعَتَيِ الْوِتْرِ. (ن)', 'ആഇശ(റ): നബി(സ) വിത്റിന്റെ രണ്ടാമത്തെ റക്അത്തുകളിൽ സലാം വീട്ടാറുണ്ടായിരുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْوِتْرُ حَقٌّ، فَمَنْ شَاءَ فَلْيُوتِرْ بِخَمْسٍ، وَمَنْ شَاءَ فَلْيُوتِرْ بِثَلَاثٍ، وَمَنْ شَاءَ فَلْيُوتِرْ بِوَاحِدَةٍ". (د,ن,جه)', 'അബൂഅയ്യൂബുൽ അൻസ്വാരി(റ): നബി(സ) പറഞ്ഞു: "വിത്റ് ഓരോരുത്തരുടെയും ബാധ്യതയാണ്. അഞ്ച് റക്അത്തു കൊണ്ട് വിത്റാക്കാനുദ്ദേശിച്ചവൻ അങ്ങനെ നിർവ്വഹിക്കട്ടെ. മൂന്ന് കൊണ്ട് വിത്റാക്കനുദ്ദേശിച്ചാൽ അങ്ങിനെ ചെയ്യട്ടെ. ഒരു റക്അത് കൊണ്ട് വിത്റാക്കാനുദ്ദേശിച്ചാൽ അപ്രകാരം ചെയ്യട്ടെ." (ദ,ന,ജ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബുൽ അൻസ്വാരി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ يَقُولُ: الْوِتْرُ حَقٌّ، فَمَنْ أَحَبَّ أَنْ يُوتِرَ بِخَمْسِ رَكَعَاتٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِثَلَاثٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِوَاحِدَةٍ فَلْيَفْعَلْ. (ن)', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ): വിത്റ് ഓരോരുത്തരുടെയും ബാധ്യതയാണ്. ആരെങ്കിലും അഞ്ച് റക്അത്ത് കൊണ്ട് വിത്റാക്കാനുദ്ദേശിച്ചാൽ അവൻ അപ്രകാരം ചെയ്യട്ടെ, ഒരാൾ മൂന്ന് റക്അത്ത് ഉദ്ദേശിച്ചാൽ അപ്രകാരവും, ഒറ്റ റക്അത്ത് ഉദ്ദേശിച്ചാൽ അപ്രകാരവും ചെയ്യട്ടെ. (ന)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ شَاءَ أَوْتَرَ بِسَبْعٍ، وَمَنْ شَاءَ أَوْتَرَ بِخَمْسٍ، وَمَنْ شَاءَ أَوْتَرَ بِثَلَاثٍ، وَمَنْ شَاءَ أَوْتَرَ بِوَاحِدَةٍ، وَمَنْ شَاءَ أَوْمَأَ إِيمَاءً. (ن)', 'അബൂഅയ്യൂബ്(റ): വിത്റ് എഴ് റക്അത്ത് ഉദ്ദേശിക്കുന്നവൻ അപ്രകാരവും, അഞ്ച് ഉദ്ദേശിക്കുന്നവൻ അപ്രകാരവും മൂന്ന് ഉദ്ദേശിക്കുന്നവൻ അപ്രകാരവും ഒന്ന് ഉദ്ദേശിക്കുന്നവൻ അപ്രകാരവും നിർവ്വഹിക്കട്ടെ. (അതിന്നും സാധ്യമല്ലെങ്കിൽ) ആംഗ്യം കാണിച്ചു നിർവ്വഹിക്കുവാൻ ഉദ്ദേശിക്കുന്നവൻ അങ്ങനെ ചെയ്യട്ടെ. (ന)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سُئِلَتْ عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ، عَلَيْهِ وَسَلَّمَ قَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللهُ فِيمَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ، ثُمَّ يُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيهَا إِلَّا عِنْدَ الثَّامِنَةِ، فَيَدْعُو رَبَّهُ، فَيَذْكُرُ اللهَ، وَيَحْمَدُهُ، وَيَدْعُوهُ ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، ثُمَّ يَقُومُ فَيُصَلِّي التَّاسِعَةَ، ثُمَّ يَقْعُدُ فَيَذْكُرُ اللهَ وَيَحْمَدُهُ، وَيَدْعُو رَبَّهُ، وَيُصَلِّي عَلَى نَبِيِّهِ، ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا، ثُمَّ يُصَلِّي رَكْعَتَيْنِ بَعْدَ مَا يُسَلِّمُ وَهُوَ قَاعِدٌ، فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً، فَلَمَّا أَسَنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَخَذَ اللَّحْمَ، أَوْتَرَ بِسَبْعٍ، وَصَلَّى رَكْعَتَيْنِ بَعْدَ مَا سَلَّمَ. (ن,جه)', 'ആയിശ(റ): നബി(സ)യുടെ വിത്റിനെക്കുറിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: ഞങ്ങൾ നബി(സ)ക്ക് പല്ലു തേക്കാനും ശുദ്ധി വരുത്താനുമുള്ള സജ്ജീകരണങ്ങൾ ഒരുക്കിക്കൊടുക്കും. അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ നബിയെ ഉണർത്തും. അപ്പോൾ ദന്തശുദ്ധി വരുത്തി വുദു ചെയ്ത് ഒമ്പത് റക്അത് നിസ്കരിക്കും. അതിൽ എട്ടാമത്തെ റക്അതിലല്ലാതെ അവിടുന്ന് ഇരിക്കാറില്ല. അപ്പോൾ അല്ലാഹുവോട് പ്രാർത്ഥിക്കും, അല്ലാഹുവിനെ സ്മരിക്കുകയും അവനെ സ്തുതിക്കുകയും ചെയ്യും. സലാം വീട്ടാതെ വീണ്ടും എഴുന്നേറ്റ് ഒമ്പതാമത്തെ റക്അത് നിർവ്വഹിക്കും. പിന്നീട് ഇരുന്ന് അല്ലാഹുവിനെ സ്മരിക്കും. അവനെ സ്തുതിക്കുകയും അവനോട് പ്രാർത്ഥിക്കുകയും അവന്റെ പ്രവാചകനു വേണ്ടി സ്വലാത്ത് ചൊല്ലുകയും ചെയ്യും. പിന്നീട് ഞങ്ങൾ കേൾക്കെ സലാം വീട്ടും. സലാം വീട്ടിയശേഷം നബി(സ) ഇരുന്ന് രണ്ട് രക്അത്ത് നിസ്കരിക്കും. അങ്ങനെ പതിനൊന്ന് റക്അത്ത് പൂർത്തിയാക്കും. നബി(സ)ക്ക് പ്രായമാവുകയും തടി കൊഴുക്കുകയും ചെയ്തപ്പോൾ ഏഴാമത്തെ റക്അത്തു വിത്റ് ആക്കുകയും സലാം വീട്ടിയ ശേഷം രണ്ട് റക്അത്തു കൂടി നിസ്കരിക്കുകയും ചെയ്യും. (ന,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً فِيمَا بَيْنَ أَنْ يَفْرُغَ مِنْ صَلَاةِ الْعِشَاءِ إِلَى الْفَجْرِ بِاللَّيْلِ، سِوَى رَكْعَتَيِ الْفَجْرِ، وَيَسْجُدُ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً. (ن)', 'ആഇശ(റ): നബി(സ) ഇശാ നിസ്കാരശേഷം പ്രഭാത നിസ്കാരത്തിനു മുമ്പായി പതിനൊന്ന് റക്അത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. ഫജ്റിന്റെ രണ്ട് റക്അത് ഇതിൽ പെടുകയില്ല. നിങ്ങളിലൊരാൾ അൻപത് ആയത്ത് ഓതുന്നത്രയും ദീർഘമായി സുജൂദ് ചെയ്യുകയും ചെയ്യും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِسَبْعٍ، أَوْ بِخَمْسٍ، لَا يَفْصِلُ بَيْنَهُنَّ بِتَسْلِيمٍ وَلَا كَلَامٍ. (ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) ഏഴ് റക്അത്തോ അഞ്ച് റക്അത്തോ ആണ് വിത്റ് നിസ്കരിച്ചിരുന്നത്. അതിനിടയിൽ സലാം വീട്ടലോ മറ്റുവല്ല സംസാരമോ ഉണ്ടായിരുന്നില്ല. (ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَائِشَةَ وَمَيْمُونَةَ رَضِيَ اللهُ عَنْهُمَا: الْوِتْرُ سَبْعٌ، فَلَا أَقَلَّ مِنْ خَمْسٍ. (ن)', 'ആഇശ, മൈമൂന(റ): വിത്ർ നിസ്കാരം ഏഴ് റക്അത്താണ്. അഞ്ച് റക്അത്തിൽ കുറഞ്ഞ വിത്റ് ഇല്ല. (ന)', 'عَائِشَةَ وَمَيْمُونَةَ', 'ആഇശ, മൈമൂന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْها: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِخَمْسٍ، وَلَا يَجْلِسُ إِلَّا فِي آخِرِهِنَّ. (ن)', 'ആഇശ(റ): നബി(സ) അഞ്ച് റക്അത്ത് വിത്റ് നിർവ്വഹിച്ചിരുന്നു. അതിന്റെ അവസാനത്തിലല്ലാതെ നബി(സ) ഇരിക്കാറുണ്ടായിരുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْها قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَوْتَرَ بِتِسْعِ رَكَعَاتٍ، لَمْ يَقْعُدْ إِلَّا فِي الثَّامِنَةِ، فَيَحْمَدُ اللهَ، وَيَذْكُرُهُ، وَيَدْعُو، ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، ثُمَّ يُصَلِّي التَّاسِعَةَ، فَيَجْلِسُ فَيَذْكُرُ اللهَ عَزَّ وَجَلَّ وَيَدْعُو، ثُمَّ يُسَلِّمُ تَسْلِيمَةً يُسْمِعُنَا، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَلَمَّا كَبِرَ وَضَعُفَ، أَوْتَرَ بِسَبْعِ رَكَعَاتٍ، لَا يَقْعُدُ إِلَّا فِي السَّادِسَةِ، ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، فَيُصَلِّي السَّابِعَةَ، ثُمَّ يُسَلِّمُ تَسْلِيمَةً، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ. (ن)', 'ആഇശ(റ): നബി(സ) ഒമ്പത് റക്അത് വിത്റ് നിസ്കരിക്കുമ്പോൾ എട്ടാമത്തെ റക്അത്തിലല്ലാതെ ഇരിക്കാറുണ്ടായിരുന്നില്ല. അന്നേരം ഹംദും, ദിക്റും, പ്രാർത്ഥനയും നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. ശേഷം സലാം വീട്ടാതെ തന്നെ എഴുന്നേറ്റ് നിൽക്കും. ഒമ്പതാമത്തെ റക്അത് കൂടി നിസ്കരിക്കും. വീണ്ടും ഇരുന്ന് ദിക്റും ദുആയും നിർവ്വഹിക്കും. പിന്നീട് ഞങ്ങൾ കേൾക്കുമാറ് ഉച്ചത്തിൽ സലാം വീട്ടും. ശേഷം ഇരുന്നു കൊണ്ട് തന്നെ രണ്ട് റക്അത് നിസ്കരിക്കും. നബി(സ)ക്ക് പ്രായമാവുകയും ക്ഷീണം ബാധിക്കുകയും ചെയ്തപ്പോൾ ഏഴ് റക്അത് വിത്റ് നിസ്കരിച്ചു. ആറാമത്തേതിലല്ലാതെ ഇരുന്നില്ല. എന്നിട്ട് സലാം വീട്ടാതെ തന്നെ എഴുന്നേൽക്കും. ഏഴാമത്തെ റക്അത്ത് നിർവഹിച്ചശേഷം സലാം വീട്ടും. എന്നിട്ട് ഇരുന്നുകൊണ്ട് തന്നെ രണ്ട് റക്അത് നിസ്കരിക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْه وَسَلَّمَ يُوتِرُ بِثَلَاثٍ، يَقْرَأُ فِيهِنَّ بِتِسْعِ سُوَرٍ مِنَ الْمُفَصَّلِ، يَقْرَأُ في كُلِّ رَكْعَةٍ بِثَلَاثِ سُوَرٍ، آخِرُهُنَّ {قُلْ هُوَ اللهُ أَحَدٌ}. (ت)', 'അലി(റ): നബി(സ) മൂന്ന് റക്അത്താണ് വിത്റ് നിർവ്വഹിച്ചിരുന്നത്. ചെറിയ അദ്ധ്യായങ്ങളിൽ നിന്നും² ഒമ്പത് അദ്ധ്യായങ്ങളാണ് നബി(സ) അതിൽ പാരായണം ചെയ്തത്. ഓരോ റക്അത്തിലും മൂന്നെണ്ണം വീതം ഓതും. അവസാനം ''ഖുൽ ഹുവല്ലാഹു അഹദ്'' എന്ന അദ്ധ്യായം പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (തു)', 'عَلِيٍّ', 'അലി(റ)', '². മുഫസ്സ്വൽ: സൂറത്തു ഖാഫ് മുതലുള്ള സൂറത്തുകൾ. മറ്റൊരഭിപ്രായത്തിൽ: സൂറത്തു ഹുജറാത്ത് മുതൽ ഖുർആനിലെ അവസാന സൂറത്തുകൾ വരെ.', null, array['ت']::text[], array['തു']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْها قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِثَلَاثَ عَشْرَةَ رَكْعَةً، فَلَمَّا كَبِرَ وَضَعُفَ أَوْتَرَ بِسَبْعٍ. (ت,ن)', 'ഉമ്മുസലമ(റ): നബി(സ) പതിമൂന്ന് റക്അത്താണ് വിത്റ് നിർവ്വഹിച്ചിരുന്നത്. പ്രായാധിക്യവും അശക്തതയുമെത്തിയപ്പോൾ ഏഴ് റക്അത്ത് കൊണ്ട് വിത്റാക്കി. (തു,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْها قَالَتْ: كَانَتْ صَلَاةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ في شَيْءٍ مِنْهُنَّ إِلَّا في آخِرِهِنَّ، فَإِذَا أَذَّنَ الْمُؤَذِّنُ قَامَ، فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ. (ق,د,ت,ن)', 'ആഇശ(റ): നബി(സ)യുടെ രാത്രി നിസ്കാരം പതിമൂന്ന് റക്അത്തായിരുന്നു. അതിൽ അഞ്ച് റക്അത് കൊണ്ട് വിത്റാക്കും. അവയിൽ അവസാന റക്അത്തിലല്ലാതെ (തശഹുദിന് വേണ്ടി) ഇരിക്കാറുണ്ടായിരുന്നില്ല. (സുബ്ഹ്) ബാങ്ക് വിളിച്ചാൽ എഴുന്നേറ്റു നിന്ന് ലഘുവായ രണ്ട് റക്അത് നിർവ്വഹിക്കും. (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَعْدِ بْنِ هِشَامِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُمَا: لَمَّا أَنْ قَدِمَ عَلَيْنَا، أَخْبَرَنَا أَنَّهُ أَتَى ابْنَ عَبَّاسٍ، فَسَأَلَهُ عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: أَلَا أَدُلُّكَ أَوْ أَلَا أُنَبِّئُكَ بِأَعْلَمِ أَهْلِ الْأَرْضِ بِوِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قُلْتُ: مَنْ. قَالَ عَائِشَةُ، فَأَتَيْنَاهَا، فَسَلَّمْنَا عَلَيْهَا، وَدَخَلْنَا، فَسَأَلْنَاهَا، فَقُلْتُ: أَنْبِئِينِي عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللهُ عَزَّ وَجَلَّ مَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ، ثُمَّ يُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَقْعُدُ فِيهِنَّ إِلَّا فِي الثَّامِنَةِ، فَيَحْمَدُ اللهَ، وَيَذْكُرُهُ وَيَدْعُو، ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، ثُمَّ يُصَلِّي التَّاسِعَةَ، فَيَجْلِسُ فَيَحْمَدُ اللهَ وَيَذْكُرُهُ وَيَدْعُو، ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً، يَا بُنَيَّ، فَلَمَّا أَسَنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَخَذَ اللَّحْمَ، أَوْتَرَ بِسَبْعٍ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ مَا يُسَلِّمُ، فَتِلْكَ تِسْعًا، أَيْ بُنَيَّ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَحَبَّ أَنْ يُدَاوِمَ عَلَيْهَا. (ن)', 'സഅ്ദുബ്നു ഹിശാമുബ്നു ആമിർ(റ) ഞങ്ങളുടെ അടുക്കൽ വന്നപ്പോൾ ഞങ്ങളോടിപ്രകാരം പറഞ്ഞു: അദ്ദേഹം ഇബ്നുഅബ്ബാസി(റ)ന്റെ അടുത്തു ചെന്ന് നബി(സ)യുടെ വിത്റിനെക്കുറിച്ച് അന്വേഷിച്ചു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഭൂമിയിലെ ജനങ്ങളിൽ നബി(സ)യുടെ വിത്റിനെക്കുറിച്ച് ഏറ്റവും നന്നായറിയുന്ന ഒരാളെ ഞാൻ അറിയിച്ചു തരട്ടെയോ? ഞാൻ ചോദിച്ചു: അതാരാണ്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ആഇശ(റ)യാണത്. അങ്ങനെ ഞങ്ങൾ ആഇശ(റ)യുടെ അടുത്ത്ചെന്ന് അവർക്ക് സലാം പറഞ്ഞ് അകത്ത് പ്രവേശിച്ചു. ശേഷം മഹതിയോട് വിത്റിനെക്കുറിച്ച് ചോദിക്കാൻ തുടങ്ങി. ഞാൻ ചോദിച്ചു. നബി(സ)യുടെ വിത്റിനെക്കുറിച്ച് എനിക്ക് അറിയിച്ചു തന്നാലും. ആഇശ(റ) പറഞ്ഞു: ഞങ്ങൾ (ഭാര്യമാർ) നബി(സ)ക്ക് ദന്തശുദ്ധി വരുത്താനും അംഗശുദ്ധി വരുത്താനുമുള്ള ഒരുക്കങ്ങൾ ചെയ്തു കൊടുക്കും. രാത്രിയിൽ അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ നബി(സ)ഉണർന്ന് ദന്തശുദ്ധിയും അംഗശുദ്ധിയും വരുത്തി ഒമ്പത് റക്അത് നിസ്കരിക്കും. അതിൽ എട്ടാമത്തേതിലല്ലാതെ പ്രവാചകൻ(സ) ഇരിക്കാറില്ല. അങ്ങനെ ഹംദും ദിക്റും ദുആയും കഴിഞ്ഞ് സലാം വീട്ടാതെ തന്നെ എഴുന്നേറ്റ് നിന്ന് ഒമ്പതാമത്തെ റക്അത് നിർവ്വഹിക്കും. ശേഷം ഇരുന്ന് ഹംദും ദിക്റും ദുആയും നിർവ്വഹിക്കുകയും ഞങ്ങൾ കേൾക്കെ സലാം ചൊല്ലുകയും ചെയ്യും ശേഷം ഇരുന്നുകൊണ്ട് രണ്ട് റക്അത് നിർവ്വഹിക്കും. അങ്ങനെ അത് പതിനൊന്ന് പൂർത്തിയാക്കും. എന്റെ മോനെ, നബി(സ)ക്ക് പ്രായമാവുകയും ശരീരം കൊഴുക്കുകയും ചെയ്തപ്പോൾ ഏഴാമത്തെ റക്അത്തിനെ വിത്റാക്കി നിർവ്വഹിച്ചു. ശേഷം സലാം വീട്ടി ഇരുന്നുകൊണ്ട് രണ്ട് റക്അത് നിസ്കരിക്കും. അങ്ങനെ ഒമ്പത് പൂർത്തിയാക്കും. മോനേ, നബി(സ) ഒരു നിസ്കാരം നിർവഹിച്ചാൽ അത് പതിവാക്കുന്നത് അങ്ങേയറ്റം ഇഷ്ടപ്പെടുന്നു. (ന)', 'سَعْدِ بْنِ هِشَامِ بْنِ عَامِرٍ', 'സഅ്ദുബ്നു ഹിശാമുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْها قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِتِسْعِ رَكَعَاتٍ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَلَمَّا ضَعُفَ أَوْتَرَ بِسَبْعِ رَكَعَاتٍ، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ. (ن)', 'ആഇശ(റ): നബി(സ) ഒമ്പത് റക്അത്താണ് വിത്റ് ആയി നിർവഹിച്ചിരുന്നത്. പിന്നീട് ഇരുന്നു കൊണ്ട് രണ്ട് റക്അത് നിർവ്വഹിക്കും. വാർദ്ധക്യം ബാധിച്ചപ്പോൾ ഏഴ് റക്അത് വിത്റ് നിസ്കരിച്ചു. ശേഷം ഇരുന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْها: وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: كَانَ يُصَلِّي مِنَ اللَّيْلِ ثَمَانَ رَكَعَاتٍ، وَيُوتِرُ بِالتَّاسِعَةِ، وَيُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ. (ن)', 'ആഇശ(റ): നബി(സ)യുടെ (രാത്രി) നിസ്കാരത്തെക്കുറിച്ച് അവർ ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) രാത്രി എട്ടു റക്അത്താണ് നിസ്കരിച്ചത്. ഒമ്പതാമത്തേത് ഒറ്റയാക്കും. ശേഷം ഇരുന്നു കൊണ്ട് രണ്ട് റക്അത്ത് നിസ്കരിക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِثَلَاثٍ، يَقْرَأُ فِي الْأُولَى بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}، وَفِي الثَّانِيَةِ بِ{قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَفِي الثَّالِثَةِ بِ{قُلْ هُوَ اللهُ أَحَدٌ}. (ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മൂന്ന് റക്അത്താണ് വിത്റ് നിർവ്വഹിച്ചിരുന്നത്. ഒന്നാമത്തെതിൽ ''സബ്ബിഹിസ്മ......'', രണ്ടാമത്തെതിൽ ''ഖുൽയാ അയ്യുഹൽ കാഫിറൂൻ.........'', മൂന്നാമത്തെതിൽ ''ഖുൽ ഹുവല്ലാഹു.......'' എന്നീ സൂറത്തുകൾ അതിൽ പാരായണം ചെയ്യും. (ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ فَتَوَضَّأَ وَاسْتَاكَ، وَهُوَ يَقْرَأُ هَذِهِ الْآيَةَ حَتَّى فَرَغَ مِنْهَا {إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ} ثُمَّ صَلَّى رَكْعَتَيْنِ، ثُمَّ عَادَ فَنَامَ حَتَّى سَمِعْتُ نَفْخَهُ، ثُمَّ قَامَ فَتَوَضَّأَ وَاسْتَاكَ، ثُمَّ صَلَّى رَكْعَتَيْنِ، ثُمَّ نَامَ، ثُمَّ قَامَ فَتَوَضَّأَ وَاسْتَاكَ، وَصَلَّى رَكْعَتَيْنِ، وَأَوْتَرَ بِثَلَاثٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഞാൻ നബി(സ)യുടെ അടുത്തായിരിക്കെ (ഒരു രാത്രി), നബി(സ) എഴുനേറ്റ് വുളു ചെയ്യുകയും ദന്തശുദ്ധി വരുത്തുകയും (ശേഷം നിസ്കാരത്തിൽ) ''ഇന്ന ഫീ ഖൽഖിസ്സമാവാത്തി......'' (ആലുഇംറാൻ: 190) എന്നുതുടങ്ങുന്ന സൂക്തം തീരുന്നതുവരെ പാരായണം ചെയ്തു. പിന്നെ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ശേഷം തിരിച്ചുവന്ന് വീണ്ടും ഉറങ്ങി. ഞാൻ നബിയുടെ നിശ്വാസത്തിന്റെ (കൂർക്കം വലിക്കുന്ന) ശബ്ദം കേട്ടിരുന്നു. പിന്നെ എഴുന്നേറ്റ് വുളുചെയ്ത് ദന്തശുദ്ധി വരുത്തി രണ്ട് റക്അത് നിസ്കരിച്ച് വീണ്ടും ഉറങ്ങി, വീണ്ടും ഉണർന്ന് വുദു ചെയ്ത് ദന്തശുദ്ധി വരുത്തി രണ്ട് റക്അത് നിസ്കരിച്ചു. പിന്നെ മൂന്ന് റക്അത് നിർവ്വഹിച്ചുകൊണ്ട് വിത്റാക്കി. (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَامَ مِنَ اللَّيْلِ فَاسْتَنَّ، ثُمَّ صَلَّى رَكْعَتَيْنِ، ثُمَّ نَامَ، ثُمَّ قَامَ فَاسْتَنَّ، ثُمَّ تَوَضَّأَ فَصَلَّى رَكْعَتَيْنِ حَتَّى صَلَّى سِتًّا، ثُمَّ أَوْتَرَ بِثَلَاثٍ وَصَلَّى رَكْعَتَيْنِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രാത്രി ഉണർന്നു, ദന്തശുദ്ധീകരണം ചെയ്ത് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ ഉറങ്ങി, പിന്നെയും ഉണർന്നു. ദന്തശുദ്ധീകരണം വരുത്തി ശേഷം വുദു ചെയ്ത് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ആകെ ആറ് റക്അത്ത് നിസ്കരിച്ചു. ശേഷം മൂന്ന് റക്അത്ത് വിത്റും അതിന് ശേഷം രണ്ട് റക്അത്ത് സുന്നത്തും നിസ്കരിച്ചു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ، لَا أَدَعُهُنَّ فِي سَفَرٍ وَلَا حَضَرٍ، رَكْعَتَيِ الضُّحَى، وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنَ الشَّهْرِ، وَأَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ. (د,ن)', 'അബൂഹുറൈറ(റ): എന്റെ പ്രിയകൂട്ടുകാരൻ നബി(സ) എന്നോട് മൂന്ന് കാര്യങ്ങൾ ഉപദേശിച്ചു. അത് ഞാൻ നാട്ടിൽ ഉണ്ടായിരിക്കുമ്പോഴോ, യാത്രയിലോ ഉപേക്ഷിക്കുകയില്ല: ളുഹായുടെ രണ്ട് റക്അത്ത്, ഒരു മാസത്തിലെ മൂന്ന് ദിവസത്തെ നോമ്പ്, രാത്രിയിൽ വിത്റ് നിസ്കരിച്ചിട്ടല്ലാതെ ഞാൻ ഉറങ്ങരുത് എന്നിവയാണത്. (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ لَا أَدَعُهُنَّ لِشَيْءٍ أَوْصَانِي بِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَلَا أَنَامَ إِلَّا عَلَى وِتْرٍ وَبِسُبْحَةِ الضُّحَى فِي الْحَضَرِ وَالسَّفَرِ. (د)', 'അബുദ്ദർദാഅ്(റ): എന്റെ പ്രിയ സ്നേഹിതൻ (റസൂൽ) (സ) മൂന്ന് കാര്യങ്ങൾ എന്നോട് വസ്വിയ്യത്ത് ചെയ്തു. ഞാനവയെ ഒരു നിലക്കും ഉപേക്ഷിക്കുകയില്ല. എല്ലാ മാസവും മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കാനും, വിത്ർ നിസ്ക്കരിക്കാതെ ഉറങ്ങരുതെന്നും, യാത്രയിലും അല്ലാത്തപ്പോഴും ളുഹാ നിസ്കരിക്കാനും എന്നോട് പറഞ്ഞു. (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أُوتِرَ قَبْلَ أَنْ أَنَامَ. (ت)', 'അബൂഹുറൈറ(റ): ഉറങ്ങുന്നതിനു മുമ്പ് വിത്റ് നിസ്കരിക്കാൻ നബി(സ) എന്നോട് കൽപിച്ചു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ خَشِيَ مِنْكُمْ أَنْ لَا يَسْتَيْقِظَ مِنْ آخِرِ اللَّيْلِ، فَلْيُوتِرْ مِنْ أَوَّلِهِ، وَمَنْ طَمِعَ مِنْكُمْ أَنْ يَقُومَ مِنْ آخِرِ اللَّيْلِ، فَلْيُوتِرْ مِنْ آخِرِ اللَّيْلِ، فَإِنَّ قِرَاءَةَ الْقُرْآنِ فِي آخِرِ اللَّيْلِ مَحْضُورَةٌ، وَهِيَ أَفْضَلُ". (م,ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രാത്രിയുടെ അന്ത്യസമയത്ത് ഉണരില്ലെന്ന് ഭയപ്പെട്ടാൽ അതിന്റെ ആദ്യത്തിൽ തന്നെ വിത്റ് നിസ്കരിക്കട്ടെ. രാത്രിയുടെ അന്ത്യത്തിൽ എഴുന്നേൽക്കാനാഗ്രഹിക്കുന്നവൻ രാത്രിയുടെ അന്ത്യത്തിൽ വിത്റ് നിസ്കരിക്കട്ടെ. കാരണം, രാത്രിയുടെ അന്ത്യയാമത്തിലുള്ള ഖുർആൻ പാരായണം അനുഗ്രഹീത മലക്കുകളുടെ സാന്നിധ്യമുള്ളതാണ്. അതാണ് ശ്രേഷ്ഠകരം." (മു,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ سَالِمٍ رَضِيَ اللهُ عَنْهُ: عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي السَّفَرِ رَكْعَتَيْنِ، لَا يَزِيدُ عَلَيْهِمَا، وَكَانَ يَتَهَجَّدُ مِنَ اللَّيْلِ، قُلْتُ: وَكَانَ يُوتِرُ؟ قَالَ: نَعَمْ. (جه)', 'സാലിം(റ): ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി(സ) യാത്രയിൽ രണ്ട് റക്അത്താണ് നിസ്കരിച്ചിരുന്നത്. അതിനേക്കാൾ വർദ്ധിപ്പിച്ചിരുന്നില്ല. തിരുമേനി(സ) രാത്രിയിൽ തഹജ്ജുദ് നിസ്കാരം നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: നബി(സ) വിത്റ് നിർവ്വഹിച്ചിരുന്നോ? ഇബ്നുഉമർ(റ) പറഞ്ഞു: അതെ. (ജ)', 'سَالِمٍ', 'സാലിം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ ابْنِ عَبَّاسٍ وَابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَا: سَنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ السَّفَرِ رَكْعَتَيْنِ، وَهُمَا تَمَامٌ غَيْرُ قَصْرٍ، وَالْوِتْرُ فِي السَّفَرِ سُنَّةٌ. (جه)', 'ഇബ്നുഅബ്ബാസ്, ഇബ്നുഉമർ(റ): യാത്രയിലെ നിസ്കാരം രണ്ട് റക്അത്തായി നബി(സ) ചര്യയാക്കി. ആ രണ്ട് റക്അത്ത് പൂർണ്ണ നിസ്കാരമായിരുന്നു, ഖസ്ർ അല്ല. യാത്രയിൽ വിത്റ് നിസ്കരിക്കൽ നബി(സ)യുടെ ചര്യയിൽപ്പെട്ടതാണ്. (ജ)', 'ابْنِ عَبَّاسٍ وَابْنِ عُمَرَ', 'ഇബ്നുഅബ്ബാസ്, ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ سَعِيدِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَمْشِي مَعَ ابْنِ عُمَرَ فِي سَفَرٍ، فَتَخَلَّفْتُ عَنْهُ، فَقَالَ: أَيْنَ كُنْتَ؟ فَقُلْتُ: أَوْتَرْتُ، فَقَالَ: أَلَيْسَ لَكَ فِي رَسُولِ اللهِ أُسْوَةٌ؟ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ عَلَى رَاحِلَتِهِ. (ت,ن,جه)', 'സഈദുബ്നു യസാർ(റ): ഞാൻ ഒരു യാത്രയിൽ ഇബ്നുഉമറി(റ)നോടൊപ്പം നടക്കുകയായിരുന്നു. യാത്രക്കിടയിൽ ഞാൻ കുറച്ച് പിന്തി. അദ്ദേഹം ചോദിച്ചു: നീ എവിടെയായിരുന്നു? ഞാൻ പറഞ്ഞു: ഞാൻ വിത്റ് നിസ്കരിച്ചു. അദ്ദേഹം ചോദിച്ചു: നിനക്ക് നബി(സ)യിൽ ഉത്തമ മാതൃകയില്ലേ? റസൂൽ (സ) തന്റെ വാഹനപ്പുറത്ത് വിത്റ് നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (തു,ന,ജ)', 'سَعِيدِ بْنِ يَسَارٍ', 'സഈദുബ്നു യസാർ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ عَلَى رَاحِلَتِهِ. وَفِي إِسْنَادِهِ ضَعِيفٌ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) തന്റെ വാഹനപ്പുറത്തു വെച്ച് വിത്ർ നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ عَلَى الْبَعِيرِ. وَفِي رِوَايَةٍ: عَلَى الرَّاحِلَةِ. (خ,ت,ن)', 'ഇബ്നുഉമർ(റ): നബി (സ) (യാത്രാവേളയിൽ) ഒട്ടകപ്പുറത്തിരുന്ന് വിത്ർ നിസ്കരിക്കാറുണ്ടായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: വാഹനപ്പുറത്തിരുന്ന്. (ബു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=82), 1, 'وَفِي رِوَايَةٍ: عَلَى الرَّاحِلَةِ. (خ,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: വാഹനപ്പുറത്തിരുന്ന്. (ബു,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يُوتِرُ عَلَى بَعِيرِهِ، وَيَذْكُرُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ഒട്ടകത്തിന്മേൽ വിത്ർ നിസ്കരിക്കാറുണ്ടായിരുന്നു. എന്നിട്ട് പറയും: റസൂൽ(സ) ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ ابْنِ عُمَرَ: كَانَ يُوتِرُ عَلَى بَعِيرِهِ، وَيُذْكَرُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ഒട്ടകത്തിന്മേൽ വിത്റ് നിസ്കരിക്കാറുണ്ടായിരുന്നു. എന്നിട്ട് പറയും: റസൂൽ(സ) ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَادِرُوا الصُّبْحَ بِالْوِتْرِ". (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വിത്റ് നിസ്കാരം സുബ്ഹിക്കു മുൻപ് നിർവ്വഹിക്കുവിൻ." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوْتِرُوا قَبْلَ أَنْ تُصْبِحُوا". وَفِي رِوَايَةٍ: قَالَ: "أَوْتِرُوا قَبْلَ الْفَجْرِ". (ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സുബ്ഹ്ന് മുമ്പ് വിത്റ് നിർവ്വഹിക്കുക." മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഫജ്റിനു മുമ്പ് വിത്റ് നിർവ്വഹിക്കുവിൻ." (തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=86), 1, 'وَفِي رِوَايَةٍ: قَالَ: "أَوْتِرُوا قَبْلَ الْفَجْرِ". (ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഫജ്റിനു മുമ്പ് വിത്റ് നിർവ്വഹിക്കുവിൻ." (തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا سُئِلَتْ: كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ؟ قَالَتْ: مَا كَانَ يَزِيدُ فِي رَمَضَانَ وَلَا فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً: يُصَلِّي أَرْبَعَ رَكَعَاتٍ فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلَاثًا، فَقُلْتُ: يَا رَسُولَ اللهِ، تَنَامُ قَبْلَ أَنْ تُوتِرَ؟ قَالَ: "تَنَامُ عَيْنِي وَلَا يَنَامُ قَلْبِي". (ق,د,ت,ن)', 'ആഇശ(റ): റമദാനിൽ നബി(സ) യുടെ നിസ്കാരമെങ്ങിനെയായിരുന്നുവെന്ന് അവർ ചോദിക്കപ്പെട്ടു.അവർ പറഞ്ഞു: നബി(സ) റമദാനിലും അല്ലാത്ത സമയത്തും പതിനൊന്ന് റകഅത്തിൽ അധികരിപ്പിക്കാറില്ലായിരുന്നു. നാല് റകഅത്ത് നിസ്കരിക്കും. അതിന്റെ ദൈഘ്ല്യത്തേയും ഭംഗിയേയും സംബന്ധിച്ച് നീ ചോദിക്കരുത്. പിന്നെ നാലു റകഅത്ത് നിസ്കരിക്കും. അതിന്റെ ദൈർഘ്ല്യത്തെയും ഭംഗിയെയും കുറിച്ച് നീ ചോദിക്കരുത്. പിന്നീട് മൂന്ന് റകഅത്ത് നിസ്കരിക്കും. ആഇശ(റ) പറയുന്നു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, വിത്റ് നിസ്കരിക്കുന്നതിനു മുമ്പ് നിങ്ങൾ ഉറങ്ങുകയാണോ? പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം എന്റെ കണ്ണുകളേ ഉറങ്ങുന്നുള്ളൂ, ഹൃദയം ഉറങ്ങുന്നില്ല." (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا طَلَعَ الْفَجْرُ فَقَدْ ذَهَبَ كُلُّ صَلَاةِ اللَّيْلِ وَالْوِتْرِ، فَأَوْتِرُوا قَبْلَ طُلُوعِ الْفَجْرِ". (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "പ്രഭാതം ഉദിച്ചാൽ രാത്രിയിലെ എല്ലാ നിസ്കാര സമയവും തീർന്നു. വിത്റിന്റെയും. അതിനാൽ പ്രഭാതത്തിനു മുമ്പ് തന്നെ നിങ്ങൾ വിത്ർ നിസ്കരിക്കുവീൻ." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنْ جَوْفِ اللَّيْلِ، فَصَلَّى فِي الْمَسْجِدِ، فَصَلَّى رِجَالٌ بِصَلَاتِهِ، فَأَصْبَحَ النَّاسُ يَتَحَدَّثُونَ بِذَلِكَ، فَاجْتَمَعَ أَكْثَرُ مِنْهُمْ، فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي اللَّيْلَةِ الثَّانِيَةِ، فَصَلَّوْا بِصَلَاتِهِ فَأَصْبَحَ النَّاسُ يَذْكُرُونَ ذَلِكَ، فَكَثُرَ أَهْلُ الْمَسْجِدِ مِنَ اللَّيْلَةِ الثَّالِثَةِ، فَخَرَجَ فَصَلَّوْا بِصَلَاتِهِ، فَلَمَّا كَانَتِ اللَّيْلَةُ الرَّابِعَةُ عَجَزَ الْمَسْجِدُ عَنْ أَهْلِهِ، فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَطَفِقَ رِجَالٌ مِنْهُمْ يَقُولُونَ: الصَّلَاةَ، فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، حَتَّى خَرَجَ لِصَلَاةِ الْفَجْرِ، فَلَمَّا قَضَى الْفَجْرَ أَقْبَلَ عَلَى النَّاسِ، ثُمَّ تَشَهَّدَ، فَقَالَ: "أَمَّا بَعْدُ، فَإِنَّهُ لَمْ يَخْفَ عَلَيَّ شَأْنُكُمُ اللَّيْلَةَ، وَلَكِنِّي خَشِيتُ أَنْ تُفْرَضَ عَلَيْكُمْ صَلَاةُ اللَّيْلِ، فَتَعْجِزُوا عَنْهَا". وَفِي رِوَايَةٍ: وَذَلِكَ فِي رَمَضَانَ. (ق)', 'ആഇശ(റ): നബി(സ) രാത്രിയുടെ അർദ്ധയാമത്തിൽ പള്ളിയിൽ പോയി നിസ്കരിച്ചു. കുറച്ചാളുകളും നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. പ്രഭാതമായപ്പോൾ ആളുകൾ (രാത്രിയിലെ നിസ്കാരത്തെക്കുറിച്ച്) പരസ്പരം പറയാൻ തുടങ്ങി. പിറ്റേദിവസം അധികമാളുകൾ വന്നു. നബി(സ) രണ്ടാം ദിവസം രാത്രി പുറപ്പെടുകയും (പള്ളിയിൽ വെച്ച്) നിസ്കരിക്കുകയും ചെയ്തു. രാവിലെ ജനങ്ങൾ അതേക്കുറിച്ച് പരസ്പരം പറയാൻ തുടങ്ങി. മൂന്നാം ദിവസം പള്ളിയിൽ ആളുകൾ വർദ്ധിച്ചു. പ്രവാചകൻ രാത്രിയിൽ പള്ളിയിൽ വരികയും അവർ അവിടത്തോടൊപ്പം നമസ്കരിക്കുകയും ചെയ്തു. നാലാം ദിവസം രാത്രി പള്ളി ആളുകളെ ഉൾക്കൊള്ളാൻ കഴിയാത്തത്രയും ജനങ്ങൾ ഒരുമിച്ചു കൂടി. എന്നാൽ അന്ന് നബി(സ) അവരിലേക്ക് പോയില്ല. ചിലർ വന്ന് നിസ്കാരത്തെക്കുറിച്ച് ഓർമിപ്പിച്ചു. എന്നാൽ പ്രഭാത നിസ്കാര സമയമായപ്പോഴല്ലാതെ നബി(സ) പുറത്തു വന്നില്ല. ഫജ്റ് നിസ്കരിച്ചപ്പോൾ ജനങ്ങളെ അഭിമുഖീകരിച്ച് ശഹാദത്ത് ചൊല്ലിയശേഷം നബി(സ) പറഞ്ഞു: "കഴിഞ്ഞ രാത്രി നിങ്ങളുടെ കാര്യം ഞാൻ മറന്നതല്ല. രാത്രി നിസ്കാരം നിർബന്ധമാവുകയും നിങ്ങൾക്കത് നിർവ്വഹിക്കാൻ കഴിയാതെ വരികയും ചെയ്തേക്കുമോ എന്ന് ഭയന്നതിനാലാണ് ഞാൻ വരാതിരുന്നത്." മറ്റൊരു റിപ്പോർട്ടിൽ: അത് റമദാനിലായിരുന്നു. (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=89), 1, 'وَفِي رِوَايَةٍ: وَذَلِكَ فِي رَمَضَانَ. (ق)', 'മറ്റൊരു നിവേദനിൽ: അത് റമദാനിലായിരുന്നു. (ബു,മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُرَغِّبُ فِي قِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَهُمْ بِعَزِيمَةٍ، ثُمَّ يَقُولُ: "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". فَتُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْأَمْرُ عَلَى ذَلِكَ، ثُمَّ كَانَ الْأَمْرُ عَلَى ذَلِكَ فِي خِلَافَةِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ وَصَدْرًا مِنْ خِلَافَةِ عُمَرَ رَضِيَ اللهُ عَنْهُ. (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) റമദാനിലെ നിസ്കാരത്തെക്കുറിച്ച് നിർബന്ധിക്കാത്ത രീതിയിൽ പ്രേരിപ്പിക്കാറുണ്ടായിരുന്നു. ശേഷം ഇപ്രകാരം പറയും: "ആരെങ്കിലും വിശ്വാസത്തോടെയും പ്രതിഫലമാഗ്രഹിച്ചും റമദാനിലെ രാത്രി നിസ്കാരം നിർവ്വഹിച്ചാൽ അവന്റെ മുൻകഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." നബി(സ)യുടെ മരണംവരെ ഇപ്രകാരമായിരുന്നു. അബൂബക്കർ(റ)വിന്റെ ഭരണ കാലത്തും ഉമർ(റ)വിന്റെ ഭരണത്തിന്റെ തുടക്കത്തിലും ഇപ്രകാരം തന്നെയായിരുന്നു. (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَامَ رَمَضَانَ وَقَامَهُ إِيمَانًا وَاحْتِسَابًا، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും റമദാനിൽ വിശ്വാസത്തോടെയും പ്രതിഫലം കാംക്ഷിച്ചു കൊണ്ടും നോമ്പനുഷ്ഠിക്കുകയും, രാത്രി നിസ്കരിക്കുകയും ചെയ്താൽ അവന്റെ മുൻകഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്". (തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: صُمْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَمَضَانَ، فَلَمْ يَقُمْ بِنَا شَيْئًا مِنْهُ حَتَّى بَقِيَ سَبْعُ لَيَالٍ، فَقَامَ بِنَا لَيْلَةَ السَّابِعَةِ، حَتَّى مَضَى نَحْوٌ مِنْ ثُلُثِ اللَّيْلِ، ثُمَّ كَانَتِ اللَّيْلَةُ السَّادِسَةُ الَّتِي تَلِيهَا فَلَمْ يَقُمْهَا، حَتَّى كَانَتِ الْخَامِسَةُ الَّتِي تَلِيهَا، ثُمَّ قَامَ بِنَا حَتَّى مَضَى نَحْوٌ مِنْ شَطْرِ اللَّيْلِ، فَقُلْتُ: يَا رَسُولَ اللهِ، لَوْ نَفَّلْتَنَا بَقِيَّةَ لَيْلَتِنَا هَذِهِ؟ فَقَالَ: "إِنَّهُ مَنْ قَامَ مَعَ الْإِمَامِ حَتَّى يَنْصَرِفَ، فَإِنَّهُ يَعْدِلُ قِيَامَ لَيْلَةٍ". ثُمَّ كَانَتِ الرَّابِعَةُ الَّتِي تَلِيهَا فَلَمْ يَقُمْهَا، حَتَّى كَانَتِ الثَّالِثَةُ الَّتِي تَلِيهَا، قَالَ: فَجَمَعَ نِسَاءَهُ وَأَهْلَهُ، وَاجْتَمَعَ النَّاسُ، قَالَ: فَقَامَ بِنَا حَتَّى خَشِينَا أَنْ يَفُوتَنَا الْفَلَاحُ، قِيلَ: وَمَا الْفَلَاحُ؟ قَالَ: السُّحُورُ، قَالَ: ثُمَّ لَمْ يَقُمْ بِنَا شَيْئًا مِنْ بَقِيَّةِ الشَّهْرِ. (د,ت,ن,جه)', 'അബൂദർറ്(റ): ഞങ്ങൾ റമദാനിൽ നബി(സ)യോടൊപ്പം നോമ്പനുഷ്ഠിക്കുമ്പോൾ റമദാനിലെ അവസാനത്തെ ഏഴ് രാവുകൾ വരെ അവിടുന്ന് ഞങ്ങൾക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകിയില്ല. ആ ഏഴാം രാവിൽ (ഏഴ് രാവ് ശേഷിച്ചിരിക്കെ) രാത്രിയുടെ മൂന്നിലൊന്ന് സമയം ഞങ്ങൾക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകി. അടുത്ത രാവിൽ നബി(സ) ഞങ്ങളുടെ കൂടെ നിസ്കരിച്ചില്ല. അടുത്ത രാവിൽ (അതായത് അഞ്ച് രാവുകൾ ശേഷിക്കുന്ന അവസരത്തിൽ.) രാത്രിയുടെ പകുതി വരെ ഞങ്ങളുടെ കൂടെ നിസ്കരിച്ചു. നബി(സ)യോട് ഞാൻ പറഞ്ഞു: നബിയെ, ഈ രാത്രിയുടെ ശേഷിക്കുന്ന ഭാഗവും അവിടുന്ന് നിസ്കാരത്തിന് നേതൃത്വം നൽകിയാലും.! നബി(സ) പറഞ്ഞു: "ഇമാം പിരിഞ്ഞു പോവുന്നതു വരെ ഒരാൾ ഇമാമിനോടൊപ്പം നിസ്കരിച്ചാൽ അവൻ ഒരു രാത്രി മുഴുവൻ നിസ്കരിച്ചതു പോലെയാണ്." അടുത്ത രാവിൽ (നാലാം രാവിൽ) നബി(സ) ഞങ്ങൾക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകിയില്ല. മൂന്നാം രാവിൽ (മൂന്ന് രാവ് ശേഷിച്ചിരിക്കെ) നബി(സ) തന്റെ ഭാര്യമാരെയും വീട്ടുകാരെയും, ഒരുമിച്ചു കൂട്ടുകയും ജനങ്ങൾ ഒരുമിച്ചു കൂടുകയും ചെയ്തു. അങ്ങനെ നബി(സ) ഞങ്ങൾക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകി. അബൂദർറ്(റ) പറയുന്നു: നിസ്കാരം ദീർഘിച്ചപ്പോൾ ഫലാഹ് നഷ്ടപ്പെടുമോ എന്ന് ഞങ്ങൾ ഭയന്നു. ''ഫലാഹ്'' കൊണ്ടുള്ള ഉദ്ദേശ്യമെന്തെന്ന് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത്താഴം. ശേഷം അബൂദർറ്(റ) പറയുന്നു: അതിന് ശേഷം ആ മാസത്തിൽ ഒരു നിസ്കാരത്തിനും നബി(സ) നേതൃത്വം നൽകിയിട്ടില്ല. (ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ شَهْرَ رَمَضَانَ، فَقَالَ: "شَهْرٌ كَتَبَ اللهُ عَلَيْكُمْ صِيَامَهُ، وَسَنَنْتُ لَكُمْ قِيَامَهُ، فَمَنْ صَامَهُ وَقَامَهُ إِيمَانًا وَاحْتِسَابًا، خَرَجَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". (ت,ن,جه)', 'അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ): നബി(സ) റമദാനിനെക്കുറിച്ച് സ്മരിക്കുകയും ഇപ്രകാരം അരുളുകയും ചെയ്തു: "അല്ലാഹു നിങ്ങൾക്ക് നോമ്പ് നിർബന്ധമാക്കുകയും രാത്രി നിസ്കരിക്കൽ ഞാൻ നിങ്ങൾക്ക് ചര്യയായി കാണിച്ചു തരികയും ചെയ്ത മാസമാണത്. ഒരാൾ ഈമാനോടെയും പ്രതിഫലം ആഗ്രഹിച്ചു കൊണ്ടും നോമ്പെടുക്കുകയും നിസ്കരിക്കുകയും ചെയ്താൽ അവൻ തന്റെ മാതാവ് പ്രസവിച്ച ദിവസത്തിലേതുപോലെ കുറ്റ വിമുക്തനായി തീരും." (തു,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു. അല്ലാഹുവിൽ വിശ്വസിച്ചും അവന്റെ പ്രീതി കാംക്ഷിച്ചും റമളാനിലെ രാത്രികളിൽ നമസ്കരിക്കുന്നവന്റെ കഴിഞ്ഞു പോയ ദോഷങ്ങൾ പൊറുക്കപ്പെടും. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 567, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي الْمَسْجِدِ ذَاتَ لَيْلَةٍ، وَصَلَّى بِصَلَاتِهِ نَاسٌ، ثُمَّ صَلَّى مِنَ الْقَابِلَةِ وَكَثُرَ النَّاسُ، ثُمَّ اجْتَمَعُوا مِنَ اللَّيْلَةِ الثَّالِثَةِ أَوِ الرَّابِعَةِ، فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَصْبَحَ قَالَ: "قَدْ رَأَيْتُ الَّذِي صَنَعْتُمْ، فَلَمْ يَمْنَعْنِي مِنَ الْخُرُوجِ إِلَيْكُمْ إِلَّا أَنِّي خَشِيتُ أَنْ يُفْرَضَ عَلَيْكُمْ". وَذَلِكَ فِي رَمَضَانَ. (ن)', 'ആഇശ(റ)യിൽ നിന്ന് നിവേദനം: ഒരു രാത്രിയിൽ പ്രവാചകർ(സ) പള്ളിയിൽ നമസ്കരിച്ചു, കൂടെ ഒട്ടേറെ ജനങ്ങളുമുണ്ടായിരുന്നു. അടുത്ത ദിവസവും അവിടുന്ന് നിസ്കരിക്കുകയും ജനങ്ങൾ വർദ്ധിക്കുകയും ചെയ്തു. മൂന്നാം ദിവസം അല്ലെങ്കിൽ നാലാം ദിവസം ജനങ്ങൾ പള്ളിയിൽ തിങ്ങി കൂടിയെങ്കിലും നബി(സ) വന്നില്ല, പ്രഭാതമായപ്പോൾ നബി(സ) വന്ന് പറഞ്ഞു: "ഇന്നലെ നിങ്ങളുടെ പ്രവർത്തനങ്ങൾ ഞാൻ കണ്ടു. നിങ്ങൾക്ക് അവ നിർബന്ധമാക്കപ്പെടുമെന്ന് ഭയപ്പെട്ടത് കൊണ്ട് മാത്രമാണ് ഞാൻ വരാതിരുന്നത്." അത് റമദാൻ മാസത്തിലായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قُمْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي شَهْرِ رَمَضَانَ لَيْلَةَ ثَلَاثٍ وَعِشْرِينَ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ، ثُمَّ قُمْنَا مَعَهُ لَيْلَةَ خَمْسٍ وَعِشْرِينَ إِلَى نِصْفِ اللَّيْلِ، ثُمَّ قُمْنَا مَعَهُ لَيْلَةَ سَبْعٍ وَعِشْرِينَ حَتَّى ظَنَنَّا أَنْ لَا نُدْرِكَ الْفَلَاحَ، وَكَانُوا يُسَمُّونَهُ السُّحُورَ. (ن)', 'നുഅ്മാനുബ്നുബശീർ(റ): റമദാൻ മാസത്തിലെ ഇരുപ്തിമൂന്നാം രാവിന്റെ മൂന്നിലൊന്ന് വരെ ഞങ്ങൾ നബി(സ)യോട് കൂടെ നമസ്കരിച്ചു. ഇരുപത്തിയഞ്ചിലെ അർദ്ധരാത്രി വരെയും ഇരുപത്തിയേഴാം രാവിൽ പുലർച്ച വരെയും നിസ്കരിക്കുകയും ചെയ്തു. അത്താഴം നഷ്ടപ്പെടുമെന്ന് വരെ ഞങ്ങൾ ഭയപ്പെട്ടിരുന്നു. അത്താഴത്തിന് ''സുസൂർ'' എന്നാണ് അവർ പറയാറുള്ളത്. (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നുബശീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّاسُ يُصَلُّونَ فِي الْمَسْجِدِ فِي رَمَضَانَ أَوْزَاعًا، فَأَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَضَرَبْتُ لَهُ حَصِيرًا فَصَلَّى عَلَيْهِ بِهَذِهِ الْقِصَّةِ، قَالَتْ فِيهِ: قَالَ – تَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّهَا النَّاسُ، أَمَا وَاللهِ مَا بِتُّ لَيْلَتِي هَذِهِ بِحَمْدِ اللهِ غَافِلًا، وَلَا خَفِيَ عَلَيَّ مَكَانُكُمْ". (د)', 'ആഇശ(റ): റമദാനിൽ ജനങ്ങൾ അവിടവിടെയായിട്ടായിരുന്നു പള്ളിയിൽ നിസ്കരിച്ചിരുന്നത്. നബി(സ) എന്നോട് വരാൻ പറഞ്ഞു. ഞാൻ ഒരു പായ വിരിച്ചു കൊടുത്തു. നബി(സ) അതിൽ നിസ്കരിച്ചു. ഇപ്രകാരമാണ് കഥ. മഹതി പറയുന്നു: നബി(സ) പറഞ്ഞു: "ജനങ്ങളെ, ഈ രാത്രിയിൽ അല്ലാഹുവിനെ സ്തുതിക്കുന്നതിൽ ഞാൻ അശ്രദ്ധനായിട്ടില്ല. നിങ്ങളുടെ ഓരോരുത്തരുടെയും സ്ഥാനം എനിക്കു അവ്യക്തവുമല്ല." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَإِذَا أُنَاسٌ فِي رَمَضَانَ يُصَلُّونَ فِي نَاحِيَةِ الْمَسْجِدِ، فَقَالَ: "مَا هَؤُلَاءِ". فَقِيلَ: هَؤُلَاءِ نَاسٌ مَعَهُمْ قُرْآنٌ، وَأُبَيُّ بْنُ كَعْبٍ يُصَلِّي وَهُمْ يُصَلُّونَ بِصَلَاتِهِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَابُوا، وَنِعْمَ مَا صَنَعُوا" قَالَ أَبُو دَاوُدَ: لَيْسَ هَذَا الْحَدِيثُ بِالْقَوِيِّ. (د)', 'അബൂഹുറൈറ(റ): ഒരിക്കൽ നബി(സ) പള്ളിയിൽ വന്നപ്പോൾ ഒരു കൂട്ടമാളുകൾ പള്ളിയുടെ ഒരു ഭാഗത്ത് നിസ്കരിക്കുന്നു. നബി(സ) ചോദിച്ചു: "ഇവർ ആരാണ്?" അപ്പോൾ പറയപ്പെട്ടു: ഇവർ ഖുർആൻ കൂടെയുള്ള വിഭാഗമാണ്, ഉബയ്യുബ് നു കഅ്ബ് നിസ്കരിക്കുന്നു. അവരും അപ്രകാരം നിസ്കരിക്കുന്നു. നബി(സ) പറഞ്ഞു: അവർ സത്യത്തെ എത്തിച്ചിരിക്കുന്നു. അവർ ചെയ്തത് എന്തു നല്ല കാര്യം!." (അബൂദാവൂദ് പറയുന്നു: ഈ ഹദീസ് ശക്തമല്ലാത്തതാണ്.) (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي وَائِلٍ رَضِيَ اللهُ عَنْهُ قَالَ: غَدَوْنَا عَلَى عَبْدِ اللهِ ابْنِ مَسْعُودٍ يَوْمًا بَعْدَ مَا صَلَّيْنَا الْغَدَاةَ، فَسَلَّمْنَا بِالْبَابِ، فَأَذِنَ لَنَا، قَالَ: فَمَكَثْنَا بِالْبَابِ هُنَيَّةً، قَالَ: فَخَرَجَتِ الْجَارِيَةُ فَقَالَتْ: أَلَا تَدْخُلُونَ؟ فَدَخَلْنَا، فَإِذَا هُوَ جَالِسٌ يُسَبِّحُ، فَقَالَ: مَا مَنَعَكُمْ أَنْ تَدْخُلُوا، وَقَدْ أُذِنَ لَكُمْ؟ فَقُلْنَا: لَا، إِلَّا أَنَّا ظَنَنَّا أَنَّ بَعْضَ أَهْلِ الْبَيْتِ نَائِمٌ، قَالَ: ظَنَنْتُمْ بِآلِ ابْنِ أُمِّ عَبْدٍ غَفْلَةً، قَالَ: ثُمَّ أَقْبَلَ يُسَبِّحُ حَتَّى ظَنَّ أَنَّ الشَّمْسَ قَدْ طَلَعَتْ، فَقَالَ: يَا جَارِيَةُ، انْظُرِي هَلْ طَلَعَتْ؟ قَالَ: فَنَظَرَتْ، فَإِذَا هِيَ لَمْ تَطْلُعْ، فَأَقْبَلَ يُسَبِّحُ حَتَّى إِذَا ظَنَّ أَنَّ الشَّمْسَ قَدْ طَلَعَتْ، قَالَ: يَا جَارِيَةُ، انْظُرِي هَلْ طَلَعَتْ، فَنَظَرَتْ، فَإِذَا هِيَ قَدْ طَلَعَتْ، فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَقَالَنَا يَوْمَنَا هَذَا، فَقَالَ مَهْدِيٌّ: وَأَحْسِبُهُ قَالَ: وَلَمْ يُهْلِكْنَا بِذُنُوبِنَا، قَالَ: فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: قَرَأْتُ الْمُفَصَّلَ الْبَارِحَةَ كُلَّهُ، قَالَ: فَقَالَ عَبْدُ اللهِ: هَذًّا كَهَذِّ الشِّعْرِ، إِنَّا لَقَدْ سَمِعْنَا الْقَرَائِنَ، وَإِنِّي لَأَحْفَظُ الْقَرَائِنَ الَّتِي كَانَ يَقْرَؤُهُنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَمَانِيَةَ عَشَرَ مِنَ الْمُفَصَّلِ، وَسُورَتَيْنِ مِنْ آلِ حم. (ق,د,ن)', 'അബൂവാഇൽ(റ): ഒരിക്കൽ പ്രഭാത നിസ്കാരശേഷം ഞങ്ങൾ അബ്ദുല്ലാഹിബ്നു മസ്ഊദി(റ)ന്റെ അടുത്തേക്ക് പോയി. വാതിലിനടുത്തു വെച്ച് ഞങ്ങൾ സലാം ചൊല്ലി. അദ്ദേഹം ഞങ്ങൾക്ക് പ്രവേശനാനുമതി നൽകി. ഞങ്ങൾ വാതിലിന്നരികിൽ അൽപനേരം നിന്നു. ഒരു സ്ത്രീ (ആ വീട്ടിലെ) വന്ന് ഞങ്ങളോട് ചോദിച്ചു: നിങ്ങൾ അകത്തേക്കു വരുന്നില്ലേ? അപ്പോൾ ഞങ്ങൾ അകത്തു കടന്നു. അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) ഇരുന്ന് തസ്ബീഹ് ചൊല്ലുകയായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾക്ക് സമ്മതം ലഭിച്ചിരിക്കെ എന്തുകൊണ്ട് നിങ്ങൾ അകത്തേക്കു വന്നില്ല? ഞങ്ങൾ പറഞ്ഞു. ഒന്നുമില്ല, ഈ വീട്ടിലെ ചിലർ ഉറങ്ങുകയാണെന്നു കരുതിയതുകൊണ്ടാണ് ഞങ്ങൾ അകത്തേക്കു വരാതിരുന്നത്. അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഉമ്മുഅബ്ദിന്റെ കുടുംബക്കാരെ കുറിച്ച് നിങ്ങൾ അശ്രദ്ധ ഭാവിച്ചിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അദ്ദേഹം വീണ്ടും മുന്നോട്ടിരുന്ന് തസ്ബീഹ് ചൊല്ലിത്തുടങ്ങി. സൂര്യൻ ഉദിച്ചു എന്നു തോന്നിയപ്പോൾ അടിമസ്ത്രീയെ വിളിച്ചു പറഞ്ഞു: സൂര്യൻ ഉദിച്ചിട്ടുണ്ടോ എന്നു നോക്കുക. നിവേദകൻ പറയുന്നു. അടിമസ്ത്രീ നോക്കിയപ്പോൾ സൂര്യൻ ഉദിച്ചിരുന്നില്ല. അദ്ദേഹം വീണ്ടും മുന്നിട്ടിരുന്ന് തസ്ബീഹ് ചൊല്ലിത്തുടങ്ങി. സൂര്യൻ ഉദിച്ചുവെന്ന് തോന്നിയപ്പോൾ അടിമ സ്ത്രീയെ വിളിച്ച് പറഞ്ഞു: സൂര്യൻ ഉദിച്ചോയെന്നു നോക്കുക. അടിമ സ്ത്രീ നോക്കിയപ്പോൾ സൂര്യൻ ഉദിച്ചിരുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അൽഹംദുലില്ലാഹില്ലദീ അഖാലനാ യൗമനാ ഹാദാ'' (ഇന്ന് ഞങ്ങളെ ഉണർത്തിയ അല്ലാഹുവിന് സർവ്വ സ്തുതിയും) മഹ്ദി പറയുന്നു. അദ്ദേഹം ''വലം യുഹ്ലിക്നാ ബി ദുനൂബിനാ'' (ഞങ്ങളുടെ പാപം കാരണം ഞങ്ങളെ നശിപ്പിക്കാത്ത അല്ലാഹുവിന് സർവ്വസ്തുതിയും) എന്നുകൂടി പറഞ്ഞുവെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. നിവേദകൻ പറയുന്നു: കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: ഇന്നലെ രാത്രി ഞാൻ മുഫസ്സ്വൽ മുഴുവനായി ഓതിയിട്ടുണ്ട്. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: കവിത ചെല്ലുന്നപോലെ വേഗത്തിലാണോ ചൊല്ലിയത്? ഞങ്ങൾ അൽ ഖറാഇൻ³ എന്നു കേട്ടിട്ടുണ്ട്. റസൂൽ(സ) ഓതാറുണ്ടായിരുന്ന ഖറാഇൻ എനിക്കു മനഃപാഠമുണ്ട്. മുഫസ്സ്വലിൽ നിന്നുള്ള പതിനെട്ട് സൂറത്തും, ''ഹാമീം'' ഗണത്തിലെ രണ്ടു സൂറത്തുകളുമായിരുന്നു അത്. (ബു,മു,ദ,ന)', 'أَبِي وَائِلٍ', 'അബൂവാഇൽ(റ)', '³. ദൈർഘ്യം കൊണ്ടോ അർത്ഥം കൊണ്ടോ സദൃശമായ സൂറത്തുകൾ.', null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ الْمُنْتَشِرِ بْنِ اجْدَعَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ فِي مَسْجِدِ عَمْرِو بْنِ شُرَحْبِيلَ، فَأُقِيمَتِ الصَّلَاةُ، فَجَعَلُوا يَنْتَظِرُونَهُ، فَجَاءَ فَقَالَ: إِنِّي كُنْتُ أُوتِرُ، قَالَ: وَسُئِلَ عَبْدُ اللهِ: هَلْ بَعْدَ الْأَذَانِ وِتْرٌ؟ قَالَ: نَعَمْ، وَبَعْدَ الْإِقَامَةِ. وَحُدِّثَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَامَ عَنِ الصَّلَاةِ حَتَّى طَلَعَتِ الشَّمْسُ ثُمَّ صَلَّى. (ن)', 'മുൻതശിറുബ്നുൽ അജ്ദഅ്(റ): അദ്ദേഹം അംറുബ്നു ശുറഹ്ബീലിന്റെ പള്ളിയിലായിരിക്കെ നിസ്കാരത്തിന്ന് ഇഖാമത്ത് കൊടുക്കപ്പെട്ടു. അപ്പോൾ അവർ അംറ്(റ)വിനെ പ്രതീക്ഷിച്ചിരുന്നു. അദ്ദേഹം വന്നു പറഞ്ഞു: ഞാൻ വിത്റ് നിർവ്വഹിക്കുകയായിരുന്നു. അപ്പോൾ അബ്ദുല്ല(റ)വിനോട് ചോദ്ക്കപ്പെട്ടു: ബാങ്കിനു ശേഷം വിത്റുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഇഖാമത്തിനു ശേഷവും വിത്റ് നിർവ്വഹിക്കാം. നബി(സ) ഒരിക്കൽ (വിത്റ്) നിസ്കരിക്കാതെ ഉറങ്ങുകയും പ്രഭാതമായപ്പോൾ നിസ്കരിക്കുകയും ചെയ്തു എന്ന് റിപ്പോർട്ട് ചെയ്യപ്പെട്ടിട്ടുണ്ട്. (ന)', 'الْمُنْتَشِرِ بْنِ اجْدَعَ', 'മുൻതശിറുബ്നുൽ അജ്ദഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْوِتْرُ حَقٌّ، فَمَنْ لَمْ يُوتِرْ فَلَيْسَ مِنَّا، الْوِتْرُ حَقٌّ، فَمَنْ لَمْ يُوتِرْ فَلَيْسَ مِنَّا، الْوِتْرُ حَقٌّ، فَمَنْ لَمْ يُوتِرْ فَلَيْسَ مِنَّا". (ن)', 'ബുറൈദ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "വിത്റ് ബാധ്യതയാണ്, വിത്റ് നിർവ്വഹിക്കാത്തവൻ നമ്മിൽപെട്ടവനല്ല. വിത്റ് ബാധ്യതയാണ്. അത് നിർവ്വഹിക്കാത്തവൻ നമ്മിൽ പെട്ടവനല്ല. വിത്റ് ബാധ്യതയാണ്. അത് നിർവ്വഹിക്കാത്തവൻ നമ്മിൽപെട്ടവനല്ല." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "خَمْسُ صَلَوَاتٍ كَتَبَهُنَّ اللهُ عَلَى الْعِبَادِ، فَمَنْ جَاءَ بِهِنَّ لَمْ يُضَيِّعْ مِنْهُنَّ شَيْئًا اسْتِخْفَافًا بِحَقِّهِنَّ، كَانَ لَهُ عِنْدَ اللهِ عَهْدٌ أَنْ يُدْخِلَهُ الْجَنَّةَ، وَمَنْ لَمْ يَأْتِ بِهِنَّ فَلَيْسَ لَهُ عِنْدَ اللهِ عَهْدٌ، إِنْ شَاءَ عَذَّبَهُ، وَإِنْ شَاءَ أَدْخَلَهُ الْجَنَّةَ". (د)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അഞ്ചുനേരത്തെ നിസ്കാരം അല്ലാഹു തന്റെ അടിമകൾക്ക് നിർബന്ധമാക്കിയിരിക്കുന്നു. ആരെങ്കിലും അത് (ഒന്നും നഷ്ടപ്പെടുത്താതെ അർഹിക്കും പ്രകാരം) നിർവ്വഹിച്ചാൽ അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുമെന്ന് അല്ലാഹുവിൽ നിന്ന് കരാറുണ്ട്. ആർ അത് നിർവ്വഹിക്കുന്നില്ലയോ അവന് അല്ലാഹുവിൽ നിന്നുള്ള യാതൊരു വാഗ്ദാനവും ഇല്ല. അല്ലാഹു ഉദ്ദേശിച്ചാൽ അവനെ ശിക്ഷിക്കും അല്ലാഹു ഉദ്ദേശിച്ചാൽ അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കും." (ദ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَلَّى بَعْدَ الْمَغْرِبِ سِتَّ رَكَعَاتٍ لَمْ يَتَكَلَّمْ بَيْنَهُنَّ بِسُوءٍ عُدِلْنَ لَهُ بِعِبَادَةِ ثِنْتَيْ عَشْرَةَ سَنَةً. (جه)', 'അബൂഹുറ്റൈ(റ)നിവേദനം : നബി(സ) പറഞ്ഞു: ആരെങ്കിലും മഗ്രിബിനുശേഷം ആറു റക്അത്ത് നമസ്കരിക്കുകയും അതിനിടയിൽ മോശമായതൊന്നും സംസാരിക്കാതിരിക്കുകയും ചെയ്താൽ ആ നമസ്കാരത്തെ പന്ത്രണ്ട് വർഷം ഇബാദത്തുകൾ നിർവ്വഹിച്ചതിനോട് തുല്യമാക്കും. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറ്റൈ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ خَارِجَةَ بْنِ حُذَافَةَ الْعَدَوِيِّ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ قَدْ أَمَدَّكُمْ بِصَلَاةٍ، وَهِيَ خَيْرٌ لَكُمْ مِنْ حُمْرِ النَّعَمِ، وَهِيَ الْوِتْرُ فَجَعَلَهَا لَكُمْ فِيمَا بَيْنَ الْعِشَاءِ إِلَى طُلُوعِ الْفَجْرِ". (د,ت,جه)', 'ഖാരിജതുബ്നു ഹുദാഫതുൽ അദവി(റ): നബി(സ) ഞങ്ങളുടെ അടുത്തു വന്ന് പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്ക് ഒരു നിസ്കാരം കനിഞ്ഞേകിയിരിക്കുന്നു. ചുവന്ന ഒട്ടകത്തേക്കാൾ നിങ്ങൾക്ക് നല്ലത് അതാണ്. അത് വിത്ർ നിസ്കാരമാണ്. ഇശാഇനും ഉദയത്തിനും ഇടയിലാണതിന്റെ സമയം." (ദ,തു,ജ)', 'خَارِجَةَ بْنِ حُذَافَةَ الْعَدَوِيِّ قَالَ', 'ഖാരിജതുബ്നു ഹുദാഫതുൽ അദവി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِثَلَاثِ رَكَعَاتٍ، كَانَ يَقْرَأُ فِي الْأُولَى بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}، وَفِي الثَّانِيَةِ بِ{قُلْ يَا أَيُّهَا الْكَافِرُونَ}، وَفِي الثَّالِثَةِ بِ{قُلْ هُوَ اللهُ أَحَدٌ} وَيَقْنُتُ قَبْلَ الرُّكُوعِ، فَإِذَا فَرَغَ قَالَ عِنْدَ فَرَاغِهِ: "سُبْحَانَ الْمَلِكِ الْقُدُّوسِ". ثَلَاثَ مَرَّاتٍ، يُطِيلُ فِي آخِرِهِنَّ. وَفِي رِوَايَةٍ: وَلَا يُسَلِّمُ إِلَّا فِي آخِرِهِنَّ. (ن)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) മൂന്ന് റക്അത്താണ് വിത്റ് നിർവ്വഹിച്ചിരുന്നത് ഒന്നാമത്തേതിൽ ''സബ്ബിഹിസ്മ......'', രണ്ടാമത്തേതിൽ ''ഖുൽയാഅയ്യുഹൽകാഫിറൂൻ, മൂന്നാമത്തേതിൽ ''ഖുൽഹുവല്ലാഹു അഹദ്...'' എന്നിവ പാരായണം ചെയ്യുമായിരുന്നു. റുകൂഇനു മുമ്പായി ഖുനൂത്തും നിർവ്വഹിക്കും. നിസ്കാരത്തിൽ നിന്നും വിരമിച്ച ഉടനെ ''സുബ്ഹാനൽ മലിക്കിൽ ഖുദ്ദൂസ്'' എന്ന് മൂന്ന് പ്രാവശ്യം പറയുകയും മൂന്നാമത്തേത് നീട്ടിപ്പറയുകയും ചെയ്യും. മറ്റൊരു റിപ്പോർട്ടിൽ: മൂന്ന് റക്അതും നിർവ്വഹിച്ചശേഷമല്ലാതെ സലാം വീട്ടിയിരുന്നില്ല. (ന)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=105), 1, 'وَفِي رِوَايَةٍ: وَلَا يُسَلِّمُ إِلَّا فِي آخِرِهِنَّ. (ن)', 'മറ്റൊരു നിവേദനിൽ: മൂന്ന് റക്അതും നിർവ്വഹിച്ചശേഷമല്ലാതെ സലാം വീട്ടിയിരുന്നില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: وَاللهِ لَأُقَرِّبَنَّ لَكُمْ صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَكَانَ أَبُو هُرَيْرَةَ يَقْنُتُ فِي الرَّكْعَةِ الْآخِرَةِ مِنْ صَلَاةِ الظُّهْرِ، وَصَلَاةِ الْعِشَاءِ الْآخِرَةِ، وَصَلَاةِ الصُّبْحِ، فَيَدْعُو لِلْمُؤْمِنِينَ وَيَلْعَنُ الْكَافِرِينَ. (ق,د,ن)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവാണെ, നബി(സ)യുടെ നിസ്കാരം നിങ്ങൾക്ക് ഞാൻ അടുത്തറിയിച്ചുതരും. അങ്ങനെ അബൂഹുറൈറ(റ) ളുഹ്റിന്റെയും ഇശാഇന്റെയും സുബ്ഹിന്റെയും അവസാന റക്അത്തിൽ ഖുനൂത് ഓതിയിരുന്നു. വിശ്വാസികൾക്കായി പ്രാർത്ഥിക്കുകയും സത്യനിഷേധികളെ ശപിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا مُتَتَابِعًا فِي الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ وَصَلَاةِ الصُّبْحِ، فِي دُبُرِ كُلِّ صَلَاةٍ إِذَا قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". مِنَ الرَّكْعَةِ الْآخِرَةِ، يَدْعُو عَلَى أَحْيَاءٍ مِنْ بَنِي سُلَيْمٍ: عَلَى رِعْلٍ وَذَكْوَانَ وَعُصَيَّةَ، وَيُؤَمِّنُ مَنْ خَلْفَهُ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരുമാസം തുടർച്ചയായി ളുഹ്റിലും അസ്റിലും മഗ്രിബിലും ഇശാഇലും സുബ്ഹിലും അവസാന റക്അത്തിൽ ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നു പറഞ്ഞശേഷം ഖുനൂത് ഓതുകയും ബനൂസുലൈമിലെ ചില ഗോത്രങ്ങൾക്കും രിഅ്ല്, ദക്വാൻ, ഉസ്വയ്യ, ഗോത്രക്കാർക്കും എതിരെ പ്രാർത്ഥിക്കുകയും. പിന്നിലുള്ളവർ ''ആമീൻ'' എന്ന് പറയുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سُئِلَ: هَلْ قَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الصُّبْحِ؟ فَقَالَ: نَعَمْ، فَقِيلَ لَهُ: قَبْلَ الرُّكُوعِ أَوْ بَعْدَ الرُّكُوعِ؟ قَالَ: بَعْدَ الرُّكُوعِ بِيَسِيرٍ. (ق,د,ن,جه)', 'അനസ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: നബി(സ) സുബ്ഹി നിസ്കാരത്തിൽ ഖുനൂത് ഓതിയിരുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: അതെ, അപ്പോൾ ചോദിക്കപ്പെട്ടു: റുകൂഇനു മുമ്പോ ശേഷമോ? അദ്ദേഹം പറഞ്ഞു: റുകൂഇന്റെ അല്പം ശേഷം. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَنَتَ شَهْرًا، ثُمَّ تَرَكَهُ. (م,د)', 'അനസ്(റ): നബി(സ) ഒരുമാസം ഖുനൂത് ഓതി. പിന്നെ നിർത്തി. (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ قَالَ: حَدَّثَنِي مَنْ صَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْغَدَاةِ، فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرَّكْعَةِ الثَّانِيَةِ قَامَ هُنَيَّةً. (د,ن)', 'മുഹമ്മദുബ്നു സീരീൻ(റ): നബി(സ)യോടൊപ്പം പ്രഭാത നിസ്കാരം നിർവ്വഹിച്ച ഒരാൾ എന്നോട് ഇപ്രകാരം പറഞ്ഞു: പ്രവാചകൻ(സ) രണ്ടാം റക്അത്തിൽ നിന്നെഴുന്നേറ്റപ്പോൾ അൽപസമയം നിന്നു. (ദ,ന)', 'مُحَمَّدِ بْنِ سِيرِينَ قَالَ', 'മുഹമ്മദുബ്നു സീരീൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ عَنِ الْقُنُوتِ فِي صَلَاةِ الصُّبْحِ؟ فَقَالَ: كُنَّا نَقْنُتُ قَبْلَ الرُّكُوعِ وَبَعْدَهُ. (خ,جه)', 'അനസുബ്നു മാലിക്(റ): സുബ്ഹി നിസ്കാരത്തിലെ ഖുനൂത്തിനെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ റുകൂഇന് മുമ്പും ശേഷവും ഖുനൂത്ത് ഓതാറുണ്ടായിരുന്നു. (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سُئِلَ عَنِ الْقُنُوتِ فَقَالَ: قَدْ كَانَ الْقُنُوتُ، فَقِيلَ لَهُ: قَبْلَ الرُّكُوعِ أَوْ بَعْدَهُ قَالَ: قَبْلَهُ، قِيلَ: فَإِنَّ فُلَانًا أَخْبَرَنِي عَنْكَ أَنَّكَ قُلْتَ بَعْدَ الرُّكُوعِ، فَقَالَ: كَذَبَ، إِنَّمَا قَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الرُّكُوعِ شَهْرًا أُرَاهُ، كَانَ بَعَثَ قَوْمًا يُقَالُ لَهُمُ الْقُرَّاءُ زُهَاءَ سَبْعِينَ رَجُلًا إِلَى قَوْمٍ مِنَ الْمُشْرِكِينَ دُونَ أُولَئِكَ، وَكَانَ بَيْنَهُمْ وَبَيْنَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَهْدٌ، فَقَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا يَدْعُو عَلَيْهِمْ. وَفِي رِوَايَةٍ عَنْهُ قَالَ: قَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا يَدْعُو عَلَى رِعْلٍ وَذَكْوَانَ. (خ)', 'അനസുബ്നു മാലിക്(റ): ഖുനൂത്തിനെപ്പറ്റി അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഖുനൂത്ത് ഉണ്ടായിരുന്നു. അപ്പോൾ ചോദിക്കപ്പെട്ടു: റുകൂഇനു മുമ്പോ ശേഷമോ?. അദ്ദേഹം പറഞ്ഞു: മുമ്പ്. റുകൂഇനു ശേഷമാണെന്നു താങ്കൾ പറഞ്ഞതായി എന്നോടൊരാൾ പറഞ്ഞിട്ടുണ്ടല്ലോ എന്നു ചോദിക്കപ്പെട്ടപ്പോൾ അനസ്(റ) പറഞ്ഞു: അയാൾ കളവു പറയുകയാണ്, നബി(സ) ഒരു മാസം റുകൂഇനു ശേഷം ഖുനൂത്ത് ഓതി എന്നാണ് ഞാൻ കണ്ടത്. നബി(സ) ഖുർആൻ പാരായണം ചെയ്യുന്നവർ എന്നു വിളിക്കപ്പെടുന്ന എഴുപതോളം ആളുകളെ ഒരു കൂട്ടം അവിശ്വാസികളിലേക്ക് നിയോഗിച്ചു. അവരല്ലാത്ത മറ്റൊരു വിഭാഗം അവിശ്വാസികളുമുണ്ടായിരുന്നു. അവർക്കും നബി(സ)ക്കുമിടയിൽ ഒരു സമാധാനസന്ധി നിലവിലുണ്ടായിരുന്നു. (എന്നിട്ടുകൂടി അവരെ (ഖുർറാഇനെ) ആ ബഹുദൈവ വിശ്വാസികൾ കൊന്നു കളഞ്ഞു. അപ്പോൾ നബി(സ) അവർക്കെതിരായി പ്രാർത്ഥിച്ച് ഒരുമാസം ഖുനൂത്ത് ഓതി. ഒരു റിപ്പോർട്ടിൽ: റഅ്ൽ, ദക്വാൻ ഗോത്രക്കാർക്കെതിരായി പ്രാർത്ഥിച്ചുകൊണ്ട് നബി(സ) ഒരുമാസം ഖുനൂത്ത് ഓതി. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=112), 1, 'وَفِي رِوَايَةٍ عَنْهُ قَالَ: قَنَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا يَدْعُو عَلَى رِعْلٍ وَذَكْوَانَ. (خ)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الْقُنُوتُ فِي الْمَغْرِبِ وَالْفَجْرِ. (خ)', 'അനസ്(റ): മഗ്രിബ് നിസ്കാരത്തിലും സുബ്ഹ് നിസ്കാരത്തിലും നബി(സ) ഖുനൂത് ഓതിയിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ دُعَائِهِ إِلَّا عِنْدَ الِاسْتِسْقَاءِ. (ن)', 'അനസുബ്നു മാലിക്(റ): മഴ തേടിയുള്ള നിസ്കാരത്തിലൊഴികെ മറ്റു പ്രാർത്ഥനകളിലൊന്നും നബി(സ) തന്റെ കൈ (കൂടുതലായി) ഉയർത്തിയിരുന്നില്ല. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 572, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَعَوْتَ اللَّهَ فَادْعُ بِبَاطِنِ كَفَّيْكَ، وَلَا تَدْعُ بِظُهُورِهِمَا، فَإِذَا فَرَغْتَ فَامْسَحْ بِهِمَا وَجْهَكَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുമ്പോൾ നിന്റെ ഉള്ളം കൈകൾ (ഉയർത്തി) കൊണ്ട് പ്രാർത്ഥിക്കുക. പുറം കൈകൾ കൊണ്ട് പ്രാർത്ഥിക്കരുത്. പ്രാർത്ഥനക്കു ശേഷം അവ കൊണ്ട് മുഖം തടവുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سُئِلَ: أَقَنَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصُّبْحِ؟ قَالَ: نَعَمْ، فَقِيلَ لَهُ: أَوَقَنَتَ قَبْلَ الرُّكُوعِ؟ قَالَ: بَعْدَ الرُّكُوعِ يَسِيرًا. (ق,د,ن,جه)', 'അനസ്(റ): അദ്ദേഹം ചോദിക്കപ്പെട്ടു: സുബ്ഹ് നിസ്കാരത്തിൽ നബി(സ) ഖുനൂത്ത് ഓതിയിരുന്നോ? അനസ്(റ) പറഞ്ഞു: അതെ, അപ്പോൾ ചോദിക്കപ്പെട്ടു: റുകൂഇനു മുമ്പായിരുന്നോ ഖുനൂത്ത് ഓതിയത്? അദ്ദേഹം പറഞ്ഞു: റുകൂഇനു ശേഷം ലഘുവായാണ് നിർവ്വഹിച്ചിരുന്നത്. (ബു,മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْنُتُ فِي صَلَاةِ الصُّبْحِ، وَصَلَاةِ الْمَغْرِبِ. (د,ت,ن)', 'ബർറാഅ്(റ): സുബ്ഹിക്കും മഗ്രിബിനും നബി(സ) ഖുനൂത് ഓതിയിരുന്നു. (ദ,തു,ന)', 'الْبَرَاءِ', 'ബർറാഅ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَنَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْعَتَمَةِ شَهْرًا، يَقُولُ فِي قُنُوتِهِ: "اللَّهُمَّ نَجِّ الْوَلِيدَ بْنَ الْوَلِيدِ، اللَّهُمَّ نَجِّ سَلَمَةَ بْنَ هِشَامٍ، اللَّهُمَّ نَجِّ الْمُسْتَضْعَفِينَ مِنَ الْمُؤْمِنِينَ، اللَّهُمَّ اشْدُدْ وَطْأَتَكَ عَلَى مُضَرَ، اللَّهُمَّ اجْعَلْهَا عَلَيْهِمْ سِنِينَ كَسِنِي يُوسُفَ". قَالَ أَبُو هُرَيْرَةَ: وَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَلَمْ يَدْعُ لَهُمْ، فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "وَمَا تَرَاهُمْ قَدْ قَدِمُوا". (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) ഇശാ നിസ്കാരത്തിൽ ഒരുമാസം ഖുനൂത്ത് ഓതി. ഖുനൂതിൽ ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവെ, വലീദുബ്നുൽ വലീദിനെ രക്ഷിക്കേണമേ, സലമതുബ്നു ഹിശാമിനെ രക്ഷിക്കേണമേ, വിശ്വാസികളായ ബലഹീനരെ രക്ഷിക്കേണമേ, മുളർ ഗോത്രത്തിൽ നീ ബുദ്ധിമുട്ട് ഇറക്കേണമേ. അവർക്ക് യൂസുഫ് നബിയുടെ കാലത്തുണ്ടായ പോലുള്ള വരൾച്ച നൽകേണമേ." അബൂഹുറൈറ പറയുന്നു: ഒരു ദിവസം നബി(സ) അവർക്കു വേണ്ടി പ്രാർത്ഥിക്കാതെയായി. ഞാൻ അതിനെക്കുറിച്ച് നബിയോട് പറഞ്ഞപ്പോൾ എന്നോട് പറഞ്ഞു: "അവർ മടങ്ങി വന്നിരിക്കുന്നു." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ طَارِقِ بْنِ أَشْيَمَ الْأَشْجَعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَقْنُتْ، وَصَلَّيْتُ خَلْفَ أَبِي بَكْرٍ فَلَمْ يَقْنُتْ، وَصَلَّيْتُ خَلْفَ عُمَرَ فَلَمْ يَقْنُتْ، وَصَلَّيْتُ خَلْفَ عُثْمَانَ فَلَمْ يَقْنُتْ، وَصَلَّيْتُ خَلْفَ عَلِيٍّ فَلَمْ يَقْنُتْ. ثُمَّ قَالَ: يَا بُنَيَّ إِنَّهَا بِدْعَةٌ. (ن)', 'ത്വാരിഖുബ്നു അശീമിൽ അശ്ജഈ(റ): ഞാൻ പ്രവാചകർ(സ)യുടെ പിന്നിൽ നിസ്കരിച്ചിട്ടുണ്ട്. അവിടുന്ന് ഖുനൂത്ത് ഓതിയിട്ടില്ല. അബൂബക്കറി(റ)ന്റെ പിന്നിലും നിസ്കരിച്ചിട്ടുണ്ട് അദ്ദേഹവും ഖുനൂത്ത് ഓതിയിട്ടില്ല. ഉമറി(റ)ന്റെ കൂടെയും ഞാൻ നിസ്കരിച്ചു. അദ്ദേഹവും ഖുനൂത്ത് ഓതിയിട്ടില്ല. ഉസ്മാനി(റ)ന്റെ കൂടെയും ഞാൻ നിസ്കരിച്ചു. അദ്ദേഹവും ഖുനൂത്ത് ഓതിയിട്ടില്ല. അലി(റ)യുടെ പിന്നിലും ഞാൻ നിസ്കരിച്ചു. അദ്ദേഹവും ഖുനൂത്ത് ഓതിയിട്ടില്ല. ശേഷം അദ്ദേഹം (ത്വാരിഖ്) പറഞ്ഞു: എന്റെ പ്രിയമകനേ! ഇതു മതത്തിൽ പുതുതായി കടത്തിക്കൂട്ടിയ സമ്പ്രദായമാണ്. (ന)', 'طَارِقِ بْنِ أَشْيَمَ الْأَشْجَعِيِّ', 'ത്വാരിഖുബ്നു അശീമിൽ അശ്ജഈ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ يَفْرُغُ مِنْ صَلَاةِ الْفَجْرِ مِنَ الْقِرَاءَةِ وَيُكَبِّرُ، وَيَرْفَعُ رَأْسَهُ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ". ثُمَّ يَقُولُ وَهُوَ قَائِمٌ: "اللَّهُمَّ أَنْجِ الْوَلِيدَ بْنَ الْوَلِيدِ وَسَلَمَةَ بْنَ هِشَامٍ وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ، وَالْمُسْتَضْعَفِينَ مِنَ الْمُؤْمِنِينَ، اللَّهُمَّ اشْدُدْ وَطْأَتَكَ عَلَى مُضَرَ، وَاجْعَلْهَا عَلَيْهِمْ كَسِنِي يُوسُفَ، اللَّهُمَّ الْعَنْ لِحْيَانَ وَرِعْلًا وَذَكْوَانَ وَعُصَيَّةَ، عَصَتِ اللَّهَ وَرَسُولَهُ". ثُمَّ بَلَغَنَا أَنَّهُ تَرَكَ ذَلِكَ لَمَّا أُنْزِلَتْ: {لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ} [آل عمران: ١٢٨]. (م)', 'അബൂഹുറൈറ(റ): നബി(സ) സുബ്ഹ് നിസ്കാത്തിൽ ഖുർആൻ പാരായണം ചെയ്തു കഴിഞ്ഞ് തക്ബീർ ചൊല്ലിക്കൊണ്ട്(റുകൂഇൽ നിന്ന്) തല ഉയർത്തുമ്പോൾ ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' (അല്ലാഹുവിനെ സ്തുതിച്ചവനു വേണ്ടി അവൻ കേൾക്കട്ടെ), ''റബ്ബനാ വലകൽ ഹംദു'' (ഞങ്ങളുടെ നാഥാ! സർവ്വ സ്തുതിയും നിനക്കാകുന്നു) എന്ന് പറയുകയും അനന്തരം നിന്നു കൊണ്ട് "അല്ലാഹുവേ! വലീദിന്റെ മകൻ വലീദിനെയും ഹിശാമിന്റെ മകൻ സലമത്തിനെയും, അബൂറബീഅയുടെ മകൻ അയ്യാശിനെയും, സത്യവിശ്വാസികളിലെ ദുർബ്ബലരേയും നീ രക്ഷിക്കണേ, അല്ലാഹുവേ, മുള്ർ ഗോത്രക്കാരെ നീ കഠിനമായി ശിക്ഷിക്കേണമേ! ആ ശിക്ഷ യൂസുഫിന്റെ കാലത്തുണ്ടായ ക്ഷാമത്തെപ്പോലെയാക്കേണമേ! അല്ലാഹുവേ ലിഹ്യാൻ, രിഅ്ൽ, ദക്വാൻ, ഉസയ്യ തുടങ്ങിയ അല്ലാഹിവനെയും അവന്റെ ദൂതനെയും ധിക്കരിച്ച ഗോത്രക്കാരെ നീ ശപിക്കേണമേ!" എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (നിവേദകൻ തുടന്ന് പറയുന്നു) പിന്നീട് ''കാര്യത്തിന്റെ തീരുമാനത്തിൽ നിനക്ക് യാതൊരു അവകാശവുമില്ല. അവൻ( അല്ലാഹു) ഒന്നുകിൽ അവരുടെ പശ്ചാതാപം സ്വീകരിച്ചേക്കാം. അല്ലെങ്കിൽ അവൻ അവർക്ക് ശിക്ഷ നൽകിയേക്കാം തീർച്ചയായും അവർ അക്രമികൾ തന്നെയാകുന്നു'' (ആലുഇംറാൻ:129) എന്ന ആയത്ത് അവതരിക്കപ്പെട്ടപ്പോൾ തിരുമേനി(സ) ആ പ്രാർത്ഥന ഉപേക്ഷിച്ചു എന്നു ഞങ്ങൾക്ക് വിവരം ലഭിച്ചിട്ടുണ്ട്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'آل عمران: ١٢٨', null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ سَعْدِ بْنِ هِشَامِ بْنِ عَامِرٍ الْأَنْصَارِيِّ: أَنَّهُ لَقِيَ ابْنَ عَبَّاسٍ فَسَأَلَهُ عَنِ الْوِتْرِ. فَقَالَ: أَلَا أُنَبِّئُكَ بِأَعْلَمِ أَهْلِ الْأَرْضِ بِوِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ نَعَمْ قَالَ: عَائِشَةُ، ائْتِهَا فَسَلْهَا ثُمَّ ارْجِعْ إِلَيَّ فَأَخْبِرْنِي بِرَدِّهَا عَلَيْكَ فَأَتَيْتُ عَلَى حَكِيمِ بْنِ أَفْلَحَ فَاسْتَلْحَقْتُهُ إِلَيْهَا فَقَالَ: مَا أَنَا بِقَارِبِهَا إِنِّي نَهَيْتُهَا أَنْ تَقُولَ فِي هَاتَيْنِ الشِّيعَتَيْنِ شَيْئًا فَأَبَتْ فِيهَا إِلَّا مُضِيًّا فَأَقْسَمْتُ عَلَيْهِ، فَجَاءَ مَعِي فَدَخَلَ عَلَيْهَا فَقَالَتْ لِحَكِيمٍ: مَنْ هَذَا مَعَكَ، قُلْتُ: سَعْدُ بْنُ هِشَامٍ، قَالَتْ: مَنْ هِشَامٌ؟ قُلْتُ ابْنُ عَامِرٍ، فَتَرَحَّمَتْ عَلَيْهِ وَقَالَتْ: نِعْمَ الْمَرْءُ كَانَ عَامِرًا قَالَ: يَا أُمَّ الْمُؤْمِنِينَ أَنْبِئِينِي عَنْ خُلُقِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: أَلَيْسَ تَقْرَأُ الْقُرْآنَ قَالَ: قُلْتُ: بَلَى، قَالَتْ: فَإِنَّ خُلُقَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقُرْآنُ، فَهَمَمْتُ أَنْ أَقُومَ، فَبَدَا لِي قِيَامُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: يَا أُمَّ الْمُؤْمِنِينَ أَنْبِئِينِي عَنْ قِيَامِ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: أَلَيْسَ تَقْرَأُ هَذِهِ السُّورَةَ يَا أَيُّهَا الْمُزَّمِّلُ. قُلْتُ: بَلَى، قَالَتْ: فَإِنَّ اللَّهَ عَزَّ وَجَلَّ افْتَرَضَ قِيَامَ اللَّيْلِ فِي أَوَّلِ هَذِهِ السُّورَةِ فَقَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ حَوْلًا، حَتَّى انْتَفَخَتْ أَقْدَامُهُمْ وَأَمْسَكَ اللَّهُ عَزَّ وَجَلَّ خَاتِمَتَهَا اثْنَيْ عَشَرَ شَهْرًا ثُمَّ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ التَّخْفِيفَ فِي آخِرِ هَذِهِ السُّورَةِ فَصَارَ قِيَامُ اللَّيْلِ تَطَوُّعًا بَعْدَ أَنْ كَانَ فَرِيضَةً، فَهَمَمْتُ أَنْ أَقُومَ. فَبَدَا لِي وِتْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ أَنْبِئِينِي عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ فَيَبْعَثُهُ اللَّهُ عَزَّ وَجَلَّ لِمَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ فَيَتَسَوَّكُ وَيَتَوَضَّأُ وَيُصَلِّي ثَمَانِيَ رَكَعَاتٍ لَا يَجْلِسُ فِيهِنَّ إِلَّا عِنْدَ الثَّامِنَةِ يَجْلِسُ فَيَذْكُرُ اللَّهَ عَزَّ وَجَلَّ وَيَدْعُو ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ مَا يُسَلِّمُ ثُمَّ يُصَلِّي رَكْعَةً فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً يَا بُنَيَّ فَلَمَّا أَسَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَخَذَ اللَّحْمَ أَوْتَرَ بِسَبْعٍ وَصَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ مَا سَلَّمَ فَتِلْكَ تِسْعُ رَكَعَاتٍ يَا بُنَيَّ وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَحَبَّ أَنْ يَدُومَ عَلَيْهَا وَكَانَ إِذَا شَغَلَهُ عَنْ قِيَامِ اللَّيْلِ نَوْمٌ أَوْ مَرَضٌ أَوْ وَجَعٌ صَلَّى مِنَ النَّهَارِ اثْنَتَيْ عَشْرَةَ رَكْعَةً وَلَا أَعْلَمُ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ وَلَا قَامَ لَيْلَةً كَامِلَةً حَتَّى الصَّبَاحِ وَلَا صَامَ شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ، فَأَتَيْتُ ابْنَ عَبَّاسٍ فَحَدَّثْتُهُ بِحَدِيثِهَا فَقَالَ صَدَقَتْ أَمَا إِنِّي لَوْ كُنْتُ أَدْخُلُ عَلَيْهَا لَأَتَيْتُهَا حَتَّى تُشَافِهَنِي مُشَافَهَةً. (ن)', 'സഅദുബ്നു ഹിശാം(റ): അദ്ദേഹം ഇബ്നുഅബ്ബാസി(റ) നെ കണ്ടുമുട്ടിയപ്പോൾ വിത്റിനെക്കുറിച്ച് അന്വേഷിച്ചു. അദ്ദേഹം പറഞ്ഞു: പ്രവാചകന്റെ(സ) വിത്റിനെക്കുറിച്ച് ഭൂമിയിൽ ഏറ്റവും നന്നായി അറിയുന്ന ഒരാളെ ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞു തരട്ടയോ. ഞാൻ പറഞ്ഞു: അതെ, അദ്ദേഹം പറഞ്ഞു: അത് ആയിശ(റ) യാണ്. മഹതിയുടെ അടുത്ത് ചെന്ന് അന്വേഷിക്കുക. എന്നിട്ട് തിരിച്ചു വന്ന് മഹതിയുടെ മറുപടി എന്നെയും അറിയിക്കുക. അങ്ങനെ ഞാൻ ആയിശയുടെ അടുത്തേക്ക് എന്റെ കൂടെ പോരാൻ ഹക്കീമുബ്നു അഫ്ലഹിനെ ചെന്നു കണ്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഈയിടെയായി മഹതിയെ കാണാറേ ഇല്ല. രണ്ട് പക്ഷത്തും ചേർന്ന് ഒന്നും പറയരുതെന്ന് ഞാൻ മഹതിയോട് അപേക്ഷിച്ചിട്ടുണ്ടായിരുന്നു. മഹതി അത് നിരാകരിക്കുകയും തന്റെ നിലപാടുമായി മുമ്പോട്ട് പോകാൻ തന്നെ തീരുമാനിക്കുകയും ചെയ്തു. സഅദ് പറയുന്നു: ഞാൻ തറപ്പിച്ചു പറഞ്ഞപ്പോൾ ഹകീം കൂടെ വരികയും ആയിശ(റ)യുടെ അടുത്ത് ചെന്നു അനുവാദം ചോദിക്കുകയും ചെയ്തു. അനുവാദം കിട്ടിയപ്പോൾ ഞങ്ങൽ അകത്തു കടന്നു. അപ്പോൾ ആയിശ(റ) ഹകീമിനോട് ചോദിച്ചു?: നിങ്ങളുടെ കൂടെ ആരാണ്? ഞാൻ പറഞ്ഞു: സഅദുബ്നു ഹിശാം. ആയിശ(റ) ചോദിച്ചു. ആരാണ് ഹിശാം. ആമീറിന്റെ മകൻ എന്ന് ഞാൻ മറുപടി പറഞ്ഞു. അപ്പോൾ ആയിശ(റ) അദ്ദേഹത്തെ പ്രശംസിച്ചു കൊണ്ട് പറഞ്ഞു. ആമീർ എത്ര നല്ലവരായിരുന്നു. സഅദ് ചോദിച്ചു: ഉമ്മുൽ മുഅ്മിനീൻ, നബി(സ) യുടെ സ്വഭാവം വിവരിച്ചു തന്നാലും. ആയിശ(റ) ചോദിച്ചു. താങ്കൾ ഖുർആൻ ഓതാറില്ലേ? ഞാൻ പറഞ്ഞു: അതെ. മഹതി പറഞ്ഞു: നബിയുടെ സ്വഭാവം ഖുർആനായിരുന്നു. ഞാൻ എഴുന്നേറ്റു പോരാനൊരുങ്ങി. അപ്പോഴാണ് റസൂലിന്റെ(സ) രാത്രി നമസ്കാരത്തെക്കുറിച്ചു ചോദിക്കുവാനുള്ളത് ഓർമ്മയിൽ വന്നത്. ഞാൻ പറഞ്ഞു: ഉമ്മുൽ മുഅമിനീൻ! റസൂലി(സ)ന്റെ രാത്രി നമസ്കാരത്തെക്കുറിച്ച് പറഞ്ഞു തന്നാലും!. ആയിശ(റ) ചോദിച്ചു: ''യാ അയ്യുഹൽ മുസമ്മിൽ'' എന്നു തുടങ്ങുന്ന സുറത് ഓതാറില്ലേ? ഞാൻ പറഞ്ഞു: അതെ. മഹതി പറഞ്ഞു: ഈ അദ്ധ്യായത്തിന്റെ തുടക്കത്തിൽ അല്ലാഹു രാത്രി നമസ്കാരം നിർബന്ധമാക്കി, അങ്ങനെ നബി(സ) യും സഹാബിമാരും ഒരു കൊല്ലക്കാലം രാത്രി നമസ്കരിച്ചു. അങ്ങനെ അവരുടെ കാലുകൾ നീര് വന്ന് തടിച്ചു. അദ്ധ്യായത്തിന്റെ അവസാനഭാഗം പന്ത്രണ്ട് മാസക്കാലത്തേക്ക് അല്ലാഹു ഉപരിലോകത്ത് മാറ്റി വെക്കുകയായിരുന്നു. അനന്തരം അദ്ധ്യായത്തിന്റെ അവസാനഭാഗം അവതരിപ്പിച്ചു കൊണ്ട് അല്ലാഹു ലഘൂകരണം നൽകി. നിർബന്ധമായിരുന്ന രാത്രി നമസ്കാരം അതോടെ സുന്നത്തായി തീർന്നു. സഅദ്(റ) പറയുന്നു. ഞാൻ എഴുന്നേറ്റു പോരാൻ ഉദ്ദേശിച്ചു. അപ്പോഴാണ് റസൂലിന്റെ വിതിറിനെക്കുറിച്ചു ചോദിക്കാമെന്ന് തോന്നിയത്. ഞാൻ ചോദിച്ചു: ഉമ്മുൽ മുഅ്മിനീൻ റസൂലിന്റെ വിത്റിനെക്കുറ്ച്ച് പറഞ്ഞു തന്നാലും. ആയിശ(റ) പറഞ്ഞു: ഞങ്ങൾ അവിടത്തേക്ക് വേണ്ടി മിസ്വാക്കും വെള്ളവും ഒരുക്കിവെക്കും. രാത്രി, അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ അവൻ നബി(സ)യെ ഉണർത്തും. അവിടുന്ന് പല്ല്തേച്ച് വുദു ചെയ്ത് എട്ട് റക്അത് നിസ്കരിക്കും. ഇടക്ക് ഇരിക്കാറില്ല. എട്ടാമത്തെ റക്അത് കഴിഞ്ഞ് ഇരിക്കും. അല്ലാഹുവിനെ സ്മരിക്കും പ്രാർത്ഥിക്കും ശേഷം ഞങ്ങൾ കേൾക്കെ സലാം ചൊല്ലും. സലാം ചൊല്ലിയ ശേഷം ഇരുന്നുകൊണ്ട് രണ്ട് റക്അത് കൂടി നിസ്കരിക്കും. പിന്നീട് ഒരു റക്അത് നിസ്കരിക്കും. അങ്ങനെ പതിനൊന്ന് റക്അത് നിർവഹിക്കും. എന്റെ പൊന്നുമോനേ, നബി(സ)ക്ക് പ്രായം കൂടി ക്ഷീണമായപ്പോൾ ഏഴ് റക്അത്താണ് വിത്റ് നിസ്കരിച്ചത്. സലാം വീട്ടിയശേഷം രണ്ട് റക്അത് ഇരുന്നുകൊണ്ട് നിർവഹിച്ചു. അങ്ങനെ ഒൻപത് റക്അത്താക്കും. എന്റെ പൊന്നുമോനേ, റസൂൽ(സ) ഒരു നമസ്കാരം നിർവഹിച്ചാൽ അത് പതിവാക്കാനാണിഷ്ടപ്പെട്ടിരുന്നത്. ഉറക്കം, തളർച്ച രോഗം ആദിയായ കാരണങ്ങളാൽ രാത്രി നമസ്കരിക്കാൻ കഴിയാതെ പോയാൽ പകൽ പന്ത്രണ്ട് റക്അത് നിസ്കരിക്കും. ഒരു രാത്രിയെങ്കിലും നബി(സ) ഖുർആൻ മുഴുവൻ ഓതിയതായോ പുലരുവോളം നമസ്കരിച്ചതായോ റമളാനല്ലാത്ത ഏതെങ്കിലും മാസത്തിൽ തീർത്തും നോമ്പനുഷ്ഠിച്ചതായോ എനിക്കറിയില്ല. സഅദ്(റ) പറയുന്നു: അനന്തരം ഞാൻ ഇബ്നുഅബ്ബാസിനെ ചെന്നു കണ്ടു. മഹതി പറഞ്ഞതത്രയും അദ്ദേഹത്തെ കേൾപ്പിച്ചു. അപ്പോൾ പറഞ്ഞു: മഹതി പറഞ്ഞത് ശരിയാണ്. ഞാൻ മഹതിയുടെ അടുത്ത് പോയിരുന്നെങ്കിൽ മഹതി എന്നോട് അഭിമുഖമായി സംസാരിക്കുന്ന രൂപത്തിൽ ഞാൻ മഹതിയുടെ അടുത്തേക്ക് പോകുമായിരുന്നു. (ന)', 'سَعْدِ بْنِ هِشَامِ بْنِ عَامِرٍ الْأَنْصَارِيِّ', 'സഅദുബ്നു ഹിശാം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 574, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَعْقِدُ الشَّيْطَانُ عَلَى قَافِيَةِ رَأْسِ أَحَدِكُمْ إِذَا هُوَ نَامَ ثَلَاثَ عُقَدٍ يَضْرِبُ كُلَّ عُقْدَةٍ عَلَيْكَ لَيْلٌ طَوِيلٌ فَارْقُدْ فَإِنِ اسْتَيْقَظَ فَذَكَرَ اللَّهَ انْحَلَّتْ عُقْدَةٌ فَإِنْ تَوَضَّأَ انْحَلَّتْ عُقْدَةٌ فَإِنْ صَلَّى انْحَلَّتْ عُقْدَةٌ فَأَصْبَحَ نَشِيطًا طَيِّبَ النَّفْسِ، وَإِلَّا أَصْبَحَ خَبِيثَ النَّفْسِ كَسْلَانَ. (ن)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: നിങ്ങളിലാരെങ്കിലും ഉറങ്ങുകയാണെങ്കിൽ അയാളുടെ പിടലിയിൽ പിശാച് മൂന്ന് കെട്ടുകൾ കെട്ടും. ഓരോ കെട്ടിന്റെയും സന്ദർഭത്തിൽ അടിച്ചുകൊണ്ട് പറയും നിനക്ക് ഇനിയും രാവേറെയുണ്ട് ഉറങ്ങിക്കൊള്ളുക, അങ്ങനെയിരിക്കെ എഴുന്നേറ്റ് അല്ലാഹുവിനെ ഓർമിച്ചാൽ ഒരു കെട്ടഴിയും. വുദുചെയ്താൽ രണ്ടാമത്തെ കെട്ടഴിയും. നമസ്കാരം നിർവഹിച്ചാൽ മൂന്നാമത്തെ കെട്ടഴിയും. അയാൾ ആ ദിവസം ഉന്മേഷവാനും സന്മനസ്സുള്ളവനുമായിത്തീരും. അപ്രകാരം അല്ലെങ്കിൽ (എഴുന്നേറ്റ് നമസ്കരിക്കാത്തവൻ) മടിയനും ദുഷിച്ചവനുമാകും. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: لَا تَدَعْ قِيَامَ اللَّيْلِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَدَعُهُ وَكَانَ إِذَا مَرِضَ أَوْ كَسِلَ صَلَّى قَاعِدًا. (د)', 'ആയിശ(റ) പറയുന്നു. നീ രാത്രി നമസ്കാരം ഉപേക്ഷിക്കരുത്. നിശ്ചയം റസൂൽ(സ) അതുപേക്ഷിച്ചിരുന്നില്ല. രോഗിയാവുകയോ നിൽക്കാൻ മടി തോന്നുകയോ ചെയ്താൽ അവിടുന്ന് ഇരുന്നുകൊണ്ട് നമസ്കരിക്കും. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَيْقَظَ الرَّجُلُ أَهْلَهُ مِنَ اللَّيْلِ فَصَلَّيَا أَوْ صَلَّى رَكْعَتَيْنِ جَمِيعًا كُتِبَا فِي الذَّاكِرِينَ وَالذَّاكِرَاتِ. (د)', 'അബൂസഈദ്(റ), അബൂഹുറൈറ(റ) എന്നിവർ പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു. "ഒരു പുരുഷൻ തന്റെ വീട്ടുകാരെ രാത്രിയിൽ ഉണർത്തുകയും എന്നിട്ടവർ നമസ്കരിക്കുകയും ചെയ്താൽ അല്ലെങ്കിൽ രണ്ട് റക്അത് നിർവഹിച്ചാൽ അവരെ അല്ലാഹുവിനെ സ്മരിക്കുന്നവരുടെ പട്ടികയിൽ ഉൾപ്പെടുത്തുന്നതാണ്. (ദ)', 'أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ', 'അബൂസഈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَعْقِدُ الشَّيْطَانُ عَلَى قَافِيَةِ رَأْسِ أَحَدِكُمْ بِاللَّيْلِ بِحَبْلٍ فِيهِ ثَلَاثُ عُقَدٍ، فَإِنِ اسْتَيْقَظَ فَذَكَرَ اللَّهَ انْحَلَّتْ عُقْدَةٌ، فَإِذَا قَامَ فَتَوَضَّأَ انْحَلَّتْ عُقْدَةٌ، فَإِذَا قَامَ إِلَى الصَّلَاةِ انْحَلَّتْ عُقْدَةٌ كُلُّهَا، فَيُصْبِحُ نَشِيطًا طَيِّبَ النَّفْسِ قَدْ أَصَابَ خَيْرًا، وَإِنْ لَمْ يَفْعَلْ أَصْبَحَ كَسِلًا خَبِيثَ النَّفْسِ لَمْ يُصِبْ خَيْرًا. (ن,جه)', 'അബൂഹുറൈറ(റ) പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഓരോരുത്തരുടെയും പിരടിയെ പിശാച് രാത്രിയിൽ മൂന്ന് കെട്ടുകളുള്ള ഒരു കയറ് കൊണ്ട് ബന്ധിക്കും. അയാൾ അല്ലാഹുവിനെ സ്മരിച്ചുകൊണ്ട് ഉണർന്നാൽ ഒരു കെട്ടഴിയും. എഴുന്നേറ്റ് വുദു ചെയ്താൽ രണ്ടാമത്തെ കെട്ടഴിയും. എഴുന്നേറ്റ് നമസ്കരിക്കാൻ പോയാൽ എല്ലാ കെട്ടുകളും അഴിയുന്നു. അങ്ങിനെ അയാൾ ഉന്മേഷവാനും സന്മനസ്സുള്ളവനും ആയിത്തീരുന്നു. അയാൾക്ക് നന്മ ഉണ്ടാവുന്നു. എന്നാൽ ഇപ്രകാരം ചെയ്യുന്നില്ലെങ്കിൽ അയാൾ മടിയനും ദുഷിച്ചവനുമായിത്തീരും. അയാൾക്ക് നന്മ ഉണ്ടാവുകയില്ല. (ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 576, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذُكِرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ نَامَ لَيْلَةً حَتَّى أَصْبَحَ قَالَ: ذَاكَ رَجُلٌ بَالَ الشَّيْطَانُ فِي أُذُنَيْهِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നേരം പുലരുംവരെ ഉറങ്ങിയ ഒരാളെക്കുറിച്ച് പ്രവാചകരോട്(സ) പറഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു. "അയാളുടെ ഇരു ചെവികളിലും പിശാച് മൂത്രമൊഴിച്ചിരിക്കുന്നു.'' (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَكُنْ مِثْلَ فُلَانٍ كَانَ يَقُومُ اللَّيْلَ فَتَرَكَ قِيَامَ اللَّيْلِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ ഇന്നാലിന്ന ആളെപ്പോലെ ആകരുത്. അയാൾ രാത്രി എഴുന്നേൽക്കുന്നു. രാത്രി നമസ്കാരം ഉപേക്ഷിക്കുകയും ചെയ്യുന്നു." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ: قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَتْ أُمُّ سُلَيْمَانَ بْنِ دَاوُدَ لِسُلَيْمَانَ يَا بُنَيَّ لَا تُكْثِرِ النَّوْمَ بِاللَّيْلِ، فَإِنَّ كَثْرَةَ النَّوْمِ بِاللَّيْلِ تَتْرُكُ الرَّجُلَ فَقِيرًا يَوْمَ الْقِيَامَةِ. (جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ) പറയുന്നു. റസൂൽ(സ) പറഞ്ഞു. "സുലൈമാനുബ്നു ദാവൂദ്(അ)ന്റെ ഉമ്മ തന്റെ മകനോട് പറഞ്ഞു: പൊന്നു മകനെ! രാത്രിയിൽ നീ അധികം ഉറങ്ങരുത്. രാത്രിയിലുള്ള അധിക ഉറക്കം അന്ത്യനാളിൽ ഒരാളെ ദരിദ്രനാക്കുന്നു." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ الْأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَثُرَتْ صَلَاتُهُ بِاللَّيْلِ حَسُنَ وَجْهُهُ بِالنَّهَارِ. (جه)', 'ജാബിർ(റ) പറയുന്നു. റസൂൽ(സ) പറഞ്ഞു. "രാത്രി ഒരാൾ തന്റെ നമസ്കാരം വർദ്ധിപ്പിച്ചാൽ പകലിൽ അയാളുടെ മുഖം പ്രസന്നമാകും." (ജ)', 'الْأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ انْجَفَلَ النَّاسُ إِلَيْهِ، وَقِيلَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجِئْتُ فِي النَّاسِ لِأَنْظُرَ إِلَيْهِ، فَلَمَّا اسْتَثْبَتُّ وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَفْتُ أَنَّ وَجْهَهُ لَيْسَ بِوَجْهِ كَذَّابٍ، وَكَانَ أَوَّلُ شَيْءٍ تَكَلَّمَ بِهِ أَنْ قَالَ: أَيُّهَا النَّاسُ أَفْشُوا السَّلَامَ وَأَطْعِمُوا الطَّعَامَ وَصَلُّوا وَالنَّاسُ نِيَامٌ تَدْخُلُوا الْجَنَّةَ بِسَلَامٍ. قَالَ ترمدي هَذَا حَدِيثٌ صَحِيحٌ. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): റസൂൽ(സ) മദീനയിലേക്ക് വന്നപ്പോൾ ജനങ്ങൾ പ്രവാചകരുടെ ചുറ്റും ഒന്നിച്ചു കൂടി. എല്ലാവരും പറയാൻ തുടങ്ങി. അല്ലാഹുവിന്റെ ദൂതർ ആഗതരായിരിക്കുന്നു. അല്ലാഹുവിന്റെ ദൂതർ ആഗതരായിരിക്കുന്നു. അല്ലാഹുവിന്റെ ദൂതർ ആഗതരായിരിക്കുന്നു. ജനത്തോടൊപ്പം അവിടുത്തെ കാണാൻ ഞാനും ചെന്നു. റസൂലി(സ)ന്റെ മുഖം എന്റെ മുന്നിൽ പ്രത്യക്ഷമായപ്പോൾ അതൊരു കളവ് പറയുന്നവന്റെ മുഖമല്ലെന്ന് എനിക്ക് മനസ്സിലായി. അദ്ദേഹം ഒന്നാമതായി സംസാരിച്ചു തുടങ്ങി. "ജനങ്ങളെ സലാം വ്യാപിപ്പിക്കുക, പരസ്പരം ഭക്ഷണം നൽകുക, ജനം ഉറങ്ങിക്കിടക്കുമ്പോൾ രാത്രിയിൽ എഴുന്നേറ്റ് നമസ്കരിക്കുക. എങ്കിൽ സമാധാനത്തോടെ സ്വർഗത്തിൽ കടക്കാം. (ഹദീസ് സഹീഹാണെന്ന് തുർമിദി പറയുന്നു) (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى سَمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، فَيَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ، مَنْ يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: അത്യുന്നതനും പരിശുദ്ധനുമായ നമ്മുടെ നാഥൻ ഓരോ രാത്രിയിലും ഒന്നാനാകാശത്തേക്ക് ഇറങ്ങി വരുന്നു. രാത്രിയുടെ മൂന്നിലൊരു ഭാഗം അവശേഷിക്കുന്ന സന്ദർഭത്തിലാണത്. അപ്പോൾ പറയും എന്നോട് ആർ പ്രാർത്ഥിക്കുന്നുവോ ഞാനവന് ഉത്തരം നൽകും. എന്നോട് ആർ ചോദിക്കുന്നുവോ അത് ഞാനവന് നൽകും. ആർ എന്നോട് പൊറുക്കലിനെ തേടുന്നുവോ ഞാനവന് പൊറുത്തു കൊടുക്കും. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمِ، وَأَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ". (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു. റമദാൻ മാസത്തിലെ നോമ്പിനുശേഷമുള്ള ഏറ്റവും ശ്രേഷ്ഠമായ നോമ്പ് അല്ലാഹുവിന്റെ മാസമായ മുഹർറം മാസത്തിലെ നോമ്പാകുന്നു. ഫർദ് നമസ്കാരത്തിനു ശേഷം ഏറ്റവും ശ്രേഷ്ഠമായ നമസ്കാരം രാത്രി നമസ്കാരമാകുന്നു. (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ الرَّجُلُ فِي حَيَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى رُؤْيَا قَصَّهَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَتَمَنَّيْتُ أَنْ أَرَى رُؤْيَا فَأَقُصَّهَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكُنْتُ غُلَامًا شَابًّا، وَكُنْتُ أَنَامُ فِي الْمَسْجِدِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَأَيْتُ فِي النَّوْمِ كَأَنَّ مَلَكَيْنِ أَخَذَانِي فَذَهَبَا بِي إِلَى النَّارِ، فَإِذَا هِيَ مَطْوِيَّةٌ كَطَيِّ الْبِئْرِ، وَإِذَا لَهَا قَرْنَانِ، وَإِذَا فِيهَا أُنَاسٌ قَدْ عَرَفْتُهُمْ، فَجَعَلْتُ أَقُولُ: أَعُوذُ بِاللَّهِ مِنَ النَّارِ، قَالَ: فَلَقِيَنَا مَلَكٌ آخَرُ، فَقَالَ لِي: لَمْ تُرَعْ، فَقَصَصْتُهَا عَلَى حَفْصَةَ، فَقَصَّتْهَا حَفْصَةُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "نِعْمَ الرَّجُلُ عَبْدُ اللَّهِ لَوْ كَانَ يُصَلِّي مِنَ اللَّيْلِ"، فَكَانَ بَعْدُ لَا يَنَامُ مِنَ اللَّيْلِ إِلَّا قَلِيلًا. (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് ആരെങ്കിലും സ്വപ്നം കണ്ടാൽ അത് നബി(സ)ക്ക് വിവരിച്ചു കൊടുക്കാറുണ്ടായിരുന്നു. ചെറുപ്പത്തിൽ ഒരു സ്വപ്നം കണ്ട് നബി(സ)ക്ക് വിവരിച്ചു കൊടുക്കാൻ എനിക്കും കൊതി തോന്നി. നബി(സ)യുടെ കാലത്ത് ഒരിക്കൽ പള്ളിയിൽ ഉറങ്ങവെ രണ്ട് മലക്കുകൾ എന്നെ പിടിച്ച് നരകത്തിലേക്ക് കൊണ്ടു പോവുന്നതായി ഞാൻ സ്വപ്നം കണ്ടു. നരകം കിണർ പടുത്തതു പോലെ പടുക്കപ്പെട്ടതാണ്. നരകത്തിന് രണ്ട് കൊമ്പുകളുണ്ടായിരുന്നു. അതിൽ എനിക്കറിയാവുന്ന പലരുമാണ്ടായിരുന്നു. ഞാൻ ''നരകത്തിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ തേടുന്നു!'' എന്നു പറയാൻ തുടങ്ങി. ഈ സമയം മറ്റൊരു മലക്ക് ഞങ്ങളെ കണ്ടുമുട്ടുകയും എന്നോട് ഇപ്രകാരം പറയുകയും ചെയ്തു: നീ പേടിക്കേണ്ട! ഈ കഥ ഞാൻ ഹഫ്സ(റ)യോട് പറഞ്ഞു. മഹതിയത് നബി(സ)ക്കും വിവരിച്ചു കൊടുത്തു. നബി(സ) പറഞ്ഞു: "അബ്ദുല്ല വളരെ നല്ലവനാണ്, അദ്ദേഹം രാത്രി നിസ്രിക്കുകയാണെങ്കിൽ എത്ര നന്നായിരുന്നു." ഇതിനു ശേഷം ഇബ്നുഉമർ(റ) രാത്രി അൽപമേ ഉറങ്ങാറുള്ളൂ. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ: طُولُ الْقِيَامِ، قِيلَ: فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: جُهْدُ الْمُقِلِّ، قِيلَ: فَأَيُّ الْهِجْرَةِ أَفْضَلُ؟ قَالَ: مَنْ هَجَرَ مَا حَرَّمَ اللَّهُ عَلَيْهِ قِيلَ: فَأَيُّ الْجِهَادِ أَفْضَلُ؟ قَالَ: مَنْ جَاهَدَ الْمُشْرِكِينَ بِمَالِهِ وَنَفْسِهِ، قِيلَ: فَأَيُّ الْقَتْلِ أَشْرَفُ؟ قَالَ: مَنْ أُهْرِيقَ دَمُهُ وَعُقِرَ جَوَادُهُ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യിൽ ഖസ്അമീ(റ): തിരുമേനി(സ)യോട് ഏറ്റവും നല്ല കർമ്മം ഏതാണെന്ന് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പ്രതികരിച്ചു. "രാത്രി നിസ്കാരം ദീർഘിപ്പിക്കലാണ്." ചോദിക്കപ്പെട്ടു: ധർമ്മത്തിൽ വെച്ച് ഏതാണ് ഏറ്റവും ഉത്തമം? അവിടുന്ന് പറഞ്ഞു: "ജഹ്ദുൽ മുഖില്ല്" (പ്രയാസമുള്ളവന്റെ ധർമ്മം). തിരുമേനി(സ)യോട് ചോദിക്കപ്പെട്ടു: ഹിജ്റയിൽ വെച്ച് ഏതാണ് ഏറ്റവും ഉത്തമം? അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു തനിക്ക് നിരോധിച്ചതിനെ ഒഴിവാക്കിയവൻ." പ്രവാചകൻ(സ) ചോദിക്കപ്പെട്ടു: ഏറ്റവും ഉത്തമമായ വിശുദ്ധ യുദ്ധം ഏതാണ്? അവിടുന്ന് പറഞ്ഞു: "സമ്പത്തും ശരീരവും ഉപയോഗിച്ച് ബഹുദൈവ വിശ്വാസികളോട് യുദ്ധം ചെയ്തവന്റേത്." തിരുമേനി(സ) ചോദിക്കപ്പെട്ടു: ഏറ്റവും നല്ല വധമേതാണ്? അവിടുന്ന് പറഞ്ഞു. "രക്തം ചിന്തപ്പെടുകയും കുതിര അറുക്കപ്പെടുകയും ചെയ്ത ആളുടേതാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യിൽ ഖസ്അമീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ فَلْيُصَلِّ رَكْعَتَيْنِ خَفِيفَتَيْنِ"، وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: ثُمَّ لِيَطُولَ بَعْدُ مَا شَاءَ. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും രാത്രിയിൽ ഉണർന്നാൽ ലഘുവായി രണ്ട് റക്അത്ത് നമസ്കരിക്കട്ടെ. മറ്റൊരു റിപ്പോർട്ടിൽ: ''പിന്നീടയാൾ ഉദ്ദേശിച്ചത്ര ദീർഘിപ്പിക്കട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=135), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: ثُمَّ لِيَطُولَ بَعْدُ مَا شَاءَ. (م)', 'മറ്റൊരു നിവേദനിൽ: ''പിന്നീടയാൾ ഉദ്ദേശിച്ചത്ര ദീർഘിപ്പിക്കട്ടെ." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلَاثَةٌ يُحِبُّهُمُ اللَّهُ عَزَّ وَجَلَّ، رَجُلٌ أَتَى قَوْمًا فَسَأَلَهُمْ بِاللَّهِ وَلَمْ يَسْأَلْهُمْ بِقَرَابَةٍ بَيْنَهُ وَبَيْنَهُمْ، فَمَنَعُوهُ، فَتَخَلَّفَهُمْ رَجُلٌ بِأَعْقَابِهِمْ، فَأَعْطَاهُ سِرًّا لَا يَعْلَمُ بِعَطِيَّتِهِ إِلَّا اللَّهُ عَزَّ وَجَلَّ وَالَّذِي أَعْطَاهُ، وَقَوْمٌ سَارُوا لَيْلَتَهُمْ حَتَّى إِذَا كَانَ النَّوْمُ أَحَبَّ إِلَيْهِمْ مِمَّا يُعْدَلُ بِهِ نَزَلُوا فَوَضَعُوا رُءُوسَهُمْ فَقَامَ يَتَمَلَّقُنِي وَيَتْلُو آيَاتِي، وَرَجُلٌ كَانَ فِي سَرِيَّةٍ فَلَقُوا الْعَدُوَّ فَانْهَزَمُوا فَأَقْبَلَ بِصَدْرِهِ حَتَّى يُقْتَلَ أَوْ يُفْتَحَ لَهُ. (ن)', 'അബുദർറ്(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് വിഭാഗം ആളുകളെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നു. ഒരാൾ ഒരു സമൂഹത്തിലേക്ക് വരികയും അവർക്കിടയിലുള്ള ബന്ധം കാരണമല്ലാതെ അല്ലാഹുവിനെ മുൻ നിർത്തി മാത്രം അവരോട് ചോദിക്കുകയും ചെയ്യുന്നു. പക്ഷെ, അയാൾക്ക് നൽകാൻ അവർ തയ്യാറായില്ല. അവർക്ക് പിന്നിൽ പിന്തി നിൽക്കുകയായിരുന്ന ഒരാൾ അയാൾക്ക് സ്വകാര്യമായികൊണ്ട് - നൽകപ്പെട്ടവനും അല്ലാഹുവുമല്ലാത്ത മറ്റാരുമറിയാതെ - ധർമ്മം ചെയ്യുകയും ചെയ്തു. ഒരു സമൂഹം രാത്രി ധാരാളം സഞ്ചരിച്ച് ഉറക്കം കീഴടക്കിയപ്പോൾ ഒരിടത്തിറങ്ങി തലചായ്ച്ചു. അപ്പോൾ അവരിലൊരാൾ എന്നെ ധ്യാനിക്കുകയും ഖുർആനിക സൂക്തങ്ങൾ പാരായണം ചെയ്യുകയും ചെയ്തു. മറ്റൊരാൾ ഒരു സൈന്യത്തിലായിരിക്കെ തന്റെ ശത്രുക്കളെ കണ്ടുമുട്ടുകയും തന്റെ കൂടെയുള്ളവർ പരാജിതരായി ഓടിപ്പോകുകയും ചെയ്തു. ഈ സമയം അയാൾ നെഞ്ചൂക്കോടെ യുദ്ധമുന്നണിയിലേക്ക് ചെന്ന് രക്തസാക്ഷിത്വമോ വിജയമോ ലഭിക്കുന്നത് വരെ പോരാടി." (ന)', 'أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'അബുദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، وَتَشَهَّدُ فِي كُلِّ رَكْعَتَيْنِ وَتَبَاءَسُ وَتَمَسْكَنُ وَتُقْنِعُ وَتَقُولُ: اللَّهُمَّ اغْفِرْ لِي فَمَنْ لَمْ يَفْعَلْ ذَلِكَ فَهِيَ خِدَاجٌ. (د,ت)', 'മത്വലിബുബ്നു വദാഅ(റ): റസൂൽ(സ) പറയുന്നു: "രാത്രി നിസ്കാരം ഈരണ്ടു റക്അത്തുകളായിട്ടാണ് നിർവ്വഹിക്കേണ്ടത്. ഓരോ രണ്ടു റക്അത്തിലും അത്തഹിയ്യാത്ത് ഓതണം. വിഷമങ്ങൾ അല്ലാഹുവിനോട് പറയണം, സമാധാനിക്കണം, കൈ നീട്ടി (അല്ലാഹുവേ, എനിക്ക് പൊറുത്തു തരേണമേ) എന്ന് അല്ലാഹുവിനോട് കേണപേക്ഷിക്കണം, ഇങ്ങനെയൊന്നും ഒരാൾ ചെയ്തിട്ടില്ലെങ്കിൽ അവന്റെ നിസ്കാരം ന്യൂനമാണ്." (ദ,തു)', 'الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ', 'മത്വലിബുബ്നു വദാഅ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 579, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ أَسْمَعُ قِرَاءَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ وَأَنَا عَلَى عَرِيشِي. (ن,جه)', 'ഉമ്മുഹാനിഅ് ബിൻത് അബൂത്വാലിബ്: ഞാനെന്റെ കട്ടിലിലായിരിക്കെ നബി(സ)യുടെ രാത്രി നമസ്കാരത്തിലെ ഖുർആൻ പരായണം കേട്ടിരുന്നു. (ന,ജ)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'ഉമ്മുഹാനിഅ് ബിൻത് അബൂത്വാലിബ്', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِى ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِآيَةٍ حَتَّى أَصْبَحَ يُرَدِّدُهَا وَالْآيَةُ {إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ} [المائدة: ١١٨]. (د,جه)', 'അബൂദർറ്(റ): ഒരു രാത്രി എഴുന്നേറ്റ് റസൂൽ(സ) ഒരു ആയത്ത് ആവർത്തിച്ചു കൊണ്ടേ ഇരുന്നു. അങ്ങനെ പ്രഭാതമായി: (അവരെ നീ ശിക്ഷിക്കുകയാണെങ്കിൽ അവർ നിന്റെ അടിമകളാണ്. ഇനി നീ അവർക്ക് പൊറുത്തുകൊടുക്കുകയാണെങ്കിൽ നീ യുക്തിമാനും പ്രതാപവാനുമാകുന്നു.) (അൽ മാഇദ: 118) (ദ,ജ)', 'أَبِى ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], 'المائدة: ١١٨', null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى، فَكَانَ إِذَا مَرَّ بِآيَةِ رَحْمَةٍ سَأَلَ، وَإِذَا مَرَّ بِآيَةِ عَذَابٍ اسْتَجَارَ، وَإِذَا مَرَّ بِآيَةٍ فِيهَا تَنْزِيهٌ لِلَّهِ سَبَّحَ. (جه)', 'ഹുദൈഫ(റ): നബി(സ) ഒരിക്കൽ റഹ്മത്തിനെ പ്രതിപാദിക്കുന്ന വചനങ്ങളിലൂടെ കടന്നു പോകുമ്പോൾ അതിനെ തേടുകയും ശിക്ഷയുടെ ആയത്തിലൂടെ കടന്നു പോകുമ്പോൾ രക്ഷ തേടുകയും അല്ലാഹുവിനെ കുറിച്ചുണർത്തുന്നആയത്തിലൂടെ കടന്നു പോകുമ്പോൾ അവനെ പുകഴ്തുകയും ചെയ്തു. (ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَبِي لَيْلَى قَالَ: صَلَّيْتُ إِلَى جَنْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي مِنَ اللَّيْلِ تَطَوُّعًا، فَمَرَّ بِآيَةِ عَذَابٍ، فَقَالَ: أَعُوذُ بِاللَّهِ مِنَ النَّارِ، وَيْلٌ لِأَهْلِ النَّارِ. (د,جه)', 'അബൂലൈല(റ): അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) രാത്രിയിലെ ഐച്ഛിക നമസ്കാരം നിർവഹിച്ചു കൊണ്ടിരിക്കെ ഞാൻ തിരുമേനിയുടെ ഒരു വശത്ത് നമസ്കരിക്കുകയായിരുന്നു. ശിക്ഷയെക്കുറിക്കുന്ന ആയത്ത് പാരായണം ചെയ്തു കൊണ്ടിരുന്നപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നരകത്തിൽ നിന്ന് അല്ലാഹുവിനോട് ഞാൻ രക്ഷ തേടുന്നു. നരകവാസികൾക്കെല്ലാം നാശം." (ദ,ജ)', 'أَبِي لَيْلَى قَالَ', 'അബൂലൈല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: وَقَدْ سُئِلَ عَنْ قِرَاءَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كَانَ يَمُدُّ صَوْتَهُ مَدًّا. (خ,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ ഖുർആൻ പാരായണത്തെക്കുറിച്ചു ചോദിക്കപ്പെട്ടപ്പോൾ പറഞ്ഞു: പ്രവാചകൻ(സ) തന്റെ ശബ്ദം വളരെ ഉയർത്തുമായിരുന്നു. (ബു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ غُضَيْفِ بْنِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْتُ: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْهَرُ بِالْقُرْآنِ أَوْ يُخَافِتُ بِهِ؟ قَالَتْ: رُبَّمَا جَهَرَ وَرُبَّمَا خَافَتَ، قُلْتُ: اللَّهُ أَكْبَرُ، الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي هَذَا الْأَمْرِ سَعَةً. (د,ن,جه)', 'ഗുളൈഫുബ്നുൽ ഹാരിസ്(റ): ഞാൻ ആയിശ(റ)യുടെ അടുത്ത് ചെന്ന് ചോദിച്ചു: പ്രവാചകൻ(സ) ഖുർആൻ ഉറക്കെയാണോ പാരായണം ചെയ്തിരുന്നത് അതോ പതുക്കെയോ? മഹതി പറഞ്ഞു: ചിലപ്പോൾ ഉച്ചത്തിലും ചിലപ്പോൾ ശബ്ദം താഴ്ത്തിയും. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹു എത്ര വലിയവൻ. ഇക്കാര്യത്തിൽ വിശാലത നൽകിയ അല്ലാഹുവിന് സർവ്വസ്തുതിയും. (ദ,ന,ജ)', 'غُضَيْفِ بْنِ الْحَارِثِ', 'ഗുളൈഫുബ്നുൽ ഹാരിസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: مَرَرْتُ بِكَ وَأَنْتَ تَقْرَأُ وَأَنْتَ تَخْفِضُ مِنْ صَوْتِكَ، فَقَالَ: إِنِّي أَسْمَعْتُ مَنْ نَاجَيْتُ، قَالَ: ارْفَعْ قَلِيلًا. وَقَالَ لِعُمَرَ: مَرَرْتُ بِكَ وَأَنْتَ تَقْرَأُ وَأَنْتَ تَرْفَعُ صَوْتَكَ. قَالَ: إِنِّي أُوقِظُ الْوَسْنَانَ وَأَطْرُدُ الشَّيْطَانَ. قَالَ: اخْفِضْ قَلِيلًا. (د,ت)', 'അബൂഖതാദ(റ): റസൂൽ(സ) അബൂബക്റി(റ)നോട് പറഞ്ഞു: "നിങ്ങൾ ഓതിക്കൊണ്ടിരിക്കെ ഞാൻ നിങ്ങളുടെ അടുത്തുകൂടെ നടന്നുപോയി. എന്നാൽ വളരെ പതുക്കെയാണല്ലോ താങ്കൾ ഓതുന്നത്?" അദ്ദേഹം പ്രതിവചിച്ചു: ഞാൻ ആരോടാണോ അഭിസംബോധന ചെയ്യുന്നത്, (അവൻ ഇത് കേൾക്കുന്നുണ്ടല്ലോ) റസൂൽ(സ) പറഞ്ഞു: "എന്നാലും അൽപം ശബ്ദമുയർത്തണം." നബി(സ) ഉമറി(റ)നോട് പറഞ്ഞു: "നിങ്ങൾ ഓതിക്കൊണ്ടിരിക്കെ ഞാൻ നിങ്ങളുടെ അടുത്തുകൂടെ നടന്ന് പോയി. എന്നാൽ (വളരെ) ശബ്ദമുയർത്തിയാണല്ലോ താങ്കൾ ഓതുന്നത്?" അദ്ദേഹം പ്രതിവചിച്ചു: ഞാൻ തൂങ്ങി ഉറങ്ങുന്നവരെ ഉണർത്തുകയും ചെകുത്താനെ ആട്ടിയോടിക്കുകയും ചെയ്യുകയാണ്. റസൂൽ(സ) പറഞ്ഞു: "അൽപം ശബ്ദം താഴ്ത്തണം." (ദ,തു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِآيَةٍ مِنَ الْقُرْآنِ لَيْلَةً. حسن غريب. (ت)', 'ആയിശ(റ): നബി(സ) ഒരു ആയത്ത് ഓതി കൊണ്ട് ഒരു രാത്രി മുഴുവൻ നമസ്കരിച്ചിരുന്നു. (ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമിദി പറയുന്നു) (തു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: كَيْفَ كَانَتْ قِرَاءَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ أَكَانَ يُسِرُّ بِالْقِرَاءَةِ أَمْ يَجْهَرُ؟ فَقَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، رُبَّمَا أَسَرَّ بِالْقِرَاءَةِ وَرُبَّمَا جَهَرَ. فَقُلْتُ: الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. قَالَ ترمدي: هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ. (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു അബൂഖൈസ്(റ): ഞാൻ ആയിശ(റ)യോട് ചോദിച്ചു. നബി(സ)യുടെ രാത്രി നമസ്കാരത്തിലെ ഖുർആൻ പാരായണം എപ്രകാരമായിരുന്നു; അവിടുന്ന് രഹസ്യമായിട്ടാണേ ശബ്ദമുയർത്തിയാണോ ഓതിയിരുന്നത്? മഹതി പറഞ്ഞു: രണ്ടും നിർവ്വഹിച്ചിരുന്നു. ചിലപ്പോൾ രഹസ്യമായും മറ്റു ചിലപ്പോൾ ശബ്ദമുയർത്തിയും ചെയും. അപ്പോൾ ഞാൻ പറഞ്ഞു. ഇക്കാര്യത്തിൽ വിശാലത നൽകിയ അല്ലാഹുവിനു സ്തുതി. ( ഹദീസ് ഹസനും സഹീഹു ഗരീബുമാണെന്ന് തിർമിദി പറയുന്നു) (മു,ദ,തു)', null, 'അബ്ദുല്ലാഹിബ്നു അബൂഖൈസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي مَسْعُودٍ الْبَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْآيَتَانِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ مَنْ قَرَأَهُمَا فِي لَيْلَةٍ كَفَتَاهُ". وَفِي رِوَايَةٍ: "مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ". (ق,د,ت,جه)', 'അബൂമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ബഖറ സുറത്തിൽ നിന്ന് അവസാന രണ്ട് ആയത്തുകൾ ആരെങ്കിലും ഓതിയാൽ അവനത് മതി. മറ്റൊരു റിപ്പോർട്ടിൽ: സൂറത്തു ബഖറയിൽ നിന്ന് അവസാന രണ്ട് ആയത്തുകൾ ആരെങ്കിലും ഓതിയാൽ അവന് അവ മതിയാകും. "(ബു,മു,ദ,തു,ജ)', 'أَبِي مَسْعُودٍ الْبَدْرِيِّ', 'അബൂമസ്ഊദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=147), 1, 'وَفِي رِوَايَةٍ: "مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ". (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനിൽ: സൂറത്തു ബഖറയിൽ നിന്ന് അവസാന രണ്ട് ആയത്തുകൾ ആരെങ്കിലും ഓതിയാൽ അവന് അവ മതിയാകും. "(ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ هَذَا الْقُرْآنَ نَزَلَ بِحُزْنٍ، فَإِذَا قَرَأْتُمُوهُ فَابْكُوا، فَإِنْ لَمْ تَبْكُوا فَتَبَاكَوْا، وَتَغَنَّوْا بِهِ، فَمَنْ لَمْ يَتَغَنَّ بِهِ فَلَيْسَ مِنَّا". ز: في إسناده ضعيف متروك. (جه)', 'സഅ്ദുബ്നു അബീ വഖാസ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിശ്ചയം ഈ ഖുർആൻ ദുഖത്തോടെ ഇറങ്ങി, അതുകൊണ്ട് തന്നെ നിങ്ങൾ ഖുർആൻ ഓതിയാൽ കരയണം. അഥവാ നിങ്ങൾക്ക് കരച്ചിൽ വരുന്നില്ലെങ്കിൽ നിങ്ങൾ ഉണ്ടാക്കിക്കരയണം. ഈണത്തിലായിരിക്കണം ഓതേണ്ടത്. ആരെങ്കിലും ഖുർആൻ ഈണത്തിൽ ഓതുന്നില്ലെങ്കിൽ അവൻ നമ്മിൽ പെട്ടവനല്ല." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനും പരിഗണീയമല്ലാത്തവനുമായ വ്യക്തിയുണ്ടെന്ന് ഇബ്നുമാജ) (ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീ വഖാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനും പരിഗണീയമല്ലാത്തവനുമായ വ്യക്തിയുണ്ടെന്ന് ഇബ്നുമാജ', 581, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَبْطَأْتُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً بَعْدَ الْعِشَاءِ، ثُمَّ جِئْتُ فَقَالَ: أَيْنَ كُنْتِ؟ قُلْتُ: كُنْتُ أَسْتَمِعُ قِرَاءَةَ رَجُلٍ مِنْ أَصْحَابِكَ، لَمْ أَسْمَعْ مِثْلَ قِرَاءَتِهِ وَصَوْتِهِ مِنْ أَحَدٍ قَالَتْ: فَقَامَ وَقُمْتُ مَعَهُ، حَتَّى اسْتَمَعَ لَهُ، ثُمَّ الْتَفَتَ إِلَيَّ، فَقَالَ: هَذَا سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ، الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي أُمَّتِي مِثْلَ هَذَا. (جه)', 'ആയിശ(റ): റസൂലി(സ)ന്റെ കാലത്ത് ഒരു രാത്രി ഇശാഇന് ശേഷം ഞാൻ അൽപം പിന്തി. അപ്പോൾ പ്രവാചകൻ(സ) ചോദിച്ചു: "നീ എവിടെയായിരുന്നു?" മഹതി പറഞ്ഞു: താങ്കളുടെ അനുചരരിൽ പെട്ട ഒരാളുടെ ഖുർആൻ പാരായണം ഞാൻ കേട്ടു കൊണ്ടിരിക്കുകയായിരുന്നു. അയാളുടെ ഖുർആൻ പാരായണത്തെ പോലെ ശബ്ദമാധുര്യമുള്ള ഒരു പാരായണവും ഞാൻ കേട്ടിട്ടില്ല. തുടർന്നു മഹതി പറഞ്ഞു: പിന്നീട് അവിടുന്ന് എഴുന്നേറ്റു. കൂടെ ഞാനും എഴുന്നേൽക്കുകയും അവിടുന്ന് അദ്ദേഹത്തിന്റെ ഓത്ത് ശ്രവിക്കുകയും ചെയ്തു. അപ്പോൾ എന്നിലേക്ക് തിരിഞ്ഞു കൊണ്ട് പ്രവാചകൻ(സ) പറഞ്ഞു. "അത് അബൂഹുദൈഫയുടെ അടിമ സാലിമാണ്. ഇതു പോലുള്ള ആളുകളെ എന്റെ സമുദായത്തിനു നൽകിയ അല്ലാഹുവിനു സർവ്വ സ്തുതിയും." (ജ)', 'عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ', 'ആയിശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَحْسَنِ النَّاسِ صَوْتًا بِالْقُرْآنِ الَّذِي إِذَا سَمِعْتُمُوهُ يَقْرَأُ حَسِبْتُمُوهُ يَخْشَى اللَّهَ". (ز: في اسناده راويان ضعيفان) (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളിൽ ഖുർആൻ പാരായണത്തിന് ഏറ്റവും നല്ല ശബ്ദമുള്ളവൻ, നിങ്ങൾ അയാളുടെ പാരായണം കേൾക്കുമ്പോൾ അയാൾ അല്ലാഹുവിനെ ഭയപ്പെടുന്നുവെന്ന് നിങ്ങൾക്ക് തോന്നുന്ന വിധത്തിൽ പാരായണം ചെയ്യുന്നവനാണ്." (ഇതിന്റെ പരമ്പരയിൽ രണ്ട് ദുർബ്ബലന്മാരുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, 'ഇതിന്റെ പരമ്പരയിൽ രണ്ട് ദുർബ്ബലന്മാരുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَلَّهُ أَشَدُّ أَذَنًا إِلَى الرَّجُلِ الْحَسَنِ الصَّوْتِ بِالْقُرْآنِ يَجْهَرُ بِهِ مِنْ صَاحِبِ الْقَيْنَةِ إِلَى قَيْنَتِهِ". (جه)', 'ഫുളാലത്തുബ്നു ഫുളൈൽ(റ): നബി(സ) പറഞ്ഞു: "ഗായികയുടെയാൾ അവളുടെ ഗാനം ശ്രവിക്കുന്നതിനേക്കാൾ കൂടുതലായിട്ട് ഖുർആൻ ഈണത്തിൽ ഉറക്കെ ഓതുന്നവനെ അല്ലാഹു ശ്രവിക്കുന്നതാണ്." (ജ)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫുളാലത്തുബ്നു ഫുളൈൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ فَسَمِعَ قِرَاءَةَ رَجُلٍ، فَقَالَ: مَنْ هَذَا؟ فَقِيلَ: عَبْدُ اللَّهِ بْنُ قَيْسٍ. فَقَالَ: لَقَدْ أُوتِيَ هَذَا مِنْ مَزَامِيرِ آلِ دَاوُدَ. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ ഒരാളുടെ ഖുർആൻ പാരായണം കേട്ടു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "അതാരാണ്?" അപ്പോൾ പറയപ്പെട്ടു: അബ്ദുല്ലാഹിബ്നു ഖൈസ്(റ) ആണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "തീർച്ചയായും ഇയാൾക്ക് ദാവൂദി(അ)ന്റെ കുടുംബത്തന്റെ ശബ്ദമാണ് നൽകപ്പെട്ടിട്ടുള്ളത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ". (جه)', 'ബറാഉബ്നു ഗാസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖുർആനിനെ നിങ്ങളുടെ ശബ്ദം കൊണ്ടലങ്കരിക്കുക." (ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ قَالَ', 'ബറാഉബ്നു ഗാസിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ يَجْهَرُ أَمْ يُسِرُّ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ رُبَّمَا جَهَرَ وَرُبَّمَا أَسَرَّ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബൂഖൈസ്(റ): ഞാൻ ആയിശ(റ)യോട് ചോദിച്ചു: റസൂലി(സ)ന്റെ രാത്രിനമസ്കാരത്തിലെ ഖിറാഅത്ത് എപ്രകാരമായിരുന്നു. ഉറക്കെയോ അതോ പതുക്കെയോ? മഹതി പറഞ്ഞു: രണ്ടു പ്രകാരവും ചെയ്തിരുന്നു. ചിലപ്പോൾ ഉച്ചത്തിൽ, ചിലപ്പോൾ ശബ്ദം താഴ്ത്തിയും. (ന)', 'عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബൂഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 582, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا قَامَ مِنَ اللَّيْلِ فَقَرَأَ فَرَفَعَ صَوْتَهُ بِالْقُرْآنِ، فَلَمَّا أَصْبَحَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَرْحَمُ اللهُ فُلَانًا كَأَيِّ مِنْ آيَةٍ أَذْكَرَنِيهَا اللَّيْلَةَ كُنْتُ قَدْ أُسْقِطْتُهَا. (ق,ن,د)', 'ആയിശ(റ): ഒരാൾ രാത്രി എഴുന്നേറ്റ് ഉച്ചത്തിൽ ഖുർആൻ പാരായണം ചെയ്തു. പ്രഭാതമായപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹു അയാളെ അനുഗ്രഹിക്കട്ടെ. ഞാൻ മറന്നുപോയ എത്ര ആയത്തുകളാണ് ആ രാത്രിയിൽ അയാളെന്നെ ഓർമ്മിപ്പിച്ചത്." (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','ن','د']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: اعْتَكَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَسَمِعَهُمْ يَجْهَرُونَ بِالْقِرَاءَةِ، فَكَشَفَ السِّتْرَ، وَقَالَ: أَلَا إِنَّ كُلَّكُمْ مُنَاجٍ رَبَّهُ، فَلَا يُؤْذِيَنَّ بَعْضُكُمْ بَعْضًا، وَلَا يَرْفَعْ بَعْضُكُمْ عَلَى بَعْضٍ فِي الْقِرَاءَةِ - أَوْ قَالَ فِي الصَّلَاةِ. (د)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പള്ളിയിൽ ഇഅ്തികാഫിലായിരുന്നു. അപ്പോൾ അവർ(സഹാബികൾ) ഖുർആൻ ഉച്ചത്തിലോതുന്നത് കേട്ടു. മറ നീക്കിക്കൊണ്ടവിടുന്ന് പറഞ്ഞു: "നിങ്ങളിലോരുത്തരും നിങ്ങളുടെ നാഥനുമായി സംഭാഷണത്തിലാണ്. നിങ്ങൾ പരസ്പരം ഉപദ്രവിക്കരുത്. നിങ്ങൾ ഖുർആൻ പാരായണത്തിൽ പരസ്പരം ശബ്ദമുയർത്തരുത്." അല്ലെങ്കിൽ ''നമസ്കാരത്തിൽ'' എന്നായിരിക്കണം പറഞ്ഞത്. (ദ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْجَاهِرُ بِالْقُرْآنِ كَالْجَاهِرِ بِالصَّدَقَةِ، وَالْمُسِرُّ بِالْقُرْآنِ كَالْمُسِرِّ بِالصَّدَقَةِ. (د,ت,ن)', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ): "ഖുർആൻ പാരായണം ഉച്ചത്തിൽ നിർവ്വഹിക്കുന്നവൻ ദാനധർമങ്ങൾ പരസ്യമാക്കുന്നവനെപ്പോലെയാണ്. രഹസ്യമായി ഖുർആൻ പാരായണം ചെയ്യുന്നവൻ രഹസ്യമായി ദാനധർമ്മങ്ങൾ ചെയ്യുന്നവനെ പേലെയാണ്" എന്ന് റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. (ദ,തു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ قِرَاءَةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى قَدْرِ مَا يَسْمَعُهُ مَنْ فِي الْحُجْرَةِ وَهُوَ فِي الْبَيْتِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ ഖുർആൻ പാരായണം അവിടുന്ന് വീട്ടീലായിരിക്കെ മുറിയുലുള്ളവർ കേൾക്കുന്നത്ര ശബ്ദത്തിലായിരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّهُ قَالَ: كَانَتْ قِرَاءَةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ يَرْفَعُ طَوْرًا وَيَخْفِضُ طَوْرًا. (د)', 'അബൂഹുറൈറ(റ): റസൂലി(സ)ന്റെ രാത്രിയിലുള്ള ഖുർആൻ പരായണം ചിലപ്പോൾ ശബ്ദമുയർത്തിയും ചിലപ്പോൾ ശബ്ദം താഴ്ത്തിയുമായിരുന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ لَيْلَةً فَإِذَا هُوَ بِأَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ يُصَلِّي يَخْفِضُ مِنْ صَوْتِهِ، قَالَ: وَمَرَّ بِعُمَرَ بْنِ الْخَطَّابِ وَهُوَ يُصَلِّي رَافِعًا صَوْتَهُ، قَالَ: فَلَمَّا اجْتَمَعَا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا أَبَا بَكْرٍ مَرَرْتُ بِكَ وَأَنْتَ تُصَلِّي تَخْفِضُ صَوْتَكَ. قَالَ: قَدْ أَسْمَعْتُ مَنْ نَاجَيْتُ يَا رَسُولَ اللهِ. قَالَ: وَقَالَ لِعُمَرَ: مَرَرْتُ بِكَ وَأَنْتَ تُصَلِّي رَافِعًا صَوْتَكَ. قَالَ: فَقَالَ: يَا رَسُولَ اللهِ! أُوقِظُ الْوَسْنَانَ وَأَطْرُدُ الشَّيْطَانَ. (د)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=160), 1, 'وَفِي رِوَايَةٍ: فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا بَكْرٍ ارْفَعْ مِنْ صَوْتِكَ شَيْئًا وَقَالَ لِعُمَرَ: اخْفِضْ مِنْ صَوْتِكَ شَيْئًا"', 'മറ്റൊരു നിവേദനം: അപ്പോൾ നബി(സ) മറുപടി കൊടുത്തു: "അബൂബക്റേ, കുറച്ചുകൂടി ശബ്ദമുയർത്തുക." ഉമറി(റ)നോട് പറഞ്ഞു: "നിങ്ങളൽപം ശബ്ദം താഴ്ത്തുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=160), 2, 'وَفِي رِوَايَةٍ: وَقَدْ سَمِعْتُكَ يَا بِلَالُ وَأَنْتَ تَقْرَأُ مِنْ هَذِهِ السُّورَةِ وَمِنْ هَذِهِ السُّورَةِ! قَالَ: كَلَامٌ طَيِّبٌ يَجْمَعُ اللَّهُ تَعَالَى بَعْضَهُ إِلَى بَعْضٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّكُمْ قَدْ أَصَابَ. (د,ت)', 'മറ്റൊരു നിവേദനം: "ബിലാലേ, താങ്കൾ ഈ സൂറത്തിൽ നിന്നും മറ്റൊരു സൂറത്തിൽ നിന്നും ഓതുന്നത് ഞാൻ കേട്ടല്ലോ." അദ്ദേഹം പ്രതിവചിച്ചു. നല്ല നല്ല വാക്യങ്ങൾ. അല്ലാഹു അവയിൽ ചിലതിനെ ചിലതിനോട് കൂടെ ഒരുമിച്ച് കൂട്ടുന്നു. ഇത് കേട്ട് നബി(സ) പറഞ്ഞു: "നിങ്ങളിലോരോരുത്തരും ശരിയാണ് പറഞ്ഞത്." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فِي قَوْلِهِ عَزَّ وَجَلَّ: {وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا} قَالَ: نَزَلَتْ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُخْتَفٍ بِمَكَّةَ، فَكَانَ إِذَا صَلَّى بِأَصْحَابِهِ رَفَعَ صَوْتَهُ وَقَالَ ابْنُ مَنِيعٍ يَجْهَرُ بِالْقُرْآنِ، وَكَانَ الْمُشْرِكُونَ إِذَا سَمِعُوا صَوْتَهُ سَبُّوا الْقُرْآنَ وَمَنْ أَنْزَلَهُ وَمَنْ جَاءَ بِهِ، فَقَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {وَلَا تَجْهَرْ بِصَلَاتِكَ} أَيْ بِقِرَاءَتِكَ فَيَسْمَعَ الْمُشْرِكُونَ فَيَسُبُّوا الْقُرْآنَ {وَلَا تُخَافِتْ بِهَا} عَنْ أَصْحَابِكَ فَلَا يَسْمَعُوا {وَابْتَغِ بَيْنَ ذَلِكَ سَبِيلًا} [الإسراء: ١١٠]. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''പ്രാർത്ഥന നീ ഉച്ചത്തിലാക്കരുത്. അത് നീ പതുക്കെയുമാക്കരുത്...'' (ഇസ്റാഅ്: 110) എന്ന അല്ലാഹുവിന്റെ വചനത്തെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഈ ആയത്ത് അവതീർണ്ണമായത് പ്രവാചകൻ മക്കയിൽ ഒളിഞ്ഞിരുന്ന് പ്രബോധനം നടത്തുന്ന ഘട്ടത്തിലാണ്. തിരുമേനി(സ) തന്റെ അനുചരന്മാരെയുമായി നിസ്കരിക്കുമ്പോൾ ശബ്ദമുയർത്തി ഓതും. ബഹുദൈവവിശ്വാസികളാകട്ടെ അതു കേട്ടാ അവർ പരിശുദ്ധ ഖുർആനിനെയും, അത് അവതരിപ്പിച്ച അല്ലാഹുവിനെയും, അതു കൊണ്ടുവന്ന പ്രവാചകനെ(സ)യും ചീത്ത വിളിക്കും. ആ സന്ദർഭത്തിൽ അല്ലാഹു തിരുമേനി(സ)യോടു പറഞ്ഞു: ''താങ്കൾ പ്രാർത്ഥന - അതായത് ഖുർആൻ പാരായണം - ഉച്ചത്തിലാക്കരുത്'' അതു ബഹുദൈവവിശ്വാസികൾ കേൾക്കുവാനും, അങ്ങിനെ ഖുർആനിനെ ശകാരിക്കുവാനും ഇടയാകും. ''അതു പതുക്കെയുമാകരുത്'' താങ്കളുടെ അനുചരന്മാർക്ക് അതു കേൾക്കാൻ സാധിക്കുകയില്ല. ''രണ്ടിനും മദ്ധ്യേയുള്ള മാർഗ്ഗം സ്വീകരിച്ചുകൊള്ളുക''. (ബു,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ബു','തു','ന']::text[], 'الإسراء: ١١٠', null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُ صَوْتَهُ بِالْقُرْآنِ، وَكَانَ الْمُشْرِكُونَ إِذَا سَمِعُوا صَوْتَهُ سَبُّوا الْقُرْآنَ وَمَنْ جَاءَ بِهِ، فَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْفِضُ صَوْتَهُ بِالْقُرْآنِ، مَا كَانَ يَسْمَعُهُ أَصْحَابُهُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَلِكَ سَبِيلًا} (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) തന്റെ ഖുർആൻ പാരായണം ഉച്ചത്തിലാക്കിയിരുന്നു. അങ്ങനെ ബഹുദൈവ വിശ്വാസികൾ അതിന്റെ ശബ്ദം കേട്ടപ്പോൾ ഖുർആനെയും അതു കൊണ്ടുവന്നവനെയും ശകാരിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) തന്റെ ഖുർആൻ പാരായണം പതുക്കെയാക്കാൻ തുടങ്ങി. അത് തിരുമേനിയുടെ അനുചരർക്ക് കേൾക്കുമായിരുന്നില്ല. അപ്പോൾ അല്ലാഹു ഇപ്രകാരം അവതരിപ്പിച്ചു: ''നബിയേ, താങ്കൾ പ്രാർത്ഥന ഉച്ചത്തിലാക്കരുത്, അത് പതുക്കെയുമാക്കരുത്. രണ്ടിനും മദ്ധ്യേയുള്ള മാർഗ്ഗം സ്വീകരിച്ചു കൊള്ളുക'' (ഇസ്റാഅ്: 110) (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 584, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَوْسِ بْنِ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْنَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي وَفْدِ ثَقِيفٍ قَالَ نَزَلَتِ الْأَحْلَافُ عَلَى الْمُغِيرَةِ بْنِ شُعْبَةَ، وَأَنْزَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَنِي مَالِكٍ فِي قُبَّةٍ لَهُ، قَالَ مُسَدَّدٌ: وَكَانَ فِي الْوَفْدِ الَّذِينَ قَدِمُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ثَقِيفٍ، قَالَ: كَانَ كُلَّ لَيْلَةٍ يَأْتِينَا بَعْدَ الْعِشَاءِ يُحَدِّثُنَا، وَ قَالَ أَبُو سَعِيدٍ: قَائِمًا عَلَى رِجْلَيْهِ حَتَّى يُرَاوِحَ بَيْنَ رِجْلَيْهِ مِنْ طُولِ الْقِيَامِ، وَأَكْثَرُ مَا يُحَدِّثُنَا مَا لَقِيَ مِنْ قَوْمِهِ مِنْ قُرَيْشٍ ثُمَّ يَقُولُ لَا سَوَاءَ كُنَّا مُسْتَضْعَفِينَ مُسْتَذَلِّينَ قَالَ مُسَدَّدٌ: بِمَكَّةَ، فَلَمَّا خَرَجْنَا إِلَى الْمَدِينَةِ كَانَتْ سِجَالُ الْحَرْبِ بَيْنَنَا وَبَيْنَهُمْ نُدَالُ عَلَيْهِمْ وَيُدَالُونَ عَلَيْنَا فَلَمَّا كَانَتْ لَيْلَةٌ أَبْطَأَ عَنِ الْوَقْتِ الَّذِي كَانَ يَأْتِينَا فِيهِ فَقُلْنَا لَقَدْ أَبْطَأْتَ عَنَّا اللَّيْلَةَ قَالَ إِنَّهُ طَرَأَ عَلَيَّ حِزْبِي مِنَ الْقُرْآنِ فَكَرِهْتُ أَنْ أَجِيءَ حَتَّى أُتِمَّهُ. قَالَ أَوْسٌ سَأَلْتُ أَصْحَابَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَيْفَ يُحَزِّبُونَ الْقُرْآنَ قَالُوا ثَلَاثَ وَخَمْسَ وَسَبْعَ وَتِسْعَ وَإِحْدَى عَشْرَةَ وَثَلَاثَ عَشْرَةَ وَحِزْبُ الْمُفَصَّلِ. (د،جه)', 'ഔസുബ്നു ഹുദൈഫ(റ): സഖീഫ് ഗോത്രത്തിലെ ഒരു സംഘത്തിൽ ഞങ്ങൾ നബി(സ)യുടെ അടുത്ത് ചെന്നു. ഔസ് പറയുന്നു: സഖ്യ കക്ഷികൾ മുഗീറത്തുബ്നു ശുഅ്ബ(റ)യുടെ അടുത്ത് ഇറങ്ങിയിട്ടുണ്ട്. നബി(സ)യാണെങ്കിൽ ബനു മാലിക് ഗോത്രക്കാരെ തന്റെ തന്നെ ഒരു ഖുബ്ബയിൽ പാർപ്പിച്ചിട്ടുണ്ട്. റാവികളിൽ പെട്ട മുസദ്ദദ്(റ)പറയുന്നു: നബി(സ)യുടെ അടുത്ത് വന്ന ഗോത്ര സംഘങ്ങളിൽ സഖീഫ് ഗോത്രത്തിൽ നിന്നുമുണ്ടായിരുന്ന ഹദീസ് റിപ്പോർട്ടർ പറയുന്നു: നബി(സ)ഓരോ രാത്രിയിലും ഞങ്ങളുടെ അടുത്ത് വന്ന് സംസാരിക്കും. അബൂസഈദ്(റ) പറയുന്നു: ഇത് രണ്ട് കാലിൽ നിന്ന് കൊണ്ടായിരുന്നു പറഞ്ഞ് തന്നിരുന്നത്. അങ്ങനെ ദീർഘ നേരം നിൽക്കുന്നതിനാൽ തിരുമേനി(സ) ഓരോ കാലിലും നിന്ന് ആശ്വാസം കൊള്ളുമായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞുതന്നിരുന്നതിൽ അധികവും തന്റെ സമുദായമായ ഖുറൈശികളിൽ നിന്ന് തിരുമേനി(സ)ക്ക് അഭിമുഖീകരിക്കേണ്ടി വന്ന കാര്യങ്ങളായിരുന്നു. നബി(സ) പറയും. ലാ സവാഅ്, ഞങ്ങൾ ബലഹീനരും നിന്ദിതരുമായിരുന്നു. മുസദ്ദദ് പറഞ്ഞു: മക്കയിലായിരിക്കെയാണിത്. ഞങ്ങൾ മദീനയിലേക്ക് പുറപ്പെട്ടപ്പോൾ ഞങ്ങൾക്കും ശത്രുക്കൾക്കുമിടയിൽ വിജയം മാറി മാറിവരും. ചിലപ്പേൾ അവരും അല്ലെങ്കിൽ ഞങ്ങളും വിജയിക്കും. ഒരു രാത്രി അസാധാരണയായി പ്രവാചകൻ(സ) വൈകിയെത്തി. കാരണമന്വേഷിച്ചപ്പോൾ പതിവായി ഓതുന്ന ഖുർആൻ ഭാഗം പൂർത്തിയാക്കുന്നതിന് മുമ്പ് വരാൻ മടിച്ചതാണെന്ന് അവിടുന്ന് പറഞ്ഞു. ഔസ്(റ) പറയുന്നു: പ്രവാചകന്റെ അനുചരന്മാരോട് എങ്ങനെയാണ് നിങ്ങൾ ഖുർആൻ ഭാഗം നിർണയിച്ച് ഓതിയിരുന്നത്? എന്ന് ഞാൻ ചോദിച്ചു. അവർ പറഞ്ഞു: മൂന്ന്, അഞ്ച്, ഏഴ്, ഒമ്പത്, പതിനൊന്ന്, പതിമൂന്ന് എന്നിങ്ങനെ ഭാഗങ്ങൾ തിരിച്ചും മുഫസ്സ്വലുകളും ഓതാറായിരുന്നു പതിവ്. (ദ,ജ)', 'أَوْسِ بْنِ حُذَيْفَةَ', 'ഔസുബ്നു ഹുദൈഫ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: جَمَعْتُ الْقُرْآنَ فَقَرَأْتُهُ كُلَّهُ فِي لَيْلَةٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي أَخْشَى أَنْ يَطُولَ عَلَيْكَ الزَّمَانُ، وَأَنْ تَمَلَّ، فَاقْرَأْهُ فِي شَهْرٍ". فَقُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي. قَالَ: "فَاقْرَأْهُ فِي عَشْرَةٍ". قُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي. قَالَ: "فَاقْرَأْهُ فِي سَبْعٍ". قُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي، فَأَبَى. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞാൻ ഖുർആൻ ഒരുമിച്ച് കൂട്ടുകയും ഒറ്റ രാത്രി കൊണ്ട് എല്ലാം ഓതി തീർക്കുകയും ചെയ്തു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിന്നിൽ കാലം നീണ്ടു പോകുന്നതും, നിനക്ക് മടുപ്പ് അനുഭവപ്പെടുന്നതും ഞാൻ ഭയപ്പെടുന്നു. അതിനാൽ നീ ഒരു മാസത്തിൽ ഓതി തീർക്കുക." അപ്പോൾ ഞാൻ പറഞ്ഞു: എന്നെ വിട്ടേക്കൂ! എന്റെ യുവത്വത്തിലും ശക്തിയിലും ഞാൻ ആനന്ദിക്കട്ടെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ പത്ത് ദിവസംകൊണ്ട് നീ ഓതി തീർക്കുക." ഞാൻ പറഞ്ഞു: എന്നെ വിട്ടേക്കൂ. എന്റെ യുവത്വത്തിലും ശക്തിയിലും ഞാൻ ആനന്ദിക്കട്ടെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ ഒരാഴ്ചയിൽ." ഞാൻ പറഞ്ഞു: എന്നെ വിട്ടേക്കൂ. എന്റെ യുവത്വത്തിലും ശക്തിയിലും ഞാൻ ആനന്ദിക്കട്ടെ. റസൂൽ(സ) അത് തടഞ്ഞു. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 585, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمْ يَفْقَهُ مَنْ قَرَأَ الْقُرْآنَ فِي أَقَلَّ مِنْ ثَلَاثٍ ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "മൂന്നിൽ കുറഞ്ഞ ദിവസങ്ങൾ കൊണ്ട് ഒരാൾ ഖുർആൻ മുഴുവൻ ഓതിയാൽ അവന്ന് ഖുർആൻ മനസ്സിലാക്കാനാവില്ല." (ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ حَتَّى الصَّبَاحِ. (ن)', 'ആഇശ(റ) പറഞ്ഞു. നബി(സ്വ) പ്രഭാതം വരെ ഖുർആൻ പൂർണ്ണമായി ഓതിയതായി എനിക്കറിയില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ". (خ,د,ت,جه)', 'ഉസ്മാൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഉത്തമൻ ഖുർആൻ പഠിക്കുകയും അത് പഠിപ്പിക്കുകയും ചെയ്തവനാണ്." (ബു,ദ,തു,ജ)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ مُعَاذٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَرَأَ الْقُرْآنَ وَعَمِلَ بِمَا فِيهِ أُلْبِسَ وَالِدَاهُ تَاجًا يَوْمَ الْقِيَامَةِ، ضَوْءُهُ أَحْسَنُ مِنْ ضَوْءِ الشَّمْسِ فِي بُيُوتِ الدُّنْيَا لَوْ كَانَتْ فِيكُمْ، فَمَا ظَنُّكُمْ بِالَّذِي عَمِلَ بِهَذَا". (د)', 'മുആദുനിൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഖുർആൻ ഓതുകയും അതിലുള്ളതനുസരിച്ച് പ്രവർത്തിക്കുകയും ചെയ്താൽ അവന്റെ മാതാപിതാക്കൾക്ക് അന്ത്യനാളിൽ ഒരു കിരീടം അണിയിക്കപ്പെടും. ആ കിരീടത്തിന്റെ പ്രകാശം ഇഹലേകത്തെ സൂര്യപ്രകാശത്തേക്കാൾ ഉത്തമമായിരിക്കും. ഈ ഖുർആൻ കൊണ്ട് അമൽ ചെയ്തവനെപ്പറ്റി നിങ്ങളുടെ വിചാരമെന്താണ്?" (ദ)', 'مُعَاذٍ الْجُهَنِيِّ', 'മുആദുനിൽ ജുഹനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ مَاهِرٌ بِهِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَؤُهُ - قَالَ هِشَامٌ: وَهُوَ شَدِيدٌ عَلَيْهِ. قَالَ شُعْبَةُ: - وَهُوَ عَلَيْهِ شَاقٌّ فَلَهُ أَجْرَانِ". (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) അരുൾ ചെയ്തു: ഒരാൾ വിശുദ്ധ ഖുർആൻ അവഗാഹത്തോട് കൂടി ഓതുകയാണെങ്കിൽ അവർ മഹാന്മാരും പുണ്യവാളന്മാരുമായ സന്ദേശ വാഹകരായ മലക്കുകളോടു കൂടെയാണ്. ഹിശാം(റ) പറഞ്ഞു: തീർച്ചയായും പ്രയാസമായിരിക്കെ (പ്രയാസം സഹിച്ചു കൊണ്ട്) ഖുർആൻ ഓതുകയാണെങ്കിൽ അവന് രണ്ട് കൂലിയുണ്ട്. ശുഅ്ബ(റ) പറയുന്നു: ഖുർആൻ ബുദ്ധിമുട്ടായി ഓതുന്നവന് രണ്ട് കൂലിയുണ്ട്. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ حَافِظٌ لَهُ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَمَثَلُ الَّذِي يَقْرَأُ وَهُوَ يَتَعَاهَدُهُ وَهُوَ عَلَيْهِ شَدِيدٌ فَلَهُ أَجْرَانِ. (خ)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ അറിഞ്ഞ് ഓതുന്നവൻ അല്ലാഹുവിന്റെ ഇഷ്ട ദാസരായ മലക്കുകളോടും പ്രവാചകന്മാരോടും കൂടെയാണ്. ബുദ്ധിമുട്ടോടെ വളരെ സൂക്ഷിച്ച് ഓതുന്നവന് രണ്ട് പ്രതിഫലമുണ്ട്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 586, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ تَعَالَى، يَتْلُونَ كِتَابَ اللَّهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ، إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഭവനങ്ങളിലെ ഏതെങ്കിലുമൊരു ഭവനത്തിൽ ഒരുമിച്ചു കൂടുകയും അല്ലാഹുവിന്റെ ഗ്രന്ഥം പാരായണം ചെയ്യുകയും അവർക്കിടയിൽ അത് ചർച്ചചെയ്യപ്പെടുകയും ചെയ്യുന്ന ഒരു സമൂഹത്തിന്റെ മേൽ സമാധാനം ഇറങ്ങുകയും കാരുണ്യം പൊതിയുകയും, മലക്കുകളാൽ അവർ വലയം ചെയ്യപ്പെടുകയും ചെയ്യാതിരിക്കുകയില്ല. അല്ലാഹു തന്റെ അടുത്തുള്ളവരോട് അവരെക്കുറിച്ച് പറയുന്നതാണ്." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا وَنَحْنُ فِي الصُّفَّةِ، فَقَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يَغْدُوَ إِلَى بُطْحَانَ أَوِ الْعَقِيقِ فَيَأْتِيَ كُلَّ يَوْمٍ بِنَاقَتَيْنِ كَوْمَاوَيْنِ زَهْرَاوَيْنِ فَيَأْخُذَهُمَا فِي غَيْرِ إِثْمٍ وَلَا قَطْعِ رَحِمٍ"، قَالَ: قُلْنَا: كُلُّنَا يَا رَسُولَ اللَّهِ يُحِبُّ ذَلِكَ، قَالَ: "فَلَأَنْ يَغْدُوَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَيَتَعَلَّمَ آيَتَيْنِ مِنْ كِتَابِ اللَّهِ خَيْرٌ لَهُ مِنْ نَاقَتَيْنِ، وَثَلَاثٌ خَيْرٌ مِنْ ثَلَاثٍ، وَأَرْبَعٌ خَيْرٌ مِنْ أَرْبَعٍ، وَمِنْ أَعْدَادِهِنَّ مِنَ الْإِبِلِ". (م,د)', 'ഉഖ്ബത്തുബ്നു ആമിറുൽ ജുഹനി(റ) യിൽ നിന്ന് നിവേദനം: ഒരു ദിവസം ഞങ്ങൾ സുഫ്ഫയിൽ (നബി(സ) പഠിപ്പിക്കുന്ന സ്ഥലം) ഇരിക്കവെ നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. അപ്പോൾ നബി ചോദിച്ചു: "ബത്ഹാനിലേക്കോ അഖീഖിലേക്കോ രാവിലെ വരികയും എന്നിട്ട് ഓരോ ദിവസവും നല്ല തടിയുള്ള വിലപിടിച്ച ഗർഭസ്ഥമായ ഒട്ടകങ്ങളെ കൊണ്ടുവരുകയും കുറ്റമില്ലാതെയും കുടുംബബന്ധം മുറിക്കാതെയും അവയെ എടുക്കാനും നിങ്ങളിൽ ആരെങ്കിലും ആഗ്രഹിക്കുന്നുവോ?" അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങളെല്ലാവരും ആഗ്രഹിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പള്ളിയിലേക്ക് പോകുകയും അല്ലാഹുവിന്റെ കിതാബി(ഖുർആനി)ൽ നിന്നും രണ്ട് ആയത്ത് പഠിക്കലുമാണ് രണ്ട് ഒട്ടകത്തെക്കാളും നിങ്ങൾക്കുത്തമം. മൂന്ന് ആയത്ത് മൂന്ന് ഒട്ടകങ്ങളെക്കാളും നാല് ആയത്ത് നാല് ഒട്ടകങ്ങളെക്കാളും, മാത്രമല്ല, ആയത്തുകളടെ എണ്ണമനുസരിച്ചുള്ള ഒട്ടകങ്ങളേക്കാളും ഉത്തമമാണത്." (മു,ദ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബത്തുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} أُمُّ الْقُرْآنِ وَأُمُّ الْكِتَابِ، وَالسَّبْعُ الْمَثَانِي". هذا حديث حسن صحيح. (خ,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ എന്നത് ഖുർആന്റെ മാതാവും കിതാബിന്റെ മാതാവും സബ്ഉൽ മസാനിയ്യും(ആവർത്തിക്കപ്പെടുന്ന ഏഴും) ആകുന്നു." ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِ وَهُوَ يُصَلِّي، فَدَعَاهُ، قَالَ: فَصَلَّيْتُ ثُمَّ أَتَيْتُهُ، قَالَ: فَقَالَ: "مَا مَنَعَكَ أَنْ تُجِيبَنِي"، قَالَ: كُنْتُ أُصَلِّي، قَالَ: "أَلَمْ يَقُلِ اللَّهُ عَزَّ وَجَلَّ: {يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ} [الأنفال: ٢٤]. لَأُعَلِّمَنَّكَ أَعْظَمَ سُورَةٍ مِنَ الْقُرْآنِ - أَوْ فِي الْقُرْآنِ - شَكَّ خَالِدٌ، قَبْلَ أَنْ أَخْرُجَ مِنَ الْمَسْجِدِ". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ قَوْلُكَ، قَالَ: {الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ} هِيَ السَّبْعُ الْمَثَانِي الَّتِي أُوتِيتُ وَالْقُرْآنُ الْعَظِيمُ." (خ,د,ت)', 'അബൂസഈദുബ്നു മുഅല്ലാ(റ): അദ്ദേഹം നമസ്കരിച്ചു കൊണ്ടിരിക്കേ നബി(സ) അദ്ദേഹത്തിന്റെ അടുത്തു കൂടെ നടന്നു. അപ്പോൾ അദ്ദേഹത്തെ വിളിച്ചു. അദ്ദേഹം പറയുന്നു: ഞാൻ നിസ്കാരം കഴിഞ്ഞ ശേഷം നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ പ്രവാചകൻ(സ) ചോദിച്ചു: ''എനിക്കുത്തരം നൽകുന്നതിൽ നിന്ന് എന്താണ് നിന്നെ തടഞ്ഞത്?'' അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ നമസ്കാരത്തിലായിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "യുക്തിമാനും പ്രതാപവാനുമായ അല്ലാഹു ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ: ''വിശ്വസിച്ചവരേ, നിങ്ങളെ സജീവരാക്കുന്നതിലേക്ക് ക്ഷണിക്കുമ്പോൾ നിങ്ങൾ അല്ലാഹുവിന്നും അവന്റെ ദൂതനും മറുപടി നൽകുക.'' (അൻഫാൽ: 24) ഞാൻ പള്ളിയിൽ നിന്ന് പുറപ്പെടുന്നതിനു മുമ്പു തന്നെ ഞാൻ ഖുർആനിലെ ഏറ്റവും മഹത്തരമായ സൂക്തങ്ങൾ നിനക്ക് പഠിപ്പിച്ചു തരാം." ഞാൻ പറഞ്ഞു: റസൂലേ! താങ്കൾ പറഞ്ഞാലും! തിരുമേനി പറഞ്ഞു: "അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ(സർവ്വ സ്തുതിയും അല്ലാഹിവിന്നാകുന്നു) എന്നതാണ് എനിക്ക് നൽകപ്പെട്ട ആവർത്തിച്ചു വരുന്ന ഏഴെണ്ണം. അത് മഹത്തരമായ ഖുർആനുമാകുന്നു." (ബു,ദ,തു)', 'أَبِي سَعِيدِ بْنِ الْمُعَلَّى', 'അബൂസഈദുബ്നു മുഅല്ലാ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], 'الأنفال: ٢٤', null, 587, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أُوتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبْعًا مِنَ الْمَثَانِي الطُّوَلِ، وَأُوتِيَ مُوسَى عَلَيْهِ السَّلَام سِتًّا، فَلَمَّا أَلْقَى الْأَلْوَاحَ رُفِعَتْ ثِنْتَانِ وَبَقِيَ أَرْبَعٌ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലി(സ)ന് ഏഴ് സൂക്തങ്ങൾ (ആവർത്തിക്കപ്പെട്ട) നൽകപ്പെട്ടു. മൂസാ(അ)ക്ക് ആറെണ്ണവും നൽകപ്പെട്ടു. മൂസാ(അ) തനിക്ക് നൽകപ്പെട്ട ഫലകങ്ങൾ താഴെയിട്ടപ്പോൾ രണ്ടെണ്ണം ഉയർത്തപ്പെടുകയും നാലെണ്ണം അവശേഷിക്കുകയും ചെയ്തു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبَا الْمُنْذِرِ، أَيُّ آيَةٍ مَعَكَ مِنْ كِتَابِ اللهِ أَعْظَمُ". قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "أَبَا الْمُنْذِرِ، أَيُّ آيَةٍ مَعَكَ مِنْ كِتَابِ اللهِ أَعْظَمُ". قَالَ: قُلْتُ: {اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ} [البقرة: ٢٥٥] قَالَ: فَضَرَبَ فِي صَدْرِي وَقَالَ: "لِيَهْنِ لَكَ يَا أَبَا الْمُنْذِرِ الْعِلْمُ". (م,د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) ചോദിച്ചു: "ഓ അബുൽമുൻദിർ, അല്ലാഹുവിന്റെ ഖുർആനിൽ നിന്ന് ഏറ്റവും മഹത്തായ ഏത് സൂക്തമാണ് താങ്കളുടെയടുത്തുള്ളത്?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതനും മാത്രമാണ് ഏറ്റം അറിവുള്ളവർ. റസൂൽ(സ) ചോദ്യം ആവർത്തിച്ചു. "ഓ അബുൽ മുൻദിർ, ഖുർആനിൽനിന്ന് ഏറ്റവും മഹത്തായ ഏത് സൂക്തമാണ് താങ്കളുടെയടുത്തുള്ളത്" അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''അല്ലാഹു ലാഇലാഹ ഇല്ലാ ഹുവൽ ഹയ്യുൽ ഖയ്യൂം'' (ബഖറ: 255) അന്നേരം റസൂൽ(സ) എന്റെ നെഞ്ചത്ത് തട്ടുകയും "ഓ അബുൽ മുൻദിർ, നിനക്ക് അറിവ് എളുപ്പമാകട്ടെ" എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്തു. (മു,ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], 'البقرة: ٢٥٥', null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَمِعَ رَجُلًا يَقْرَأُ: {قُلْ هُوَ اللهُ أَحَدٌ} يُرَدِّدُهَا، فَلَمَّا أَصْبَحَ جَاءَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ لَهُ، وَكَأَنَّ الرَّجُلَ يَتَقَالُّهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ." (خ,د,ن)', 'അബൂസഈദുൽ ഖുദ്‌രീ: ഒരാൾ, ‘ഖുൽ ഹുവല്ലാഹു അഹദ്’ ആവർത്തിച്ചോതുന്നതായി മറ്റൊരു വ്യക്തി കേട്ടു. പിറ്റേ ദിവസം രാവിലെ അയാൾ അതിനെക്കുറിച്ച് പ്രവാചകനോട് അയാൾ പറയുന്നതു പോലെ പറഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: “എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം. തീർച്ചയായും അത് ഖുർആന്റെ മൂന്നിലൊന്നിനു തുല്യമാണ്.” (ബു,ദ,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രീ', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 588, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَقُودُ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عُقْبَةُ، أَلَا أُعَلِّمُكَ خَيْرَ سُورَتَيْنِ قُرِئَتَا"، فَعَلَّمَنِي: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} فَلَمْ يَرَنِي سُرِرْتُ بِهِمَا جِدًّا، فَلَمَّا نَزَلَ لِصَلَاةِ الصُّبْحِ صَلَّى بِهِمَا صَلَاةَ الصُّبْحِ لِلنَّاسِ، فَلَمَّا فَرَغَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الصَّلَاةِ الْتَفَتَ إِلَيَّ فَقَالَ: "يَا عُقْبَةُ، كَيْفَ رَأَيْتَ". (د,ن)', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ): യാത്രയിൽ ഞാൻ റസൂലി(സ)ന്റെ ഒട്ടകത്തെ നയിക്കുകയായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) എന്നോട് പറഞ്ഞു: “ഓതപ്പെട്ടതിൽ ഏറ്റവും നല്ല രണ്ട് സൂറത്തുകൾ ഞാൻ നിനക്ക് പഠിപ്പിച്ചു തരട്ടെയോ?” അപ്പോൾ എനിക്ക് ‘ഖുൽ അഊദുബിറബ്ബിൽ ഫലഖ്’, ‘ഖുൽ അഊദുബിറബ്ബിന്നാസ്’ എന്നിവ പഠിപ്പിച്ചു തന്നു. ഞാൻ അതിൽ അതിയായി സന്തോഷിച്ചു. സുബ്‌ഹി നിസ്കാരത്തിനിറങ്ങിയപ്പോൾ ജനങ്ങൾക്കിമാമായി ഈ സൂറത്തുകളോതി നബി(സ) നിസ്കരിച്ചു. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ച ശേഷം നബി(സ) ചോദിച്ചു: “ഉഖ്ബാ, എന്തു തോന്നുന്നു.” (ദ,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا أَنَا أَسِيرُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْجُحْفَةِ وَالْأَبْوَاءِ، إِذْ غَشِيَتْنَا رِيحٌ وَظُلْمَةٌ شَدِيدَةٌ، فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ: {بِأَعُوذُ بِرَبِّ الْفَلَقِ} وَ{أَعُوذُ بِرَبِّ النَّاسِ} وَيَقُولُ: "يَا عُقْبَةُ، تَعَوَّذْ بِهِمَا، فَمَا تَعَوَّذَ مُتَعَوِّذٌ بِمِثْلِهِمَا". قَالَ: وَسَمِعْتُهُ يَؤُمُّنَا بِهِمَا فِي الصَّلَاةِ. (د)', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ): ഞാൻ റസൂലി(സ)നോട് കൂടെ ജുഹ്ഫക്കും അബവാഇനുമിടയിലുള്ള സ്ഥലത്ത് കൂടെ യാത്ര ചെയ്യുകയായിരുന്നു. ആ സമയത്ത് ശക്തമായ കാറ്റും ഇരുട്ടും ഞങ്ങളെ മൂടി. അപ്പോൾ പ്രവാചകൻ(സ) അല്ലാഹുവിനോട് ‘ഖുൽഅഉദു ബിറബ്ബിൽ ഫലഖ്’ (പ്രഭാതത്തിന്റെ രക്ഷിതാവിനെക്കൊണ്ട്) എന്നും ‘ഖൽ അഉദുബി റബ്ബിന്നാസ്’ (ജനങ്ങളുടെ രക്ഷിതാവിനെക്കൊണ്ട്) എന്നും വിളിച്ച് കാവൽ ചോദിക്കാൻ തുടങ്ങി. അവിടുന്ന് എന്നോട് പറഞ്ഞു: “ഉഖ്ബത്തേ, ഇവകൊണ്ട് അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക. കാരണം, കാവൽ ചോദിക്കുന്ന ഒരുത്തനും ഇതുപോലുള്ള ഒന്നുകൊണ്ട് കാവൽ ചോദിച്ചിട്ടില്ല.” അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമായിനിന്നുകൊണ്ട് ഇവ ചൊല്ലുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തുബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُقَالُ لِصَاحِبِ الْقُرْآنِ: اقْرَأْ وَارْتَقِ وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا، فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَأُ بِهَا". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: “ഖുർആൻ പാരായണം ചെയ്യുന്നവരോട് പറയപ്പെടും: നീ പാരായണം നടത്തുക. സൂക്ഷ്മത പാലിക്കുക. ദുൻയാവിൽവെച്ച് നീ ഭംഗിയായി ഓതിയിരുന്നത് പോലെ ഭംഗിയായി ഓതുകയും ചെയ്യുക. കാരണം നിന്റെ പദവി നീ പാരായണം ചെയ്യുന്ന ആയത്തുകളുടെ ഒടുക്കത്തിലാണ്.” (തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنْ قِرَاءَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: كَانَ يَمُدُّ مَدًّا. (خ, د, ت, ن)', 'ഖതാദ(റ): ഞാൻ അനസി(റ)നോട് തിരുമേനി(സ)യുടെ ഖുർആൻ പാരായണത്തെക്കുറിച്ച് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) നീട്ടേണ്ട പ്രകാരം നീട്ടിയിരുന്നു. (ബു,ദ,തു,ന)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: سُئِلَتْ عَنْ قِرَاءَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَلَاتِهِ، فَقَالَتْ: وَمَا لَكُمْ وَصَلَاتَهُ؟ كَانَ يُصَلِّي وَيَنَامُ قَدْرَ مَا صَلَّى، ثُمَّ يُصَلِّي قَدْرَ مَا نَامَ، ثُمَّ يَنَامُ قَدْرَ مَا صَلَّى، حَتَّى يُصْبِحَ. وَنَعَتَتْ قِرَاءَتَهُ، فَإِذَا هِيَ تَنْعَتُ قِرَاءَتَهُ حَرْفًا حَرْفًا. (د, ت, ن)', 'ഉമ്മുസലമ(റ): തിരുമേനി(സ)യുടെ നിസ്കാരത്ത കുറിച്ചും ഖുർആൻ പാരായണത്തെക്കുറിച്ചും മഹതി ചോദിക്കപ്പെട്ടു. മഹതി പറഞ്ഞു: നിങ്ങളും പ്രവാചകർ(സ)യുടെ നിസ്കാരവും എവിടെ നിൽക്കുന്നു? തിരുമേനി നമസ്കരിക്കും.പിന്നീട് നമസ്കരിച്ച അത്രയും സമയം ഉറങ്ങും. പിന്നീട് ഉറങ്ങിയ അത്ര സമയം തന്നെ നിസ്കരിക്കും.പിന്നീട് നമസ്കരിച്ച അത്രയും സമയം ഉറങ്ങും. പ്രഭാതം വരെ ഇപ്രകാരം ചെയ്യും. പ്രവാചകരുടെ ഖുർആൻ പാരായണത്തെയും മഹതി വർണ്ണിച്ചു. ഓരോ അക്ഷരവും എണ്ണിത്തിട്ടപ്പെടുത്താൻ കഴിയുന്ന അത്രയും സ്ഫുടമായിട്ടായിരുന്നു അവുടത്തെ പാരായണമെന്നാണ് മഹതി വർണ്ണിച്ചത്. (ദ,തു,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ وَهُوَ عَلَى نَاقَةٍ، يَقْرَأُ بِسُورَةِ الْفَتْحِ وَهُوَ يُرَجِّعُ. (ق, د, ت)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): ഞാൻ റസൂലി(സ)നെ മക്കാ വിജയദിനത്തിൽ കണ്ടു. അവിടുന്ന് ഒട്ടകപ്പുറത്തായിരുന്നു. അപ്പോൾ സൂറത്തുൽ ഫത്ഹ് മുഴക്കമുണ്ടാകുന്ന ശബ്ദത്തിൽ ഓതുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ." (د, ن, جه)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ശബ്ദമാധുര്യത്താൽ ഖുർആനിനെ അലങ്കരിക്കുക." (ദ,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : "لَيْسَ مِنَّا مَنْ لَمْ يَتَغَنَّ بِالْقُرْآنِ." (د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ പാരായണം ചെയ്യുമ്പോൾ ശബ്ദം നന്നാക്കാത്തവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أَذِنَ اللَّهُ لِشَيْءٍ مَا أَذِنَ لِنَبِيٍّ حَسَنِ الصَّوْتِ يَتَغَنَّى بِالْقُرْآنِ، يَجْهَرُ بِهِ". (ق, د, ن)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: " ഖുർആൻ നല്ല സ്വരത്തിലും ഈണത്തിലും ഉച്ചത്തിൽ പരായണം നടത്തുന്നതിന്ന് അനുവാദം നൽകിയപോലെ അല്ലാഹു ഒരു കാര്യത്തിനും ഒരു നബിക്കും അനുവാദം നൽകിയിട്ടില്ല." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنِ امْرِئٍ يَقْرَأُ الْقُرْآنَ ثُمَّ يَنْسَاهُ إِلَّا لَقِيَ اللَّهَ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ أَجْذَمَ". (د)', 'സഅ്ദുബ്നു ഉബാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ(കാണാതെ) പാരായണം ചെയ്യുകയും പിന്നീട് അത് മറക്കുകയും ചെയ്ത ഒരാളും വികാലാംഗനായിട്ടല്ലാതെ അന്ത്യനാളിൽ അല്ലാഹുവിനെ കണ്ടുമുട്ടുകയില്ല." (ദ)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عُمَرَ ابْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ هِشَامَ بْنَ حَكِيمِ بْنِ حِزَامٍ يَقْرَأُ سُورَةَ الْفُرْقَانِ عَلَى غَيْرِ مَا أَقْرَؤُهَا، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقْرَأَنِيهَا، فَكِدْتُ أَنْ أَعْجَلَ عَلَيْهِ، ثُمَّ أَمْهَلْتُهُ حَتَّى انْصَرَفَ، ثُمَّ لَبَّبْتُهُ بِرِدَائِهِ، فَجِئْتُ بِهِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي سَمِعْتُ هَذَا يَقْرَأُ سُورَةَ الْفُرْقَانِ عَلَى غَيْرِ مَا أَقْرَأْتَنِيهَا، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَأْ". فَقَرَأَ الْقِرَاءَةَ الَّتِي سَمِعْتُهُ يَقْرَأُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَكَذَا أُنْزِلَتْ". ثُمَّ قَالَ لِي: "اقْرَأْ". فَقَرَأْتُ، فَقَالَ: "هَكَذَا أُنْزِلَتْ"، ثُمَّ قَالَ: "إِنَّ هَذَا الْقُرْآنَ أُنْزِلَ عَلَى سَبْعَةِ أَحْرُفٍ، فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ". (ق,ت,ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): ഹിശാമുബ്നു ഹകീമുബ്നുഹിസാം സൂറത്തുൽ ഫുർഖാൻ പാരായണം ചെയ്യുന്നതു ഞാൻ കേട്ടു. ഞാൻ പാരായണം ചെയ്യുന്ന രീതിയിലല്ലായിരുന്നു അത്. റസൂൽ(സ) എനിക്കത് പാരായണം ചെയ്തു തന്നിരുന്നു. തന്നിമിത്തം അദ്ദേഹത്തെ എന്തെങ്കിലും ചെയ്യട്ടെ എന്നെനിക്ക് തോന്നി. പക്ഷേ അദ്ദേഹം നമസ്കാരത്തിൽ നിന്നും വിരമിക്കുന്നതു വരെ ഞാൻ ക്ഷമിച്ചു. അനന്തരം ഞാനദ്ദേഹത്തെ കഴുത്തിൽ മുണ്ടിട്ടു പിടിച്ചു വലിച്ച് നബിയുടെ മുന്നിലെത്തിച്ചു. എന്നിട്ട് ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! അദ്ദേഹം ഫുർഖാൻ എന്ന അധ്യായം എനിക്കു താങ്കൾ പഠിപ്പിച്ചു തന്നതല്ലാത്ത രൂപത്തിൽ പാരായണം ചെയ്യുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് പാരായണം ചെയ്യാൻ പറഞ്ഞു. ഉടനെ അദ്ദേഹം ഓതുന്നതായി ഞാൻ കേട്ട അതേ രൂപത്തിൽ തന്നെ അദ്ദേഹം പാരായണം ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) അരുളി: "ഇപ്രകാരം അത് അവതരിപ്പിക്കപ്പെട്ടിരിക്കുന്നു." പിന്നീട് തിരുമേനി(സ) എന്നോട് പാരായണം ചെയ്യാൻ പറഞ്ഞു. അതനുസരിച്ച് ഞാൻ പാരായണം ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) അരുളി: "ഇപ്രകാരവും അത് അവതരിപ്പിക്കപ്പെട്ടിരിക്കുന്നു." തുടർന്ന് പറഞ്ഞു: "നിശ്ചയമായും ഈ ഖുർആൻ ഏഴ് ഹർഫിന്മേലാണ് (ഭാഷാ ശൈലികളിന്മേലാണ്) അവതരിക്കപ്പെട്ടിരിക്കുന്നത്. അതിൽ നിന്ന് എളുപ്പമായി തോന്നുന്ന ഹർഫിൽ (ഭാഷാശൈലിയിൽ) നിങ്ങൾ പാരായണം ചെയ്തു കൊള്ളുക." (ബു,മു,തു,ന)', 'عُمَرَ ابْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أُبَيُّ، إِنِّي أُقْرِئْتُ الْقُرْآنَ، فَقِيلَ لِي: عَلَى حَرْفٍ أَوْ حَرْفَيْنِ؟ فَقَالَ الْمَلَكُ الَّذِي مَعِي: قُلْ: عَلَى حَرْفَيْنِ، قُلْتُ: عَلَى حَرْفَيْنِ، فَقِيلَ لِي: عَلَى حَرْفَيْنِ أَوْ ثَلَاثَةٍ؟ فَقَالَ الْمَلَكُ الَّذِي مَعِي: قُلْ: عَلَى ثَلَاثَةٍ، قُلْتُ: عَلَى ثَلَاثَةٍ، حَتَّى بَلَغَ سَبْعَةَ أَحْرُفٍ، ثُمَّ قَالَ: لَيْسَ مِنْهَا إِلَّا شَافٍ كَافٍ، إِنْ قُلْتَ: سَمِيعًا عَلِيمًا عَزِيزًا حَكِيمًا، مَا لَمْ تَخْتِمْ آيَةَ عَذَابٍ بِرَحْمَةٍ، أَوْ آيَةَ رَحْمَةٍ بِعَذَابٍ". (د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) പറഞ്ഞു: "ഉബയ്യേ! എന്നെ കൊണ്ട് ഖുർആൻ പാരായണം ചെയ്യിപ്പിച്ചു. അപ്പോൾ എന്നോട് ചോദിക്കപ്പെട്ടു: ''ഒരു ശൈലിയിലാണോ അതോ രണ്ടു രീതിയിലോ'' അപ്പോൾ എന്റെ കൂടെയുണ്ടായിരുന്ന മലക്ക് പറഞ്ഞു: രണ്ട് രീതിയിലെന്ന് താങ്കൾ പറയുക. ഞാൻ അത് പ്രകാരം രണ്ടു രീതിയിലെന്ന് മറുപടി പറഞ്ഞു. അപ്പോൾ എന്നോട് ''രണ്ടു രീതിയിലാണോ മൂന്ന് രീതിയിലാണോ എന്ന് ചോദിക്കപ്പെട്ടു''. കൂടെയുണ്ടായിരുന്ന മലക്ക് പറഞ്ഞു: താങ്കൾ മൂന്ന് രീതിയിലെന്ന് പറഞ്ഞേക്കൂ. അത് പ്രകാരം മൂന്ന് രീതിയിലെന്ന് ഞാൻ മറുപടി നൽകി. അങ്ങനെ ''ഏഴ് ശൈലികൾ'' എന്ന് എത്തുവോളം സംഭാഷണം തുടർന്നു. ശേഷം പറഞ്ഞു: അത് മുഖേന പൂർണ്ണമായും ആശ്വാസമാണ് ഉദ്ദേശിച്ചത്. എല്ലാം കേൾക്കുന്നവൻ, എല്ലാം അറിയുന്നവൻ ''പ്രതാപവാൻ'' ''യുക്തിജ്ഞൻ'' എന്നൊക്കെ നീ പറഞ്ഞാലും ശിക്ഷയുടെ ഒരായത്തും കാരുണ്യത്തിന്റെ ആയത്തായി മാറുകയില്ല. അല്ലെങ്കിൽ കാരുണ്യത്തിന്റെ ഒരായത്തും ശിക്ഷയുടെതായി മാറുകയുമില്ല." (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 591, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ عِنْدَ أَضَاةِ بَنِي غِفَارٍ، فَأَتَاهُ جِبْرِيلُ عليه السلام، فَقَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يَأْمُرُكَ أَنْ تَقْرِئَ أُمَّتَكَ عَلَى حَرْفٍ. قَالَ: أَسْأَلُ اللَّهَ مُعَافَاتَهُ وَمَغْفِرَتَهُ، إِنَّ أُمَّتِي لَا تُطِيقُ ذَلِكَ". ثُمَّ أَتَاهُ ثَانِيَةً فَذَكَرَ نَحْوَ هَذَا، حَتَّى بَلَغَ سَبْعَةَ أَحْرُفٍ، قَالَ: "إِنَّ اللَّهَ يَأْمُرُكَ أَنْ تَقْرِئَ أُمَّتَكَ عَلَى سَبْعَةِ أَحْرُفٍ، فَأَيُّمَا حَرْفٍ قَرَءُوا عَلَيْهِ فَقَدْ أَصَابُوا". (م،د،ن)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): ഒരിക്കൽ നബി(സ) ഗിഫാർ ഗോത്രക്കാരുടെ തടാകത്തിങ്കൽ നിൽക്കുമ്പോൾ ജിബ്‌രീൽ(അ) വന്നു കൊണ്ട് പറഞ്ഞു. "താങ്കളുടെ അനുയായികൾ ഖുർആൻ ഒരേ ഹർഫിൽ പാരായണം ചെയ്തു കൊടുക്കണമെന്ന് അല്ലാഹു കൽപിക്കുന്നു." പ്രവാചകൻ(സ) പറഞ്ഞു. "ഞാൻ അല്ലാഹുവിനോട് അവന്റെ സംരക്ഷണത്തിനും പാപമോചനത്തിനും അപേക്ഷിക്കുന്നു. നിശ്ചയം എന്റെ സമുദായത്തിന് അതിന് സാധിക്കുകയില്ല." ജിബ്‌രീൽ രണ്ടാം തവണയും വന്ന് അത് തന്നെ ആവശ്യപ്പെട്ടു. അങ്ങനെ ഏഴ് ഹർഫുകളായി നിശ്ചയിക്കും വരെ തുടർന്നു. ശേഷം ജിബ്‌രീൽ പറഞ്ഞു: നിശ്ചയം താങ്കൾ താങ്കളുടെ അനുയായികൾക്ക് ഏഴു ഹർഫുകളിലായി ഖുർആൻ പാരായണം ചെയ്തുകൊടുക്കാൻ അല്ലാഹു കൽപ്പിച്ചിരിക്കുന്നു. അതിൽ ഏത് രീതിയിൽ അവർ പാരായണം ചെയ്താലും അത് ശരിയായതു തന്നെ. (മു,ദ,ന)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ عَشْرَ رَكَعَاتٍ، وَيُوتِرُ بِسَجْدَةٍ، وَيَسْجُدُ سَجْدَتَيِ الْفَجْرِ، فَذَلِكَ ثَلَاثَ عَشْرَةَ رَكْعَةً. (ق،د،ن)', 'ആഇശ(റ)യിൽ നിന്ന്: റസൂൽ(സ) രാത്രി പത്ത് റകഅത്ത് നിസ്കരിക്കുകയും ഒരു റക്അത്ത് കൊണ്ട് അതിനെ ഒറ്റയാക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. പിന്നെ ഫജ്‌റിന്റെ രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്യും. ആകെ കൂടി പതിമൂന്ന് റക്അത്ത് നിർവ്വഹിക്കും. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بِاللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً يُوتِرُ مِنْهَا بِوَاحِدَةٍ فَإِذَا فَرَغَ مِنْهَا اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ. حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ. (ق،د،جه)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അതിൽ ഒരു റക്അത്ത് വിത്ർ നിസ്കരിക്കും. വിരമിച്ചാൽ വലത് ഭാഗത്തിൻ മേൽ ചെരിഞ്ഞ് കിടക്കും.അങ്ങനെ മുഅദ്ദിൻ വന്നശേഷം രണ്ടുറകഅത്ത് ലഘുവായി നമസ്ക്കരിക്കും. (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِيمَا بَيْنَ أَنْ يَفْرُغَ مِنْ صَلَاةِ الْعِشَاءِ إِلَى أَنْ يَنْصَدِعَ الْفَجْرُ إِحْدَى عَشْرَةَ رَكْعَةً يُسَلِّمُ مِنْ كُلِّ ثَنْتَيْنِ وَيُوتِرُ بِوَاحِدَةٍ، وَيَمْكُثُ فِي سُجُودِهِ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ، فَإِذَا سَكَتَ الْمُؤَذِّنُ بِالْأُولَى مِنْ صَلَاةِ الْفَجْرِ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ. (ق،د،ن،جه)', 'ആഇശ(റ): നബി(സ) ഇശാ നിസ്കാരത്തിനും ഫജ്ർ വെളിവാകുന്നതിനുമിടയിൽ പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. ഓരോ രണ്ട് റക്അത്തിലും സലാം വിട്ടുമായിരുന്നു. ഒരു റക്അത്ത് വിതർ നിസ്കരിക്കും. നിങ്ങളൊക്കെ അൻപത് ആയത്ത് ഓതുന്ന സമയം റസൂൽ(സ) സുജൂദ് ചെയ്യും. മുഅദ്ദിൻ ബാങ്ക് നിർത്തിയാൽ എഴുന്നേറ്റ് ചുരുങ്ങിയ രണ്ട് റകഅത്ത് നിസ്കരിക്കും.പിന്നീട് മുഅദ്ദിൻ വരുന്നത് വരെ വലത് പാർശ്വത്തിന്മേൽ ചെരിഞ്ഞ് കിടക്കും. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 592, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِاللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً ثُمَّ يُصَلِّي إِذَا سَمِعَ النِّدَاءَ بِالصُّبْحِ رَكْعَتَيْنِ خَفِيفَتَيْنِ. (د)', 'ആഇശ(റ): നബി(സ)രാത്രിയിൽ പതിമൂന്ന് റകഅത്ത് നിസ്കരിക്കുമായിരുന്നു. പിന്നീട് സുബ്ഹ് ബാങ്ക് കേട്ടാൽ ലഘുവായി രണ്ട് റകഅത്ത് നിസ്കരിക്കും. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، كَانَ يُصَلِّي ثَمَانِيَ رَكَعَاتٍ، وَيُوتِرُ بِرَكْعَةٍ، ثُمَّ يُصَلِّي، قَالَ مُسْلِمٌ: بَعْدَ الْوِتْرِ [ثُمَّ اتَّفَقَا] رَكْعَتَيْنِ وَهُوَ قَاعِدٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ، وَيُصَلِّي بَيْنَ أَذَانِ الْفَجْرِ وَالْإِقَامَةِ رَكْعَتَيْنِ. (م،د،ن)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ പതിമൂന്ന് റകഅത്ത് നിസ്കരിക്കുമായിരുന്നു. ഏട്ട് റകഅത്ത് നിസ്കരിക്കും. ഒരു റകഅത്ത് വിത്റും. പിന്നെ വിത്റിന്ന് ശേഷം രണ്ട് റകഅത്ത് ഇരുന്ന് നിസ്കരിക്കും. റുകൂഇനുദ്ദേശിച്ചാൽ എഴുന്നേറ്റുനിന്ന് റുകൂഅ് ചെയ്യും. ഫജർ ബാങ്കിന്നും ഇടയിൽ രണ്ട് റകഅത്തും നിസ്കരിക്കും. (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], 'ثُمَّ اتَّفَقَا', null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'أَنَّ سَعْدَ بْنَ هِشَامِ ابْنِ عَامِرٍ أَرَادَ أَنْ يَغْزُوَ فِي سَبِيلِ اللهِ. فَقَدِمَ الْمَدِينَةَ. فَأَرَادَ أَنْ يَبِيعَ عَقَارًا لَهُ بِهَا. فَيَجْعَلَهُ فِي السِّلَاحِ وَالْكُرَاعِ، وَيُجَاهِدَ الرُّومَ حَتَّى يَمُوتَ. فَلَمَّا قَدِمَ الْمَدِينَةَ، لَقِيَ أُنَاسًا مِنْ أَهْلِ الْمَدِينَةِ. فَنَهَوْهُ عَنْ ذَلِكَ. وَأَخْبَرُوهُ؛ أَنَّ رَهْطًا سِتَّةً أَرَادُوا ذَلِكَ فِي حَيَاةِ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَهَاهُمْ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ: "أَلَيْسَ لَكُمْ فِيَّ أُسْوَةٌ؟" فَلَمَّا حَدَّثُوهُ بِذَلِكَ رَاجَعَ امْرَأَتَهُ. وَقَدْ كَانَ طَلَّقَهَا. وَأَشْهَدَ عَلَى رَجْعَتِهَا. فَأَتَى ابْنَ عَبَّاسٍ فَسَأَلَهُ عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ ابْنُ عَبَّاسٍ: أَلَا أَدُلُّكَ عَلَى أَعْلَمِ أَهْلِ الْأَرْضِ بِوِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَنْ؟ قَالَ: عَائِشَةَ. فَأْتِهَا فَاسْأَلْهَا. ثُمَّ ائْتِنِي فَأَخْبِرْنِي بِرَدِّهَا عَلَيْكَ. فَانْطَلَقْتُ إِلَيْهَا. فَأَتَيْتُ عَلَى حَكِيمِ بْنِ أَفْلَحَ. فَاسْتَلْحَقْتُهُ إِلَيْهَا. فَقَالَ: مَا أَنَا بِقَارِبِهَا. لِأَنِّي نَهَيْتُهَا أَنْ تَقُولَ فِي هَاتَيْنِ الشِّيعَتَيْنِ شَيْئًا فَأَبَتْ فِيهِمَا إِلَّا مُضِيًّا. قَالَ: فَأَقْسَمْتُ عَلَيْهِ. فَجَاءَ. فَانْطَلَقْنَا إِلَى عَائِشَةَ. فَاسْتَأْذَنَّا عَلَيْهَا، فَأَذِنَتْ لَنَا. فَدَخَلْنَا عَلَيْهَا. فَقَالَتْ: أَحَكِيمٌ؟ - فَعَرَفَتْهُ - فَقَالَ: نَعَمْ. فَقَالَتْ: مَنْ مَعَكَ؟ قَالَ: سَعْدُ بْنُ هِشَامٍ قَالَتْ: مَنْ هِشَامٌ؟ قَالَ: ابْنُ عَامِرٍ. فَتَرَحَّمَتْ عَلَيْهِ. وَقَالَتْ خَيْرًا. - قَالَ قَتَادَةُ: وَكَانَ أُصِيبَ يَوْمَ أُحُدٍ - فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، أَنْبِئِينِي عَنْ خُلُقِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: أَلَسْتَ تَقْرَأُ الْقُرْآنَ؟ قُلْتُ: بَلَى. قَالَتْ: فَإِنَّ خُلُقَ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ الْقُرْآنَ. قَالَ فَهَمَمْتُ أَنْ أَقُومَ، وَلَا أَسْأَلَ أَحَدًا عَنْ شَيْءٍ حَتَّى أَمُوتَ. ثُمَّ بَدَا لِي فَقُلْتُ: أَنْبِئِينِي عَنْ قِيَامِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ: أَلَسْتَ تَقْرَأُ: يَا أَيُّهَا الْمُزَّمِّلُ؟ قُلْتُ: بَلَى. قَالَتْ: فَإِنَّ اللهَ عَزَّ وَجَلَّ افْتَرَضَ قِيَامَ اللَّيْلِ فِي أَوَّلِ هَذِهِ السُّورَةِ، فَقَامَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ حَوْلًا. وَأَمْسَكَ اللهُ خَاتِمَتَهَا اثْنَيْ عَشَرَ شَهْرًا فِي السَّمَاءِ. حَتَّى أَنْزَلَ اللهُ، فِي آخِرِ هَذِهِ السُّورَةِ، التَّخْفِيفَ. فَصَارَ قِيَامُ اللَّيْلِ تَطَوُّعًا بَعْدَ فَرِيضَةٍ. قَالَ: قُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، أَنْبِئِينِي عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ. فَيَبْعَثُهُ اللَّهُ مَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ وَيُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ، فَيَذْكُرُ اللَّهَ وَيَحْمَدُهُ وَيَدْعُوهُ، ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، ثُمَّ يَقُومُ فَيُصَلِّ التَّاسِعَةََ، ثُمَّ يَقْعُدُ فَيَذْكُرُ اللَّهَ وَيَحْمَدُهُ وَيَدْعُوهُ، ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا، ثُمَّ يُصَلِّي رَكْعَتَيْنِ بَعْدَ مَا يُسَلِّمُ وَهُوَ قَاعِدٌ، وَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً، يَا بُنَيَّ، فَلَمَّا سَنَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَخَذَهُ اللَّحْمُ، أَوْتَرَ بِسَبْعٍ، وَصَنَعَ فِي الرَّكْعَتَيْنِ مِثْلَ صَنِيعِهِ الْأَوَّلِ، فَتِلْكَ تِسْعٌ، يَا بُنَيَّ، وَكَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَحَبَّ أَنْ يُدَاوِمَ عَلَيْهَا، وَكَانَ إِذَا غَلَبَهُ نَوْمٌ، أَوْ وَجَعٌ، عَنْ قِيَامِ اللَّيْلِ صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً، وَلَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا صَلَّى لَيْلَةً إِلَى الصُّبْحِ وَلَا صَامَ شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ، قَالَ: فَانْطَلَقْتُ إِلَى ابْنِ عَبَّاسٍ فَحَدَّثْتُهُ بِحَدِيثِهَا، فَقَالَ: صَدَقَتْ، لَوْ كُنْتُ أَقْرَبُهَا أَوْ أَدْخُلُ عَلَيْهَا لَأَتَيْتُهَا حَتَّى تُشَافِهَنِي بِهِ، قَالَ: قُلْتُ: لَوْ عَلِمْتُ أَنَّكَ لَا تَدْخُلُ عَلَيْهَا مَا حَدَّثْتُكَ حَدِيثَهَا.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=196), 1, 'وَفِي رِوَايَةٍ عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللَّهُ لِمَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ وَيُصَلِّي ثَمَانِ رَكَعَاتٍ، لَا يَجْلِسُ فِيهِنَّ إِلَّا عِنْدَ الثَّامِنَةِ، فَيَجْلِسُ فَيَذْكُرُ اللَّهَ عَزَّ وَجَلَّ وَيَدْعُو، ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا. (م,د,ن)', 'മറ്റൊരു നിവേദനിൽ ഇങ്ങനെയാണ്: മിസ്വാക്ക്ചെയ്യാനും ശുദ്ധി ചെയ്യുവാനുമുള്ള വെള്ളം ഞങ്ങൾ തയ്യാറാക്കിയിരുന്നു. അല്ലാഹു ഉദ്ദേശിക്കുമ്പോൾ രാത്രിയിൽ തിരുമേനിയെ ഉണർത്തും. ശേഷം അവിടുന്ന് ദന്തശുദ്ധി വരുത്തി വുദു ചെയ്യും. ആഇശ(റ) പറഞ്ഞു: നബി(സ) എട്ട് റകഅത്ത് നിസ്കരിക്കും. എട്ടാമത്തേതിലേ ഇരിക്കുകയുള്ളൂ. അതിൽ ഇരുന്ന് അല്ലാഹുവിനെ സ്മരിക്കുകയും പ്രാർത്ഥിക്കുകയും ചെയ്യും. പിന്നീട് ഞങ്ങളെ കേൾപ്പിക്കും വിധം സലാം വീട്ടും. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جَوْفِ اللَّيْلِ، فَقَالَتْ: كَانَ يُصَلِّي الْعِشَاءَ فِي جَمَاعَةٍ ثُمَّ يَرْجِعُ إِلَى أَهْلِهِ فَيَرْكَعُ أَرْبَعَ رَكَعَاتٍ، ثُمَّ يَأْوِي إِلَى فِرَاشِهِ وَيَنَامُ وَطَهُورُهُ مُغَطَّى عِنْدَ رَأْسِهِ وَسِوَاكُهُ مَوْضُوعٌ حَتَّى يَبْعَثَهُ اللهُ سَاعَتَهُ الَّتِي يَبْعَثُهُ مِنَ اللَّيْلِ فَيَتَسَوَّكُ وَيُسْبِغُ الْوُضُوءَ ثُمَّ يَقُومُ إِلَى مُصَلَّاهُ فَيُصَلِّي ثَمَانِيَ رَكَعَاتٍ يَقْرَأُ فِيهِنَّ بِأُمِّ الْكِتَابِ وَسُورَةٍ مِنَ الْقُرْآنِ وَمَا شَاءَ اللهُ، وَلَا يَقْعُدُ فِي شَيْءٍ مِنْهَا حَتَّى يَقْعُدَ فِي الثَّامِنَةِ، وَلَا يُسَلِّمُ، وَيَقْرَأُ فِي التَّاسِعَةِ ثُمَّ يَقْعُدُ فَيَدْعُو بِمَا شَاءَ اللهُ أَنْ يَدْعُوَهُ وَيَسْأَلَهُ وَيَرْغَبَ إِلَيْهِ وَيُسَلِّمُ تَسْلِيمَةً وَاحِدَةً شَدِيدَةً يَكَادُ يُوقِظُُ أَهْلَ الْبَيْتِ مِنْ شِدَّةِ تَسْلِيمِهِ، ثُمَّ يَقْرَأُ وَهُوَ قَاعِدٌ بِأُمِّ الْكِتَابِ، وَيَرْكَعُ وَهُوَ قَاعِدٌ، ثُمَّ يَقْرَأُ الثَّانِيَةَ فَيَرْكَعُ وَيَسْجُدُ وَهُوَ قَاعِدٌ، ثُمَّ يَدْعُو مَا شَاءَ اللهُ أَنْ يَدْعُوَ، ثُمَّ يُسَلِّمُ وَيَنْصَرِفُ، فَلَمْ تَزَلْ تِلْكَ صَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدُنَ فَنَقَصَ مِنَ التِّسْعِ ثِنْتَيْنِ فَجَعَلَهَا إِلَى السِّتِّ وَالسَّبْعِ وَرَكْعَتَيْهِ وَهُوَ قَاعِدٌ حَتَّى قُبِضَ عَلَى ذَلِكَ، صَلَّى اللهمُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: يُصَلِّي الْعِشَاءَ ثُمَّ يَأْوِي إِلَى فِرَاشِهِ، لَمْ يُذْكَرِ الْأَرْبَعَ رَكَعَاتٍ، وَسَاقَ الْحَدِيثَ وَقَالَ فِيهِ: فَيُصَلِّي ثَمَانِيَ رَكَعَاتٍ يُسَوِّي بَيْنَهُنَّ فِي الْقِرَاءَةِ وَالرُّكُوعِ وَالسُّجُودِ، وَلَا يَجْلِسُ فِي شَيْءٍ مِنْهُنَّ إِلَّا فِي الثَّامِنَةِ فَإِنَّهُ كَانَ يَجْلِسُ ثُمَّ يَقُومُ وَلَا يُسَلِّمُ فِيهِ فَيُصَلِّي رَكْعَةًً يُوتِرُ بِهَا، ثُمَّ يُسَلِّمُ تَسْلِيمَةً يَرْفَعُ بِهَا صَوْتَهُ حَتَّى يُوقِظَنَا، ثُمَّ سَاقَ مَعْنَاهُ .
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=197), 1, 'وَفِي رِوَايَةٍ: يُصَلِّي الْعِشَاءَ ثُمَّ يَأْوِي إِلَى فِرَاشِهِ، لَمْ يُذْكَرِ الْأَرْبَعَ رَكَعَاتٍ، وَسَاقَ الْحَدِيثَ وَقَالَ فِيهِ: فَيُصَلِّي ثَمَانِيَ رَكَعَاتٍ يُسَوِّي بَيْنَهُنَّ فِي الْقِرَاءَةِ وَالرُّكُوعِ وَالسُّجُودِ، وَلَا يَجْلِسُ فِي شَيْءٍ مِنْهُنَّ إِلَّا فِي الثَّامِنَةِ فَإِنَّهُ كَانَ يَجْلِسُ ثُمَّ يَقُومُ وَلَا يُسَلِّمُ فِيهِ فَيُصَلِّي رَكْعَةًً يُوتِرُ بِهَا، ثُمَّ يُسَلِّمُ تَسْلِيمَةً يَرْفَعُ بِهَا صَوْتَهُ حَتَّى يُوقِظَنَا، ثُمَّ سَاقَ مَعْنَاهُ .
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=197), 2, null, 'മറ്റൊരു നിവേദനിൽ: ''നബി(സ) ജനങ്ങളുമായി ഇശാഅ് നിസ്കരിക്കുമായിരുന്നു. പിന്നെ വീട്ടുകാരിലേക്ക് മടങ്ങി അവിടന്ന് നാലു റകഅത്ത് നിസ്കരിക്കും. പിന്നെ വിരിപ്പിലേക്ക് കടക്കും.'' ഹദീസ് ഇപ്രകാരം തന്നെ തുടരുന്നു; ''ഖിറാഅത്തിലും സുജൂദിലും റുകൂഇലും അവയെ സമമാക്കും'' എന്നതും സലാം വീട്ടുന്ന കാര്യം പറഞ്ഞപ്പോൾ ''ഞങ്ങളെ ഉണർത്തുംവരെ'' എന്നതും ഈ റിപ്പോർട്ടിൽ പറഞ്ഞിട്ടില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً يُوتِرُ بِتِسْعٍ، أَوْ كَمَا قَالَتْ، وَيُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، وَرَكْعَتَيِ الْفَجْرِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ. (د)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ പതിമൂന്ന് റകഅത്ത് നിസ്കരിക്കുമായിരുന്നു. ഒമ്പതാമത്തെത് വിത്റ് നിസ്കരിക്കും. ഇരുന്ന് രണ്ട് റകഅത്ത് നിസ്കരിക്കും. ഫജ്‌റിന്‌റെ രണ്ട് റകഅത്ത് ബാങ്കിനും ഇഖാമത്തിനുമിടയിൽ നിർവ്വഹിക്കും. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِتِسْعِ رَكَعَاتٍ، ثُمَّ أَوْتَرَ بِسَبْعِ رَكَعَاتٍ، وَرَكَعَ رَكْعَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ الْوِتْرِ يَقْرَأُ فِيهِمَا، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ ثُمَّ سَجَدَ. (م، د)', 'ആഇശ(റ): നബി(സ) ഒമ്പത് റകഅത്ത് വിത്റ് നിസ്കരിക്കുമായിരുന്നു, പിന്നെ ഏഴ് റകഅത്ത് വിത്റ് നിസ്കരിച്ചു. പിന്നെ വിത്റിനു ശേഷം ഇരുന്ന് രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. അതിൽ നബി(സ) ഖുർആൻ പാരായണം ചെയ്തു. റുകൂഇന് ഉദ്ദേശിച്ചാൽ എഴുന്നേറ്റ് റുകൂഅ് ചെയ്യും ശേഷം സുജൂദും ചെയ്യും. (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 596, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ سَعْدِ بْنِ هِشَامٍ قَالَ: قَدِمْتُ الْمَدِينَةَ، فَدَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَقُلْتُ: أَخْبِرِينِي عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بِالنَّاسِ صَلَاةَ الْعِشَاءِ، ثُمَّ يَأْوِي إِلَى فِرَاشِهِ فَيَنَامُ، فَإِذَا كَانَ جَوْفُ اللَّيْلِ قَامَ إِلَى حَاجَتِهِ وَإِلَى طَهُورِهِ فَتَوَضَّأَ، ثُمَّ دَخَلَ الْمَسْجِدَ فَصَلَّى ثَمَانِيَ رَكَعَاتٍ، يُخَيَّلُ إِلَيَّ أَنَّهُ يُسَوِّي بَيْنَهُنَّ فِي الْقِرَاءَةِ وَالرُّكُوعِ وَالسُّجُودِ، ثُمَّ يُوتِرُ بِرَكْعَةٍ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، ثُمَّ يَضَعُ جَنْبَهُ، فَرُبَّمَا جَاءَ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ، ثُمَّ يُغْفِي، وَرُبَّمَا شَكَكْتُ: أَغْفَى أَوْ لَا؟ حَتَّى يُؤْذِنَهُ بِالصَّلَاةِ، فَكَانَتْ تِلْكَ صَلَاتُهُ حَتَّى أَسَنَّ لَحِمَ، فَذَكَرْتُ مِنْ لَحْمِهِ مَا شَاءَ اللهُ... وَسَاقَ الْحَدِيثَ. (د,ن)', 'സഅദ് ബിൻ ഹിശാം(റ): ഞാൻ മദീനയിൽ വന്ന് ആഇശ(റ)യുടെ അടുക്കൽ ചെന്നു. ഞാൻ പറഞ്ഞു: നബി(സ) യുടെ നിസ്കാരത്തെ സംബന്ധിച്ച് എനിക്ക് പറഞ്ഞു തരിക. അവർ പറഞ്ഞു: നബി(സ) ജനങ്ങളോടു കൂടെ ഇശാഅ് നിസ്കരിക്കുമായിരുന്നു. പിന്നെ വിരിപ്പിലേക്ക് കിടന്ന് ഉറങ്ങും. അർദ്ധ രാത്രിയായാൽ പ്രാഥമിക ആവശ്യം നിർവ്വഹിക്കാനും ശുദ്ധി ചെയ്യാനും എഴുന്നേൽക്കും. ശേഷം വുദു ചെയ്ത് പള്ളിയിൽ പ്രവേശിച്ച് എട്ട് റകഅത്ത് നിസ്കരിക്കും. ഖിറാഅത്തും റുകൂഉം സുജൂദും (ദൈർഘ്യത്തിൽ) തുല്യമാക്കുന്നതായി എനിക്കു തോന്നുന്നു. പിന്നെ ഒരു റകഅത്ത് വിത്റ് നിസ്കരിക്കും. പിന്നെ ഇരുന്ന് രണ്ട് റകഅത്ത് നിസ്കരിക്കും. പിന്നെ ചെരിഞ്ഞു കിടക്കും. ചിലപ്പോൾ ബിലാൽ(റ) നിസ്കാരത്തെ കുറിച്ച് അറിയിക്കും. പിന്നെ നേരിയ ഉറക്കം ഉറങ്ങും. ചിലപ്പോൾ ഞാൻ സംശയിക്കും: നബി(സ) ഉറങ്ങിയോ അതോ ഇല്ലയോ. നിസ്കാരത്തെ കുറിച്ച് അറിയിക്കുന്നത് വരെ. പ്രായാധിക്യം വരുന്നത് വരെ അങ്ങനെയായിരുന്നു നബി(സ)യുടെ നിസ്കാരം. നബി(സ)യുടെ പേശികളെപ്പറ്റി അല്ലാഹു ഉദ്ദേശിച്ചത് മഹതി പറഞ്ഞു. ശേഷം ഹദീസ് മേൽ പ്രകാരം തുടർന്ന് പറഞ്ഞു. (ദ,ന)', 'سَعْدِ بْنِ هِشَامٍ قَالَ', 'സഅദ് ബിൻ ഹിശാം(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَقَدَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَرَآهُ اسْتَيْقَظَ فَتَسَوَّكَ وَتَوَضَّأَ وَهُوَ يَقُولُ: {إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ} [آل عمران: ١٩] حَتَّى خَتَمَ السُّورَةَ، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ أَطَالَ فِيهِمَا الْقِيَامَ وَالرُّكُوعَ وَالسُّجُودَ، ثُمَّ انْصَرَفَ فَنَامَ حَتَّى نَفَخَ، ثُمَّ فَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ بِسِتِّ رَكَعَاتٍ، كُلُّ ذَلِكَ يَسْتَاكُ ثُمَّ يَتَوَضَّأُ وَيَقْرَأُ هَؤُلَاءِ الْآيَاتِ، ثُمَّ أَوْتَرَ قَالَ عُثْمَانُ بِثَلَاثِ رَكَعَاتٍ، فَأَتَاهُ الْمُؤَذِّنُ فَخَرَجَ إِلَى الصَّلَاةِ- وَفِي رِوَايَةٍ: ثُمَّ أَوْتَرَ فَأَتَاهُ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ حِينَ طَلَعَ الْفَجْرُ، فَصَلَّى رَكْعَتَي الْفَجْرِ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ- وَهُوَ يَقُولُ: "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَاجْعَلْ فِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ خَلْفِي نُورًا، وَأَمَامِي نُورًا وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، اللَّهُمَّ وَأَعْظِمْ لِي نُورًا". (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ (രാത്രി താമസിച്ചു) ഉറങ്ങി. അപ്പോൾ നബി(സ) ഉണർന്ന് മിസ്‌വാക്ക് ചെയ്ത് വുദു ചെയ്ത് ''നിശ്ചയം ആകാശ ഭൂമികളുടെ സൃഷ്ടിപ്പിൽ......'' (ആലു ഇംറാൻ: 190) എന്നു തുടങ്ങുന്ന ആയത്തു മുതൽ ആ സൂക്തത്തിന്റെ അവസാനം വരെ ഓതുന്നതായി കണ്ടു. പിന്നെ നിന്ന് രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. അതിൽ നിർത്തം, റുകൂഅ്, സുജൂദ് എന്നിവ ദീർഘിപ്പിച്ചു പിന്നെ സലാം വീട്ടി പിരിഞ്ഞു. പിന്നെ ചെരിഞ്ഞ് കിടന്ന് കൂർക്കം വലിച്ച് ഉറങ്ങി. പിന്നെ അങ്ങനെ മൂന്നു പ്രാവശ്യ മായി ആകെ ആറു റകഅത്ത് നിർവ്വഹിച്ചു. ഓരേ പ്രാവശ്യവും മിസ്‌വാക്ക് ചെയ്യും, വുദൂഅ് ചെയ്യും. ഈ ആയത്തുകൾ ഓതും. പിന്നെ വിത്റ് നിസ്കരിച്ചു. അത് മൂന്ന് റക്അതായിരുന്നുവെന്ന് ഉസ്മാൻ(റ) പറഞ്ഞിരിക്കുന്നു. ശേഷം മുഅദ്ദിൻ വന്നു. നബി(സ) നിസ്കാരത്തിന് പുറപ്പെട്ടു. മറ്റൊരു റിപ്പോർട്ടിൽ: പിന്നെ വിത്റ് നിസ്കരിച്ചു. ഫജ്റ് ഉദിച്ചപ്പോൾ ബിലാൽ(റ) നിസ്കാരത്തെക്കുറിച്ച് അറിയിച്ചു. ഫജ്റിന്റെ രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ നിസ്കാരത്തിന് പുറപ്പെട്ടു. അന്നേരം നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തിൽ നീ വെളിച്ചം നൽക്കേണമേ, എന്റെ നാവിൽ തെളിച്ചമുണ്ടാക്കേണമേ. എന്റെ കേൾവിയിൽ പ്രകാശം പരത്തേണമേ. എന്റെ കാഴ്ചയിൽ പ്രകാശമേകേണമേ. എന്റെ മുന്നിലും പിന്നിലും മുകളിലും താഴെയും പ്രകാശം പരത്തേണമേ!. എനിക്ക് വെളിച്ചത്തെ അധികരിപ്പിക്കേണമേ.” (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], 'آل عمران: ١٩', null, 597, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: ثُمَّ أَوْتَرَ فَأَتَاهُ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ حِينَ طَلَعَ الْفَجْرُ، فَصَلَّى رَكْعَتَي الْفَجْرِ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ- وَهُوَ يَقُولُ: "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَاجْعَلْ فِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ خَلْفِي نُورًا، وَأَمَامِي نُورًا وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، اللَّهُمَّ وَأَعْظِمْ لِي نُورًا". (ق,د,ن)', 'മറ്റൊരു നിവേദനിൽ: പിന്നെ വിത്റ് നിസ്കരിച്ചു. ഫജ്റ് ഉദിച്ചപ്പോൾ ബിലാൽ(റ) നിസ്കാരത്തെക്കുറിച്ച് അറിയിച്ചു. ഫജ്റിന്റെ രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ നിസ്കാരത്തിന് പുറപ്പെട്ടു. അന്നേരം നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തിൽ നീ വെളിച്ചം നൽക്കേണമേ, എന്റെ നാവിൽ തെളിച്ചമുണ്ടാക്കേണമേ. എന്റെ കേൾവിയിൽ പ്രകാശം പരത്തേണമേ. എന്റെ കാഴ്ചയിൽ പ്രകാശമേകേണമേ. എന്റെ മുന്നിലും പിന്നിലും മുകളിലും താഴെയും പ്രകാശം പരത്തേണമേ!. എനിക്ക് വെളിച്ചത്തെ അധികരിപ്പിക്കേണമേ.” (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنِ الْفَضْلِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ لَيْلَةً عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَنْظُرَ كَيْفَ يُصَلِّي، فَقَامَ فَتَوَضَّأَ وَصَلَّى رَكْعَتَيْنِ، قِيَامُهُ مِثْلُ رُكُوعِهِ وَرُكُوعُهُ مِثْلُ سُجُودِهِ، ثُمَّ نَامَ، ثُمَّ اسْتَيْقَظَ فَتَوَضَّأَ وَاسْتَنَّ، ثُمَّ قَرَأَ بِخَمْسِ آيَاتٍ مِنْ آلِ عِمْرَانَ [١٩٠]: {إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهَارِ} فَلَمْ يَزَلْ يَفْعَلُ هَذَا حَتَّى صَلَّى عَشْرَ رَكَعَاتٍ، ثُمَّ قَامَ فَصَلَّى سَجْدَةً وَاحِدَةً فَأَوْتَرَ بِهَا، وَنَادَى الْمُنَادِي عِنْدَ ذَلِكَ فَقَامَ رَسُولُ اللهِ صَلَّى اللَّهُم عَلَيْهِ وَسَلَّمَ بَعْدَمَا سَكَتَ الْمُؤَذِّنُ، فَصَلَّى سَجْدَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ جَلَسَ حَتَّى صَلَّى الصُّبْحَ. (د)', 'ഫദ്‌ലുബ്നു അബ്ബാസ്(റ): നബി(സ) എങ്ങനെയാണ് നിസ്കരിക്കുന്നതെന്ന് നോക്കാൻ ഞാൻ ഒരു ദിവസം രാത്രി നബി(സ) യുടെ അടുക്കൽ താമസിച്ചു. തിരുമേനി(സ) എഴുന്നേറ്റ് വുദു ചെയ്ത് രണ്ടു റകഅത്ത് നിസ്കരിച്ചു. പ്രവാചകന്റെ(സ) ഖിയാം (നിൽക്കൽ) റുകൂഅ് പോലെ (ദൈർഘ്യത്തിൽ) തന്നെയാണ്. റുകൂഅ് സുജൂദ് പോലെയും. പിന്നെ ഉറങ്ങി. പിന്നെ എഴുന്നേറ്റ് മിസ്‌വാക്ക് ചെയ്ത് വുദു ചെയ്തു. പിന്നെ ആലു ഇംറാൻ സൂറത്തിലെ അഞ്ചു ആയത്തുകൾ ഓതി. പത്ത് റകഅത്ത് ആകും വരെ ഇപ്രകാരം ചെയ്തുകൊണ്ടിരുന്നു. പിന്നെ എഴുന്നേറ്റ് ഒരു റകഅത്ത് മാത്രം നിസ്കരിച്ചു. അന്നേരം വിളിക്കുന്നവൻ (മുഅദ്ദിൻ) വിളിച്ചു. മുഅദ്ദിൻ ബാങ്ക് അവസാനിപ്പിച്ച ശേഷം നബി(സ) എഴുന്നേറ്റ് ലഘുവായ രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. ശേഷം സുബ്ഹ് നിസ്കാരം വരെ ഇരുന്നു. (ദ)', 'الْفَضْلِ بْنِ عَبَّاسٍ', 'ഫദ്‌ലുബ്നു അബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], '١٩٠', null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَمَا أَمْسَى، فَقَالَ: "أَصَلَّى الْغُلَامُ". قَالُوا: نَعَمْ، فَاضْطَجَعَ، حَتَّى إِذَا مَضَى مِنَ اللَّيْلِ مَا شَاءَ اللهُ قَامَ فَتَوَضَّأَ، ثُمَّ صَلَّى سَبْعًا أَوْ خَمْسًا أَوْتَرَ بِهِنَّ، لَمْ يُسَلِّمْ إِلَّا فِي آخِرِهِنَّ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ എന്റെ എളാമ മൈമൂനയുടെ അടുക്കൽ രാത്രി താമസിച്ചു. രാത്രിയായ ശേഷം നബി(സ) വന്നു. നബി(സ) ചോദിച്ചു: കുട്ടി നിസ്കരിച്ചോ? മഹതി പറഞ്ഞു: അതെ. നബി(സ) ചെരിഞ്ഞ് കിടന്നു. രാത്രി കുറച്ച് കഴിഞ്ഞപ്പോൾ എഴുന്നേറ്റു വുദു ചെയ്തു. പിന്നീട് ഏഴോ അഞ്ചോ വിത്റ് നിസ്കരിച്ചു. അവസാനത്തേതിൽ മാത്രമേ സലാം വീട്ടിയിരുന്നുള്ളൂ. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ فِي بَيْتِ خَالَتِي مَيْمُونَةَ بِنْتِ الْحَارِثِ، فَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، ثُمَّ جَاءَ فَصَلَّى أَرْبَعًا، ثُمَّ نَامَ، ثُمَّ قَامَ يُصَلِّي، فَقُمْتُ عَنْ يَسَارِهِ، فَأَدَارَنِي فَأَقَامَنِي عَنْ يَمِينِهِ، فَصَلَّى خَمْسًا، ثُمَّ نَامَ حَتَّى سَمِعْتُ غَطِيطَهُ، أَوْ: خَطِيطَهُ، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ خَرَجَ فَصَلَّى الْغَدَاةَ. وَفِي رِوَايَةٍ: فَقَامَ فَصَلَّى رَكْعَتَيْنِ، رَكْعَتَيْنِ حَتَّى صَلَّى ثَمَانِيَ رَكَعَاتٍ، ثُمَّ أَوْتَرَ بِخَمْسٍ، وَلَمْ يَجْلِسْ بَيْنَهُنَّ. (ق،د،ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ എന്റെ എളാമ മൈമൂന ബിൻത് ഹാരിസിന്റെ അടുക്കൽ താമസിച്ചു. അപ്പോൾ നബി(സ) ഇശാഅ് നിസ്കരിച്ചു. പിന്നെ വന്ന് നാലു റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ ഉറങ്ങി. പിന്നെ എഴുന്നേറ്റ് നിസ്കരിക്കാൻ തുടങ്ങി. ഞാൻ തിരുമേനി(സ)യുടെ ഇടതു ഭാഗത്ത് നിന്നു. അപ്പോൾ നബി(സ) എന്നെ പിടിച്ച് അവിടുത്തെ വലതു ഭാഗത്ത് നിർത്തി. അങ്ങനെ അഞ്ച് റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ ഉറങ്ങി. നബി(സ)യുടെ കൂർക്കം വലി ഞാൻ കേൾക്കുക പോലും ചെയ്തു. പിന്നെ എഴുന്നേറ്റ് രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ അവിടന്ന് പുറപ്പെട്ട് സുബ്ഹ് നിസ്കരിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഈരണ്ട് റകഅത്തായി എട്ട് റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ അഞ്ചു റകഅത്ത് വിത്റ് നിസ്കരിച്ചു. അവക്കിടയിൽ ഇരുന്നില്ല. (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=204), 1, 'وَفِي رِوَايَةٍ: فَقَامَ فَصَلَّى رَكْعَتَيْنِ، رَكْعَتَيْنِ حَتَّى صَلَّى ثَمَانِيَ رَكَعَاتٍ، ثُمَّ أَوْتَرَ بِخَمْسٍ، وَلَمْ يَجْلِسْ بَيْنَهُنَّ. (ق،د،ن)', 'മറ്റൊരു നിവേദനിൽ: ഈരണ്ട് റകഅത്തായി എട്ട് റകഅത്ത് നിസ്കരിച്ചു. പിന്നെ അഞ്ചു റകഅത്ത് വിത്റ് നിസ്കരിച്ചു. അവക്കിടയിൽ ഇരുന്നില്ല. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً بِرَكْعَتَيْهِ قَبْلَ الصُّبْحِ: يُصَلِّي سِتًّا مَثْنَى مَثْنَى، وَيُوتِرُ بِخَمْسٍ لَا يَقْعُدُ بَيْنَهُنَّ إِلَّا فِي آخِرِهِنَّ. (د)', 'ആഇശാ(റ): സുബ്ഹിക്ക് മുമ്പുള്ള രണ്ട് റകഅത്ത് അടക്കം നബി(സ) പതിമൂന്ന് റകഅത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. ആറു റകഅത്ത് ഈരണ്ടായി നിസ്കരിക്കും. അഞ്ച് റകഅത്ത് വിത്റായി നിസ്കരിക്കും. അവസാനത്തെ റകഅത്തിലല്ലാതെ അവക്കിടയിൽ ഇരിക്കാറില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا أَخْبَرَتْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بِاللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً بِرَكْعَتَيِ الْفَجْرِ. (م,د)', 'ആഇശ(റ): സുബ്ഹിയുടെ രണ്ട് റകഅത്ത് അടക്കം നബി(സ) രാത്രി പതിമൂന്ന് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعِشَاءَ، ثُمَّ صَلَّى ثَمَانِيَ رَكَعَاتٍ قَائِمًا، وَرَكْعَتَيْنِ بَيْنَ الْأَذَانَيْنِ، وَلَمْ يَكُنْ يَدَعُهُمَا، وَفِي رِوَايَةٍ: وَرَكْعَتَيْنِ جَالِسًا بَيْنَ الْأَذَانَيْنِ. (د)', 'ആഇശ(റ): നബി(സ) ഇശാഅ് നിസ്കരിച്ചു. പിന്നെ നിന്ന് എട്ട് റക്അത്ത് നിസ്കരിച്ചു. രണ്ടു ബാങ്കുകൾക്കിടയിൽ (ബാങ്കും ഇഖാമത്തും) രണ്ടു റകഅത്തും. അവ ഉപേക്ഷിക്കാറില്ലായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: രണ്ടു ബാങ്കിനിടയിൽ ഇരുന്ന് രണ്ടു റക്അത്തും നിർവ്വഹിച്ചു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=207), 1, 'وَفِي رِوَايَةٍ: وَرَكْعَتَيْنِ جَالِسًا بَيْنَ الْأَذَانَيْنِ. (د)', 'മറ്റൊരു നിവേദനിൽ: രണ്ടു ബാങ്കിനിടയിൽ ഇരുന്ന് രണ്ടു റക്അത്തും നിർവ്വഹിച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: بِكَمْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ؟ قَالَتْ: كَانَ يُوتِرُ بِأَرْبَعٍ وَثَلَاثٍ، وَسِتٍّ وَثَلَاثٍ، وَثَمَانٍ وَثَلَاثٍ، وَعَشْرٍ وَثَلَاثٍ، وَلَمْ يَكُنْ يُوتِرُ بِأَنْقَصَ مِنْ سَبْعٍ، وَلَا بِأَكْثَرَ مِنْ ثَلَاثَ عَشْرَةَ. وَفِي رِوَايَةٍ: وَلَمْ يَكُنْ يُوتِرُ بِرَكْعَتَيْنِ قَبْلَ الْفَجْرِ، قُلْتُ: مَا يُوتِرُ؟ قَالَتْ: لَمْ يَكُنْ يَدَعُ ذَلِكَ. (د)', 'ആഇശ(റ): എത്രയായിരുന്നു നബി(സ) വിത്റ് നിസ്കരിച്ചിരുന്നത് എന്ന് അവർ ചോദിക്കപ്പെട്ടു. മഹതി പറഞ്ഞു: നബി(സ) നാലും മൂന്നുമായി, ആറും മൂന്നുമായി, എട്ടും മൂന്നുമായി, പത്തും മൂന്നുമായി, എന്നിങ്ങനെ വിത്റ് നിസ്കരിക്കാറുണ്ടായിരുന്നു. ഏഴിനേക്കാൾ കുറവും പതിമൂന്നിനേക്കാൾ കൂടുതലും വിത്റ് നിസ്കരിക്കാറില്ലായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഫജ്‌റിന്റെ മുമ്പുള്ള രണ്ടു റക്അത്തു കൊണ്ട് റസൂൽ(സ) വിത്റ് ആക്കി നിസ്കരിക്കാറില്ലായിരുന്നു. റിപ്പോർട്ടർ ചോദിച്ചു: എന്തായിരുന്നു നബി(സ)വിത്റ് നിസ്കരിച്ചത്. മഹതി പറഞ്ഞു. അത് ഉപേക്ഷിക്കാറില്ലായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=208), 1, 'وَفِي رِوَايَةٍ: وَلَمْ يَكُنْ يُوتِرُ بِرَكْعَتَيْنِ قَبْلَ الْفَجْرِ، قُلْتُ: مَا يُوتِرُ؟ قَالَتْ: لَمْ يَكُنْ يَدَعُ ذَلِكَ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഫജ്‌റിന്റെ മുമ്പുള്ള രണ്ടു റക്അത്തു കൊണ്ട് റസൂൽ(സ) വിത്റ് ആക്കി നിസ്കരിക്കാറില്ലായിരുന്നു. റിപ്പോർട്ടർ ചോദിച്ചു: എന്തായിരുന്നു നബി(സ)വിത്റ് നിസ്കരിച്ചത്. മഹതി പറഞ്ഞു. അത് ഉപേക്ഷിക്കാറില്ലായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، وَقَدْ سُئِلَ: كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ قَالَ: بِتُّ عِنْدَهُ لَيْلَةً وَهُوَ عِنْدَ مَيْمُونَةَ، فَنَامَ، حَتَّى إِذَا ذَهَبَ ثُلُثُ اللَّيْلِ أَوْ نِصْفُهُ اسْتَيْقَظَ، فَقَامَ إِلَى شَنٍّ فِيهِ مَاءٌ، فَتَوَضَّأَ وَتَوَضَّأْتُ مَعَهُ، ثُمَّ قَامَ فَقُمْتُ إِلَى جَنْبِهِ عَلَى يَسَارِهِ، فَجَعَلَنِي عَلَى يَمِينِهِ، ثُمَّ وَضَعَ يَدَهُ عَلَى رَأْسِي كَأَنَّهُ يَمَسُّ أُذُنِي، كَأَنَّهُ يُوقِظُنِي، فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَدْ قَرَأَ فِيهِمَا بِأُمِّ الْقُرْآنِ فِي كُلِّ رَكْعَةٍ، ثُمَّ سَلَّمَ، ثُمَّ صَلَّى حَتَّى صَلَّى إِحْدَى عَشْرَةَ رَكْعَةً بِالْوِتْرِ، ثُمَّ نَامَ، فَأَتَاهُ بِلَالٌ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: الصَّلَاةَ يَا رَسُولَ اللَّهِ. فَقَامَ فَرَكَعَ رَكْعَتَيْنِ، ثُمَّ صَلَّى لِلنَّاسِ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം നബി(സ)യുടെ രാത്രിനിസ്കാരത്തെ സംബന്ധിച്ച് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: മൈമൂന(റ)യുടെ അടുത്തായിരിക്കെ ഒരിക്കൽ ഞാൻ തിരുമേനിയോട് കൂടെ താമസിച്ചു. തിരുമേനി(സ) ഉറങ്ങി. രാത്രിയുടെ മൂന്നിലൊന്നോ പകുതിയോ കഴിഞ്ഞപ്പോൾ എഴുന്നേറ്റ് വെള്ളമുള്ള ഒരു പാത്രത്തിനടുത്തു പോയി വുദു ചെയ്തു. ഞാനും തിരുമേനിയുടെ കൂടെ വുദൂ ചെയ്തു. പിന്നെ തിരുമേനി നിന്നു ഞാൻ തങ്ങളുടെ ഇടത് ഭാഗത്തായി നിന്നു. അപ്പോൾ തിരുമേനി എന്നെ വലത് ഭാഗത്തേക്കാക്കി. പിന്നെ എന്റെ തലക്ക് മുകളിലായി കൈ വച്ചു. അത് എന്റെ ചെവി തടവും പോലെയും. എന്നെ ഉണർത്താനാണെന്നു എനിക്കു തേന്നി ഫാത്തിഹ ഒതി ചുരുങ്ങിയ രണ്ട് റകഅത്ത് നിസ്കരിച്ച് സലാം വീട്ടി.പിന്നെ പതിനൊന്ന് റകഅത്ത് വിത്റ് നിസ്കരിച്ച് സലാം വീട്ടി. പിന്നെ ഉറങ്ങി. ബിലാൽ(റ) തിരുമേനിയുടെ അടുക്കൽ വന്ന് അല്ലാഹുവിന്റെ ദൂതരേ നിസ്കാരം എന്നു പറഞ്ഞു. അപ്പോൾ എഴുന്നേറ്റ് രണ്ടു റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 599, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنِ الْأَسْوَدِ بْنِ يَزِيدَ: أَنَّهُ دَخَلَ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَسَأَلَهَا عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ، فَقَالَتْ: كَانَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً مِنَ اللَّيْلِ، ثُمَّ إِنَّهُ صَلَّى إِحْدَى عَشْرَةَ رَكْعَةً، وَتَرَكَ رَكْعَتَيْنِ ثُمَّ قُبِضَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قُبِضَ وَهُوَ يُصَلِّي مِنَ اللَّيْلِ تِسْعَ رَكَعَاتٍ، وَكَانَ آخِرُ صَلَاتِهِ مِنَ اللَّيْلِ الْوِتْرَ. (م،د،ت،ن)', 'അസ്‌വദ് ബിൻ യസീദ്(റ): അദ്ദേഹം ആഇശ(റ) യുടെ അടുക്കൽ ചെന്ന് നബി(സ)യുടെ രാത്രി നിസ്കാരത്തെ സംബന്ധിച്ച് ചോദിച്ചു. ആഇശ(റ) പറഞ്ഞു: രാത്രിയിൽ തിരുമേനി പതിമൂന്ന് റകഅത്ത് നിസ്കരിക്കുമായിരുന്നു. പിന്നെ രണ്ടു ചുരുക്കി പതിനൊന്ന് റകഅത്ത് നിസ്കരിച്ചു. തിരുമേനി(സ)യുടെ വഫാതിനോടടുത്ത കാലത്ത് ഒമ്പത് റക്അത്തായിരുന്നു നിസ്കരിച്ചിരുന്നത്. പ്രവാചകന്റെ രാത്രിയിലെ അവസാന നിസ്കാരം വിത്റായിരുന്നു. (മു,ദ,തു,ന)', 'الْأَسْوَدِ بْنِ يَزِيدَ', 'അസ്‌വദ് ബിൻ യസീദ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ، فَصَلَّى ثَلَاثَ عَشْرَةَ رَكْعَةً مِنْهَا رَكْعَتَا الْفَجْرِ، حَزَرْتُ قِيَامَهُ فِي كُلِّ رَكْعَةٍ بِقَدْرِ: {يَا أَيُّهَا الْمُزَّمِّلُ}. (د،ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): ഞാൻ എന്റെ എളാമ മൈമൂന(റ)യുടെ അടുക്കൽ രാത്രി താമസിച്ചു. നബി(സ) നിസ്കരിക്കാനെഴുന്നേറ്റു. എന്നിട്ട് ഫജ്റിന്റെ രണ്ട് റക്അത്തടക്കം പതിമൂന്ന് റക്അത്ത് നിസ്കരിച്ചു. ഓരോ റക്അത്തിലും തിരുമേനിയുടെ നിർത്തം മുസ്സമ്മിൽ സൂറത്ത് ഓതുന്നത്ര ഞാൻ കണക്കാക്കി. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: لَأَرْمُقَنَّ صَلَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّيْلَةَ، فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ صَلَّى رَكْعَتَيْنِ طَوِيلَتَيْنِ طَوِيلَتَيْنِ طَوِيلَتَيْنِ، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ أَوْتَرَ فَذَلِكَ ثَلَاثَ عَشْرَةَ رَكْعَةً. (م،د،جه)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ): ഞാൻ റസൂൽ(സ) രാത്രി നിസ്കരിക്കുന്നത് നിരീക്ഷിക്കുക തന്നെ ചെയ്യും. തിരുമേനി(സ) ആദ്യം രണ്ട് റക്അത്തുകൾ ലഘുവായി നിസ്കരിച്ചു. പിന്നീട് ദീർഘമായി ഈരണ്ട് റകഅത്തായി ആറു റകഅത്തുകൾ നിസ്കരിച്ചു. പിന്നീട് അതിലും ചെറുതും, പിന്നെ അതിലും ചെറുതുമാ ഈരണ്ടു റക്അത്തുകൾ നിസ്കരിച്ചു. പിന്നീട് ഒരൊറ്റ റക്അത്തും അങ്ങനെ ആകെ പതിമൂന്ന് റക്അത്തുകൾ നിർവ്വഹിച്ചു. (മു,ദ,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ بَاتَ لَيْلَةً عِنْدَ مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ خَالَتُهُ، قَالَ: فَاضْطَجَعْتُ فِي عِرْضِ الْوِسَادَةِ وَاضْطَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَهْلُهُ فِي طُولِهَا، فَنَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا انْتَصَفَ اللَّيْلُ - أَوْ: قَبْلَهُ بِقَلِيلٍ أَوْ بَعْدَهُ بِقَلِيلٍ - اسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَلَسَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ بِيَدِهِ، ثُمَّ قَرَأَ الْعَشْرَ الْآيَاتِ الْخَوَاتِمَ مِنْ سُورَةِ آلِ عِمْرَانَ، ثُمَّ قَامَ إِلَى شَنٍّ مُعَلَّقَةٍ، فَتَوَضَّأَ مِنْهَا فَأَحْسَنَ وَضُوءَهُ ثُمَّ قَامَ يُصَلِّي، قَالَ ابْنُ عَبَّاسٍ: فَقُمْتُ فَصَنَعْتُ مِثْلَ مَا صَنَعَ، ثُمَّ ذَهَبْتُ فَقُمْتُ إِلَى جَنْبِهِ، فَوَضَعَ يَدَهُ الْيُمْنَى عَلَى رَأْسِي، وَأَخَذَ بِأُذُنِي الْيُمْنَى يَفْتِلُهَا، فَصَلَّى رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ أَوْتَرَ، ثُمَّ اضْطَجَعَ حَتَّى أَتَاهُ الْمُؤَذِّنُ فَقَامَ فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ خَرَجَ فَصَلَّى الصُّبْحَ. (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): തന്റെ എളയുമ്മയും നബി(സ)യുടെ ഭാര്യയുമായ മൈമൂന(റ)യുടെ അടുക്കൽ അദ്ദേഹം ഒരിക്കൽ രാത്രി താസിച്ചു. അദ്ദേഹം പറയുന്നു: ഞാൻ തലയണയുടെ വീതിയിലും തിരുമേനിയും മൈമൂന(റ)യും നീളത്തിലും കിടന്നു. നബി(സ) ഉറങ്ങി. പാതി രാത്രിയോ അതിനൽപം മുമ്പോ ശേഷമോ ആയപ്പോൾ നബി(സ) എഴുന്നേറ്റു. ഉറക്കച്ചുവ ഇല്ലാതാക്കാൻ മുഖം തടവിക്കൊണ്ടിരുന്നു. പിന്നെ ആലു ഇംറാൻ സുറത്തിലെ അവസാനത്തെ പത്ത് ആയത്തുകൾ ഓതി. പിന്നെ വെള്ളമുള്ള പാത്രത്തിനടുത്തേക്ക് ചെന്ന് അവിടെ നിന്ന് നല്ല നിലയിൽ വുദൂ ചെയ്ത് നിസ്കരിക്കാൻ തുടങ്ങി. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു. ഞാനും എഴുന്നേറ്റ് റസൂൽ(സ) ചെയ്യുന്നതു പോലെ ചെയ്തു. പിന്നെ തിരുമേനിയുടെ വശത്തു നിന്നു. അപ്പോൾ റസൂലി(സ)ന്റെ വലതു കൈ എന്റെ തലക്കുമേൽ വെച്ചു. എന്റെ വലതു ചെവി പിടിച്ച് തിരുമ്മുകയും ചെയ്തു. പിന്നെ ആറ് പ്രാവശ്യം ഈ രണ്ടു റക്അത്ത് നിസ്കരിച്ചു. അവസാനം ഒരു റക്അത്തും നിസ്കരിച്ചു; പിന്നെ ബാങ്ക് വിളിക്കുന്നവൻ എത്തുന്നതു വരെ ചെരിഞ്ഞ്കിടന്നു. പിന്നീട് എഴുന്നേറ്റ് രണ്ട് റക്അത്ത് ലഘുവായി നിസ്കരിക്കുകയും ചെയ്തു. പിന്നീട് പള്ളിയിൽ പോയി സുബ്ഹ് നിസ്കരിച്ചു. (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 600, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيُوقِظُهُ اللَّهُ عَزَّ وَجَلَّ، فَمَا يَجِيءُ السَّحَرُ حَتَّى يَفْرُغَ مِنْ حِزْبِهِ . (د)', 'ആയിശ(റ)യിൽ നിന്ന് നിവേദനം. നിശ്ചയം അല്ലാഹു നബി(സ)യെ ഉണർത്തുമായിരുന്നു. അങ്ങനെ പുലർച്ചസമയം (സഹർ) ആകും മുമ്പ് നബി(സ) നിശ്ചിത ഭാഗം ഖുർആൻ ഓതി അതിൽനിന്നും വിരമിക്കുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ لَهَا: أَيَّ حِينٍ كَانَ يُصَلِّي؟ قَالَتْ: كَانَ إِذَا سَمِعَ الصُّرَاخَ قَامَ فَصَلَّى. (ق,د,ن)', 'റസൂലി(സ)ന്റെ നമസ്കാരത്തെക്കുറിച്ച് ആയിശ(റ): മഹതിയോട് ഞാൻ ചോദിച്ചു: ഏത് സമയത്തായിരുന്നു റസൂൽ(സ) നമസ്കരിച്ചിരുന്നത്? മഹതി പറഞ്ഞു: നബി(സ) കോഴിയുടെ കൂവൽ കേട്ടാൽ എഴുന്നേറ്റ് നിസ്കരിക്കുമായിരുന്നു. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'റസൂലി(സ)ന്റെ നമസ്കാരത്തെക്കുറിച്ച് ആയിശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا أَلْفَاهُ السَّحَرُ عِنْدِي إِلَّا نَائِمًا، تَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,جه)', 'ആഇശ(റ): എന്റെ കൂടെയാവുമ്പോൾ സഹ്റിന്റെ (പുലർച്ച) സമയത്ത് ഉറങ്ങുന്നതായിട്ടല്ലാതെ ഞാൻ പ്രവാചകൻ(സ)യെ ദർശിച്ചിട്ടില്ല. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ إِذَا حَزَبَهُ أَمْرٌ صَلَّى. (د)', 'ആയിശ(റ): നബി(സ)ക്ക് വല്ല ബുദ്ധിമുട്ടും വന്നാൽ അവിടുന്ന് നമസ്കരിക്കുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ أَبِيتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُهُ بِوَضُوئِهِ وَحَاجَتِهِ، فَقَالَ: "سَلْنِي". فَقُلْتُ: أَسْأَلُكَ مُرَافَقَتَكَ فِي الْجَنَّةِ، قَالَ: "أَوْ غَيْرَ ذَلِكَ"، قُلْتُ: هُوَ ذَاكَ، قَالَ: "فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ". (ق,د,ت,ن,جه)', 'റബീഅത്ബ്നു കഅ്ബുൽ അസ്‌ലമീ(റ): ഞാൻ നബി(സ)യോടു കൂടെ രാപാർക്കുകയായിരുന്നു. അപ്പോൾ ഞാൻ നബി(സ)ക്ക് വുദു ചെയ്യുവാനുള്ള വെള്ളവും ആവശ്യസാധനവും കൊണ്ടു വന്നു കൊടുത്തു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ ചോദിക്കുക." അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ അങ്ങയോട് കൂടെ സ്വർഗത്തിൽ സഹവസിക്കാൻ ആവശ്യപ്പെടുന്നു. നബി ചോദിച്ചു: "അതല്ലാത്ത വല്ലതും ഉണ്ടോ?" ഞാൻ പറഞ്ഞു: റസൂലേ! അതുതന്നെയാണ് വേണ്ടത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എങ്കിൽ ദേഹേച്ചയെ അവഗണിച്ച് നീ സുജൂദ് വർദ്ധിപ്പിച്ചു കൊണ്ട് എന്നെ സഹായിക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ', 'റബീഅത്ബ്നു കഅ്ബുൽ അസ്‌ലമീ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 601, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ فِي هَذِهِ الْآيَةِ: {تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ} [السجد: ١٦] قَالَ: كَانُوا يَتَيَقَّظُونَ مَا بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ يُصَلُّونَ. وَكَانَ الْحَسَنُ يَقُولُ: قِيَامُ اللَّيْلِ. (د)', '"ഭയത്തോടും പ്രത്യാശയോടും കൂടി തങ്ങളുടെ രക്ഷിതാവിനോടു പ്രാർത്ഥിക്കുവാനായി; കിടന്നുറങ്ങുന്ന സ്ഥലങ്ങൾ വിട്ട് അവരുടെ പാർശ്വങ്ങൾ അകലുന്നതാണ്. അവർക്ക് നാം നൽകിയതിൽ നിന്ന് അവർ ചെലവഴിക്കുകയും ചെയ്യും" (സൂറത്തുസ്സജദ: 16) എന്ന ഈ ഖുർആനിക സൂക്തത്തെക്കുറിച്ച് അനസ്ബ്നു മാലികി(റ)ൽ നിന്ന് നിവേദനം: അദ്ദേഹം പറഞ്ഞു: "അവർ മഗ്‌രിബിന്റെയും ഇശാഇന്റെയും ഇടയിൽ ഉണർന്നിരുന്നു നമസ്കരിക്കുന്നവരായിരുന്നു." ''രാത്രി നമസ്കാരം'' എന്നാണ് ഇതിനെ കുറിച്ച് ഹസൻ(റ) പറയാറുണ്ടായിരുന്നത്. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', null, null, null, array['د']::text[], array['ദ']::text[], 'السجد: ١٦', null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَنْزِلُ رَبُّنَا تَبَارَكَ اسْمُهُ كُلَّ لَيْلَةٍ، حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ إِلَى سَمَاءِ الدُّنْيَا فَيَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ؟ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ؟ حَتَّى يَطْلُعَ الْفَجْرُ". فَلِذَلِكَ كَانُوا يُفَضِّلُونَ صَلَاةَ آخِرِ اللَّيْلِ عَلَى صَلَاةِ أَوَّلِهِ. (ق,د,ت,جه)', 'അബൂഹുറൈറ: നബി(സ) പറഞ്ഞു: "എല്ലാ രാത്രിയും അവസാനത്തെ മൂന്നിലൊരു ഭാഗം ശേഷിക്കുമ്പോൾ അനുഗ്രഹ ദാദാവായ നമ്മുടെ നാഥൻ ഒന്നാം ആകാശത്തേക്ക് ഇറങ്ങും. എന്നിട്ട് അവൻ പുലരും വരെ ഇപ്രകാരം പറഞ്ഞു കൊണ്ടിരിക്കും: "എന്നോട് തേടുന്നവന് ഞാൻ കൊടുക്കുകയും എന്നോട് പ്രാർത്ഥിക്കുന്നവന് ഞാനുത്തരം നൽകുകയും എന്നോട് മാപ്പപേക്ഷിക്കുന്നവന് മാപ്പു നൽകുകയും ചെയ്യും." ഇക്കാരണത്താൽ അവർ രാത്രിയുടെ അവസാന ഭാഗത്തെ നിസ്കാരം ആദ്യഭാഗത്തെ നിസ്കാരത്തെക്കാൾ ശ്രേഷ്ടമായി ഗണിച്ചിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ فِي قَوْلِهِ عَزَّ وَجَلَّ: {كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ} [الذاريات: ١٧] قَالَ: كَانُوا يُصَلُّونَ فِيمَا بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، زَادَ فِي حَدِيثِ يَحْيَى وَكَذَلِكَ: {تَتَجَافَىٰ جُنُوبُهُمْ} [السجدة: ١٦]. (د)', '''രാത്രിയിൽ നിന്നുള്ള അൽപ ഭാഗമേ അവർ ഉറങ്ങാറുണ്ടായിരുന്നുള്ളൂ'' എന്ന ഖുർആനിക സൂക്തത്തെക്കുറിച്ച് അനസി(റ)ൽ നിന്ന് നിവേദനം: അദ്ദേഹം പറഞ്ഞു. "അവർ മഗ്‌രിബിന്റേയും ഇശാഇന്റെയും ഇടയിൽ നമസ്കരിക്കുന്നവരായിരുന്നു." "അവരുടെ പാർശ്വങ്ങൾ അകലുന്നതാണ്" എന്ന സൂക്തവും ഇപ്രകാരമാണ് എന്ന് അദ്ദേഹം യഹ്‌യ(റ)യുടെ ഹദീസിൽ കൂട്ടിച്ചേർത്തിരിക്കുന്നു. (ദ)', 'أَنَسٍ', null, null, null, array['د']::text[], array['ദ']::text[], 'السجدة: ١٦', null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ مَسْرُوقٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ لِعَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَيُّ الْأَعْمَالِ أَحَبُّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتِ: الدَّائِمُ. قُلْتُ: فَأَيُّ اللَّيْلِ كَانَ يَقُومُ؟ قَالَتْ: إِذَا سَمِعَ الصَّارِخَ. (ن)', 'മസ്‌റൂഖി(റ)ൽ നിന്ന് നിവേദനം: അദ്ദേഹം പറഞ്ഞു: "ഞാൻ ആയിശ(റ)യോട് ചോദിച്ചു: റസൂലി(സ)ന് ഏറ്റവും ഇഷ്ടപ്പെട്ട ആരാധനാ കർമം ഏതാണ്?". മഹതി പറഞ്ഞു: ''പതിവായി ചെയ്യുന്നത്''. ഞാൻ ചോദിച്ചു: എങ്കിൽ രാത്രിയുടെ ഏത് സമയത്തായിരുന്നു റസൂൽ(സ) നിസ്കരിച്ചിരുന്നത്? മഹതി പറഞ്ഞു: കോഴിയുടെ കൂവൽ കേട്ടാൽ. (ന)', 'مَسْرُوقٍ', 'മസ്‌റൂഖി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، مَنْ أَسْلَمَ مَعَكَ؟ قَالَ: "حُرٌّ وَعَبْدٌ". قُلْتُ: هَلْ مِنْ سَاعَةٍ أَقْرَبُ إِلَى اللهِ مِنْ أُخْرَى؟ قَالَ: "نَعَمْ، جَوْفُ اللَّيْلِ الْأَوْسَطُ". (جه)', 'അംറുബ്നു അബസ(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്ന് ചോദിച്ചു: ''അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങയോടൊപ്പം മുസ്‌ലിമായതാരാണ്?'' നബി(സ): ''ഒരടിമയും ഒരു സ്വതന്ത്രനും''. ഞാൻ: ''ഇതര സമയത്തേക്കാൾ അല്ലാഹുവിലേക്ക് കൂടുതൽ അടുക്കാവുന്ന സമയമുണ്ടോ?'' നബി(സ): ''അതെ, അർദ്ധരാത്രിയുടെ ഉള്ളിൽ.'' (ജ)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنَامُ أَوَّلَ اللَّيْلِ وَيُحْيِي آخِرَهُ. (جه)', 'ആയിശ(റ): റസൂൽ(സ) രാത്രിയുടെ ആദ്യഭാഗത്തിൽ ഉറങ്ങുകയും അവസാന ഭാഗത്തെ ജീവിപ്പിക്കുകയും (ഉണർന്നിരിക്കുകയും) ചെയ്യുമായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ رِفَاعَةَ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يُمْهِلُ، حَتَّى إِذَا ذَهَبَ مِنَ اللَّيْلِ نِصْفُهُ أَوْ ثُلُثَاهُ قَالَ: لَا يَسْأَلَنَّ عِبَادِي غَيْرِي. مَنْ يَدْعُنِي أَسْتَجِبْ لَهُ، مَنْ يَسْأَلْنِي أُعْطِهِ، مَنْ يَسْتَغْفِرْنِي أَغْفِرْ لَهُ. حَتَّى يَطْلُعَ الْفَجْرُ". (ز: فى إسناده ضعيف) (جه)', 'രിഫാഅത്തുൽ ജുഹനി: നബി(സ) പറഞ്ഞു: "അല്ലാഹു സാവകാശം നൽകും. അങ്ങനെ രാത്രിയുടെ പകുതിയോ മൂന്നിൽ രണ്ട് ഭാഗമോ കഴിഞ്ഞാൽ പുലരും വരെ അവൻ പറയും: ''എന്റെ അടിമകൾ എന്നോടല്ലാതെ ഒന്നും ചോദിക്കരുത്. എന്നോട് പ്രാർത്ഥിച്ചവന് ഞാൻ ഉത്തരം നൽകും. എന്നോട് ചോദിച്ചവന് ഞാൻ നൽകും. എന്നോട് പൊറുക്കൽ തേടുന്നവന് ഞാൻ പൊറുത്തു കൊടുക്കും." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'رِفَاعَةَ الْجُهَنِيِّ', 'രിഫാഅത്തുൽ ജുഹനി', null, null, array['جه']::text[], array['ജ']::text[], null, 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا نَعَسَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَرْقُدْ حَتَّى يَذْهَبَ عَنْهُ النَّوْمُ، فَإِنَّ أَحَدَكُمْ إِذَا صَلَّى وَهُوَ نَاعِسٌ لَعَلَّهُ يَذْهَبُ يَسْتَغْفِرُ فَيَسُبُّ نَفْسَهُ". (ق,د,ت,ن,جه)', 'ആയിശ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നിസ്കാരത്തിൽ ഉറങ്ങിത്തൂങ്ങിയാൽ ഉറക്കം പോകുന്നത് വരെ അവൻ ഉറങ്ങട്ടെ. കാരണം, ഉറങ്ങിത്തൂങ്ങി നിസ്കരിച്ചാൽ പൊറുക്കൽ തേടാൻ ഒരുങ്ങി സ്വന്തത്തെ ചീത്തപറയൽ ആയിരിക്കും ഉണ്ടാവുക." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ، فَاسْتَعْجَمَ الْقُرْآنُ عَلَى لِسَانِهِ، فَلَمْ يَدْرِ مَا يَقُولُ فَلْيَضْطَجِعْ". (م,د)', 'അബൂഹുറൈറ: നബി(സ) പറഞ്ഞു: "ഒരാൾ രാത്രി എഴുന്നേറ്റ് ഖുർആൻ ഓതി. ഖുർആൻ അവന്റെ നാവിൽ അവ്യക്തമാവുകയും എന്താണ് അവൻ പറയുന്നതെന്ന് അറിയാതിരിക്കുകയും ചെയ്താൽ അവൻ കിടന്നു കൊള്ളട്ടെ." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ، وَحَبْلٌ مَمْدُودٌ بَيْنَ سَارِيَتَيْنِ، فَقَالَ: "مَا هَذَا الْحَبْلُ". فَقِيلَ: يَا رَسُولَ اللهِ، هَذِهِ حَمْنَةُ بِنْتُ جَحْشٍ تُصَلِّي، فَإِذَا أَعْيَتْ تَعَلَّقَتْ بِهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِتُصَلِّ مَا أَطَاقَتْ، فَإِذَا أَعْيَتْ فَلْتَجْلِسْ". قَالَ زِيَادٌ فَقَالَ: "مَا هَذَا". فَقَالُوا: لِزَيْنَبَ تُصَلِّي، فَإِذَا كَسِلَتْ أَوْ فَتَرَتْ أَمْسَكَتْ بِهِ. فَقَالَ: "حُلُّوهُ، فَقَالَ لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ، فَإِذَا كَسِلَ- أَوْ فَتَرَ- فَلْيَقْعُدْ." (ق,د,ن)', 'അനസ്: നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചു. രണ്ട് തൂണുകൾക്കിടയിൽ ഒരു കയർ തൂക്കിയിട്ടുണ്ടായിരുന്നു. നബി(സ) ചോദിച്ചു: ''ഈ കയറെന്താണ്?'' നബി(സ)യോട് പറയപ്പെട്ടു: ''ഹംനത് ബിൻത് ജഹ്ശ് നിസ്കരിച്ച് ക്ഷീണിച്ചാൽ പിടിച്ച് തൂങ്ങാൻ ഉപയോഗിക്കുന്ന കയറാണിത്.'' നബി(സ) പറഞ്ഞു: ''അവൾക്ക് സാധിക്കുന്നത്ര അവൾ നിസ്കരിക്കട്ടെ. ക്ഷീണിച്ചാൽ അവൾ ഇരിക്കട്ടെ.'' മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) ചോദിച്ചു: ''ഇതെന്താണ്?'' അവർ പറഞ്ഞു: ''ഇത് സൈനബക്ക് നിസ്കരിക്കാനുള്ളതാണ്. അവൾക്ക് മടുപ്പ് വരികയോ ക്ഷീണിക്കുകയോ ചെയ്താൽ ഇതിൽ പിടിക്കും.'' നബി(സ) പറഞ്ഞു: ''അത് അഴിച്ചിടുക. ഉന്മേഷത്തോടെ നിസ്കരിച്ചാൽ മതി. ക്ഷീണിച്ചാൽ അല്ലെങ്കിൽ മടുപ്പ് തോന്നിയാൽ അവൻ ഇരിക്കട്ടെ.'' (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 603, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=228), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) ചോദിച്ചു: ''ഇതെന്താണ്?'' അവർ പറഞ്ഞു: ''ഇത് സൈനബക്ക് നിസ്കരിക്കാനുള്ളതാണ്. അവൾക്ക് മടുപ്പ് വരികയോ ക്ഷീണിക്കുകയോ ചെയ്താൽ ഇതിൽ പിടിക്കും.'' നബി(സ) പറഞ്ഞു: ''അത് അഴിച്ചിടുക. ഉന്മേഷത്തോടെ നിസ്കരിച്ചാൽ മതി. ക്ഷീണിച്ചാൽ അല്ലെങ്കിൽ മടുപ്പ് തോന്നിയാൽ അവൻ ഇരിക്കട്ടെ.'' (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الَّذِي يُصَلِّي قَاعِدًا؟ قَالَ: "مَنْ صَلَّى قَائِمًا فَهُوَ أَفْضَلُ، وَمَنْ صَلَّى قَاعِدًا فَلَهُ نِصْفُ أَجْرِ الْقَائِمِ، وَمَنْ صَلَّى نَائِمًا فَلَهُ نِصْفُ أَجْرِ الْقَاعِدِ". (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ഞാൻ നബി(സ)യോട് ഇരുന്ന് നമസ്ക്കരിക്കുന്നവന്റെ കാര്യത്തെക്കുറിച്ച് ചോദിച്ചു. തിരുനബി(സ) പറഞ്ഞു: "വല്ലവനും നിന്ന് കൊണ്ട് നിസ്കരിക്കുകയാണെങ്കിൽ അതാണ് ഏറ്റവും ശ്രേഷ്ടമായത്. എന്നാൽ വല്ലവനും ഇരുന്ന് നിസ്ക്കരിക്കുകയാണെങ്കിൽ അവന്ന് നിന്ന് നിസ്ക്കരിക്കുന്നവന്റെ പകുതി പ്രതിഫലം ഉണ്ട്. വല്ലവനും ഉറക്കം തൂങ്ങിക്കൊണ്ട് നിസ്കരിക്കുകയാണെങ്കിൽ അവന്ന് ഇരുന്ന് നിസ്കരിക്കുന്നവന്റെ പകുതി പ്രതിഫലം ആണ് ഉള്ളത്." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَتَى حَاجَتَهُ، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ نَامَ، ثُمَّ قَامَ، فَأَتَى الْقِرْبَةَ فَأَطْلَقَ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ وُضُوءَيْنِ لَمْ يُكْثِرْ، وَقَدْ أَبْلَغَ، فَصَلَّى فَقُمْتُ فَتَمَطَّيْتُ، كَرَاهِيَةَ أَنْ يَرَى أَنِّي كُنْتُ أَتَّقِيهِ فَتَوَضَّأْتُ، فَقَامَ يُصَلِّي، فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَ بِأُذُنِي فَأَدَارَنِي عَنْ يَمِينِهِ، فَتَتَامَّتْ صَلَاتُهُ ثَلَاثَ عَشْرَةَ رَكْعَةً، ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ، وَكَانَ إِذَا نَامَ نَفَخَ، فَآذَنَهُ بِلَالٌ بِالصَّلَاةِ، فَصَلَّى وَلَمْ يَتَوَضَّأْ، وَكَانَ يَقُولُ فِي دُعَائِهِ: "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا، وَاجْعَلْ لِي نُورًا، قَالَ كُرَيْبٌ: وَسَبْعٌ فِي التَّابُوتِ. فَلَقِيتُ رَجُلًا مِنْ وَلَدِ الْعَبَّاسِ، فَحَدَّثَنِي بِهِنَّ فَذَكَرَ: "عَصَبِي وَلَحْمِي وَدَمِي وَشَعْرِي وَبَشَرِي" وَذَكَرَ خَصْلَتَيْنِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ''ഞാനൊരു രാത്രി എന്റെ എളാമ മൈമൂനയുടെ അടുക്കൽ പാർക്കുകയുണ്ടായി. അന്ന് നബി(സ) രാത്രി എഴുന്നേൽക്കുകയും മലമൂത്ര വിസർജനം ചെയ്തു വരികയും ചെയ്തു. ശുചീകരിച്ച ശേഷം ഉറങ്ങുകയും ചെയ്തു. (രാത്രി അൽപം കഴിഞ്ഞ് വെള്ളം സൂക്ഷിച്ച) തോൽപാത്രത്തിന്റെ അടുത്ത് ചെന്ന് മൂടി തുറന്ന് മിതമായ രൂപത്തിൽ വുദൂ ചെയ്തു. അവിടുന്ന് കൂടുതൽ വെള്ളം ചെലവാക്കിയിരുന്നില്ല. പൂർണമായി വുദു ചെയ്ത ശേഷം നിന്ന് നമസ്കരിച്ചു. പ്രവാചകന്റെ പ്രവൃത്തി ഞാൻ വീക്ഷിക്കുന്നത് അവിടുന്ന് കാണുന്നത് എനിക്കിഷ്ടമില്ലായിരുന്നു. ഞാൻ എഴുന്നേറ്റ് വെള്ളമെടുത്ത് വുളു ചെയ്തു. അനന്തരം നിസ്കരിക്കാനായി തിരുമേനിയുടെ ഇടത് ഭാഗത്ത് ചെന്ന് നിന്നു. അപ്പോൾ നബി(സ) എന്റെ കൈ പിടിച്ച് വലതു ഭാഗം ചേർത്തു നിർത്തി. അനന്തരം പതിമൂന്ന് റക്അത്ത് പൂർണമായി നിസ്കരിക്കുകയും ശേഷം ചെരിഞ്ഞ് കിടന്ന് കൂർക്കം വലിച്ചുറങ്ങുകയും ചെയ്തു. അവിടുന്ന് ഉറക്കത്തിൽ കൂർക്കം വലിക്കാറുണ്ടായിരുന്നു. ശേഷം ബിലാൽ(റ) അവിടുത്തെ അടുക്കൽ ചെന്ന് സുബ്ഹ് നിസ്കാരത്തിന് സമയമായിരിക്കുന്നു എന്ന് അറിയിക്കുകയും ഉടനെ പ്രവാചകൻ എഴുന്നേറ്റ് പുതുതായി വുദൂ ചെയ്യാതെ തന്നെ നിസ്കരിക്കുകയും ചെയ്തു. അവിടുന്ന് പ്രാർത്ഥിക്കുമ്പോൾ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തിനും കണ്ണിനും കാതിനും നീ പ്രകാശം നൽകേണമേ. എന്റെ വലതു ഭാഗത്തും ഇടതു ഭാഗത്തും താഴെയും മുകളിലും മുൻവശത്തും പിൻവശത്തും പ്രകാശം ഉണ്ടാക്കിത്തരേണമേ. എനിക്ക് കൂടുതൽ പ്രകാശം നൽകേണമേ." നിവേദകരിലൊരാളായ കുറൈബ് പറയുന്നു: ''വാരിയെല്ലിന്റെയും നെഞ്ചിന്റെയും ഉൾഭാഗത്ത് സ്ഥിതി ചെയ്യുന്ന ഹൃദയത്തെയും മറ്റും സംബന്ധിച്ച ഏഴ് കാര്യങ്ങൾക്ക് (പ്രകാശം നൽമേണമേ എന്ന് പ്രാർത്ഥിക്കുന്നതിനെക്കുറിച്ച്) തിരുമേനി(സ) പറഞ്ഞിരുന്നു. (ഞാനത് മറന്ന് പോയി.) പിന്നീട് ഞാൻ അബ്ബാസിന്റെ സന്താനങ്ങളിൽ ചിലരെ കണ്ടപ്പോൾ അവർ അത് എനിക്ക് പറഞ്ഞു തന്നു: ''എന്റെ ഞരമ്പും മാംസവും രക്തവും മുടിയും തൊലിയും - വേറെ രണ്ടു കാര്യങ്ങളും പറഞ്ഞു - (പ്രഭാ പൂരിതമാക്കേണമേ)''എന്നും തിരുമേനി പ്രാർത്ഥിച്ചിരുന്നു.'' (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 604, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ لِيُصَلِّيَ، افْتَتَحَ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ. (م)', 'ആഇശ(റ): നബി(സ) നിസ്കാരത്തിനായി രാത്രി എഴുന്നേറ്റാൽ ലഘുവായ രണ്ട് റക്അത്ത് കൊണ്ട് തന്റെ നമസ്കാരം ആരംഭിക്കുമായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الدُّعَاءُ هُوَ الْعِبَادَةُ، ثُمَّ قَرَأَ ( وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ )". (د,ت,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ''പ്രാർത്ഥന തന്നെയാണ് ഇബാദത്ത് (ആരാധന). ''നിങ്ങൾ എന്നോട് തേടുക. ഞാൻ നിങ്ങൾക്ക് ഉത്തരം നൽകാം എന്ന് നിങ്ങളുടെ നാഥൻ പറഞ്ഞിട്ടുണ്ട്'' എന്ന ആയത്തോതി. (ദ,തു,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَبِي نَعَامَةَ قَيْسِ بْنِ عَبَايَةَ عَنِ ابْنِ لِسَعْدٍ أَنَّهُ قَالَ: سَمِعَنِي أَبِي وَأَنَا أَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَنَعِيمَهَا وَبَهْجَتَهَا، وَكَذَا وَكَذَا، وَأَعُوذُ بِكَ مِنَ النَّارِ وَسَلَاسِلِهَا وَأَغْلَالِهَا، وَكَذَا وَكَذَا، فَقَالَ: يَا بُنَيَّ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَيَكُونُ قَوْمٌ يَعْتَدُونَ فِي الدُّعَاءِ" فَإِيَّاكَ أَنْ تَكُونَ مِنْهُمْ، إِنَّكَ إِنْ أُعْطِيتَ الْجَنَّةَ أُعْطِيتَهَا وَمَا فِيهَا، مِنَ الْخَيْرِ وَإِنْ أُعِذْتَ مِنَ النَّارِ أُعِذْتَ مِنْهَا وَمَا فِيهَا مِنَ الشَّرِّ. (د)', 'അബൂനആമ ഖൈസുബ്നു ഉബായ(റ): അദ്ദേഹം സഅ്ദിന്റെ ഒരു പുത്രനിൽ നിന്ന് നിവേദനം: അദ്ദേഹം പറഞ്ഞു: ''അല്ലാഹുവേ, നിന്നോട് ഞാൻ സ്വർഗ്ഗവും അതിലെ അനുഗ്രഹങ്ങളും ശോഭയും മറ്റും ചോദിക്കുന്നു. അതുപോലെ അല്ലാഹുവേ, ഞാൻ നിന്നോട് നരകത്തിൽനിന്നും അതിലെ ചങ്ങലകളിൽനിന്നും ബന്ധനങ്ങളിൽനിന്നും മറ്റും കാവലിനെ ചോദിക്കുന്നു.'' എന്ന് ഞാൻ പ്രാർത്ഥിക്കുന്നത് എന്റെ പിതാവ് കേട്ടു. അപ്പോൾ പിതാവ് പറഞ്ഞു. എന്റെ കുഞ്ഞുമോനേ, "പ്രാർത്ഥനയിൽ അതിരുവിട്ട് കടക്കുന്ന ഒരു കൂട്ടം ആളുകൾ വരും" എന്ന് റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. അതുകൊണ്ട് നീ അവരിൽ പെട്ടു പോകുന്നതിനെ സൂക്ഷിക്കുക. തീർച്ചയായും നിനക്കു സ്വർഗ്ഗം നൽകപ്പെടുകയാണെങ്കിൽ നിനക്ക് സ്വർഗ്ഗവും അതിലെ മറ്റു അനുഗ്രഹങ്ങളും നൽകപ്പെടും. നീ നരകത്തിൽ നിന്ന് രക്ഷിക്കപ്പെടുകയാണെങ്കിൽ അതിൽ നിന്നും അതിലെ മറ്റ് ശിക്ഷകളിൽ നിന്നും രക്ഷിക്കപ്പെടും. (ദ)', 'أَبِي نَعَامَةَ قَيْسِ بْنِ عَبَايَةَ عَنِ ابْنِ لِسَعْدٍ أَنَّهُ قَالَ', 'അബൂനആമ ഖൈസുബ്നു ഉബായ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَدْعُو فِي صَلَاتِهِ، فَلَمْ يُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَجِلَ هَذَا". ثُمَّ دَعَاهُ فَقَالَ لَهُ أَوْ لِغَيْرِهِ: "إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأُ بِتَحْمِيدِ اللهِ وَالثَّنَاءِ عَلَيْهِ، ثُمَّ لِيُصَلِّ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَدْعُو بِمَا شَاءَ". (د,ت,ن)', 'ഫളാലത്തുബ്നു ഉബൈദ്(റ): ഒരാൾ തന്റെ നമസ്കാരത്തിൽ പ്രവാചക(സ)ന്റെ പേരിൽ സ്വലാത്ത് ചൊല്ലാതെ പ്രാർത്ഥിക്കുന്നത് തിരുമേനി(സ) കേൾക്കാനിടയായി. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇദ്ദേഹം ധൃതി കാണിച്ചിരിക്കുന്നു." ശേഷം അദ്ദേഹത്തെ വിളിച്ച് അദ്ദേഹത്തോടോ അല്ലെങ്കിൽ മറ്റാരോടോ അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നമസ്കരിക്കുമ്പോൾ തന്റെ നാഥനെ പുകഴ്ത്തുകയും അവനെ സ്തുതിക്കുകയും അവന്റെ മഹത്വത്തെ വാഴ്ത്തുകയും ചെയ്തു കൊണ്ട് തുടങ്ങട്ടെ. പിന്നീട് നബി(സ)യുടെ പേരിൽ സ്വലാത്ത് ചൊല്ലട്ടെ. പിന്നീട് അവൻ ഉദ്ദേശിക്കുന്നത് പ്രാർത്ഥിക്കട്ടെ." (ദ,തു,ന)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫളാലത്തുബ്നു ഉബൈദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 605, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ فَيَقُولُ: قَدْ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) അരുൾ ചെയ്തു: "നിങ്ങളിലൊരാൾ (പ്രാർത്ഥനക്ക് ഉത്തരം ലഭിക്കുന്നതിൽ) ധൃതിപ്പെട്ടു കൊണ്ട്, ഞാൻ പ്രാർത്ഥിച്ചു പക്ഷേ, എനിക്ക് ഉത്തരം ലഭിക്കുന്നില്ല എന്ന് പരാതിപ്പെടാത്തിടത്തോളം നിങ്ങളുടെ പ്രാർത്ഥനക്ക് ഉത്തരം നൽകപ്പെടും." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْتَحِبُّ الْجَوَامِعَ مِنَ الدُّعَاءِ، وَيَدَعُ مَا سِوَى ذَلِكَ. (د)', 'ആയിശ(റ): നബി(സ) പ്രാർത്ഥനകളിൽ മൊത്തമായി കാര്യങ്ങൾ പറയാറുണ്ടായിരുന്നു. അതല്ലാത്തതൊക്കെ ഒഴിവാക്കുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقُولَنَّ أَحَدُكُمُ: اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ: اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ، لِيَعْزِمِ الْمَسْأَلَةَ، فَإِنَّهُ لَا مُكْرِهَ لَهُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: ''നിങ്ങളിലൊരാളും പ്രാർത്ഥനകളിൽ അല്ലാഹുവേ, നീ ഉദ്ദേശിക്കുന്നുണ്ടെങ്കിൽ എനിക്ക് പൊറുത്തു തരേണമേ, അല്ലാഹുവേ, നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ എന്നോട് കരുണ കാണിക്കേണമേ എന്ന് പറയരുത്. കാര്യങ്ങളെ ഉറപ്പിച്ചു കൊണ്ട് ചോദിക്കുകയാണ് വേണ്ടത്. കാരണം, അവന് അതൊന്നും ചെയ്യൽ ബുദ്ധിമുട്ടുള്ള കാര്യമല്ല.'' (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَسْتُرُوا الْجُدُرَ، مَنْ نَظَرَ فِي كِتَابِ أَخِيهِ بِغَيْرِ إِذْنِهِ فَإِنَّمَا يَنْظُرُ فِي النَّارِ. سَلُوا اللهَ بِبُطُونِ أَكُفِّكُمْ وَلَا تَسْأَلُوهُ بِظُهُورِهَا، فَإِذَا فَرَغْتُمْ فَامْسَحُوا بِهَا وُجُوهَكُمْ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ചുമരുകളെ (വസ്ത്രം കൊണ്ടോ മറ്റോ) മറക്കുവാൻ പാടില്ല. ആരെങ്കിലും തന്റെ സ്നേഹിതന്റെ പുസ്തകത്തിലേക്ക് അവന്റെ സമ്മതം കൂടാതെ നോക്കിയാൽ അവൻ നരകത്തിലേക്കാണ് നോക്കുന്നത്. നിങ്ങൾ ഉള്ളംകൈ കൊണ്ട് അല്ലാഹുവിനോട് ചോദിക്കുക. പുറംകൈ കൊണ്ട് ചോദിക്കരുത്. പ്രാർത്ഥനയിൽ നിന്ന് വിരമിച്ചാൽ അവ കൊണ്ട് നിങ്ങളുടെ മുഖം തടവുക." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ مَالِكِ بْنِ يَسَارٍ السَّكُونِيِّ ثُمَّ الْعَوْفِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَأَلْتُمُ اللهَ فَاسْأَلُوهُ بِبُطُونِ أَكُفِّكُمْ، وَلَا تَسْأَلُوهُ بِظُهُورِهَا". (د)', 'മാലികുബ്നു യസാറു സുകുനിയും, ഔഫി(റ)യും നിവേദനം ചെയ്യുന്നു: റസൂൽ(സ) പറഞ്ഞു: ''നിങ്ങൾ അല്ലാഹുവിനോട് തേടുമ്പോൾ ഉള്ളം കൈ കൊണ്ട് തേടുക. പുറം കൈകൊണ്ട് പ്രാർത്ഥിക്കരുത്.'' (ദ)', 'مَالِكِ بْنِ يَسَارٍ السَّكُونِيِّ ثُمَّ الْعَوْفِيِّ', 'മാലികുബ്നു യസാറു സുകുനിയും, ഔഫി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُوا هَكَذَا بِبَاطِنِ كَفَّيْهِ وَظَاهِرِهِمَا. (د)', 'അനസുബ്നു മാലിക്ക്(റ): റസൂൽ(സ) ഇപ്രകാരം തന്റെ ഉള്ളം കൈകൊണ്ടും പുറം കൈകൾകൊണ്ടും പ്രാർത്ഥിക്കുന്നത് ഞാൻ കണ്ടു. (ദ)', 'أَنَسٍ', 'അനസുബ്നു മാലിക്ക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ رَبَّكُمْ تَبَارَكَ وَتَعَالَى حَيِيٌّ كَرِيمٌ، يَسْتَحْيِي مِنْ عَبْدِهِ إِذَا رَفَعَ يَدَيْهِ إِلَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا". (د،ت،جه)', 'സൽമാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: ''അനുഗ്രഹീതനും അത്യുന്നതനുമായ നിങ്ങളുടെ നാഥൻ ഉത്കൃഷ്ട ലജ്ജയുള്ളവനാകുന്നു. തന്റെ ഒരടിമ തന്നിലേക്ക് കൈകൾ നീട്ടിയിട്ട് അതിനെ ഒന്നുമില്ലാതെ മടക്കുന്നതിൽ അവൻ ലജ്ജിക്കുന്നു.'' (ദ,തു,ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: الْمَسْأَلَةُ أَنْ تَرْفَعَ يَدَيْكَ حَذْوَ مَنْكِبَيْكَ، أَوْ نَحْوَهُمَا، وَالِاسْتِغْفَارُ أَنْ تُشِيرَ بِأُصْبُعٍ وَاحِدَةٍ، وَالِابْتِهَالُ أَنْ تَمُدَّ يَدَيْكَ جَمِيعًا. وَفِي رِوَايَةٍ: وَالابْتِهَالُ هَكَذَا. وَرَفَعَ يَدَيْهِ وَجَعَلَ ظُهُورَهُمَا مِمَّا يَلِي وَجْهَهُ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''മസ്അല'' (ആവശ്യപ്പെടൽ) എന്നാൽ നിന്റെ രണ്ട് തോളിനു നേരെ ഇരുകരങ്ങളെ ഉയർത്തലാണ്. ''ഇസ്തിഗ്ഫാർ'' (പാപമോചനം തേടൽ) എന്നാൽ നീ ഒരു വിരൽ കൊണ്ട് ചൂണ്ടി കാണിക്കലാണ്. ''ഇബ്തിഹാൽ'' എന്നാൽ നിന്റെ ഇരുകരങ്ങൾ ഒന്നാകെ നീട്ടലാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) ''ഇബ്തിഹാൽ'' (കേണപേക്ഷിക്കൽ) ഇപ്രകാരമാണെന്ന് പറയുകയും ഇരു കരങ്ങളും മുഖത്തോടടുപ്പിച്ച് പിടിക്കുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=242), 1, 'وَفِي رِوَايَةٍ: وَالابْتِهَالُ هَكَذَا. وَرَفَعَ يَدَيْهِ وَجَعَلَ ظُهُورَهُمَا مِمَّا يَلِي وَجْهَهُ. (د)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) ''ഇബ്തിഹാൽ'' (കേണപേക്ഷിക്കൽ) ഇപ്രകാരമാണെന്ന് പറയുകയും ഇരു കരങ്ങളും മുഖത്തോടടുപ്പിച്ച് പിടിക്കുകയും ചെയ്തു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا دَعَا فَرَفَعَ يَدَيْهِ مَسَحَ وَجْهَهُ بِيَدَيْهِ. (د)', 'സാഇബ് ബ്നു യസീദ്(റ): നിശ്ചയം റസൂൽ(സ) പ്രാർത്ഥിക്കുമ്പോൾ കൈ ഉയർത്തുകയും മുഖം തടവുകയും ചെയ്തിരുന്നു. (ദ)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബ് ബ്നു യസീദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ عَنْ أَبِيهِ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقُولُ، اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللهُ، لَا إِلَهَ إِلَّا أَنْتَ الأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. فَقَالَ: "لَقَدْ سَأَلْتَ اللهَ بِالاسْمِ الَّذِي إِذَا سُئِلَ بِهِ أَعْطَى، وَإِذَا دُعِيَ بِهِ أَجَابَ". وَفِي رِوَايَةٍ: "لَقَدْ سَأَلْتَ اللهَ عَزَّ وَجَلَّ بِاسْمِهِ الْأَعْظَمِ". (د،ت،ن،جه)', 'ബുറൈദ(റ): ഒരാൾ ഇപ്രകാരം പ്രാർത്ഥിക്കുന്നതായി നബി(സ) കേട്ടു: അല്ലാഹുവേ, നിശ്ചയം നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നീ മാത്രമാണ് നാഥൻ എന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. നീയല്ലാതെ ആരാധ്യനില്ല. നീ ഏകനും നിരാശ്രയനുമാകുന്നു. നീയാരുടെയും സന്താനമല്ല. നിനക്കാകട്ടെ സന്താനവുമില്ല. നിനക്ക് തുല്യതയുള്ള ആരും തന്നെയില്ല.'' ഇതു കേട്ടപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് അവന്റെ നാമങ്ങൾ കൊണ്ട് ചോദിച്ചു. അവ കൊണ്ട് ചോദിച്ചാൽ അവൻ നൽകും. അവ കൊണ്ട് പ്രാർത്ഥിച്ചാൽ അവൻ ഉത്തരം നൽകും." മറ്റൊരു റിപ്പോർട്ടിൽ: "യുക്തിജ്ഞനും പ്രതാപിയുമായ അല്ലാഹുവിനോട് അവന്റെ ഉത്കൃഷ്ട നാമങ്ങൾ കൊണ്ട് നീ ചോദിച്ചിരിക്കുന്നു" എന്നാണ്. (ദ,തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=244), 1, 'وَفِي رِوَايَةٍ: "لَقَدْ سَأَلْتَ اللهَ عَزَّ وَجَلَّ بِاسْمِهِ الْأَعْظَمِ". (د،ت،ن،جه)', 'മറ്റൊരു നിവേദനിൽ: "യുക്തിജ്ഞനും പ്രതാപിയുമായ അല്ലാഹുവിനോട് അവന്റെ ഉത്കൃഷ്ട നാമങ്ങൾ കൊണ്ട് നീ ചോദിച്ചിരിക്കുന്നു" എന്നാണ്. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ وَرَجُلٌ قَدْ صَلَّى وَهُوَ يَدْعُو وَيَقُولُ فِي دُعَائِهِ: اللَّهُمَّ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ، ذَا الْجَلَالِ وَالْإِكْرَامِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهم عَلَيْهِ وَسَلَّمَ: أَتَدْرُونَ بِمَ دَعَا اللهَ؟ دَعَا اللهَ بِاسْمِهِ الْأَعْظَمِ، الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى. (د, ن)', 'അനസ്(റ): റസൂൽ(സ) ഒരിക്കൽ പള്ളിയിൽ വന്നപ്പോൾ നിസ്കരിച്ചു കഴിഞ്ഞിരിക്കുന്ന ഒരാൾ ഇപ്രകാരം പ്രാർത്ഥിച്ചു: ''അല്ലാഹുവേ, നീയല്ലാതെ ആരാധ്യനില്ല. നീ വളരെയേറെ നൽകുന്നവനാണ്. ആകാശ ഭൂമികളെ സ്വയം സൃഷ്ടിച്ചവനാണ്. പ്രതാപിയും ഉത്കൃഷ്ടനുമായവനേ.'' ഇതു കേട്ടപ്പോൾ പ്രവാചകൻ(സ) ചേദിച്ചു: അദ്ദേഹം എന്തു മുഖേനയാണ് അല്ലാഹുവിനേട് പ്രാർത്ഥിച്ചത് എന്ന് നിങ്ങൾക്കറിയുമോ? അല്ലാഹുവിന്റെ ഇസ്മുൽ അഅ്ളം (ഉത്കൃഷ്ട നാമം) കൊണ്ടാണ് അദ്ദേഹം പ്രാർത്ഥിച്ചിരിക്കുന്നത്. അവ മുഖേന പ്രാർത്ഥിച്ചാൽ ഉത്തരം നൽകും. അവ മുഖേന ചോദിച്ചാൽ നൽകുകയും ചെയ്യും.'' (ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ أَسْمَاءِ بِنْتِ يَزِيدَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اسْمُ اللَّهِ الْأَعْظَمُ فِي هَاتَيْنِ الْآيَتَيْنِ: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ} [البقرة: ١٦٣] وَفَاتِحَةِ آلِ عِمْرَانَ: {الم. اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ}". (د, ت, جه)', 'അസ്മാ ബിൻത് യസീദ്(റ): നബി(സ) പറഞ്ഞു: ''നിങ്ങളുടെ നാഥൻ ഏകനാകുന്നു. അവനല്ലാതെ ആരാധ്യനില്ല അവൻ പരമകാരുണികനും കരുണാനിധിയുമാകുന്നു'' (അൽ ബഖറ:163). സൂറത്തു ആലുഇംറാന്റെ തുടക്കത്തിലുള്ള ''അലിഫ് ലാം മീം, അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല. അവൻ എന്നെന്നും ജീവിക്കുന്നവനും നിയന്താവുമാകുന്നു''. എന്നീ രണ്ട് ആയത്തുകളിൽ അല്ലാഹുവിന്റെ ഇസ്മുൽ അഅ്ളം (ഉത്തമ നാമം) ഉണ്ട്. (ദ,തു,ജ)', 'أَسْمَاءِ بِنْتِ يَزِيدَ', 'അസ്മാ ബിൻത് യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'البقرة: ١٦٣', null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سُرِقَتْ مِلْحَفَةٌ لَهَا، فَجَعَلَتْ تَدْعُو عَلَى مَنْ سَرَقَهَا، فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُسَبِّخِي عَنْهُ". قَالَ أَبُو دَاوُدَ: لَا تُسَبِّخِي أَيْ لَا تُخَفِّفِي عَنْهُ. (د)', 'ആഇശ(റ): മഹതിയുടെ പുതപ്പ് മോഷ്ടിക്കപ്പെട്ടു. അപ്പോൾ അത് കട്ടെടുത്തവനെതിരെ അവർ പ്രാർത്ഥിച്ചു; അപ്പോൾ നബി(സ) പറഞ്ഞു: ''നീ അതിൽ ശക്തി കുറക്കേണ്ട.'' (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَأْذَنْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْعُمْرَةِ، فَأَذِنَ لِي وَقَالَ: "لَا تَنْسَنَا يَا أُخَيَّ مِنْ دُعَائِكَ". وَفِي رِوَايَةٍ: "أَشْرِكْنَا يَا أَخِي فِي دُعَائِكَ". فَقَالَ كَلِمَةً مَا يَسُرُّنِي أَنَّ لِي بِهَا الدُّنْيَا. (د, ت, جه)', 'ഉമർ(റ): ''ഞാൻ നബി(സ)യോട് ഉംറ ചെയ്യാൻ അനുവാദം ചോദിച്ചു. എനിക്കതിനുള്ള അനുവാദം തന്നു കൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: ''എന്റെ സഹേദരാ, നിന്റെ പ്രാർത്ഥനയിൽ ഞങ്ങളെ മറക്കരുത്. " - മറ്റൊരു റിപ്പോർട്ടിൽ: എന്റെ സഹോദരാ നിന്റെ പ്രാർത്ഥനയിൽ ഞങ്ങളെയും ഉൾപ്പെടുത്തുക. - ഉമർ(റ) പറയുന്നു: ''എനിക്ക് ദുനിയാവ് മുഴുവൻ കിട്ടിയാലുണ്ടാവുന്നതിനേക്കാൾ സന്തോഷമേകുന്ന വാക്കുകളാണത്.'' (ദ,തു, ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=248), 1, 'وَفِي رِوَايَةٍ: "أَشْرِكْنَا يَا أَخِي فِي دُعَائِكَ". فَقَالَ كَلِمَةً مَا يَسُرُّنِي أَنَّ لِي بِهَا الدُّنْيَا. (د, ت, جه)', 'മറ്റൊരു നിവേദനിൽ: എന്റെ സഹോദരാ നിന്റെ പ്രാർത്ഥനയിൽ ഞങ്ങളെയും ഉൾപ്പെടുത്തുക. - ഉമർ(റ) പറയുന്നു: ''എനിക്ക് ദുനിയാവ് മുഴുവൻ കിട്ടിയാലുണ്ടാവുന്നതിനേക്കാൾ സന്തോഷമേകുന്ന വാക്കുകളാണത്.'' (ദ,തു, ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَدْعُو بِأَصَابِعِي، فَقَالَ: "أَحِّدْ أَحِّدْ" وَأَشَارَ بِالسَّبَّابَةِ. (د, ت, ن)', 'സഅ്ദ്(റ): ഞാൻ എന്റെ വിരലുകൾ ഉയർത്തി ദുആ ചെയ്തുകൊണ്ടിരിക്കുമ്പോൾ നബി(സ) എന്റെ സമീപത്തു കൂടെ നടക്കുകയും എന്നോട് ഒരു വിരലുയർത്തുവിൻ എന്ന് പറയുകയും തന്റെ ചൂണ്ടു വിരൽ കൊണ്ട് ആംഗ്യം കാണിക്കുകയും ചെയ്തു. (ദ,തു,ന)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَتَهَجَّدُ قَالَ: "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ، لَكَ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ. وَلَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ. وَلَكَ الْحَمْدُ، أَنْتَ مَلِكُ السَّمَوَاتِ وَالأَرْضِ وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ أَوْ لَا إِلَهَ غَيْرُكَ قَالَ سُفْيَانُ وَزَادَ عَبْدُالْكَرِيمِ أَبُو أُمَيَّةَ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ". (ق,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) രാത്രി എഴുന്നേറ്റ് തഹജ്ജുദ് നിസ്ക്കരിക്കും എന്നിട്ട് ഇപ്രകാരം പ്രാർത്ഥിക്കും "അല്ലാഹുവേ, നിനക്ക് സ്തുതി. ആകാശ ഭൂമികളുടേയും അവയിലുള്ളവരുടെയും പരിപാലകൻ നീയാണ്, നിനക്കുസ്തുതി. ആകാശ ഭൂമിയുടെയും അവയിലുള്ളവരുടെയും ആധിപത്യം നിനക്കാണ്. നിക്കാണ് സ്തുതി. ആകാശ ഭൂമിളുടെയും അവയിലുള്ളവരുടെയും പ്രകാശമാണ് നീ, നിനക്ക് സ്തുതി ആകാശങ്ങളുടെയും ഭൂമിയുടെയും രാജാവാണ് നീ. നിനക്ക് സ്തുതി, നീയാണ് പരമസത്യം. നിന്റെ വാഗ്ദാനം സത്യമാണ്. നീയുമായുള്ള കൂടിക്കാഴ്ച സത്യമാണ്. നിന്റെ വാക്കുകൾ സത്യമാണ്. സ്വർഗ്ഗം സത്യമാണ്. നരകവും സത്യമാണ്, നബിമാർ സത്യമാണ്. മുഹമ്മദ്(സ) സത്യമാണ്. അന്ത്യസമയം സത്യമാണ്. അല്ലാഹുവെ ഞാൻ നിനക്ക് കീഴ്പെട്ടു, ഞാൻ നിന്നിൽ വിശ്വസിച്ചു, നിന്റെ മേൽ ഭരമേൽപ്പിച്ചു, നിന്നിലേക്ക് ഖേദിച്ചു മടങ്ങി നിന്റെ പേരിൽ വാദിക്കുകയും നിന്നേട് വിധി തേടുകയും ചെയ്യുന്നു. അതുകൊണ്ട് ഞാൻ മുന്തിച്ചതും പിന്തിച്ചതും പരസ്യമായും രഹസ്യമായും ചെയ്തതും നീ എനിക്കു പൊറുത്തു തരേണമേ! നീയാണ് മുന്തിക്കുന്നവൻ നീയാണ് പിന്തിക്കുന്നവൻ നീയല്ലാതെ മറ്റെരു ഇലാഹില്ല. സുഫ്യാൻ പറഞ്ഞു അബൂഉമയ്യ ഇങ്ങനെക്കൂടെ റിപ്പേർട്ട് ചെയ്തു: നിനക്കല്ലാതെ ശക്തിയും കഴിവുമില്ല. (ബു,മു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ عَاصِمِ بْنِ حُمَيْدٍ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: بِمَ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ قِيَامَ اللَّيْلِ؟ قَالَتْ: سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ يُكَبِّرُ عَشْرًا، وَيَحْمَدُ عَشْرًا، وَيُسَبِّحُ عَشْرًا، وَيُهَلِّلُ عَشْرًا، وَيَسْتَغْفِرُ عَشْرًا، وَيَقُولُ: "اللَّهُمَّ اغْفِرْ لِي وَاهْدِنِي وَارْزُقْنِي وَعَافِنِي، وَيَتَعَوَّذُ مِنْ ضِيقِ الْمُقَامِ يَوْمَ الْقِيَامَةِ". (د,ن,جه)', 'ആസിമുബ്നു ഹുമൈദ്(റ): ''ഞാൻ ആഇശയോട് ചോദിച്ചു: ''പ്രവാചകൻ(സ) രാത്രി നമസ്കാരങ്ങളിൽ പ്രാരംഭമായി എന്താണ് പ്രാർത്ഥിച്ചിരുന്നത്?'' മഹതി പറഞ്ഞു: ''ഒരാളും മുമ്പ് എന്നോട് ചോദിച്ചിട്ടില്ലാത്ത ഒരു കാര്യമാണ് നിങ്ങൾ ചോദിച്ചിരിക്കുന്നത്. പ്രവാചകൻ(സ) പത്ത് തവണ തക്ബീർ ചൊല്ലകുയും പത്ത് തവണ അല്ലാഹുവിനെ സ്തുതിക്കുകയും പത്ത് തവണ അവനെ മഹത്വപ്പെടുത്തുകയും പത്ത് തവണ തഹ്‌ലീൽ ചൊല്ലുകയും പത്ത് തവണ പാപമോചനം നടത്തുകയും ശേഷം ''അല്ലാഹുവേ, എനിക്ക് നീ പൊറുത്തു തരേണമേ. എനിക്ക് മാർഗദർശനം നൽകേണമേ. എനിക്ക് ഭക്ഷണം നൽകേണമേ. എനിക്ക് സൗഖ്യം നൽകേണമേ'' എന്നു പ്രാർത്ഥിക്കുകയും ചെയ്യും. അന്ത്യദിനത്തിലെ നിർത്തത്തിന്റെ വിഷമങ്ങളാൽ നിന്ന് അഭയം തേടുകയും ചെയ്യും." (ദ,ന,ജ)', 'عَاصِمِ بْنِ حُمَيْدٍ قَالَ', 'ആസിമുബ്നു ഹുമൈദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، أَنَّهَا سُئِلَتْ: بِأَيِّ شَيْءٍ كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنَ اللَّيْلِ، قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ فَقَالَ: "اللَّهُمَّ رَبَّ جِبْرِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُّسْتَقِيمٍ “. (م،د،ت،ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) രാത്രി നമസ്കാരങ്ങളിൽ പ്രാരംഭമായി എന്താണ് പ്രാർത്ഥിച്ചിരുന്നത് എന്ന് അവർ ചോദിക്കപ്പെട്ടു. മറുപടിയായി മഹതി പറഞ്ഞു: ''പ്രവാചകൻ(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു, ''ജിബ്‌രീലിന്റെയും മീക്കാഈലിന്റെയും ഇസ്റാഫീലിന്റെയും നാഥനും ആകാശഭൂമികളുടെ സൃഷ്ടാവും രഹസ്യവും പരസ്യവും അറിയുന്നവനുമായ അല്ലാഹുവേ, നിന്റെ ദാസന്മാർ ഭിന്നിച്ച വിഷയത്തിൽ നീയാണ് വിധി കൽപിക്കുന്നത്. അങ്ങനെ ഭിന്നിച്ച വിഷയത്തിൽ നിന്റെ അനുമതിയോടെ നീ എന്നെ സത്യത്തിലാക്കേണമേ. നിശ്ചയമായും നീ ഉദ്ദേശിച്ചവരെ നീ നേർവഴിയിലാക്കുന്നു.''" (മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 609, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ اللَّهُ إِلَى السَّمَاءِ الدُّنْيَا كُلَّ لَيْلَةٍ حِينَ يَمْضِي ثُلُثُ اللَّيْلِ الْأَوَّلُ، فَيَقُولُ: "أَنَا الْمَلِكُ أَنَا الْمَلِكُ، مَنْ ذَا الَّذِي يَدْعُونِي فَأَسْتَجِيبَ لَهُ، مَنْ ذَا الَّذِي يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ ذَا الَّذِي يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ، فَلَا يَزَالُ كَذَلِكَ حَتَّى يُضِيءَ الْفَجْرُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പരിശുദ്ധനും പ്രതാപിയുമായ അല്ലാഹു ഓരോ രാത്രിയിലും ഒന്നാമാകാശത്തിലേക്ക് ഇറങ്ങി വരും. രാത്രിയുടെ മൂന്നിലൊന്നിൽ ഒന്നാമത്തെ സമയം കഴിയുമ്പോഴാണത്. അപ്പോൾ അവൻ പറയും: ''ഞാനാണ് സർവ്വാധി രാജൻ! ഞാനാണ് സർവ്വാധി രാജൻ!! ആരെന്നോട് പ്രാർത്ഥിക്കുന്നുവോ അപ്പോൾ ഞാൻ അവന് ഉത്തരം നൽകും. ആര് എന്നോട് ചോദിക്കുന്നുവോ ഞാനവന് നൽകും. ആര് എന്നോട് മാപ്പപേക്ഷിക്കുന്നുവോ അവന് ഞാൻ പൊറുത്തു കൊടുക്കും.'' അത് പ്രഭാതമാകുന്നത് വരെ തുടർന്നു കൊണ്ടിരിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 610, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَامَ عَنْ حِزْبِهِ - أَوْ عَنْ شَيْءٍ مِنْهُ - فَقَرَأَهُ فِيمَا بَيْنَ صَلَاةِ الْفَجْرِ وَصَلَاةِ الظُّهْرِ، كُتِبَ لَهُ كَأَنَّمَا قَرَأَهُ مِنَ اللَّيْلِ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=254), 1, 'وَفِي رِوَايَةٍ: "مَنْ فَاتَهُ عَنْ حِزْبِهِ، أَوْ عَنْ شَيْءٍ مِنْهُ فَقَرَأَهُ حِينَ تَزُولُ الشَّمْسُ الى صَلَاةِ الظُّهْرِ، فَإِنه لَمْ يَفِتْهُ. أَوْ كَأَنَّه أَدْرَكَهُ". (ن،جه)', 'മറ്റൊരു നിവേദന്: "ഒരാൾക്ക് തന്റെ നിശ്ചിത ഓഹരി (പതിവായി ചെയ്യാറുള്ള പാരായണം) നഷ്ടമാവുകയും അത് സുബ്ഹി നമസ്കാരത്തിനും ദുഹർ നമസ്കാരത്തിനുമിടക്ക് അത് പാരായണം ചെയ്യുകയും ചെയ്താൽ അയാൾ രാത്രി ഓതിപോലെ അത് രേഖപ്പെടുത്തപ്പെടും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=254), 2, null, 'മറ്റൊരു നിവേദനിൽ: "ആർക്കെങ്കിലും തന്റെ വിഹിതം (പതിവു പാരായണം) രാത്രിയിൽ നഷ്ടപ്പെട്ടാൽ അത് അയാൾ ളുഹ്റിന്റെ സമയത്ത് സൂര്യൻ മധ്യത്തിൽ നിന്ന് തെറ്റുന്നതിന്റെ മുമ്പായി പാരായണം ചെയ്തിട്ടുണ്ടെങ്കിൽ അയാൾക്ക് അത് നഷ്ടപ്പെടില്ല. അല്ലെങ്കിൽ അയാൾക്കത് ലഭിച്ചിരിക്കുന്നു." (ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَامَ عَنْ حِزْبِهِ أَوْ عَنْ شَيْءٍ مِنْهُ فَقَرَأَهُ فِيمَا بَيْنَ صَلَاةِ الْفَجْرِ وَصَلَاةِ الظُّهْرِ، كُتِبَ لَهُ كَأَنَّمَا قَرَأَهُ مِنَ اللَّيْلِ". (م,د,ت,ن,جه)', 'ഉമർബ്നു ഖത്താബ്(റ): നബി(സ) പറയുന്നു: "ആർക്കെങ്കിലും (രാത്രിയിലെ ഖുർആൻ പാരായണം) തന്റെ നിശ്ചിത ഓഹരി നഷ്ടപ്പെട്ടാൽ, അല്ലെങ്കിൽ അതിലൊരു ഭാഗം നഷ്ടപ്പെട്ടാൽ അയാളത് ഫജ്റ് നമസ്കാരത്തിന്റെയും ളുഹ്റിന്റെയും ഇടയിൽ പാരാണം ചെയ്യട്ടെ. എങ്കിൽ അയാളത് രാത്രിയിൽ തന്നെ നിർവഹിച്ചതിന്റെ പ്രതിഫലം നൽകപ്പെടും." (മു,ദ,തു,ന,ജ)', null, 'ഉമർബ്നു ഖത്താബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'أَنَّ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنِ امْرِئٍ تَكُونُ لَهُ صَلَاةٌ بِلَيْلٍ، فَغَلَبَهُ عَلَيْهَا نَوْمٌ، إِلَّا كَتَبَ اللَّهُ لَهُ أَجْرَ صَلَاتِهِ، وَكَانَ نَوْمُهُ صَدَقَةً عَلَيْهِ". (د,ن)', 'ആയിശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ രാത്രി നിസ്കാരം ഉദ്ദേശിക്കുകയും എന്നിട്ടയാളെ ഉറക്കം കീഴ്പ്പെടുത്തുകയും ചെയ്താൽ അയാൾക്ക് നസ്കാരത്തിന്റെ പ്രതിഫലം നൽകാതിരിക്കില്ല. അയാളുടെ ഉറക്കം അല്ലാഹുവിൽ നിന്നുള്ളൊരു ദാനമാണ്." (ദ,ന)', null, 'ആയിശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَتْ لَهُ صَلَاةٌ صَلَّاهَا مِنَ اللَّيْلِ، فَنَامَ عَنْهَا، كَانَ ذَلِكَ صَدَقَةً تَصَدَّقَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ، وَكَتَبَ لَهُ أَجْرَ صَلَاتِهِ". (ن)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് രാത്രി നമസ്കാരം നിർവഹിക്കണമെന്നുണ്ടായിരിക്കെ അയാൾ ഉറങ്ങിപ്പോയാൽ അത് അയാക്ക് അല്ലാഹു നൽകുന്ന ഒരു സ്വദഖയാണ്. അയാൾക്ക് നിസ്കരിച്ചതിന്റെ പ്രതിഫലം നൽകപ്പെടുകയും ചെയ്യും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي سَعِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "مَنْ نَامَ عَنْ وِتْرِهِ أَوْ نَسِيَهُ فَلْيُصَلِّهِ إِذَا ذَكَرَهُ". (د)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉറങ്ങിയോ മറന്നോ വിത്ർ ഉപേക്ഷിച്ചാൽ അവൻ ഓർമ്മ വരുമ്പോൾ നിസ്കരിക്കട്ടെ." (ദ)', 'أَبِي سَعِيدٍ قَالَ', 'അബൂസഈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا لَمْ يُصَلِّ مِنَ اللَّيْلِ - مَنَعَهُ مِنْ ذَلِكَ نَوْمٌ أَوْ وَجَعٌ - صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً. (د,ن)', 'ആഇശ(റ): നബി(സ) രാത്രി നമസ്കരിച്ചിട്ടില്ലെങ്കിൽ - വേദനയോ ഉറക്കമോ അതിനെ തടഞ്ഞാൽ - പകലിൽ പന്ത്രണ്ട് റക്അത്ത് നസ്കരിക്കും. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ نَامَ لَيْلَهُ حَتَّى أَصْبَحَ، قَالَ: "ذَاكَ رَجُلٌ بَالَ الشَّيْطَانُ فِي أُذُنَيْهِ"، أَوْ قَالَ: "فِي أُذُنِهِ". (م)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): രാത്രിയിൽ നേരം വെളുക്കുന്നത് വരെ ഉറങ്ങിയ ഒരാളെക്കുറിച്ച് പ്രവാചക(സ)നോട് പറയപ്പെട്ടു. അപ്പോൾ പ്രവാചകൻ പറഞ്ഞു: ''അത് പിശാച് ചെവികളിൽ മൂത്രമൊഴിച്ചിട്ടുള്ള വ്യക്തിയാണ്''. (മു)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 611, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَرَقَهُ وَفَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُمْ: "أَلَا تُصَلُّونَ". فَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّمَا أَنْفُسُنَا بِيَدِ اللَّهِ، فَإِذَا شَاءَ أَنْ يَبْعَثَنَا بَعَثَنَا، فَانْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَالَ لَهُ ذَلِكَ، وَلَمْ يَرْجِعْ إِلَيْهِ شَيْئًا، ثُمَّ سَمِعَهُ وَهُوَ مُدْبِرٌ يَضْرِبُ فَخِذَهُ وَهُوَ يَقُولُ: {وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ جَدَلًا} [الكهف: ٥٤]. (ق, ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) ഫാതിമയെയും എന്നെയും മുട്ടിവിളിച്ചു. എന്നിട്ട് ചോദിച്ചു: ''നിങ്ങൾ നമസ്കരിക്കുന്നില്ലേ?'' ഞാൻ ചോദിച്ചു: ''അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങളുടെ ആത്മാവ് അല്ലാഹുവിന്റെ കൈയിലാണല്ലോ. അല്ലാഹു അതിനെ ഉണർത്താൻ ഉദ്ദേശിക്കുമ്പോൾ അവൻ അതിനെ ഉണർത്തുന്നു. ഞാനത് പറഞ്ഞപ്പോൾ റസൂൽ(സ) മിറച്ചൊന്നും പറയാതെ തിരിച്ചു പോയി. പിന്തിരിഞ്ഞ് പോകുമ്പോൾ അവിടുത്തെ തുടയിൽ അടിച്ചു കൊണ്ട് അവിടുന്ന് ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടു: ''മനുഷ്യൻ വളരെയേറെ കുതർക്കിയായിരിക്കുന്നു.'' (അൽ കഹ്ഫ്: 54) (ബു,മു,ന)', null, 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], 'الكهف: ٥٤', null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'وَعَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى فَاطِمَةَ مِنَ اللَّيْلِ، فَأَيْقَظَنَا لِلصَّلَاةِ، ثُمَّ رَجَعَ إِلَى بَيْتِهِ، فَصَلَّى هَوِيًّا مِنَ اللَّيْلِ، فَلَمْ يَسْمَعْ لَنَا حِسًّا، فَرَجَعَ إِلَيْنَا فَأَيْقَظَنَا، فَقَالَ: "قُومَا فَصَلِّيَا". قَالَ: فَجَلَسْتُ وَأَنَا أَعْرُكُ عَيْنِي وَأَقُولُ: إِنَّا وَاللَّهِ مَا نُصَلِّي إِلَّا مَا كَتَبَ اللَّهُ لَنَا، إِنَّمَا أَنْفُسُنَا بِيَدِ اللَّهِ، فَإِنْ شَاءَ أَنْ يَبْعَثَنَا بَعَثَنَا، قَالَ: فَوَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ وَيَضْرِبُ بِيَدِهِ عَلَى فَخِذِهِ: "مَا نُصَلِّي إِلَّا مَا كَتَبَ اللَّهُ لَنَا {وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ جَدَلًا}". (ق, ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): എന്റെയം ഫാതിമയുടെയും അടുത്തേക്ക് റസൂൽ(സ) കടന്നു വന്നു. ഞങ്ങളിരുവരെയും രാത്രി നമസ്കാരത്തിനായി ഉണർത്തി. പിന്നീട് തിരുമേനി വീട്ടിൽ പോയി രാത്രി ദീർഘനേരം നിന്ന് നമസ്കരിച്ചു. ഞങ്ങളുടെ ഒരു അനക്കവും കേൾക്കാതിരുന്നപ്പോൾ തിരിച്ചു വന്ന് ഞങ്ങളെ ഉണർത്തിയിട്ട് പറഞ്ഞു: ''നിങ്ങൾ എഴുനേറ്റ് നമസ്കരിക്കുക.'' അലി(റ) പറയുന്നു: ''ഞാൻ കണ്ണു തുടച്ചു കൊണ്ട് എഴുന്നേറ്റു. എന്നിട്ട് പറഞ്ഞു: ''അല്ലാഹു ഞങ്ങൾക്ക് നിർബന്ധമാക്കിയതല്ലാതെ ഞങ്ങൾ നിസ്കരിക്കുന്നില്ല. ഞങ്ങളുടെ ആത്മാവ് അല്ലാഹുവിന്റെ കൈയിലാണ്. അവൻ ഉദ്ദേശിക്കുമ്പോൾ അവൻ ഞങ്ങളെ ഉണർത്തും.'' അപ്പോൾ റസൂൽ(സ) തന്റെ കൈകൊണ്ട് അവിടുത്തെ തുടയിലടിച്ച് ഇപ്രകാരം പറഞ്ഞു കൊണ്ട് തിരിഞ്ഞു നടന്നു: "ഞങ്ങൾക്ക് അല്ലാഹു നിർബന്ധമാക്കിയതല്ലാതെ ഞങ്ങൾ നിസ്കരിക്കുന്നില്ല. മനുഷ്യൻ വളരെയേറെ കുതർക്കിയായിരിക്കുന്നു!" (അൽകഹ്ഫ്) (ബു,മു,ന)', null, 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رَحِمَ اللَّهُ رَجُلًا قَامَ مِنَ اللَّيْلِ فَصَلَّى ثُمَّ أَيْقَظَ امْرَأَتَهُ فَصَلَّتْ، فَإِنْ أَبَتْ نَضَحَ فِي وَجْهِهَا الْمَاءَ، وَرَحِمَ اللَّهُ امْرَأَةً قَامَتْ مِنَ اللَّيْلِ فَصَلَّتْ ثُمَّ أَيْقَظَتْ زَوْجَهَا، فَصَلَّى فَإِنْ أَبَى نَضَحَتْ فِي وَجْهِهِ الْمَاءَ". (د, ن, جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: രാത്രിയിൽ എഴുന്നേറ്റ് നിസ്കരിക്കുകയും ശേഷം തന്റെ ഭാര്യയെ വിളിച്ചുണർത്തുകയും അങ്ങനെ അവൾ നിസ്കരിക്കുകയും ചെയ്താൽ, വിളിച്ചുണർത്തിയ വ്യക്തിയെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ. അവൾ വിസമ്മതിക്കുന്നുവെങ്കിൽ അവൻ അവളുടെ മുഖത്ത് വെള്ളം കുടയുകയും ചെയ്യും. രാത്രി എഴുന്നേറ്റ് നിസ്കരിക്കുകയും ശേഷം തന്റെ ഭർത്താവിനെ വിളിച്ചുണർത്തുകയും അങ്ങനെ അയാൾ നിസ്കരിക്കുകയും ചെയ്താൽ, വിളിച്ചുണർത്തിയ സ്ത്രീയെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ. അവൻ വിസമ്മതിച്ചാൽ അവൾ അവന്റെ മുഖത്ത് വെള്ളം കുടയുകയും ചെയ്യും. (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 612, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ وَأَبِي هُرَيْرَةَ قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَيْقَظَ مِنَ اللَّيْلِ وَأَيْقَظَ امْرَأَتَهُ فَصَلَّيَا رَكْعَتَيْنِ جَمِيعًا كُتِبَا مِنَ الذَّاكِرِينَ اللهَ كَثِيرًا وَالذَّاكِرَاتِ". (د,ن,جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ), അബൂഹുറൈറ(റ) എന്നിവരിൽനിന്നും നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: ആരെങ്കിലും രാത്രിയിൽ എഴുന്നേൽക്കുകയും തന്റെ ഭാര്യയെ ഉണർത്തുകയും എന്നിട്ട് രണ്ട് പേരും ഒരുമിച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്താൽ അല്ലാഹുവിനെ ധാരാളമായി സ്മരിക്കുന്ന സ്ത്രീ പുരുഷന്മാരിൽ അവരെ ഉൾപ്പെടുത്തുന്നതാണ്. (ദ,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ وَأَبِي هُرَيْرَةَ قَالَا', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ قَالَ: اشْتَكَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَقُمْ لَيْلَةً أَوْ لَيْلَتَيْنِ. (خ)', 'ജുൻദുബുബ്നു അബ്ദുല്ല(റ): നബി(സ) രോഗിയായിരിക്കെ ഒന്നോ രണ്ടോ രാത്രികളിൽ രാത്രി നിസ്കാരം നിർവ്വഹിച്ചിരുന്നില്ല. (ബു)', 'جُنْدَبِ بْنِ عَبْدِ اللَّهِ قَالَ', 'ജുൻദുബുബ്നു അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُ الشَّيْطَانُ عَلَى قَافِيَةِ رَأْسِ أَحَدِكُمْ ثَلَاثَ عُقَدٍ إِذَا نَامَ بِكُلِّ عُقْدَةٍ يَضْرِبُ عَلَيْكَ لَيْلًا طَوِيلًا، فَإِذَا اسْتَيْقَظَ فَذَكَرَ اللَّهَ انْحَلَّتْ عُقْدَةٌ وَإِذَا تَوَضَّأَ انْحَلَّتْ عَنْهُ عُقْدَتَانِ فَإِذَا صَلَّى انْحَلَّتِ الْعُقَدُ فَأَصْبَحَ نَشِيطًا طَيِّبَ النَّفْسِ وَإِلَّا أَصْبَحَ خَبِيثَ النَّفْسِ كَسْلَانَ. (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: നിങ്ങളിൽ ഒരാൾ ഉറങ്ങിയാൽ അവന്റെ പിരടിയിൽ പിശാച് മൂന്ന് കെട്ടുകൾ കെട്ടും. അവൻ ഉണർന്ന് അല്ലാഹുവിനെ ഓർത്താൽ ഒരു കെട്ടഴിയും. ശേഷം വുദു ചെയ്താൽ രണ്ടു കെട്ടുകളും നിസ്കരിച്ചാൽ എല്ലാ കെട്ടുകളും അഴിയുകയും അവൻ ഉന്മേഷവാനും സന്തുഷ്ടനുമായിത്തീരുകയും ചെയ്യും. അല്ലെങ്കിൽ മടിയനും ഉന്മേഷമില്ലാത്തവനുമായിത്തീരും. (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا : وَسُئِلَتْ كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ؟ فَقَالَتْ: مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزِيدُ فِي رَمَضَانَ وَلَا فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً: يُصَلِّي أَرْبَعًا، فَلَا تَسَلْ عَنْ حُسْنِهِنَّ، وَطُولِهِنَّ ثُمَّ يُصَلِّي أَرْبَعًا فَلَا تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلَاثًا. قَالَتْ عَائِشَةُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَتَنَامُ قَبْلَ أَنْ تُوتِرَ؟ فَقَالَ: "يَا عَائِشَةُ، إِنَّ عَيْنَيَّ تَنَامَانِ وَلَا يَنَامُ قَلْبِي". حَسَن صَحِيح. (ق,ت)', 'ആയിശ(റ): അവരോട് ചോദിക്കപ്പെട്ടു: റമദാനിൽ പ്രവാചകരുടെ നമസ്കാരം എങ്ങനെയായിരുന്നു? മഹതി പറഞ്ഞു: റമദാനിലോ മറ്റു മാസങ്ങളിലോ പതിനൊന്ന് റക്അത്തിൽ കൂടുതൽ നബി(സ) നിസ്കരിച്ചിരുന്നില്ല. നബി(സ) നാല് റക്അത്ത് നിസ്കരിക്കും. അവയുടെ ഭംഗിയും ദൈർഘ്യവും നീ ചോദിക്കേണ്ടതില്ല!. വീണ്ടും നാല് റക്അത്ത് നിസ്കരിക്കും. അവയുടെ ഭംഗിയും ദൈർഘ്യവും നീ ചോദിക്കേണ്ടതില്ല. പിന്നീട് മൂന്ന് റകഅത്ത് കൂടി നിസ്കരിക്കും. ആയിശ(റ) പറയുന്നു: ഞൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, വിത്റ് നിസ്കരിക്കുന്നതിന്റെ മുമ്പ് നിങ്ങൾ ഉറങ്ങുകയാണോ? നബി(സ) പറഞ്ഞു: ഓ ആയിശ, എന്റെ രണ്ട് കണ്ണുകൾ ഉറങ്ങുന്നുവെങ്കിലും എന്റെ ഹൃദയം ഉറങ്ങുന്നില്ല. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,തു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 613, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بِاللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْهَا بِوَاحِدَةٍ، فَإِذَا فَرَغَ مِنْهَا اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ. حسن صحيح. (م،ت)', 'ആയിശ(റ) : നബി(സ) രാത്രി പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. അവ ഒന്നുകൊണ്ട് ഒറ്റയാക്കും. അവയിൽ നിന്ന് വിരമിച്ചാൽ വലതുഭാഗത്തേക്ക് ചെരിഞ്ഞ് കിടക്കുമായിരുന്നു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (മു,തു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مَا كُنَّا نَشَاءُ أَنْ نَرَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي اللَّيْلِ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَلَا نَشَاءُ أَنْ نَرَاهُ نَائِمًا إِلَّا رَأَيْنَاهُ. (ن)', 'അനസ്(റ): “നബി(സ്വ)യെ രാത്രിയിൽ നിസ്കരിക്കുന്നവരായി കാണാൻ ഞങ്ങൾ വിചാരിച്ചാൽ ഞങ്ങൾ അങ്ങനെ കാണുമായിരുന്നു. ഉറങ്ങുന്നവരായി കാണണമെന്നു വിചാരിച്ചാൽ അങ്ങനെയും കാണുമായിരുന്നു.” (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا وَقَدْ سُئِلَتْ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ كَانَ يُصَلِّي الْعَتَمَةَ ثُمَّ يُسَبِّحُ ثُمَّ يُصَلِّي بَعْدَهَا مَا شَاءَ اللَّهُ مِنَ اللَّيْلِ ثُمَّ يَنْصَرِفُ فَيَرْقُدُ مِثْلَ مَا صَلَّى ثُمَّ يَسْتَيْقِظُ مِنْ نَوْمِهِ ذَلِكَ فَيُصَلِّي مِثْلَ مَا نَامَ وَصَلَاتُهُ تِلْكَ الْآخِرَةُ تَكُونُ إِلَى الصُّبْحِ. (ن)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ മഹതി പറഞ്ഞു: നബി(സ) ഇശാ നിസ്കരിക്കുകയും പിന്നീട് സുന്നത്ത് നിസ്കരിക്കുകയും, പിന്നീട് രാത്രിയിൽ അതിനു ശേഷം അല്ലാഹു ഉദ്ദേശിക്കുന്ന രീതിയിൽ നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. പിന്നീട് അവിടെനിന്നും പോയി നിസ്കരിച്ചതു പോലെതന്നെ അവിടുന്ന് കിടന്നുറങ്ങുകയും, പിന്നീട് ഉറക്കത്തിൽ നിന്നുമുണർന്ന് ഉറങ്ങിയതു പോലെതന്നെ(ദൈർഘ്യത്തിൽ) അവിടുന്ന് നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. അവസാന നിസ്കാരം സുബ്ഹി വരെ ഉണ്ടാകുമായിരുന്നു. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْهَا بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ مِنَ الْخَمْسِ حَتَّى يَجْلِسَ فِي الْآخِرَةِ فَيُسَلِّمَ. (ق،د،ت،ن،جه)', 'ആഇശ(റ): നബി(സ) രാത്രി പതിമൂന്ന് റക്അത്ത് നിസ്കരിച്ചിരുന്നു. അഞ്ച് റക്അത്ത് വിത്റായിരുന്നു. ഈ അഞ്ച് റക്അത്തിൽ അവസാനത്തേതിൽ മാത്രമേ (തശഹ്ഹുദിന്) ഇരിക്കുകയും സലാം വീട്ടുകയും ചെയ്യാറുള്ളൂ. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سُئِلَتْ عَنْ قِرَاءَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَنْ صَلَاتِهِ فَقَالَتْ: مَا لَكُمْ وَصَلَاتَهُ؟ كَانَ يُصَلِّي، ثُمَّ يَنَامُ قَدْرَ مَا صَلَّى ثُمَّ يُصَلِّي قَدْرَ مَا نَامَ ثُمَّ يَنَامُ قَدْرَ مَا صَلَّى حَتَّى يُصْبِحَ ثُمَّ نَعَتَتْ لَهُ قِرَاءَتَهُ فَإِذَا هِيَ تَنْعَتُ قِرَاءَةً مُفَسَّرَةً حَرْفًا حَرْفًا. (ن)', 'നബിതിരുമേനിയുടെ ഭാര്യ ഉമ്മുസലമ(റ): നബി(സ)യുടെ ഖുർആൻ പാരായണത്തെക്കുറിച്ചും നിസ്കാരത്തെപ്പറ്റിയും മഹതിയോട് ചോദിക്കപ്പെട്ടു. മഹതി പ്രതിവചിച്ചു: നബിയുടെ നിസ്കാരമല്ലേ. നബി(സ) നിസ്കരിച്ച് അത്ര സമയം ഉറങ്ങും. പിന്നെ ഉറങ്ങാനെടുത്ത അത്ര സമയം നിസ്കരിക്കും.. പിന്നെ അത്ര സമയം വീണ്ടും ഉറങ്ങും. അങ്ങെനെ പുലരുവോളം.... പിന്നെ നബി(സ)യുടെ ഖുർആൻ പാരായണത്തെ കുറിച്ച് മഹതി വർണ്ണിച്ചു. അവിടുത്തെ ഓരോ അക്ഷരങ്ങളെക്കുറിച്ചും വിശദീകരിച്ചു. (ന)', 'أُمِّ سَلَمَةَ', 'നബിതിരുമേനിയുടെ ഭാര്യ ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ الْحَوْلَاءَ بِنْتَ تُوَيْتِ بْنِ حَبِيبِ بْنِ أَسَدِ ابْنِ عَبْدِ الْعُزَّى مَرَّتْ بِهَا وَعِنْدَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: هَذِهِ الْحَوْلَاءُ بِنْتُ تُوَيْتٍ، وَزَعَمُوا أَنَّهَا لَا تَنَامُ اللَّيْلَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَنَامُ اللَّيْلَ؟ خُذُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ، فَوَاللَّهِ لَا يَسْأَمُ اللَّهُ حَتَّى تَسْأَمُوا". (م)', 'പ്രവാചക പത്നി ആയിശ(റ): ഒരിക്കൽ നബി(സ)യുടെയും ആയിശ(റ)യുടെയും അടുത്തുകൂടെ ഹൗലാഅ് ബിൻതു തുവൈത്ത് എന്ന സ്ത്രീ കടന്നു പോയി. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഉറങ്ങാറില്ലെന്ന് ആളുകൾ പറയുന്ന ഹൗലാ ബിൻതു തുവൈത്ത് ആണിത്. നബി(സ) ചോദിച്ചു: "രാത്രി ഉറങ്ങാറില്ലേ? നിങ്ങൾക്ക് സാധ്യമാകുന്ന കാര്യങ്ങൾ മാത്രം ചെയ്യുക. അല്ലാഹു തന്നെ സത്യം, നിങ്ങൾക്ക് മടുപ്പുണ്ടാകുന്നതു വരെ അല്ലാഹുവിന് മടുപ്പ് ഉണ്ടാവുകയില്ല." (മു)', 'عَائِشَةَ', 'പ്രവാചക പത്നി ആയിശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ. وَفِي رِوَايَةٍ قَالَ: كُنَّا نُؤْمَرُ بِالسِّوَاكِ إِذَا قُمْنَا مِنَ اللَّيْلِ. وَفِي رِوَايَةٍ: كُنَّا نُؤْمَرُ إِذَا قُمْنَا مِنَ اللَّيْلِ أَنْ نَشُوصَ أَفْوَاهَنَا بِالسِّوَاكِ. (م,د,ن)', 'ഹുദൈഫ(റ): നബി(സ) രാത്രി ഉറക്കത്തിൽ നിന്ന് എഴുന്നേറ്റാൽ മിസ്വാക്ക് ചെയ്ത് വായ വൃത്തിയാക്കാറുണ്ടായിരുന്നു. ഒരു റിപ്പോർട്ടിൽ: രാത്രിയുറക്കത്തിൽ നിന്നെണീറ്റാൽ മിസ്വാക് ചെയ്യാൻ ഞങ്ങൾ കൽപിക്കപ്പെട്ടിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: രാത്രിയിൽ ഞങ്ങൾ ഉണർന്നാൽ ഞങ്ങളുടെ മിസ്വാക് കൊണ്ട് ശുദ്ധിവരുത്താൻ ഞങ്ങൾ കൽപിക്കപ്പെട്ടിരുന്നു. (മു,ദ,ന)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=274), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنَّا نُؤْمَرُ بِالسِّوَاكِ إِذَا قُمْنَا مِنَ اللَّيْلِ.', 'മറ്റൊരു നിവേദനിൽ: രാത്രിയിൽ ഞങ്ങൾ ഉണർന്നാൽ ഞങ്ങളുടെ മിസ്വാക് കൊണ്ട് ശുദ്ധിവരുത്താൻ ഞങ്ങൾ കൽപിക്കപ്പെട്ടിരുന്നു. (മു,ദ,ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=274), 2, 'وَفِي رِوَايَةٍ: كُنَّا نُؤْمَرُ إِذَا قُمْنَا مِنَ اللَّيْلِ أَنْ نَشُوصَ أَفْوَاهَنَا بِالسِّوَاكِ. (م,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا فِي بُيُوتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا". (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറയുന്നു: റസൂൽ അരുളി: "നിങ്ങൾ നിങ്ങളുടെ വീടുകളിൽ വെച്ച് (സുന്നത്തുകൾ) നിസ്കരിക്കുക. അവയെ ഖബറിടങ്ങളാക്കരുത്." (ബു,മു,ദ,തു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ദ','ന']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ حُجْرَةً فِي الْمَسْجِدِ مِنْ حَصِيرٍ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا لَيَالِيَ حَتَّى اجْتَمَعَ إِلَيْهِ النَّاسُ، ثُمَّ فَقَدُوا صَوْتَهُ لَيْلَةً فَظَنُّوا أَنَّهُ نَائِمٌ، فَجَعَلَ بَعْضُهُمْ يَتَنَحْنَحُ لِيَخْرُجَ إِلَيْهِمْ، فَقَالَ: "مَا زَالَ بِكُمُ الَّذِي رَأَيْتُ مِنْ صَنْعِكُمْ حَتَّى خَشِيتُ أَنْ يُكْتَبَ عَلَيْكُمْ، وَلَوْ كُتِبَ عَلَيْكُمْ مَا قُمْتُمْ بِهِ. فَصَلُّوا أَيُّهَا النَّاسُ فِي بُيُوتِكُمْ، فَإِنَّ أَفْضَلَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ". (خ,ن)', 'സൈദുബ്നു സാബിത്: നബി(സ) പള്ളിയിൽ പായ വിരിച്ച് ഒരു റൂമാക്കി അതിൽ തിരുമേനി രാത്രി നമസ്കാരം നിർവഹിച്ചു പോന്നു. അങ്ങനെ ജനങ്ങൾ ഒരുമിച്ചുകൂടാൻ തുടങ്ങി. ഒരു ദിവസം അവർ തിരുമേനി(സ)യുടെ (നമസ്കരിക്കുന്ന) ശബ്ദം കേൾക്കാതായി. ജനങ്ങൾ കരുതിയത് അവിടുന്ന് ഉറക്കത്തിലായിരിക്കുമെന്നാണ്. ചിലർ ചുമച്ചുകൊണ്ട് ശബ്ദമുണ്ടാക്കി, നബി(സ) അവരിലേക്ക് എത്തുവാൻ വേണ്ടി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ദിനേന ചെയ്തുകൊണ്ടിരിക്കുന്നത് ഞാൻ മനസ്സിലാക്കി. അത് നിങ്ങൾക്ക് ഫർദാക്കപ്പെടുമോ എന്നു പോലും ഞാൻ ഭയന്നു. നിങ്ങൾക്കത് നിർബന്ധമാക്കപ്പെട്ടാൽ നിങ്ങൾക്ക് നിർവഹിക്കാൻ കഴിയില്ല. അതിനാൽ ജനങ്ങളേ, നിങ്ങൾ വീടുകളിൽ നമസ്കരിക്കുക. ഒരാൾ നിർബന്ധമല്ലാത്തവ തന്റെ വീട്ടിൽ വെച്ച് നമസ്കരിക്കുന്നതാണ് അവന് ഉത്തമമായത്." (ബു,ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 615, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْمَغْرِبِ فِي مَسْجِدِ بَنِي عَبْدِ الْأَشْهَلِ، فَلَمَّا صَلَّى قَامَ نَاسٌ يَتَنَفَّلُونَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِهَٰذِهِ الصَّلَاةِ فِي الْبُيُوتِ". (ن)', 'കഅ്ബുബ്നു ഉജ്റ(റ): ''നബി(സ) ബനൂ അബ്ദിൽ അശ്ഹലിന്റെ പള്ളിയിൽ വെച്ച് മഗ്രിബ് നമസ്കരിച്ചു. നമസ്കാരം കഴിഞ്ഞപ്പോൾ ജനങ്ങൾ എഴുന്നേറ്റ് സുന്നത്ത് നമസ്കരിക്കാൻ തുടങ്ങി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ഈ നിസ്കാരം വീട്ടിൽ വെച്ച് നിർവ്വഹിക്കുക." (ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ: أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: قُلْتُ، وَأَنَا فِي سَفَرٍ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: وَاللهِ لَأَرْقُبَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةٍ حَتَّى أَرَى فِعْلَهُ. فَلَمَّا صَلَّى صَلَاةَ الْعِشَاءِ - وَهِيَ الْعَتَمَةُ - اضْطَجَعَ هَوِيًّا مِنَ اللَّيْلِ، ثُمَّ اسْتَيْقَظَ فَنَظَرَ فِي الْأُفُقِ فَقَالَ: {رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا} حَتَّى بَلَغَ: {إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ}. ثُمَّ أَهْوَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى فِرَاشِهِ فَاسْتَلَّ مِنْهُ سِوَاكًا، ثُمَّ أَفْرَغَ فِي قَدَحٍ مِنْ إِدَاوَةٍ عِنْدَهُ مَاءً فَاسْتَنَّ، ثُمَّ قَامَ فَصَلَّى حَتَّى قُلْتُ: قَدْ صَلَّى قَدْرَ مَا نَامَ، ثُمَّ اضْطَجَعَ حَتَّى قُلْتُ: قَدْ نَامَ قَدْرَ مَا صَلَّى، ثُمَّ اسْتَيْقَظَ فَفَعَلَ كَمَا فَعَلَ أَوَّلَ مَرَّةٍ وَقَالَ مِثْلَ مَا قَالَ، فَفَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَ مَرَّاتٍ قَبْلَ الْفَجْرِ. (ن)', 'അബ്ദുർ റഹ്മാനുബ്നു ഔഫിന്റെ മകൻ ഹുമൈദ്: നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട ഒരാൾ ഇപ്രകാരം പറയുന്നു: "ഞാൻ നബി(സ)യോടൊത്തുള്ള ഒരു യാത്രയിൽ ഇപ്രകാരം പറഞ്ഞു: സത്യമായും ഞാൻ റസൂലി(സ)ന്റെ നിസ്കാരം നിരീക്ഷിക്കുകതന്നെ ചെയ്യും. നബി(സ) ഇശാനിസ്കാരം കഴിഞ്ഞപ്പോൾ കുറച്ചുനേരം ഉറങ്ങി. തുടർന്നെഴുന്നേറ്റ് ചക്രവാളത്തിലേക്ക് നോക്കി. ശേഷം "(രക്ഷിതാവേ, നീ ഇവകളെ സൃഷ്ടിച്ചത് നിഷ്ഫലമായിട്ടല്ല)" എന്ന് തുടങ്ങുന്ന സൂക്തം "(നിശ്ചയം നീ വാഗ്ദാന ലംഘനം നടത്തുകയില്ല)" എന്നതുവരെ പാരായണം ചെയ്തു. അനന്തരം തന്റെ വിരിപ്പിലേക്ക് കുനിഞ്ഞ് അതിൽ നിന്ന് ''സിവാക്ക്'' എടുക്കുകയും വെള്ളമുള്ള തോൽപാത്രത്തിൽ നിന്നും വെള്ളമൊഴിച്ച് ദന്തശുദ്ധീകരണം നടത്തുകയും തുടർന്ന് എഴുന്നേറ്റ് നമസ്കരിക്കുകയും ചെയ്തു. അനന്തരം ഞാൻ പറഞ്ഞു: ഉറങ്ങിയ അത്രത്തോളം തന്നെ ദീർഘസമയം നബി(സ) നിസ്കരിച്ചു. പിന്നെ റസൂൽ(സ) തന്റെ വിരിപ്പിലേക്ക് കിടന്നു. അവിടുന്ന് നിസ്കരിച്ച അത്ര സമയമാണ് ഉറങ്ങിയതെന്ന് ഞാൻ പറയുന്നു. വീണ്ടും എഴുന്നേറ്റ് ആദ്യം ചെയ്തതുപോലെ പ്രവർത്തിച്ചു. ആദ്യം ചൊല്ലിയതുപോലെ ചൊല്ലുകയും ചെയ്തു. സുബ്ഹിക്കു മുമ്പ് ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം ആവർത്തിച്ചു. (ന)', 'حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർ റഹ്മാനുബ്നു ഔഫിന്റെ മകൻ ഹുമൈദ്', null, null, array['ن']::text[], array['ന']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَبِيتُ عِنْدَ حُجْرَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكُنْتُ أَسْمَعُهُ إِذَا قَامَ مِنَ اللَّيْلِ يَقُولُ: "سُبْحَانَ اللهِ رَبِّ الْعَالَمِينَ"، الْهَوِيَّ، ثُمَّ يَقُولُ: "سُبْحَانَ اللهِ وَبِحَمْدِهِ". الْهَوِيَّ. (ن)', 'റബീഅതുബിൻ കഅ്ബിൽ അസ്‌ലമി(റ): ഞാൻ തിരുമേനി(സ)യുടെ റൂമിന്റെയടുത്ത് രാത്രി താമസിക്കാറുണ്ടായിരുന്നു.അപ്പോൾ നബി(സ) രാത്രി എഴുനേറ്റ് ദീർഘ നേരം "ലോകങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു" എന്നും ശേഷം "അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം അവന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു"വെന്ന് രാത്രിയിൽ കുറച്ചുനേരവും ചൊല്ലുന്നത് ഞാൻ കേൾക്കാറുണ്ടായിരുന്നു. (ന)', 'رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ', 'റബീഅതുബിൻ കഅ്ബിൽ അസ്‌ലമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 616, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ خَبَّابِ بْنِ الْأَرَتِّ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ قَدْ شَهِدَ بَدْرًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ رَاقَبَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّيْلَةَ كُلَّهَا حَتَّى كَانَ مَعَ الْفَجْرِ، فَلَمَّا سَلَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ صَلَاتِهِ جَاءَهُ خَبَّابٌ فَقَالَ: يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي، لَقَدْ صَلَّيْتَ اللَّيْلَةَ صَلَاةً مَا رَأَيْتُكَ صَلَّيْتَ نَحْوَهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَجَلْ، إِنَّهَا صَلَاةُ رَغَبٍ وَرَهَبٍ، سَأَلْتُ رَبِّي عَزَّ وَجَلَّ فِيهَا ثَلَاثَ خِصَالٍ، فَأَعْطَانِي اثْنَتَيْنِ وَمَنَعَنِي وَاحِدَةً: سَأَلْتُ رَبِّي عَزَّ وَجَلَّ: أَنْ لَا يُهْلِكَنَا بِمَا أَهْلَكَ بِهِ الْأُمَمَ قَبْلَنَا، فَأَعْطَانِيهَا. وَسَأَلْتُ رَبِّي عَزَّ وَجَلَّ: أَنْ لَا يُظْهِرَ عَلَيْنَا عَدُوًّا مِنْ غَيْرِنَا، فَأَعْطَانِيهَا. وَسَأَلْتُ رَبِّي: أَنْ لَا يَلْبِسَنَا شِيَعًا، فَمَنَعَنِيهَا". (ن)', 'ഹബ്വാബിബ്നുൽ അറത്ത്(റ): അദ്ദേഹം ബദ്‌റിൽ നബി(സ)യോടൊത്ത് പങ്കെടുത്തയാളായിരുന്നു. അദ്ദേഹം റസൂലിനെ ഒരു രാത്രി ഫജ്‌ർ വരെ വീക്ഷിച്ചു. റസൂൽ(സ) നിസ്കാരത്തിൽ നിന്നും സലാം വീട്ടിയപ്പോൾ ഖബ്ബാബ് വന്നു ചോദിച്ചു: "അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പിതാവിനെയും മാതാവിനെയും താങ്കൾക്ക് അർപ്പണം. താങ്കൾ ഈ രാത്രി നിസ്കരിച്ചതു പോലെ മുമ്പ് നിസ്കരിച്ചത് ഞാൻ കണ്ടിട്ടില്ല." റസൂൽ(സ) പറഞ്ഞു: "അത് ഭയത്തിന്റെയും ആഗ്രഹത്തിന്റെയും നിസ്കാരമായിരുന്നു. ഉന്നതനും പ്രതാപവാനുമായ എന്റെ രക്ഷിതാവിനോട് അതിൽ മൂന്നു കാര്യങ്ങൾ ചോദിച്ചു. രണ്ട് കാര്യങ്ങൾ അവൻ നൽകുകയും ഒന്നിനെ എനിക്ക് നിഷേധിക്കുകയും ചെയ്തു; ഞാൻ എന്റെ രക്ഷിതാവിനോട് ചോദിച്ചു: "എന്റെ സമൂഹത്തെ പൂർവികരെ നശിപ്പിച്ചതു കൊണ്ട് നശിപ്പിക്കരുതേ." അതെനിക്ക് അവൻ നൽകി. ഞാനെന്റെ രക്ഷിതാവിനോട് ചോദിച്ചു: നാം ഒഴികെയുള്ള ശത്രുക്കളെ നമ്മുടെ മേൽ ആധിപത്യം ഉള്ളവരാക്കരുതേ! അങ്ങനെ, അതും എനിക്ക് നൽകി. നമ്മെ പല വിഭാഗങ്ങളാക്കി മാറ്റരുതേ എന്ന് ഞാൻ ചോദിച്ചു. എന്നാൽ, അതെനിക്ക് അവൻ നൽകിയില്ല." (ന)', 'خَبَّابِ بْنِ الْأَرَتِّ', 'ഹബ്വാബിബ്നുൽ അറത്ത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ إِذَا دَخَلَتِ الْعَشْرُ أَحْيَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّيْلَ، وَأَيْقَظَ أَهْلَهُ، وَشَدَّ الْمِئْزَرَ. (ن)', 'ആഇശ(റ) പറയുന്നു: റമദാൻ അവസാന പത്ത് കടന്നുവന്നാൽ റസൂൽ(സ) രാത്രിയെ ആരാധനകൊണ്ട് സജീവമാക്കുകയും തന്റെ കുടുംബത്തെ ഉണർത്തുകയും അരമുണ്ടൊക്കെ കെട്ടിയുടുത്ത് ആരാധനക്ക് വേണ്ടി തയ്യാറാവുകയും ചെയ്യുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ أَبِي إِسْحَاقَ قَالَ: أَتَيْتُ الْأَسْوَدَ بْنَ يَزِيدَ، وَكَانَ لِي أَخًا صَدِيقًا، فَقُلْتُ: يَا أَبَا عَمْرٍو، حَدِّثْنِي مَا حَدَّثَتْكَ بِهِ أُمُّ الْمُؤْمِنِينَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: قَالَتْ: كَانَ يَنَامُ أَوَّلَ اللَّيْلِ وَيُحْيِي آخِرَهُ. (ن)', 'അബൂഇസ്ഹാഖ്: ഞാൻ അസ്‌വദുബനു യസീദിന്റെ അടുക്കൽ ചെന്നു. അവൻ എന്റെ സത്യസന്ധനായ സഹോദരൻ ആയിരുന്നു. ഞാൻ ചോദിച്ചു: ഓ അബൂഅംറേ, റസൂലി(സ)ന്റെ രാത്രി നിസ്കാരത്തെക്കുറിച്ച് ഉമ്മുൽമുഅ്മിനീൻ താങ്കൾക്ക് വിവരിച്ചു തന്നത് എനിക്ക് അറിയിച്ചു തന്നാലും. അവർ പറഞ്ഞതായി അദ്ദേഹം പറഞ്ഞു: നബി(സ) രാത്രിയുടെ തുടക്കത്തിൽ ഉറങ്ങുകയും അവസാന യാമത്തിൽ ആരാധനകൊണ്ട് സജീവമാക്കുകയും ചെയ്യുകയായിരുന്നു പതിവ്. (ന)', 'أَبِي إِسْحَاقَ قَالَ', 'അബൂഇസ്ഹാഖ്', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَا أَعْلَمُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا قَامَ لَيْلَةً حَتَّى الصَّبَاحَ، وَلَا صَامَ شَهْرًا كَامِلًا قَطُّ غَيْرَ رَمَضَانَ. (ن)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ മുഴുവനും ഖുർആൻ പാരായണം ചെയ്തതായി എനിക്കറിയില്ല. പ്രഭാതം വരെ നിസ്കരിച്ചതായും എനിക്കറിയില്ല. ഒരു മാസം മുഴുവനും - റദമാൻ ഒഴികെ - നോമ്പനുഷ്ഠിച്ചതായും എനിക്കറിയില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ، فَقَالَ: "مَنْ هَذِهِ". قَالَتْ: فُلَانَةُ، لَا تَنَامُ. فَذَكَرَتْ مِنْ صَلَاتِهَا، فَقَالَ: "مَهْ، عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللهِ لَا يَمَلُّ اللهُ عَزَّ وَجَلَّ حَتَّى تَمَلُّوا، وَلَكِنَّ أَحَبَّ الدِّينِ إِلَيْهِ مَا دَاوَمَ عَلَيْهِ صَاحِبُهُ". (ن)', 'ആയിശ(റ): നബി(സ) അവരുടെ അടുത്ത് കടന്നു ചെന്നപ്പോൾ അവിടെ ഒരു സ്ത്രീയുണ്ടായിരുന്നു. നബി(സ) ചോദിച്ചു: "അത് ആരാണ്?" മഹതി പറഞ്ഞു: ഇത് ഇന്ന സ്ത്രീയാണ്. അവൾ ഉറങ്ങുകയില്ല. മഹതി അവളുടെ നിസ്കാരത്തെക്കുറിച്ചു വിവരിച്ചു പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് വിടു. നിങ്ങൾക്ക് സാധ്യമാകുന്നത് മുറുകെ പിടിക്കുക! നിങ്ങൾ അസ്വസ്ഥരാകുന്നതു വരെ അല്ലാഹു വെറുക്കുകയില്ല. എന്നാൽ അല്ലാഹുവിന് ഏറ്റവും പ്രിയങ്കരമായത് അടിമ നിത്യമായി ചെയ്യുന്ന സൽകർമ്മങ്ങളാണ്." (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْمَسْجِدَ فَرَأَى حَبْلًا مَمْدُودًا بَيْنَ سَارِيَتَيْنِ، فَقَالَ: "مَا هَذَا الْحَبْلُ". فَقَالُوا: لِزَيْنَبَ، تُصَلِّي، فَإِذَا فَتَرَتْ تَعَلَّقَتْ بِهِ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حُلُّوهُ، لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ، فَإِذَا فَتَرَ فَلْيَقْعُدْ". (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരിക്കൽ പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ രണ്ടു തൂണുകൾക്കിടയിൽ നീണ്ട ഒരു കയർ കണ്ടു. അവിടുന്ന് ചോദിച്ചു: "ഈ കയർ ഏതാണ്?" അവർ പറഞ്ഞു: സൈനബി(റ)ന്റേതാണ്; അവർ നിസ്കരിക്കുന്നു, തളർച്ച ബാധിച്ചാൽ അവർ അതിൽ പിടിക്കും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അതിനെ അഴിക്കുക! നിങ്ങളിലൊരാൾ ഉന്മേഷസമയത്ത് നിസ്കരിക്കട്ടെ, തളർച്ച വന്നാൽ കിടന്നുറങ്ങട്ടെ!" (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عن مُغِيرَةَ بنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَوَرَّمَتْ قَدَمَاهُ، فَقِيلَ لَهُ: قَدْ غَفَرَ اللهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ. قَالَ: "أَفَلَا أَكُونُ عَبْدًا شَكُورًا". (ن)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): നബി(സ) കാലിൽ നീര് കെട്ടുന്നതു വരെ എഴുന്നേറ്റ് നിസ്കരിച്ചു. അവിടുത്തോട് ചോദിക്കപ്പെട്ടു: താങ്കളുടെ മുൻ കഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ പാപങ്ങൾ അല്ലാഹു പൊറുത്തു തന്നിട്ടുണ്ടല്ലോ. അവിടുന്ന് പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിന് നന്ദിയുള്ള ദാസനാകണ്ടേ?" (ന)', 'مُغِيرَةَ بنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي حَتَّى تَزَلَّعَ - يَعْنِي: تَشَقَّقَ - قَدَمَاهُ. (ن)', 'അബൂഹുറൈറ(റ): റസൂലി(സ)ന്റെ പാദങ്ങൾക്ക് പൊട്ടൽ സംഭവിക്കുന്നത് വരെ രാത്രി നിന്ന് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحَبُّ الصِّيَامِ إِلَى اللَّهِ عَزَّ وَجَلَّ صِيَامُ دَاوُدَ عَلَيْهِ السَّلَامُ: كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ دَاوُدَ: كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ." (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിങ്കൽ ഏറ്റവും പ്രിയങ്കരമായ നോമ്പ് ദാവൂദ് നബി(അ)യുടെ നോമ്പാണ്; അദ്ദേഹം ഒരു ദിവസം വ്രതമനുഷ്ഠിക്കുകയും ഒരു ദിവസം ഉപേക്ഷിക്കുകയും ചെയ്യുമായിരുന്നു. അല്ലാഹുവിലേക്ക് ഏറ്റവും പ്രിയങ്കരമായത് ദാവൂദ് നബി(അ)യുടെ നിസ്കാരമാണ്; രാത്രിയുടെ പകുതി വരെ അദ്ദേഹം ഉറങ്ങുകയും, അതിന്റെ മൂന്നിലൊന്ന് നിന്ന് നിസ്കരിക്കുകയും ആറിലൊന്ന് ഭാഗം ഉറങ്ങുകയും ചെയ്യുമായിരുന്നു." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتَيْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى مُوسَى عَلَيْهِ السَّلَامُ عِنْدَ الْكَثِيبِ الْأَحْمَرِ، وَهُوَ قَائِمٌ يُصَلِّي فِي قَبْرِهِ." (ن)', 'അനസ് ബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "എന്നെ ആകാശാരോഹണം ചെയ്യപ്പെട്ടിട്ടുള്ള രാത്രി ''കസീബുൽ അഹ്മറി''ന്റെ അടുത്ത് വെച്ച് ഞാൻ മൂസാ നബി(അ)യുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ മൂസാ നബി(അ) അദ്ദേഹത്തിന്റെ ഖബ്റിൽ നിസ്കരിച്ച് കൊണ്ടിരിക്കുകയായിരുന്നു." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ് ബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي لَيْلًا طَوِيلًا، فَإِذَا صَلَّى قَائِمًا رَكَعَ قَائِمًا، وَإِذَا صَلَّى قَاعِدًا رَكَعَ قَاعِدًا. (ن)', 'ആയിശ(റ): നബി(സ) രാത്രിയിൽ നീണ്ട നേരം നിസ്കരിക്കുമായിരുന്നു. നിന്ന് നിസ്കരിച്ചാൽ നിന്ന് റുകൂഅ് ചെയ്യുകയും ഇരുന്ന് നിസ്കരിച്ചാൽ ഇരുന്ന് റുകൂഅ് ചെയ്യുകയും ചെയ്യുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي وَهُوَ جَالِسٌ، فَيَقْرَأُ وَهُوَ جَالِسٌ، فَإِذَا بَقِيَ مِنْ قِرَاءَتِهِ قَدْرُ مَا يَكُونُ ثَلَاثِينَ أَوْ أَرْبَعِينَ آيَةً قَامَ فَقَرَأَ وَهُوَ قَائِمٌ ثُمَّ، رَكَعَ ثُمَّ سَجَدَ، ثُمَّ يَفْعَلُ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ. (ن)', 'ആയിശ(റ): നബി(സ) ഇരുന്ന് നിസ്കരിക്കുമായിരുന്നു. അപ്പോൾ ഇരുന്ന് ഓതുകയും ഏതാണ്ട് മുപ്പതോ നാല്പതോ ആയത്ത് ഓതുന്നത്ര സമയം തന്റെ ''ഖിറാഅത്തി''ൽ നിന്നും അവശേഷിച്ചാൽ നിന്ന് ഓതുകയും ചെയ്യുമായിരുന്നു. തുടർന്ന് റുകൂഉം സുജൂദും ചെയ്യുമായിരുന്നു. രണ്ടാമത്തെ റകഅത്തിലും ഇതു പോലെ ചെയ്യും. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى جَالِسًا حَتَّى دَخَلَ فِي السِّنِّ، فَكَانَ يُصَلِّي وَهُوَ جَالِسٌ يَقْرَأُ، فَإِذَا غَبَرَ مِنَ السُّورَةِ ثَلَاثُونَ أَوْ أَرْبَعُونَ آيَةً قَامَ فَقَرَأَ بِهَا ثُمَّ رَكَعَ. (ن)', 'ആയിശ(റ): വാർദ്ധക്യമാകുന്നതു വരെ നബി(സ) ഇരുന്ന് നിസ്കരിക്കുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. ഇരുന്ന് ഖുർആൻ പാരായണം ചെയ്ത് നബി(സ) നിസ്കരിക്കുമായിരുന്നു. സൂറത്തിൽ നിന്നും മുപ്പതും നാല്പതും ആയത്ത് കഴിഞ്ഞുകടന്നാൽ നിന്ന് ഓതുകയും തുടർന്ന് റുകൂഅ് നിർവഹിക്കുകയും ചെയ്യുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ وَهُوَ قَاعِدٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ قَدْرَ مَا يَقْرَأُ إِنْسَانٌ أَرْبَعِينَ آيَةً. (ن)', 'ആയിശ(റ): നബി(സ) ഇരുന്ന് ഖുർആൻ പാരായണം ചെയ്യുമായിരുന്നു. റുകൂഅ് നിർവഹിക്കാൻ ഉദ്ദേശിച്ചാൽ ഒരു മനുഷ്യൻ നാല്പത് ആയത്ത് ഓതുന്ന അളവ് നിൽക്കുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْتَنِعُ مِنْ وَجْهِي وَهُوَ صَائِمٌ، وَمَا مَاتَ حَتَّى كَانَ أَكْثَرُ صَلَاتِهِ قَاعِدًا، إِلَّا الْمَكْتُوبَةَ، وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ مَا دَامَ عَلَيْهِ الْإِنْسَانُ وَإِنْ كَانَ يَسِيرًا. (ن)', 'ആയിശ(റ): നബി(സ) നോമ്പുകാരനായിരിക്കെ എന്നിൽ നിന്നും അകലുമായിരുന്നില്ല. നബി(സ)യുടെ ഫർളുകളൊഴികെയുള്ള അധിക നിസ്കാരങ്ങളും ഇരുന്നുകൊണ്ടാവുന്നതുവരെ അവിടുന്ന് വഫാതായിട്ടില്ല. മനുഷ്യൻ നിത്യമായി ചെയ്യുന്ന പ്രവർത്തനമായിരുന്നു നബി(സ)ക്ക് ഏറ്റവും പ്രിയങ്കരം അത് കുറവാണെങ്കിലും ശരി. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى كَانَ أَكْثَرُ صَلَاتِهِ قَاعِدًا إِلَّا الْفَرِيضَةَ، وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ أَدْوَمَهُ وَإِنْ قَلَّ. (ن)', 'ഉമ്മുസലമ(റ): ഫർളുകളല്ലാത്ത അധിക നിസ്കാരങ്ങളും ഇരുന്ന് നിർവ്വഹിക്കുന്നതുവരെ നബി(സ) വഫാതായിട്ടില്ല. അവിടുത്തേക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത് കുറഞ്ഞതെങ്കിലും നിത്യവും ചെയ്യുന്ന ആരാധനകളാണ്. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي شَيْءٍ مِنْ صَلَاةِ اللَّيْلِ جَالِسًا حَتَّى إِذَا كَبِرَ قَرَأَ جَالِسًا حَتَّى إِذَا بَقِيَ عَلَيْهِ مِنَ السُّورَةِ ثَلَاثُونَ أَوْ أَرْبَعُونَ آيَةً قَامَ فَقَرَأَهُنَّ ثُمَّ رَكَعَ. (م)', 'ആയിശ(റ): ഏതെങ്കിലും രാത്രിനിസ്കാരങ്ങളിൽ നബി(സ) ഇരുന്നുകൊണ്ട് ഖുർആൻ പാരായണം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടില്ല. എന്നാൽ വാർദ്ധക്യമായപ്പോൾ ഇരുന്ന് ഓതാറുണ്ടായിരുന്നു. ഓതുന്ന സൂറത്തിൽ മുപ്പതോ നാൽപതോ സൂക്തങ്ങൾ ബാക്കിയുള്ളപ്പോൾ എഴുന്നേറ്റുനിന്ന് അവ ഓതും. പിന്നെ റുകൂഅ് ചെയ്യും. (മു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يَمُتْ حَتَّى كَانَ يُصَلِّي كَثِيرًا مِنْ صَلَاتِهِ وَهُوَ جَالِسٌ. (ن)', 'ആയിശ(റ): അധിക നിസ്കാരങ്ങളും ഇരുന്ന് നിർവഹിക്കുന്ന അവസ്ഥ എത്തിയതിനു ശേഷം മാത്രമാണ് നബി(സ) ഇഹലോകവാസം വെടിഞ്ഞത്. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ حَفْصَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي سُبْحَتِهِ قَاعِدًا قَطُّ، حَتَّى كَانَ قَبْلَ وَفَاتِهِ بِعَامٍ، فَكَانَ يُصَلِّي قَاعِدًا يَقْرَأُ بِالسُّورَةِ، فَيُرَتِّلُهَا حَتَّى تَكُونَ أَطْوَلَ مِنْ أَطْوَلَ مِنْهَا. (ن)', 'ഹഫ്സ(റ): മഹതി പറഞ്ഞു: നബി(സ) ഇരുന്ന് നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടേയില്ല. എന്നാൽ വഫാത്തിന്റെ ഒരു വർഷം മുമ്പു മുതൽ അവിടുന്ന് ഇരുന്ന് നിസ്കരിക്കുകയും സൂറത്ത് ഓതുകയും ചെയ്യാറുണ്ടായിരുന്നു. സാവകാശം ഓതുന്നതു കാരണം നബി(സ) ഓതുന്ന സൂറത്ത് അതിനേക്കാൾ ദീർഘമായ സൂറതുകളേക്കാൾ ദൈർഘ്യമുള്ളതായി അനുഭവപ്പെടും. (ന)', 'حَفْصَةَ', 'ഹഫ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي جَالِسًا، فَقُلْتُ: حُدِّثْتُ أَنَّكَ قُلْتَ: "إِنَّ صَلَاةَ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ". وَأَنْتَ تُصَلِّي قَاعِدًا. قَالَ: "أَجَلْ، وَلَكِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) ഇരുന്ന് നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: "ഇരുന്ന് നിസ്കരക്കുന്നവന്റെ നിസ്കാരം നിന്ന് നമസ്കരിക്കുന്നവന്റെ നിസ്കാരത്തിന്റെ പകുതിയാണെ"ന്ന് അങ്ങ് പറഞ്ഞതായി എനിക്കൊരു ഹദീസ് കിട്ടിയിട്ടുണ്ടല്ലോ? എന്നിട്ട് അങ്ങിപ്പോൾ ഇരുന്ന് നിസ്കരിക്കുകയാണോ? നബി(സ) പറഞ്ഞു: "അതെ, പക്ഷേ ഞാൻ നിങ്ങളിൽ ഒരാളെപ്പോലെയും അല്ല." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مُتَرَبِّعًا. (ن)', 'ആയിശ(റ): നബി(സ) ചമ്രം പടിഞ്ഞിരുന്ന് നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: فِي الْمُزَّمِّلِ {قُمِ اللَّيْلَ إِلَّا قَلِيلًا نِصْفَهُ} نَسَخَتْهَا الْآيَةُ الَّتِي فِيهَا {عَلِمَ أَنْ لَنْ تُحْصُوهُ فَتَابَ عَلَيْكُمْ فَاقْرَءُوا مَا تَيَسَّرَ مِنَ الْقُرْآنِ} وَ - نَاشِئَةَ اللَّيْلِ أَوَّلُهُ - وَكَانَتْ صَلَاتُهُمْ لِأَوَّلِ اللَّيْلِ. يَقُولُ: هُوَ أَجْدَرُ أَنْ تُحْصُوا مَا فَرَضَ اللهُ عَلَيْكُمْ مِنْ قِيَامِ اللَّيْلِ، وَذَلِكَ أَنَّ الْإِنْسَانَ إِذَا نَامَ لَمْ يَدْرِ مَتَى يَسْتَيْقِظُ، وَقَوْلُهُ {أَقْوَمُ قِيلًا} هُوَ أَجْدَرُ أَنْ يَفْقَهَ فِي الْقُرْآنِ، وَقَوْلُهُ {إِنَّ لَكَ فِي النَّهَارِ سَبْحًا طَوِيلًا} يَقُولُ: فَرَاغًا طَوِيلًا. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): മുസമ്മിൽ സൂറത്തിലെ ''രാത്രിയിലെ കുറച്ചു സമയം ഒഴിച്ച് എഴുന്നേറ്റുനിന്ന് നിസ്കരിക്കുക. അല്ലെങ്കിൽ രാത്രിയുടെ പകുതി.'' എന്ന സൂക്തത്തെ(അതിലെ വിധിയെ) അതേ സൂറത്തിലുള്ള ''അതിനെ ക്ലിപ്തപ്പെടുത്താൻ നിങ്ങൾക്കാവുകയില്ലെന്ന് അല്ലാഹു അറിഞ്ഞിരിക്കുന്നു. നിങ്ങളുടെ പാപങ്ങളെ അവൻ ഏറ്റെടുത്തിരിക്കുന്നു. അതിനാൽ ഖുർആനിൽ നിന്ന് സാധ്യമായത്ര നിങ്ങൾ ഓതുക.'' എന്ന സൂക്തം ദുർബലപ്പെടുത്തിയിരിക്കുന്നു. എന്നതുകൊണ്ട് വിവക്ഷ രാത്രിയുടെ ആദ്യഭാഗമെന്നാണ്. അവർ രാത്രിയുടെ ആദ്യഭാഗത്തായിരുന്നു നിസ്കരിച്ചിരുന്നത്. രാത്രി നിസ്കാരം കൃത്യമായി നിർവഹിക്കാൻ ഏറ്റവും ഉചിതം ആ സമയമാണ്. കാരണം മനുഷ്യനുറങ്ങിക്കഴിഞ്ഞാൽ എപ്പോഴാണ് ഉണരുക എന്നറിയില്ല. ''അഖ്‌വമു ഖീലാ'' എന്നാൽ ''ഖുർആൻ ഗ്രഹിക്കാൻ ഏറ്റവും ഉതകുന്നത്'' എന്നാണ്. മറ്റെരു ആയത്തിൽ ''ഇന്നലക ഫിന്നഹാരി സബ്ഹൻ ത്വവീലാ'' എന്നതുകൊണ്ട് അല്ലാഹു ഉദ്ദേശിക്കുന്നത് പകലിൽ അങ്ങേക്ക് നീണ്ട ഒഴിവു സമയുണ്ട് എന്നാണ്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ أَوَّلُ الْمُزَّمِّلِ كَانُوا يَقُومُونَ نَحْوًا مِنْ قِيَامِهِمْ فِي شَهْرِ رَمَضَانَ، حَتَّى نَزَلَ آخِرُهَا، وَكَانَ بَيْنَ أَوَّلِهَا وَآخِرِهَا سَنَةٌ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ) : മുസമ്മിൽ സൂറത്തിലെ ആദ്യഭാഗം അവതരിച്ചപ്പോൾ റമദാനിലെ നിസ്കാരത്തിൽ നിൽക്കന്നത്ര സമയം അവർ (രാത്രിനിസ്കാരങ്ങളിൽ)നിൽക്കാറുണ്ടായിരുന്നു. അങ്ങനെ അവസാന ഭാഗം അവതരിച്ചു. രണ്ടിനുമിടയിൽ ഒരു വർഷമുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أخذ بيده وَقَالَ: "يَا مُعَاذُ وَاللهِ إِنِّي لَأُحِبُّكَ". فَقَالَ: أُوصِيكَ يَا مُعَاذُ، لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُول: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عبادتك. (ن)', 'മുആദുബ്നു ജബൽ(റ): പ്രവാചകൻ(സ) അദ്ദേഹത്തിന്റെ കൈപിടിച്ചു പറഞ്ഞു: മുആദേ, അല്ലാഹുവാണേ സത്യം. ഞാൻ നിന്നെ സ്നേഹിക്കുന്നു. അല്ലാഹുവാണെ സത്യം, ഞാൻ നിന്നെ സ്നേഹിക്കുന്നു. മുആദേ, ഞാൻ നിന്നോട് വസ്വിയ്യത്ത് ചെയ്യുന്നു: ''അല്ലാഹുവേ നിന്നെ സ്മരിക്കാനും നന്ദിചെയ്യാനും നല്ല നിലയിൽ ആരാധിക്കാനും നീ എന്നെ സഹായിക്കണേ'' എന്ന് ഒരു നിസ്കാര ശേഷവും നീ പ്രാർത്ഥിക്കാതിരിക്കരുത്. (ന)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ بِالْمُعَوِّذَاتِ دُبُرَ كُلِّ صَلَاةٍ. (د)', 'ഉഖ്ബതുബ്നു ആമിർ: എല്ലാ നിസ്കാരശേഷവും ''മുഅവ്വിദാത്ത്'' (സൂറഃ ഇഖ്ലാസ് ഫലഖ്, നാസ്,) ഓതാൻ പ്രവാചകൻ(സ) എന്നോട് കൽപിച്ചു. (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ', null, null, array['د']::text[], array['ദ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ عَبْدِ اللهِ بن مسعود، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): മൂന്ന് പ്രാവശ്യം പ്രാർത്ഥിക്കലും പൊറുക്കലിനെ തേടലും പ്രവാചകനെ സന്തോഷിപ്പിക്കുമായിരുന്നു. (ദ)', null, 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَقُولِينَهُنَّ عِنْدَ الْكَرْبِ، أَوْ فِي الْكَرْبِ، اَللهُ اَللهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا". (د)', 'അസ്മാഅ് ബിൻത് ഉമൈസ്: പ്രവാചകൻ(സ) എന്നോട് പറഞ്ഞു: "പ്രയാസമനുഭവിക്കുമ്പോൾ നീ ചൊല്ലേണ്ട ചില വചനങ്ങൾ ഞാൻ നിന്നെ പഠിപ്പിക്കട്ടെയോ? അല്ലാഹുവേ, അല്ലാഹുവാകുന്നു എന്റെ പരിപാലകൻ. ഒരു വസ്തുവിനെയും അവനോട് ഞാൻ പങ്കുചേർക്കുകയില്ല." (ദ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ', 'അസ്മാഅ് ബിൻത് ഉമൈസ്', null, null, array['د']::text[], array['ദ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عن أبي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَلَمَّا دَنَوْا مِنَ الْمَدِينَةِ كَبَّرَ النَّاسُ وَرَفَعُوا أَصْوَاتَهُمْ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "يَا أَيُّهَا النَّاسُ، إِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا، إِنَّ الَّذِي تَدْعُونَهُ بَيْنَكُمْ، وَبَيْنَ أَعْنَاقِ رِكَابِكُمْ" ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا مُوسَى، أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ" فَقُلْتُ: وَمَا هُوَ؟ قَالَ "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ". وَفِي رِوَايَةٍ: أَنَّهُمْ كَانُوا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُمْ يَتَصَعَّدُونَ فِي ثَنِيَّةٍ فَجَعَلَ رَجُلٌ كُلَّمَا عَلَا الثَّنِيَّةَ نَادَى لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكُمْ لَا تُنَادُونَ أَصَمَّ وَلَا غَائِبًا" ثُمَّ قَالَ: "يَا عَبْدَ اللهِ ابْنَ قَيْسٍ" فَذَكَرَ مَعْنَاهُ. وَفِي رِوَايَةٍ: "يَا أَيُّهَا النَّاسُ ارْبَعُوا عَلَى أَنْفُسِكُمْ". (د)', 'അബുമുസൽ അശ്അരി(റ): ഞാൻ പ്രവാചകന്റെ കൂടെ യാത്രയിലായിരുന്നു. അങ്ങനെ മദീനയോടടുത്തപ്പോൾ ജനങ്ങൾ ശബ്ദമുയർത്തി തക്ബീർ മുഴക്കി. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: ജനങ്ങളേ, നിങ്ങൾ വിളിക്കുന്നവൻ ബധിരനോ മറഞ്ഞവനോ അല്ല. നിശ്ചയം; നിങ്ങൾ വിളിക്കുന്നവൻ നിങ്ങളുടെയും നിങ്ങളുടെ വാഹനത്തിന്റെ കഴുത്തിന്റെയും ഇടയിലാണ്. പിന്നെ പ്രവാചകൻ(സ) പറഞ്ഞു: "ഓ അബൂമൂസാ, സ്വർഗീയ നിധികളിൽ നിന്നുള്ള ഒരു നിധിയെ ഞാൻ അറിയിച്ചുതരട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെന്താണ്? പ്രവാചകൻ(സ) പറഞ്ഞു: "തിന്മ ഒഴിവാക്കാനുള്ള ശക്തിയും നന്മ ചെയ്യാനുള്ള ശക്തിയും നിന്നിൽനിന്നു മാത്രമാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=307), 1, 'وَفِي رِوَايَةٍ: أَنَّهُمْ كَانُوا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُمْ يَتَصَعَّدُونَ فِي ثَنِيَّةٍ فَجَعَلَ رَجُلٌ كُلَّمَا عَلَا الثَّنِيَّةَ نَادَى لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكُمْ لَا تُنَادُونَ أَصَمَّ وَلَا غَائِبًا" ثُمَّ قَالَ: "يَا عَبْدَ اللهِ ابْنَ قَيْسٍ" فَذَكَرَ مَعْنَاهُ.', 'മറ്റൊരു നിവേദനം: അവർ പ്രവാചകനോ(സ)ടൊപ്പം ഒരു മലയോരപ്പാത കയറുകയായിരുന്നു. അവരെല്ലാവരും പാത പിന്നിട്ടപ്പോൾ ഒരാൾ വിളിച്ചുപറഞ്ഞു: അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. അല്ലാഹു എത്ര മഹോന്നതൻ. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം നിങ്ങൾ വിളിക്കുന്നത് ഒരു ബധിരനെയോ അപ്രത്യക്ഷമായവനെയോ അല്ല." പിന്നെ പ്രവാചകൻ(സ) പറഞ്ഞു: "അബ്ദുല്ലാഹിബ്നു ഖൈസേ........, " പിന്നെ ഹദീസിന്റെ ആശയം പറഞ്ഞു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=307), 2, 'وَفِي رِوَايَةٍ: "يَا أَيُّهَا النَّاسُ ارْبَعُوا عَلَى أَنْفُسِكُمْ". (د)', 'മറ്റൊരു നിവേദനം: "ജനങ്ങളേ, നിങ്ങൾ സ്വയം മിതത്വം പാലിക്കുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عن أبي سعيد الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ "مَنْ قَالَ: رَضِيتُ بِاللهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ رَسُولًا، وَجَبَتْ لَهُ الْجَنَّةُ". (د)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ റബ്ബായും ഇസ്ലാമിനെ ദീനായും മുഹമ്മദി(സ)നെ നബിയായും ഞാൻ തൃപ്തിപ്പെട്ടു" എന്ന് പറഞ്ഞവന് സ്വർഗം നിർബന്ധമായിരിക്കുന്നു." (ദ)', 'أبي سعيد الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللهُ عَلَيْهِ عَشْرًا". (م,د,ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ആരെങ്കിലും എന്റെ മേൽ ഒരു സ്വലാത്ത് ചൊല്ലിയാൽ അല്ലാഹു അവന്റെ മേൽ പത്ത് സ്വലാത്ത് ചൊല്ലും." (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَوْسِ بْنِ أَوْسٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ: فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ" قَالَ: فَقَالُوا: يَا رَسُولَ اللهِ، وَكَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ قَالَ: يَقُولُونَ بَلِيتَ، قَالَ: "إِنَّ اللهَ [تَبَارَكَ وَتَعَالَى] حَرَّمَ عَلَى الْأَرْضِ أَجْسَادَ الْأَنْبِيَاءِ صَلَّى اللهُ عَلَيْهِمْ". (د)', 'ഔസുബ്നു ഔസ്(സ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ദിനങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് വെള്ളിയാഴ്ചയാണ്. അതിനാൽ ആ ദിനത്തിൽ നിങ്ങൾ എന്റെ മേൽ സ്വലാത്ത് വർദ്ധിപ്പിക്കുക. നിശ്ചയം നിങ്ങളുടെ സ്വലാത്തുകൾ എനിക്ക് കാണിക്കപ്പെടുന്നതാണ്." അവർ ചോദിച്ചു: പ്രവാചകരേ, അങ്ങ് നുരുമ്പിയിരിക്കെ എങ്ങനെയാണ് ഞങ്ങളുടെ സ്വലാത്തുകൾ കാണിക്കപ്പെടുക? പ്രവാചൻ(സ) പറഞ്ഞു: "മഹോന്നതനായ അല്ലാഹു അമ്പിയാക്കളുടെ ശരീരം ഭൂമിക്കു നിഷിദ്ധമാക്കിയിരിക്കുന്നു. അവർക്ക് അല്ലാഹു ഗുണം ചെയ്തിരിക്കുന്നു." (ദ)', 'أَوْسِ بْنِ أَوْسٍ قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], 'تَبَارَكَ وَتَعَالَى', null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيَدَعُ الْعَمَلَ وَهُوَ يُحِبُّ أَنْ يَعْمَلَ بِهِ خَشْيَةَ أَنْ يَعْمَلَ بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ، وَمَا سَبَّحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُبْحَةَ الضُّحَى قَطُّ، وَإِنِّي لَأُسَبِّحُهَا. (خ)', 'ആഇശ(റ): നബി(സ) ചെയ്യാനാഗ്രഹിക്കുന്ന പല കർമ്മങ്ങളും ജനങ്ങൾ ചെയ്ത് അതവർക്ക് നിർബന്ധമാവുമോ എന്നു ഭയന്ന് ഉപേക്ഷിക്കാറുണ്ടായിരുന്നു. നബി(സ) സ്ഥിരമായി ളുഹാ നിസ്കരിച്ചിട്ടില്ല. ഞാൻ നിസ്കരിക്കുകയും ചെയ്യുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: كَانَ أَحَبَّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الدَّائِمُ، قِيلَ لَهَا: مَتَى كَانَ يَقُومُ؟ قَالَتْ:كَانَ يَقُومُ إِذَا سَمِعَ الصَّارِخَ. وَفِي رِوَايَةٍ: إِذَا سَمِعَ الصَّارِخَ قَامَ فَصَلَّى. (خ)', 'ആഇശ(റ): നബി(സ)ക്ക് കൂടുതൽ ഇഷടം പതിവായി ചെയ്യുന്ന കർമ്മമായിരുന്നു. മഹതിയോട് ചോദിക്കപ്പെട്ടു: എപ്പോഴാണ് നബി(സ) എഴുന്നേൽക്കാറുള്ളത്. മഹതി പറഞ്ഞു: കോഴി കൂവുന്നതു കേട്ടാണ് എഴുന്നേൽക്കാറുള്ളത്. മറ്റൊരുറിപ്പോർട്ടിൽ: കോഴി കൂവുന്നതു കേട്ട് എഴുന്നേറ്റ് നിസ്കരിക്കും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=312), 1, 'وَفِي رِوَايَةٍ: إِذَا سَمِعَ الصَّارِخَ قَامَ فَصَلَّى. (خ)', 'മറ്റൊരു നിവേദനിൽ: കോഴി കൂവുന്നതു കേട്ട് എഴുന്നേറ്റ് നിസ്കരിക്കും. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا أَلْفَاهُ السَّحَرَ عِنْدِي إِلَّا نَائِمًا، تَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ,د)', 'ആഇശ(റ): നബി(സ)യെ അത്താഴ സമയത്ത് ഉറങ്ങിയതായേ ഞാൻ കണ്ടിട്ടുള്ളൂ. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عَبْد اللهِ بْنِ مَسْعُود رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَلَمْ يَزَلْ قَائِمًا حَتَّى هَمَمْتُ بِأَمْرِ سَوْءٍ، قِيلَ: مَا هَمَمْتَ؟ قَالَ: هَمَمْتُ أَنْ أَقْعُدَ وَأَذَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരു രാത്രി നബി(സ)യോടൊപ്പം ഞാൻ നിസ്കരിച്ചു. നബി(സ) നിറുത്തം തുടർന്നു കൊണ്ടേയിരുന്നു. എനിക്ക് ചില ചീത്ത വിചാരങ്ങൾ വന്നു; അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: താങ്കളെന്തു ചെയ്യാനാണ് വിചാരിച്ചത്?. അദ്ദേഹം പറഞ്ഞു: പ്രവാചകരെ വെടിഞ്ഞ് ഇരിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. (ബു,ജ)', 'عَبْد اللهِ بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَنَسِ بْنِ مَالِك رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُفْطِرُ مِنَ الشَّهْرِ حَتَّى نَظُنَّ أَنْ لَا يَصُومَ مِنْهُ، وَيَصُومُ حَتَّى نَظُنَّ أَنْ لَا يُفْطِرَهُ شَيْئًا، وَكَانَ لَا تَشَاءُ أَنْ تَرَاهُ مِنَ اللَّيْلِ مُصَلِّيًا إِلَّا رَأَيْتَهُ، وَلَا نَائِمًا إِلَّا رَأَيْتَهُ. (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ചില മാസങ്ങളിൽ നോമ്പനുഷ്ഠിക്കാതിരിക്കുന്നതായി കണ്ടാൽ ഇനിയൊരിക്കലും ആമാസത്തിൽ നോമ്പനുഷ്ഠിക്കുകയില്ലെന്ന് വിചാരിച്ചു പോവും, നോമ്പനുഷ്ഠിക്കുന്നത് കണ്ടാൽ ഒഴിവാക്കുകയില്ലെന്നും തോന്നും. നബി(സ)യെ രാത്രി നിസ്കരിക്കാതെ കാണണമെന്നു കരുതിയാൽ നിനക്കങ്ങിനെ കാണാം. ഉറങ്ങിക്കാണാനാഗ്രഹിച്ചാൽ അങ്ങനെയും കാണാം. (ബു)', 'أَنَسِ بْنِ مَالِك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا سُئِلَتْ: كَيْفَ كَانَتْ صَلَاةُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ قَالَتْ: كَانَ يَنَامُ أَوَّلَهُ، وَيَقُومُ آخِرَهُ فَيُصَلِّي، ثُمَّ يَرْجِعُ إِلَى فِرَاشِهِ، فَإِذَا أَذَّنَ الْمُؤَذِّنُ وَثَبَ، فَإِنْ كَانَ بِهِ حَاجَةٌ اغْتَسَلَ، وَإِلَّا تَوَضَّأَ وَخَرَجَ. (خ)', 'ആഇശ(റ): മഹതിയോട് ചോദിക്കപ്പെട്ടു: എങ്ങിനെയായിരുന്നു നബി(സ)യുടെ രാത്രി നിസ്കാരം?. മഹതി പറഞ്ഞു: രാത്രിയുടെ ആദ്യഭാഗം ഉറങ്ങുകയും അവസാനം എഴുന്നേറ്റ് നിസ്കരിക്കുകയും ചെയ്തിരുന്നു. പിന്നെ വിരിപ്പിലേക്കു പോവും. പക്ഷെ, ബാങ്കു വിളിച്ചാൽ ചാടി എഴുന്നേൽക്കും. ആവശ്യമെങ്കിൽ കുളിക്കും. അല്ലെങ്കിൽ വുദു ചെയ്ത ശേഷം പോവും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ عُبَادَةَ بْنُ الصَّامِت: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَعَارَّ مِنَ اللَّيْلِ فَقَالَ: لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، الْحَمْدُ للهِ، وَسُبْحَانَ اللهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ. ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِي، أَوْ دَعَا اسْتُجِيبَ لَهُ، فَإِنْ تَوَضَّأَ وَصَلَّى قُبِلَتْ صَلَاتُهُ". (خ,د,ت,جه)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും രാത്രി എണീറ്റ് ''അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും സർവ്വാധികാരവും സർവ്വ സ്തുതിയും അവന്നാണെന്നും അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്'' എന്നും, അൽഹംദുലില്ലാ, സുബ്ഹാനല്ലാ, ലാഇലാഹ ഇല്ലല്ലാഹു വല്ലാഹു അക്ബർ, വലാഹൗല വലാഖുവ്വത ഇല്ലാബില്ലാഹി എന്നു പറഞ്ഞ്, ''എനിക്കു പൊറുത്തു തരേണമേ'' എന്നു പ്രാർത്ഥിച്ചാൽ ഉത്തരം ലഭിക്കപ്പെടും. അവൻ വുദു എടുത്ത് നിസ്കരിച്ചാൽ ആ നിസ്കാരം സ്വീകരിക്കപ്പെടും." (ബു,ദ,തു,ജ)', 'عُبَادَةَ بْنُ الصَّامِت', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: وَهُوَ يَقُصُّ فِي قَصَصِهِ وَهُوَ يَذْكُرُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِنَّ أَخًا لَكُمْ لَا يَقُولُ الرَّفَثَ، يَعْنِي بِذَلِكَ عَبْدَاللهِ بْنَ رَوَاحَةَ رَضِيَ اللهُ عَنْهُ: وَفِينَا رَسُولُ اللهِ يَتْلُو كِتَابَهُ إِذَا انْشَقَّ مَعْرُوفٌ مِنَ الْفَجْرِ سَاطِعُ أَرَانَا الْهُدَى بَعْدَ الْعَمَى فَقُلُوبُنَا بِهِ مُوقِنَاتٌ أَنَّ مَا قَالَ وَاقِعُ يَبِيتُ يُجَافِي جَنْبَهُ عَنْ فِرَاشِهِ إِذَا اسْتَثْقَلَتْ بِالْمُشْرِكِينَ الْمَضَاجِعُ. (خ)', 'അബൂഹുറൈറ(റ): സാരോപദേശം നൽകുന്നതിടെ നബി(സ)യെക്കുറിച്ച് പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു റവാഹ തിരുമേനിയെ ക്കുറിച്ച് പുകഴ്ത്തി പാടിയപ്പോൾ കളവു പറയുകയുണ്ടായിട്ടില്ല – ശേഷം അബ്ദുള്ളാഹിബ്നു റവാഹ തിരുമേനി(സ)യെ വർണ്ണിച്ച് കൊണ്ട് പാടിയ കാവ്യ വാക്യങ്ങൾ ചൊല്ലി: –
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَأَنَّ بِيَدِي قِطْعَةَ إِسْتَبْرَقٍ، فَكَأَنِّي لَا أُرِيدُ مَكَانًا مِنَ الْجَنَّةِ إِلَّا طَارَتْ إِلَيْهِ، وَرَأَيْتُ كَأَنَّ اثْنَيْنِ أَتَيَانِي، وَذَكَرَ بَاقِي الْحَدِيثِ. (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് എന്റെ കയ്യിലൊരു പട്ടു കഷ്ണമുള്ളതായും, ഞാൻ സ്വർഗ്ഗത്തിലെ ഒരു സ്ഥലമാഗ്രഹിച്ചാൽ അത് ആ ഭാഗത്തേക്കു പാറുന്നതായും. രണ്ടാളുകൾ എന്റെയടുത്തേക്കു വരുന്നതായും ഞാൻ സ്വപ്നം കണ്ടു. അദ്ദേഹം ഹദീസ് തുടർന്നു പറഞ്ഞു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اكْلَفُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ، فَإِنَّ اللهَ لَا يَمَلُّ حَتَّى تَمَلُّوا، وَإِنَّ أَحَبَّ الْعَمَلِ إِلَى اللهِ أَدْوَمُهُ وَإِنْ قَلَّ". وَكَانَ إِذَا عَمِلَ عَمَلًا أَثْبَتَهُ. (د)', 'ആഇശ(റ): നബി(സ)പറഞ്ഞു: "നിങ്ങൾക്ക് കഴിയുന്ന കർമ്മങ്ങൾ നിങ്ങൾ ചെയ്യുക. നിങ്ങൾക്കു മടുക്കുന്നതു വരെ അല്ലാഹുവിന് മടുക്കുകയില്ല. എത്ര ചെറുതെങ്കിലും പതിവായി ചെയ്യുന്നതെന്തോ അതാണ് അല്ലാഹുവിനിഷ്ടം." നബി(സ) എന്തെങ്കിലും ചെയ്താൽ അത് പതിവാക്കാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 625, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى عُثْمَانَ بْنِ مَظْعُون، فَجَاءَهُ، فَقَالَ: "يَا عُثْمَانُ، أَرَغِبْتَ عَنْ سُنَّتِي" قَالَ: لَا وَاللهِ يَا رَسُولَ اللهِ، وَلَكِنْ سُنَّتَكَ أَطْلُبُ. قَالَ: فَإِنِّي أَنَامُ وَأُصَلِّي، وَأَصُومُ وَأُفْطِرُ، وَأَنْكِحُ النِّسَاءَ، فَاتَّقِ اللهَ يَا عُثْمَانُ، فَإِنَّ لِأَهْلِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِضَيْفِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِنَفْسِكَ عَلَيْكَ حَقًّا، فَصُمْ وَأَفْطِرْ، وَصَلِّ وَنَمْ". (د)', 'ആഇശ(റ): നബി(സ) ഉസ്മാനുബ്നു മള്ഊനിനെ ആളെയയച്ചു വിളിപ്പിച്ചു. അദ്ദേഹം വന്നപ്പോൾ നബി(സ) ചോദിച്ചു: "നീ എന്റെ ചര്യ വെറുക്കുന്നുവോ?." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ! ഇല്ല പ്രവാചകരെ! പക്ഷെ, താങ്കളുടെ ചര്യ ഞാൻ തേടുന്നു. നബി(സ) പറഞ്ഞു: "ഞാൻ നിസ്കരിക്കുകയും ഉറങ്ങുകയും ചെയ്യുന്നു, നോമ്പെടുക്കുകയും എടുക്കാതിരിക്കുകയും ചെയ്യുന്നു. ഭാര്യമാരെ വിവാഹം ചെയ്യുന്നു. ഉസ്മാൻ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. കാരണം നിന്റെ കുടുംബത്തിനുമേൽ നിനക്കു ബാധ്യതയുണ്ട്. നിന്റെ അതിഥിയുടെമേൽ നിനക്കു ബാധ്യതയുണ്ട്. നിന്റെ ശരീരത്തോട് ബാധ്യതയുണ്ട്, അതിനാൽ നോമ്പനുഷ്ഠിക്കുക, മുറിക്കുക, നിസ്കരിക്കുക, ഉറങ്ങുക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ عَلْقَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ: كَيْفَ كَانَ عَمَلُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ هَلْ كَانَ يَخُصُّ شَيْئًا مِنَ الْأَيَّامِ؟ قَالَتْ: لَا، كَانَ كُلُّ عَمَلِهِ دِيمَةً، وَأَيُّكُمْ يَسْتَطِيعُ مَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْتَطِيعُ؟ (د)', 'അൽഖമ(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: നബി(സ)യുടെ കർമ്മങ്ങളെങ്ങനെയായിരുന്നു. ഏതെങ്കിലും ദിവസം പ്രത്യേകമായി വല്ലതും ചെയ്യാറുണ്ടോ? മഹതി പറഞ്ഞു: ഇല്ല, എല്ലാ കർമ്മങ്ങളും പതിവാക്കിയിരുന്നു. നബി(സ)ക്കു സാധിക്കുന്നത്ര നിങ്ങളിലാർക്കു സാധിക്കും? (ദ)', 'عَلْقَمَةَ', 'അൽഖമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ إِذَا قَامَ إِلَى الصَّلَاةِ مِنْ جَوْفِ اللَّيْلِ: "اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالْأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ قَيَّامُ السَّمَوَاتِ وَالْأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ. أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَقَوْلُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَأَخَّرْتُ، وَأَسْرَرْتُ، وَأَعْلَنْتُ، أَنْتَ إِلَهِي، لَا إِلَهَ إِلَّا أَنْتَ". (ق,د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രാത്രി നിസ്കരിക്കാൻ നിന്നാൽ പറയാറുണ്ടായിരുന്നു: അല്ലാഹുവെ, നിനക്കാണ് സർവ്വ സ്തുതിയും. നീ ആകാശ ഭൂമികളിലെ പ്രകാശമാണ്. നീ ആകാശ ഭൂമികളെ നില നിർത്തുന്നവനാകയാൽ നിനക്കാണ് സർവ്വ സ്തോത്രങ്ങളും. ആകാശ ഭൂമികളുടെയും അതിലുള്ള സർവ്വതിന്റെയും രക്ഷിതാവായ നിനക്കാണ് സർവ്വ സ്തുതിയും. നീ സത്യമാണ്, നിന്റെ വാഗ്ദാനവും സത്യമാണ്. നിന്റെ വാക്കും സത്യമാണ്, നിന്നെ കണ്ടുമുട്ടുമെന്നതും സത്യമാണ്. സ്വർഗ്ഗം സത്യമാണ്, നരകവും അന്ത്യനാളും സത്യമാണ്. നാഥാ, നിനക്കായി ഞാൻ കീഴടങ്ങി. നിന്നിൽ ഞാൻ വിശ്വസിച്ചു. നിന്നിൽ സർവ്വതും ഭരമേല്പിച്ചു. നിന്നിലേക്കു ഞാൻ മടങ്ങി, നിനക്കുവേണ്ടി ഞാൻ തർക്കിക്കുന്നു. നിന്നെ ഞാൻ വിധി കർത്താവാക്കുന്നു. ഞാൻ ചെയ്തതും ചെയ്യാനിരിക്കുന്നതുമായ രഹസ്യവും, പരസ്യവുമായ പാപങ്ങൾ പൊറുത്തു തരേണമേ. നീ എന്റെ ആരാധ്യനാണ്, നീയല്ലാതെ ആരാധ്യനില്ല. (ബു,മു,ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ إِلَّا فِي آخِرِهَا. (م)', 'ആഇശ(റ): നബി(സ) രാത്രി പതിമൂന്ന് റക്അത്ത് നിസ്കരിക്കും. അഞ്ച് റക്അത്ത് വിത്റായിരുന്നു. അഞ്ചെണ്ണത്തിൽ അവസാനത്തേതിൽ മാത്രമെ ഇരിക്കാറുള്ളൂ. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عَبْد اللهِ بْنِ مَسْعُود رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ نَامَ لَيْلَةً حَتَّى أَصْبَحَ، قَالَ: "ذَاكَ رَجُلٌ بَالَ الشَّيْطَانُ فِي أُذُنَيْهِ". أَوْ قَالَ: "فِي أُذُنِهِ". (م,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): രാത്രി മുഴുവൻ ഉറങ്ങിയ ഒരാളെക്കുറിച്ച് നബി(സ)യോട് പറയപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അയാളുടെ ചെവിയിൽ പിശാച് മൂത്രമൊഴിച്ചിരിക്കുന്നു." (മു,ന,ജ)', 'عَبْد اللهِ بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلَاةِ اللَّيْلِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً تُوتِرُ لَهُ مَا قَدْ صَلَّى. (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ): ഒരാൾ പ്രവാചക(സ)നോട് രാത്രി നമസ്കാരത്തെക്കുറിച്ച് ചോദിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "രാത്രി നമസ്കാരം ഈരണ്ട് ഈരണ്ടാണ്. പ്രഭാതമാവുമെന്ന് ഭയന്നാൽ ഒറ്റ റക്അത്ത് നിർവഹിക്കുക. അയാൾ നമസ്കരിച്ചത്രയും വിത്റാക്കപ്പെടും." (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةُ اللَّيْلِ وَالنَّهَارِ مَثْنَى مَثْنَى". (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു. "രാത്രിയിലേയും പകലിലേയും നമസ്കാരങ്ങൾ ഈരണ്ട് ഈരണ്ട് റക്അത്താണ്." (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ فَلْيُصَلِّ رَكْعَتَيْنِ خَفِيفَتَيْنِ". وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: ثُمَّ لِيُطَوِّلْ بَعْدُ مَا شَاءَ. (م,د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ രാത്രി എഴുന്നേറ്റാൽ ലഘുവായി രണ്ട് റക്അത്തുകൾ നിസ്കരിക്കട്ടെ." മറ്റൊരു റിപ്പോർട്ട്: പിന്നെ അതിനു ശേഷം അവൻ ഉദ്ദേശിച്ചത്ര (റക്അത്തുകൾ) ദീർഘിപ്പിക്കട്ടെ. (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=328), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: ثُمَّ لِيُطَوِّلْ بَعْدُ مَا شَاءَ. (م,د)', 'മറ്റൊരു നിവേദന്: പിന്നെ അതിനു ശേഷം അവൻ ഉദ്ദേശിച്ചത്ര (റക്അത്തുകൾ) ദീർഘിപ്പിക്കട്ടെ. (മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: فِي كُلِّ رَكْعَتَيْنِ تَسْلِيمَةٌ. (ز:في اسناده ضعيف) (جه)', 'അബൂസഈദ്(റ) റസൂൽ(സ) പറഞ്ഞു: "ഓരോ ഈരണ്ട് റക്അത്തിനും ശേഷം സലാം വീട്ടലുണ്ട്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، مَا بَيْنَ أَنْ يَفْرُغَ مِنْ صَلَاةِ الْعِشَاءِ إِلَى الْفَجْرِ، إِحْدَى عَشْرَةَ، رَكْعَةً يُسَلِّمُ فِي كُلِّ اثْنَتَيْنِ، وَيُوتِرُ بِوَاحِدَةٍ، وَيَسْجُدُ فِيهِنَّ سَجْدَةً، بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً، قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ، فَإِذَا سَكَتَ الْمُؤَذِّنُ مِنَ الْأَذَانِ الْأَوَّلِ مِنْ صَلَاةِ الصُّبْحِ، قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ. (د,ن)', 'ആയിശ(റ): ഇശാ നിസ്കാരം കഴിഞ്ഞ് സുബ്ഹിയാകുന്നതു വരെ നബി(സ) പതിനൊന്ന് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. ഓരോ ഈ രണ്ട് റക്അത്തിലും സലാം വീട്ടുകയും ഒരു റക്അത്തുകൊണ്ട് അവയെ ഒറ്റയാക്കുക(വിത്ർ)യും ചെയ്യുമായിരുന്നു. നിങ്ങളിൽ ഒരാൾ അമ്പത് ആയത്തുകൾ ഓതുന്ന കണക്ക് നബി(സ) സുജൂദ് ചെയ്യുമായിരുന്നു. മുഅദ്ദിൻ സുബ്ഹ് നിസ്കാരത്തിന്റെ ആദ്യ ബാങ്കിൽ നിന്ന് വിരമിച്ചാൽ നബി(സ) എഴുന്നേൽക്കുകയും വളരെ ലഘുവായ രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്യും. (ദ,ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 627, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا : أَنَّ النَّبِيَّ يُصَلِّي مِنَ اللَّيْلِ تِسْعَ رَكَعَاتٍ. (ت,جه)', 'ആയിശ(റ): നബി(സ) രാത്രി ഒമ്പത് റക്അത്ത് നിസ്കരക്കാറുണ്ടായിരുന്നു. (തു,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً. (م,جه)', 'ആയിശ(റ): നബി(സ) രാത്രി പതിമൂന്ന് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. (മു,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ وَعَبْدِ اللهِ بْنِ عُمَرَ – رَضِيَ اللهُ عَنْهُمْ – سُئِلَا عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ فَقَالَا: ثَلَاثَ عَشْرَةَ رَكْعَةً: مِنْهَا ثَمَانٍ، وَيُوتِرُ بِثَلَاثٍ، وَرَكْعَتَيْنِ بَعْدَ الْفَجْرِ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ), അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) എന്നിവരിൽ നിന്ന് നിവേദനം: നബി(സ)യുടെ രാത്രി നിസ്കാരത്തെ സംബന്ധിച്ച് അവരോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: ആകെ പതിമൂന്ന് റക്അത്ത്. അവയിൽ എട്ടു റക്അത്തുകൾക്ക് ശേഷം മൂന്നെണ്ണം കൊണ്ട് അവയെ ഒറ്റയാക്കുകയും ചെയ്യും. ഫജ്റിന്റെ ശേഷം രണ്ട് റക്അത്ത് നിർവ്വഹിക്കും. (ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ وَعَبْدِ اللهِ بْنِ عُمَرَ –', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ نَامَ عِنْدَ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهِيَ خَالَتُهُ، قَالَ: فَاضْطَجَعْتُ فِي عَرْضِ الْوِسَادَةِ، وَاضْطَجَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَهْلُهُ فِي طُولِهَا، فَنَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا انْتَصَفَ اللَّيْلُ – أَوْ قَبْلَهُ بِقَلِيلٍ، أَوْ بَعْدَهُ بِقَلِيلٍ – اسْتَيْقَظَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَلَسَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ بِيَدِهِ، ثُمَّ قَرَأَ الْعَشْرَ الْآيَاتِ الْخَوَاتِمَ مِنْ سُورَةِ آلِ عِمْرَانَ، ثُمَّ قَامَ إِلَى شَنٍّ مُعَلَّقَةٍ فَتَوَضَّأَ مِنْهَا فَأَحْسَنَ وُضُوءَهُ، ثُمَّ قَامَ يُصَلِّي. قَالَ عَبْدُ اللهِ: فَقُمْتُ فَصَنَعْتُ مِثْلَ مَا صَنَعَ، ثُمَّ ذَهَبْتُ فَقُمْتُ إِلَى جَنْبِهِ، فَوَضَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدَهُ الْيُمْنَى عَلَى رَأْسِي، فَأَخَذَ بِأُذُنِي يَفْتِلُهَا فَصَلَّى رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، قَالَ الْقَعْنَبِيُّ سِتَّ مَرَّاتٍ ثُمَّ أَوْتَرَ ثُمَّ اضْطَجَعَ حَتَّى جَاءَهُ الْمُؤَذِّنُ، فَقَامَ فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ خَرَجَ الَى الصَّلَاةِ. (ق,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം തന്റെ എളാമ്മയായ നബി(സ)യുടെ പ്രിയപത്നി മൈമൂന(റ)യുടെ അടുക്കൽ കിടന്നുറങ്ങി. അദ്ദേഹം പറയുന്നു: ഞാൻ തലയിണയുടെ (വിരിപ്പിനു) കുറുകെയും റസൂലും പത്നിയും നേരെയും കിടന്നു. രാത്രി പകുതിയാകും വരെ, അല്ലെങ്കിൽ തൊട്ടുമുമ്പോ ശേഷമോ വരെ കിടന്നുറങ്ങയശേഷം തിരുമേനി(സ) ഉറക്കിൽ നിന്നും ഉണർന്നു. പ്രവാചകൻ(സ) തന്റെ കൈ കൊണ്ട് മുഖത്തെ ഉറക്കിന്റെ അടയാളങ്ങൾ മായ്ച്ചുകളയാൻ തുടങ്ങി. ശേഷം ആലുഇംറാൻ സൂറത്തിലെ അവസാനത്തെ പത്ത് സൂക്തങ്ങൾ ഓതാൻ തുടങ്ങുകയും ചെയ്തു. പിന്നെ വീട്ടിൽ തൂക്കിയിട്ട തോൽപാത്രത്തിന്റെ അടുത്തു പോയി നന്നായി വുദു ചെയ്തു. പിന്നെ നിസ്കരിക്കാൻ തുടങ്ങി. അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ) പറയുന്നു: ഉറക്കിൽ നിന്നെണീറ്റ് നബി(സ) ചെയ്തതു പോലെ ഞാനും ചെയ്തു. ശേഷം ഞാൻ നബി(സ)യുടെ ഒരു വശത്തേക്കുനിന്നു. തിരുമേനി(സ) അവിടുത്തെ വലതു കൈ എന്റെ ശിരസ്സിൽ വെക്കുകയും എന്റെ വലതു ചെവി പിടിച്ചുതിരിക്കുകയും ചെയ്തു. തുടർന്ന് രണ്ട് റക്അത്ത്, പിന്നീട് രണ്ട്, ശേഷം രണ്ട്, പിന്നെ രണ്ട്, വീണ്ടും രണ്ട്, പിന്നെ രണ്ട് എന്നിങ്ങനെ നിസ്കരിച്ചു. കഅ്നബീ പറയുന്നു: ആറു പ്രാവശ്യം ഈരണ്ടായി നിർവ്വിച്ചു. പിന്നെ ഒറ്റയാക്കി. പിന്നെ മുഅദ്ദിൻ വരുന്നതു വരെ ചെരിഞ്ഞു കിടന്നതിനു ശേഷം ലഘുവായ രണ്ടു റക്അത്ത് നിസ്കരിക്കുകയും പള്ളിയിലേക്ക് പുറപ്പെടുകയും ചെയ്തു. (ബു,മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 628, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: "صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَافْتَتَحَ الْبَقَرَةَ فَقُلْتُ: يَرْكَعُ عِنْدَ الْمِائَةِ فَمَضَى، فَقُلْتُ: يَرْكَعُ عِنْدَ الْمِائَتَيْنِ فَمَضَى، فَقُلْتُ: يُصَلِّي بِهَا فِي رَكْعَةٍ فَمَضَى، فَافْتَتَحَ النِّسَاءَ فَقَرَأَهَا ثُمَّ افْتَتَحَ آلَ عِمْرَانَ فَقَرَأَهَا يَقْرَأُ مُتَرَسِّلًا إِذَا مَرَّ بِآيَةٍ فِيهَا تَسْبِيحٌ سَبَّحَ وَإِذَا مَرَّ بِسُؤَالٍ سَأَلَ وَإِذَا مَرَّ بِتَعَوُّذٍ تَعَوَّذَ، ثُمَّ رَكَعَ فَقَالَ: سُبْحَانَ رَبِّيَ الْعَظِيمِ فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ، ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ فَكَانَ قِيَامُهُ قَرِيبًا مِنْ رُكُوعِهِ، ثُمَّ سَجَدَ فَجَعَلَ يَقُولُ: سُبْحَانَ رَبِّيَ الْأَعْلَى فَكَانَ سُجُودُهُ قَرِيبًا مِنْ رُكُوعِهِ". (ن)', 'ഹുദൈഫ(റ): അദ്ദേഹം പറയുന്നു: ഞാൻ നബി(സ)യുടെ കൂടെ ഒരു രാത്രി നിസ്കരിച്ചു. അങ്ങനെ തിരുമേനി(സ) സൂറതുൽ ബഖറ ഓതാൻ തുടങ്ങി. ഞാൻ മനസ്സിൽ പറഞ്ഞു: നൂറാം ആയത്തിൽ റുകൂഅ് ചെയ്യുമായിരിക്കും. അതും കടന്നപ്പോൾ ഞാൻ പറഞ്ഞു: ഇരുനൂറിൽ റുകൂഅ് ചെയ്യുമായിരിക്കും. അതും കഴിഞ്ഞപ്പോൾ ഞാൻ പറഞ്ഞു: അതുകൊണ്ട് (അൽബഖറ മുഴുവൻ ഓതികൊണ്ട്) ഒരു റക്അത്ത് നിസ്കരിക്കുമായിരിക്കും. അതും കടന്ന് നിസാഅ്, ആലുഇംറാൻ തുടങ്ങിയ അദ്ധ്യായങ്ങൾ ഓതാൻ തുടങ്ങി. ഓതുമ്പോൾ തസ്ബീഹിന്റെ ആയത്ത് കടന്നു പോകുമ്പോൾ തസ്ബീഹ് ചൊല്ലുകയും, (സ്വർഗ്ഗവും മറ്റും) തേടേണ്ട ഭാഗം കടന്നു പോകോമ്പുൾ അവ തേടുകയും, (നരകത്തിൽനിന്നും മറ്റും) കാവൽ ചോദിക്കേണ്ടിടത്ത് കാവൽ ചോദിക്കുകയും ചെയ്തു ശേഷം നബി(സ) റുകൂഅ് ചെയ്തു. എന്നിട്ട് സുബ്ഹാന റബ്ബിയൽ അളീം എന്ന് പറഞ്ഞു.തിരുമേനിയുടെ റുകൂഅ് അവിടുത്തെ ഖിയാമിനോളമുണ്ടായിരുന്നു. പിന്നെ തലയുയർത്തി പറഞ്ഞു: ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' അവിടുത്തെ ഖിയാം റുകൂഇനോളമുണ്ടായിരുന്നു. എന്നിട്ട് സുജൂദിലായി തിരുമേനി പറയാൻ തുടങ്ങി ''സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ''. നബി(സ)യുടെ സുജൂദ് റുകൂഇനോളമുണ്ടായിരുന്നു. (ന)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمْ هَذَا الدُّعَاءَ كَمَا يُعَلِّمُهُمُ السُّورَةَ مِنَ الْقُرْآنِ يَقُولُ: "قُولُوا: اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". (م,ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഖുർആനിൽ നിന്നുള്ള ഒരു അധ്യായം പഠിപ്പിക്കുന്നതു പോലെ ഈ ദുആ തന്റെ അനുചരന്മാർക്ക് റസൂൽ(സ) പഠിപ്പിച്ചുകൊടുത്തിരുന്നു: "അല്ലാഹുവേ, നരക ശിക്ഷയിൽ നിന്നും ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും മസീഹു ദജ്ജാലിന്റെ ഫിത്നയിൽനിന്നും ജീവിതത്തിലും മരണത്തിലുമുണ്ടാകുന്ന ഫിത്നയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (മു,ന)', 'ابْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَتْ لَهُ إِلَى اللهِ حَاجَةٌ – أَوْ إِلَى أَحَدٍ مِنْ بَنِي آدَمَ – فَلْيَتَوَضَّأْ فَلْيُحْسِنِ الْوُضُوءَ، ثُمَّ لِيُصَلِّ رَكْعَتَيْنِ، ثُمَّ لِيُثْنِ عَلَى اللهِ، وَلْيُصَلِّ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ لِيَقُلْ: لَا إِلَهَ إِلَّا اللهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ، أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ആർക്കെങ്കിലും അല്ലാഹുവിലേക്കോ, ഏതെങ്കിലും മനഷ്യനിലേക്കോ ആവശ്യമുണ്ടായാൽ അവൻ അംഗസ്നാനം ചെയ്യട്ടെ - അംഗസ്നാനത്തെ നന്നാക്കട്ടെ. പിന്നീട് രണ്ട് റക്അത്ത് നിസ്കരിക്കട്ടെ. പിന്നെ അല്ലാഹുവിനെ വാഴ്ത്തട്ടെ. പ്രവാചകന് വേണ്ടി സ്വലാത്ത് ചൊല്ലട്ടെ. ശേഷം ഇപ്രകാരം പറയട്ടെ: "ഔദാര്യവാനായ അനുകമ്പയുള്ള അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. മഹോന്നതമായ സിംഹാസനത്തിന്റെ നാഥനായ അല്ലാഹുവിന്റെ പരിശുദ്ധി ഞാൻ വാഴ്ത്തുന്നു. ലോകരക്ഷിതാവായ അല്ലാഹുവിന്ന് സ്തുതികൾ. നന്റെ കാരുണ്യത്തിന്റെ ഹേതുകങ്ങളെയും പാപമോക്ഷത്തിന്ന് കാരണമാക്കുന്നവയെയും എല്ലാ ഗുണങ്ങളുടെ നേട്ടവും എല്ലാ പാപത്തിന്റെ മോക്ഷവും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. കാരുണ്യവാനേ, പൊറുക്കപ്പെടാത്ത ദോഷങ്ങളെയോ ദൂരീകരിക്കാത്ത ദുഃഖത്തെയോ നീ തൃപ്തിയടഞ്ഞ ആവശ്യങ്ങൾ വീട്ടപ്പെടാതെയോ എനിക്ക് നീ ഉപേക്ഷിക്കരുത്." (തു)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 629, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ. وَالْكَسَلِ، وَالْجُبْنِ، وَالْبُخْلِ، وَالْهَرَمِ. وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". وَفِي رِوَايَةٍ: كُنْتُ أَخْدِمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ: "اللَّهُمَّ أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ. وَضَلْعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ". (د)', 'അനസ്(റ): നബി(സ) ഇങ്ങനെ ദുആ ചെയ്യാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, അശക്തി, അലസത, ഭീരുത്വം, പിശുക്ക്, വാർദ്ധക്യം എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. ഖബ്റ് ശിക്ഷയിൽ നിന്നും, ജീവിത മരണ ഫിത്നകളിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞാൻ നബി(സ)യുടെ സേവകനായിരുന്നപ്പോൾ നബിയിൽനിന്ന് ധാരാളം കേട്ടിരുന്നത് ഇപ്രകാരമായിരുന്നു: "അല്ലാഹുവേ, വ്യസനം, ദുഃഖം, കടക്കെണി മറ്റുള്ളവരുടെ കടന്നാക്രമണം എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ തേടുന്നു." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=338), 1, 'وَفِي رِوَايَةٍ: كُنْتُ أَخْدِمُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكُنْتُ أَسْمَعُهُ كَثِيرًا يَقُولُ: "اللَّهُمَّ أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ. وَضَلْعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ". (د)', 'മറ്റൊരു നിവേദനിൽ: ഞാൻ നബി(സ)യുടെ സേവകനായിരുന്നപ്പോൾ നബിയിൽനിന്ന് ധാരാളം കേട്ടിരുന്നത് ഇപ്രകാരമായിരുന്നു: "അല്ലാഹുവേ, വ്യസനം, ദുഃഖം, കടക്കെണി മറ്റുള്ളവരുടെ കടന്നാക്രമണം എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ തേടുന്നു." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهَؤُلَاءِ الْكَلِمَاتِ "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ، وَعَذَابِ النَّارِ وَمِنْ شَرِّ الْغِنَى وَالْفَقْرِ". (د)', 'ആഇശ(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, നരകത്തിന്റെ ഫിത്നയിൽ നിന്നും അതിന്റെ ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. ഐശ്വര്യത്തിന്റെയും ദാരിദ്ര്യത്തിന്റെയും തിന്മയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ، وَأَعُوذُ بِكَ مِنَ الْقِلَّةِ، وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ". (د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ട്. "ദാരിദ്ര്യം, നിന്ദ്യത, അക്രമിക്കൽ, അക്രമിക്കപ്പെടൽ എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവലിനെ ചോദിക്കുന്നു." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ أَبِي الْيَسَرِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الْغَرَقِ، وَالْحَرَقِ، وَالْهَرَمِ. وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا". وَفِي رِوَايَةٍ: زَادَ فِيهِ "وَالْغَمِّ". (د,ن)', 'അബുൽയസ്റ്(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, നാശം, വീഴ്ച, മുങ്ങൽ, തീപിടുത്തം, വാർദ്ധക്യം എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, മരണ സമയത്ത് പിശാചിന്റെ വഴിപിഴപ്പിക്കലിൽ നിന്നും നിന്റെ മാർഗ്ഗത്തിൽ നിന്ന് ഭ്രംശം സംഭവിച്ച് മരണപ്പെടുന്നതിൽ നിന്നും പാമ്പു കടിയേറ്റ് മരിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ തേടുന്നു." ചില റിപ്പോർട്ടുകളിൽ "ദുഃഖത്തിൽ നിന്നും" എന്നു കൂടി കാണാം. (ദ,ന)', 'أَبِي الْيَسَرِ', 'അബുൽയസ്റ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 630, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=341), 1, 'وَفِي رِوَايَةٍ: زَادَ فِيهِ "وَالْغَمِّ". (د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَال نِعْمَتِك، وَتَحْوِيل عَافِيتِك، وَفُجَاءَة نِقْمَتِك، وَجَمِيع سُخْطِك". (م,د)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഇപ്രകാരം ദുആ ചെയ്യാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ! നിന്റെ അനുഗ്രഹങ്ങൾ നീങ്ങിപ്പോകുന്നതിൽനിന്നും, നീ തന്ന ആരോഗ്യം ശോഷിക്കുന്നതിൽനിന്നും, പെട്ടെന്നുള്ള നിന്റെ ശിക്ഷയിൽനിന്നും, നിന്റെ ദേഷ്യത്തിന്റെ ആധിക്യത്തിൽനിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عن أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِن الشِّقَاق، وَالنِّفَاق، وَسُوء الْأَخْلَاق". (د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) ഇങ്ങനെ ദുആ ചെയ്യാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ ഭിന്നിപ്പ്, കാപട്യം, ചീത്ത സ്വഭാവം എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عن أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ فَإِنَّهُ بِئْسَ الضَّجِيعُ. وَأَعُوذُ بِكَ مِنَ الْخِيَانَة فَإِنَّهَا بِئْسَت الْبِطَانَةُ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ! നിന്നോട് ഞാൻ വിശപ്പിൽ നിന്നും കാവൽ ചോദിക്കുന്നു. കാരണം അതെത്ര മോശം! ഞാൻ വഞ്ചനയിൽ നിന്നും നിന്നോട് കാവൽ തേടുന്നു. കാരണം അതെത്ര ചീത്ത ആന്തരിക സ്വഭാവം!" (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عن أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْأَرْبَعِ: مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دُعَاءٍ لَا يُسْمَعُ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, നാലു കാര്യങ്ങളിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. ഉപകാരമില്ലാത്ത അറിവ്, ഭയപ്പെടാത്ത ഹൃദയം, വയറു നിറയാത്ത ശരീരം, കേൾക്കപ്പെടാത്ത പ്രാർത്ഥന. (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عن أَنَسِ بْنِ مَالك رَضِيَ اللهُ عَنْهُ حَدَّثَنَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ صَلَاة لَا تَنْفَعُ". (د)', 'അനസ്(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, ഉപകാരമില്ലാത്ത നിസ്കാരത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. (ദ)', 'أَنَسِ بْنِ مَالك', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ فَرْوَةَ بْنِ نَوْفَلٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ عَمَّا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِه اللَّهَ، قَالَتْ: كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ". (م,د,ن,جه)', 'ഫർവത്തുബ്നു നൗഫലുൽ അശ്ജഈ(റ): നബി(സ) അല്ലാഹുവോട് പ്രാർത്ഥിച്ചിരുന്നത് എപ്രകാരമായിരുന്നു എന്ന് ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു. മഹതി പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, ഞാൻ ചെയ്തതും ചെയ്യാത്തതുമായ പ്രവർത്തനങ്ങളുടെ തിന്മയിൽ നിന്ന് നിന്നോട് കാവൽ ചോദിക്കുന്നു. (മു,ദ,ന,ജ)', 'فَرْوَةَ بْنِ نَوْفَلٍ الْأَشْجَعِيِّ', 'ഫർവത്തുബ്നു നൗഫലുൽ അശ്ജഈ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنْ شَكَلِ بْنِ حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُولَ اللهِ عَلِّمْنِي دُعَاءً، قَالَ: "قُلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرٍّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي". (د,ت)', 'ശക്ലുബ്നു ഹുമൈദ്(റ): ഞാൻ നബി(സ)യോട് ഒരു ദുആ പഠിപ്പിച്ചു തരാൻ ആവശ്യപ്പെട്ടു. നബി(സ) പറഞ്ഞു: നീ ഇപ്രകാരം പറയുക: അല്ലാഹുവേ! എന്റെ കാഴ്ച, കേൾവി, നാവ്, ഹൃദയം, ലിംഗം എന്നിവയുടെ തിന്മയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. (ദ,തു)', 'شَكَلِ بْنِ حُمَيْدٍ', 'ശക്ലുബ്നു ഹുമൈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ، وَالْجُنُونِ، وَالْجُذَامِ، وَمِنْ سَيِّءِ الْأَسْقَامِ. (د,ن)', 'അനസ്(റ): നബി(സ) ഇങ്ങനെ പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, വെള്ളപ്പാണ്ട്, ഭ്രാന്ത്, കുഷ്ഠരോഗം, മോശമായ രോഗങ്ങൾ, എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ തേടുന്നു. (ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عن أَبِي سَعِيد الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِد، فَإِذَا هُوَ بِرَجُل مِنَ الْأَنْصَار يُقَالُ لَهُ أَبُو أُمَامَةَ فَقَالَ: "يَا أَبَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِد فِي غَيْرِ وَقْت الصَّلَاة". قَالَ: هُمُومٌ لَزِمَتْنِي وَدُيُونٌ يَا رَسُولَ اللهِ. قَالَ: "أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ اللهُ عَزَّ وَجَلَّ هَمَّك، وَقَضَى عَنْكَ دَيْنَكَ". قَالَ: قُلْتُ: بَلَى يَا رَسُولَ اللهِ، قَالَ: "قُلْ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَال". قَالَ: فَفَعَلْتُ ذَلِك، فَأَذْهَبَ اللهُ عَزَّ وَجَلَّ هَمِّي، وَقَضَى عَنِّي دَيْنِي. (د)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ഒരു ദിവസം നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ അബൂഉമാമ എന്നു പേരുള്ള ഒരു അൻസാരിയെ കാണാനിടയായി. നബി(സ) ചോദിച്ചു: ഓ അബൂഉമാമാ, സ്കാരത്തിന്റെ സമയമല്ലാത്ത ഇപ്പോൾ നീ എന്തിന് ഇവിടെ ഇരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: എന്നെ പിടികൂടിയ കട ബാധ്യതയും ദുഃഖവുമാണ് റസൂലേ. നബി(സ) പറഞ്ഞു: "നിന്റെ കടബാധ്യതകൾ വീട്ടുന്ന, വ്യസനങ്ങൾ അകറ്റുകയും ചെയ്യുന്ന ഒരു പ്രാർത്ഥന ഞാൻ നിനക്കു പറഞ്ഞു തരാം." അദ്ദേഹം പറഞ്ഞു. അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് പറഞ്ഞു തന്നാലും. നബി(സ) പറഞ്ഞു: "പ്രഭാതത്തിലും പ്രദോഷത്തിലും നീ ഇങ്ങനെ പറയുക: "അല്ലാഹുവേ, ദുഃഖം, വ്യസനം എന്നിവയിൽ നിന്ന് ഞാൻ കാവൽ തേടുന്നു. അശക്തത, അലസത, ഭീരുത്വം, പിശുക്ക് എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, കടങ്ങളുടെ ആധിക്യത്തിൽ നിന്നും ജനങ്ങളുടെ ആക്രമണത്തിൽ നിന്നും നിന്നും നീ എന്നെ രക്ഷിക്കേണമേ." അദ്ദേഹം പറയുന്നു: ഞാൻ അപ്രകാരം പ്രാർത്ഥിച്ചപ്പോൾ അല്ലാഹു എന്റെ ദുഃഖങ്ങൾ അകറ്റുകയും കടങ്ങൾ വീട്ടിത്തരുകയും ചെയ്തു. (ദ)', 'أَبِي سَعِيد الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عن أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْعَبَّاسِ: "يا عَمِّ، أَلَا أَحْبُوكَ، أَلَا أَنْفَعُكَ، أَلَا أُصِلُكَ". قَالَ: بَلَى يَا رَسُولَ الله. قَالَ: "فَصَلِّ أَرْبَعَ رَكَعَات: تَقْرَأُ فِي كُلِّ رَكْعَة بِفَاتِحَة الْكِتَاب وَسُورَة، فَإِذَا انْقَضَتِ الْقِرَاءَةُ فَقُلْ: سُبْحَان الله وَالْحَمْدُ لِلَّه وَلَا إِلَه إِلَّا الله وَاللهُ أَكْبَرُ، خَمْس عَشْرَة مَرَّة قَبْل أَنْ تَرْكَعَ ثُمَّ ارْكَعْ. فَقُلْهَا عَشْرًا، ثُمَّ ارْفَعْ رَأْسَك فَقُلْهَا عَشْرًا، ثُمَّ اسْجُدْ فَقُلْهَا عَشْرًا، ثُمَّ ارْفَعْ رَأْسَك فَقُلْهَا عَشْرًا، ثُمَّ اسْجُدْ فَقُلْهَا عَشْرًا، ثُمَّ ارْفَعْ رَأْسَك فَقُلْهَا عَشْرًا قَبْل أَنْ تَقُومَ. فَتِلْك خَمْسٌ وَسَبْعُونَ فِي كُلِّ رَكْعَة، وَهِيَ ثَلَاثُ مِائَة فِي أَرْبَعِ رَكَعَات، فَلَوْ كَانَتْ ذُنُوبُك مثل رَمْلِ عَالِج، غَفَرَهَا اللَّهُ لَكَ". قَالَ: يَا رَسُول الله، وَمَنْ لَمْ يَسْتَطِعْ يَقُولُهَا فِي يَوْمٍ؟ قَالَ: "قُلْهَا فِي جُمُعَة، فَإِنْ لَمْ تَسْتَطِعْ فَقُلْهَا فِي شَهْر". حَتَّى قَالَ: "فَقُلْهَا فِي سَنَة". (جه)', 'അബൂറാഫിഇ(റ)ൽനിന്ന്: റസൂൽ(സ) അബ്ബാസി(റ)നോട് പറഞ്ഞു: "പിതൃവ്യാ, ഞാൻ അങ്ങേക്ക് നൽകട്ടെയോ, ഞാൻ ഉപകാരം ചെയ്യട്ടെയോ, ഞാൻ കുടുംബബന്ധം ചേർക്കട്ടെയോ?" അബ്ബാസ്(റ) പ്രതിവചിച്ചു: "അതെ, അല്ലാഹുവിന്റെ തിരുദൂതരെ" റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ താങ്കൾ നാല് റക്അത് നിസ്കരിക്കുക. ഓരോ റക്അതിലും ഫാതിഹയും ഒരു സൂറത്തും ഓതണം. ഓത്ത് കഴിഞ്ഞാൽ താങ്കൾ ''സുബ്ഹാനല്ലാഹി വൽഹംദുലില്ലാഹി വലാഇലാഹ ഇല്ലല്ലാഹു വല്ലാഹു അക്ബർ'' എന്ന്, റുകൂഅ് ചെയ്യുന്നതിന് മുമ്പായി പതിനഞ്ചു പ്രാവശ്യം പറയുക. പിന്നെ റുകൂഅ് ചെയ്യുകയും പത്ത് പ്രാവശ്യം ഇത് ചൊല്ലുകയും ചെയ്യുക. പിന്നെ എഴുന്നേറ്റ് നിന്ന് പത്തു പ്രാവശ്യം പറയുക. പിന്നെ സുജൂദ് ചെയ്ത് പത്ത് പ്രാവശ്യം ചൊല്ലുക, പിന്നെ എഴുന്നേറ്റിരുന്ന് പത്ത് പ്രാവശ്യം പറയുക. പിന്നെ സുജൂദ് ചെയ്ത് പത്തു പ്രാവശ്യം പറയുക. പിന്നെ തലയുയർത്തി എഴുന്നേൽക്കുന്നതിനു മുമ്പായി പത്ത് പ്രാവശ്യം പറയുക. അങ്ങനെ ഓരോ റക്അതിലും എഴുപത്തിഅഞ്ച് എണ്ണം വീതം, അത് നാല് റക്അതിൽ മുന്നൂറ് എണ്ണമായിരിക്കും."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ أَنَسِ بْنِ مَالِك رَضِيَ اللهُ عَنْهُ: أَنَّ أُمَّ سُلَيْمٍ غَدَتْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: عَلِّمْنِي كَلِمَات أَقُولُهُنَّ فِي صَلَاتِي. فَقَالَ: كَبِّرِي اللهَ عَشْرًا، وَسَبِّحِي اللهَ عَشْرًا، وَاحْمَدِيه عَشْرًا، ثُمَّ سَلِي مَا شِئْت، يَقُولُ: "نَعَمْ، نَعَمْ". (ت)', 'അനസുബ്നു മാലിക്(റ): ഉമ്മുസുലൈം(റ) റസൂലി(സ)നെ സമീപിച്ച് പറഞ്ഞു: "എനിക്ക് നിസ്കാരത്തിൽ പറയാൻ ചില കലിമതുകൾ പഠിപ്പിച്ചു തന്നാലും." റസൂൽ(സ) പറഞ്ഞു: "പത്ത് പ്രാവശ്യം ''അല്ലാഹു അക്ബർ'' എന്ന് പറയുക, പത്ത് പ്രാവശ്യം ''സുബ്ഹാനല്ലാഹ്'' എന്നു പറയുക, പത്ത് പ്രാവശ്യം ''അൽഹംദുലില്ലാഹ്'' എന്നു പറയുക. ശേഷം നീ ഉദ്ദേശിച്ചത് ചോദിക്കുക. അവൻ നിനക്ക് ഉത്തരം നൽകും." (തു)', 'أَنَسِ بْنِ مَالِك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلْعَبَّاس بْنِ عَبْد الْمُطَّلِب: "يَا عَبَّاسُ، يَا عَمَّاهُ، أَلَا أُعْطِيك، أَلَا أَمْنَحُك، أَلَا أَحْبُوك أَلَا أَفْعَلُ بِك عَشْرَ خِصَال، إِذَا أَنْتَ فَعَلْتَ ذَلِكَ غَفَرَ اللَّهُ لَكَ ذَنْبَك أَوَّلَهُ وَآخِرَهُ، قَدِيمَهُ وَحَدِيثَهُ، خَطَأَهُ وَعَمْدَهُ، صَغِيرَهُ وَكَبِيرَهُ، سِرَّهُ وَعَلَانِيَتَهُ. عَشْر خِصَال: أَنْ تُصَلِّيَ أَرْبَعَ رَكَعَات: تَقْرَأُ فِي كُلِّ رَكْعَة فَاتِحَةَ الْكِتَاب وَسُورَة، فَإِذَا فَرَغْتَ مِنَ الْقِرَاءَة فِي أَوَّلِ رَكْعَة وَأَنْتَ قَائِمٌ: قُلْتَ سُبْحَان الله وَالْحَمْدُ لِلَّه وَلَا إِلَه إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ، خَمْسَ عَشْرَة مَرَّةً. ثُمَّ تَرْكَعُ فَتَقُولُهَا وَأَنْتَ رَاكِعٌ عَشْرًا، ثُمَّ تَرْفَعُ رَأْسَك مِنَ الرُّكُوع فَتَقُولُهَا عَشْرًا، ثُمَّ تَهْوِي سَاجِدًا فَتَقُولُهَا وَأَنْتَ سَاجِدٌ عَشْرًا، ثُمَّ تَرْفَعُ رَأْسَك مِنَ السُّجُود فَتَقُولُهَا عَشْرًا، ثُمَّ تَسْجُدُ فَتَقُولُهَا عَشْرًا، ثُمَّ تَرْفَعُ رَأْسَك فَتَقُولُهَا عَشْرًا. فَذَلِك خَمْسٌ وَسَبْعُونَ فِي كُلِّ رَكْعَة، تَفْعَلُ ذَلِك فِي أَرْبَعِ رَكَعَات. إِنِ اسْتَطَعْتَ أَنْ تُصَلِّيَهَا فِي كُلِّ يَوْمٍ مَرَّةً فَافْعَلْ، فَإِنْ لَمْ تَفْعَلْ فَفِي كُلِّ جُمُعَة مَرَّةً، فَإِنْ لَمْ تَفْعَلْ فَفِي كُلِّ شَهْرٍ مَرَّةً، فَإِنْ لَمْ تَفْعَلْ فَفِي كُلِّ سَنَة مَرَّةً فَإِنْ لَمْ تَفْعَلْ فَفِي عُمُرِك مَرَّةً". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) അബ്ബാസുബ്നു അബ്ദിൽ മുത്വലിബി(റ)നോട് പറഞ്ഞു: "അബ്ബാസ്! പിതൃവ്യാ! ഞാൻ താങ്കൾക്ക് നൽകട്ടെയോ, ഞാൻ താങ്കൾക്ക് (വേണ്ടത്) തരട്ടെയോ, ഞാൻ താങ്കൾക്ക് ദാനം നൽകട്ടെയോ? ഞാൻ താങ്കളോട് കുടുംബ ബന്ധം ചേർക്കട്ടെയോ? പത്ത് കാര്യങ്ങൾ, താങ്കൾ അവ ചെയ്യുകയാണെങ്കിൽ അല്ലാഹു താങ്കൾക്ക് താങ്കളുടെ ദോഷങ്ങൾ, അതിന്റെ തുടക്കവും ഒടുക്കവും, പുതിയതും പഴയതും മനഃപൂർവ്വം ചെയ്തതും പിഴച്ചു പോയതും, ചെറുതും വലുതും, രഹസ്യമായതും പരസ്യമായതും എല്ലാം പൊറുക്കപ്പെടുന്നതാണ്. പത്ത് കാര്യങ്ങൾ: താങ്കൾ നാല് റക്അത് നിസ്കരിക്കുക. ഓരോ റക്അതിലും ഫാതിഹായും സൂറത്തും ഓതുക. ആദ്യ റക്അതിൽ ഖുർആൻ പാരായണത്തിൽനിന്ന് വിരമിച്ചാൽ, ഖിയാമിൽ തന്നെയിരിക്കെ, ''സുബ്ഹാനല്ലാഹി വൽഹംദുലില്ലാഹി വലാഇലാഹ ഇല്ലല്ലാഹു അള്ളാഹു അക്ബർ'' എന്ന് പതിനഞ്ച് പ്രാവശ്യം ചൊല്ലുക. പിന്നെ റുകൂഅ് ചെയ്യുകയും റുകൂഇലായിരിക്കെ പത്ത് പ്രാവശ്യം ചൊല്ലുകയും ചെയ്യുക. പിന്നെ റുകൂഇൽ നിന്ന് തലയുയർത്തി പത്ത് പ്രാവശ്യം ചൊല്ലുക. പിന്നെ സുജൂദ് ചെയ്യുന്നവനായി കുനിയുക, എന്നിട്ട് സുജൂദിലായിരിക്കെ പത്ത് പ്രാവശ്യം ചൊല്ലുക. പിന്നെ സുജൂദിൽ നിന്ന് തലയുയർത്തി പത്ത് പ്രാവശ്യം ചൊല്ലുക. പിന്നെ സുജൂദ് ചെയ്ത് പത്തു പ്രാവശ്യം ചൊല്ലുക. പിന്നെ തലയുയർത്തി പത്ത് പ്രാവശ്യം ചൊല്ലു. അപ്പോൾ ഓരോ റക്അത്തിലും എഴുപത്തിഅഞ്ച് വീതമായി. അങ്ങനെ താങ്കൾ നാല് റക്അത്തിലും ചെയ്യുക. എല്ലാ ദിവസവും ഒരു പ്രാവശ്യം താങ്കൾക്ക് അങ്ങനെ നിസ്കരിക്കാനാവുമെങ്കിൽ ചെയ്ത് കൊള്ളുക, അങ്ങനെ ചെയ്യുന്നില്ലെങ്കിൽ ഓരോ വെള്ളിയാഴ്ചയും ചെയ്യുക. അതും ചെയ്യുന്നില്ലെങ്കൽ മാസത്തിലൊരിക്കൽ, അതുമല്ലെങ്കിൽ വർഷത്തിലൊരിക്കൽ, അതും ചെയ്യുന്നില്ലെങ്കിൽ നിന്റെ ആയുഷ്കാലത്ത് ഒരിക്കലെങ്കിലും ചെയ്യുക." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 633, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنْ أَبِي الْجَوْزَاء رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي رَجُلٌ كَانَتْ لَهُ صُحْبَةٌ يَرَوْنَ أَنَّهُ عَبْدُ اللهِ بْنُ عَمْرو قَالَ: قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ائْتِنِي غَدًا أَحْبُوكَ وَأُثِيبُكَ وَأُعْطِيكَ" حَتَّى ظَنَنْتُ أَنَّهُ يُعْطِينِي عَطِيَّةً، قَالَ "إِذَا زَالَ النَّهَارُ فَقُمْ فَصَلِّ أَرْبَعَ رَكَعَات" فَذَكَرَ نَحْوَهُ، قَالَ "ثُمَّ تَرْفَعُ رَأْسَك – يَعْنِي مِنَ السَّجْدَةِ الثَّانِيَة – فَاسْتَوِ جَالِسًا وَلَا تَقُمْ حَتَّى تُسَبِّح عَشْرًا وَتَحْمَد عَشْرًا وَتُكَبِّر عَشْرًا وَتُهَلِّل عَشْرًا، ثُمَّ تَصْنَعَ ذَلِك فِي الْأَرْبَع الرَّكَعَات" قَالَ: "فَإِنَّك لَوْ كُنْتَ أَعْظَمَ أَهْلِ الْأَرْضِ ذَنْبًا غُفِرَ لَك بِذَلِك". قُلْتُ: فَإِنْ لَمْ أَسْتَطِعْ أَنْ أُصَلِّيَهَا تِلْك السَّاعَةَ؟ قَالَ: "صَلِّهَا مِنَ اللَّيْلِ وَالنَّهَار". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِجَعْفَرٍ بِهَذَا الْحَدِيث. (د)', 'അബിൽ ജൗസാ(റ): സ്വഹാബിയായ ഒരാൾ എന്നോട് പറഞ്ഞു. (ഒരഭിപ്രായം: അത് അബ്ദുല്ലാഹിബ്നു അംറ്(റ) ആണെന്നാണ്). ഒരു ദിവസം പ്രവാചകൻ(സ) എന്നോട് പറഞ്ഞു: "നാളെ നീ എന്റെ അരികിൽ വരിക. നിനക്ക് ഞാൻ നൽകാം." പ്രവാചകൻ(സ) എനിക്ക് വല്ല ദാനവും നൽകുമെന്ന് ഞാൻ വിചാരിച്ചു. പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "രാത്രിയായാൽ നീ നാലു റകഅത്ത് നിസ്കരിക്കുക." പിന്നീട് റസൂൽ(സ) മേൽപറഞ്ഞ ഹദീസിലുള്ളതുപോലെ പറഞ്ഞു. പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "പിന്നീട് നീ രണ്ടാം സുജൂദിൽ നിന്ന് എഴുന്നേറ്റ് ഇരിക്കുക. അങ്ങനെ എഴുന്നേൽക്കുന്നതിനു മുമ്പായി പത്തു തവണ വീതം തസ്ബീഹും തഹ്മീദും തക്ബീറും തഹ്ലീലും ചൊല്ലുക. അതുപോലെ നാലു റക്അത്തിലും തുടരുക." പിന്നീട് പ്രവാചകൻ(സ) പറഞ്ഞു: "ഭൂമിയിൽ ഏറ്റവും വലിയ ദോഷി നീയാണെങ്കിലും ഈ നിസ്കാരം കാരണം അതെല്ലാം നിനക്ക് പൊറുക്കപ്പെടും." ഞാൻ ചോദിച്ചു. ആ സമയം എനിക്കത് നിർവ്വഹിക്കാൻ സാധിച്ചില്ലെങ്കിലോ. പ്രവാചകൻ(സ) അരുളി: "എങ്കിൽ നീ രാത്രിയും പകലും അത് നിർവ്വഹിക്കുക." മറ്റൊരു നിവേദനത്തിൽ: ഇപ്രകാരം പ്രവാചകൻ(സ) ജഅ്ഫറി(റ)നോട് പറഞ്ഞു. (ദ)', 'أَبِي الْجَوْزَاء', 'അബിൽ ജൗസാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=23 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=23 and h.hadith_no=354), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِجَعْفَرٍ بِهَذَا الْحَدِيث. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: ഇപ്രകാരം പ്രവാചകൻ(സ) ജഅ്ഫറി(റ)നോട് പറഞ്ഞു. (ദ)');
